-- Startup Physics & Flight Reset Guard (Guarantees character spawns completely still with zero residual forces)
pcall(function()
    if _G.FlightSettings and _G.FlightSettings.FlightConnection then
        pcall(function() _G.FlightSettings.FlightConnection:Disconnect() end)
        _G.FlightSettings.FlightConnection = nil
    end
    if _G.SetFlightState then
        pcall(function() _G.SetFlightState(false) end)
    end
    if _G.FlightToggle and _G.FlightToggle.Set then
        pcall(function() _G.FlightToggle:Set(false) end)
    end
    local p = game:GetService("Players").LocalPlayer
    local c = p and p.Character
    if c then
        for _, obj in ipairs(c:GetDescendants()) do
            if obj:IsA("BodyVelocity") or obj:IsA("BodyGyro") then
                pcall(function() obj:Destroy() end)
            end
        end
        local hum = c:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.PlatformStand = false
            hum.Sit = false
        end
        local root = c:FindFirstChild("HumanoidRootPart")
        if root then
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
    end
end)


