-- Universal Whitelist System (Friends & Custom Protection)
_G.TR_Whitelist = _G.TR_Whitelist or {}
_G.TR_AutoWhitelistFriends = true

local function TR_IsWhitelisted(p)
    if not p then return false end
    local plr = nil
    if typeof(p) == "Instance" and p:IsA("Player") then
        plr = p
    elseif type(p) == "string" then
        plr = Players:FindFirstChild(p) or Players:GetPlayerByUserId(tonumber(p) or 0)
    end
    if not plr then
        if type(p) == "string" and _G.TR_Whitelist[p] then return true end
        return false
    end
    if plr == LocalPlayer then return true end
    if _G.TR_Whitelist[plr.Name] or _G.TR_Whitelist[tostring(plr.UserId)] or _G.TR_Whitelist[plr.DisplayName] then
        return true
    end
    if _G.TR_AutoWhitelistFriends then
        local isFriend = false
        pcall(function()
            isFriend = LocalPlayer:IsFriendsWith(plr.UserId)
        end)
        if isFriend then return true end
    end
    return false
end
_G.TR_IsWhitelisted = TR_IsWhitelisted

