-- ============================================================
-- UI Kutuphane yukleyici (DUZELTME: eski FAKELIBRORY linki 404)
-- 1) Once orijinal kutuphane denenir.
-- 2) Olmazsa ayni API'yi destekleyen AxiomUI yuklenir ve asagidaki
--    adaptor ile XOCU'nun bekledigi arayuze cevrilir
--    (CreateTab/CreateBlock/CreateToggle/CreateSlider/
--     CreateDropdown(Items/List)/CreateInput/CreateButton/
--     CreateKeybind + SetValue/GetValue/Refresh/SetItems).
-- ============================================================
local function AdaptUILibrary(RealLibrary)
    local Registry = {}
    local activeNotify = nil

    local WrapperLibrary = {}
    WrapperLibrary.Flags = Registry
    WrapperLibrary.Items = Registry

    local function register(cfg, api)
        if type(cfg) ~= "table" or not api then return end
        if cfg.Flag and cfg.Flag ~= "" then Registry[cfg.Flag] = api end
        if cfg.Name and cfg.Name ~= "" then
            Registry[cfg.Name] = api
            Registry[(cfg.Name:gsub("%s+", ""))] = api
        end
    end

    function WrapperLibrary:Notify(cfg)
        if activeNotify then
            return activeNotify(cfg)
        end
        warn("[Ranax Notify]", cfg and (cfg.Title or ""), cfg and (cfg.Content or cfg.Description or ""))
    end

    function WrapperLibrary:CreateWindow(cfg)
        cfg = cfg or {}
        local oldTheme = type(cfg.Theme) == "table" and cfg.Theme or {}
        local realCfg = {}
        for k, v in pairs(cfg) do realCfg[k] = v end
        realCfg.OpenKeybind = cfg.ToggleKey or cfg.OpenKeybind or Enum.KeyCode.RightShift
        realCfg.Logo = cfg.CustomIcon or cfg.Logo or "82269833034303"
        realCfg.Watermark = true
        realCfg.ShowWatermark = true
        realCfg.WindowSize = cfg.WindowSize or Vector2.new(1180, 760) -- menu biraz buyuk
        realCfg.ConfigFolder = cfg.ConfigFolder or "TR_ftap_Config"
        realCfg.Theme = {
            Accent = oldTheme.ElementAccent or oldTheme.GradientStart or Color3.fromRGB(110, 100, 255),
            Background = oldTheme.Main or Color3.fromRGB(8, 8, 11),
            Sidebar = oldTheme.Second or Color3.fromRGB(13, 13, 17),
            Card = Color3.fromRGB(18, 18, 24),
            Element = Color3.fromRGB(22, 22, 30),
            Input = Color3.fromRGB(16, 16, 22),
            Text = oldTheme.TextColor or Color3.fromRGB(255, 255, 255),
            TextMuted = Color3.fromRGB(145, 150, 170),
            BackgroundImage = "",
            BgImageTrans = 1.0,
            TextFont = oldTheme.Font or "GothamBold",
            CornerRadius = oldTheme.CornerRadius or 12,
        }

        local RealWindow = RealLibrary:CreateWindow(realCfg)
        activeNotify = function(c) return RealWindow:Notify(c) end

        local WrapperWindow = {}
        function WrapperWindow:Notify(c)
            return RealWindow:Notify(c)
        end
        function WrapperWindow:SetThemeOption(k, v)
            if RealWindow and RealWindow.SetThemeOption then
                return RealWindow:SetThemeOption(k, v)
            end
        end
        function WrapperWindow:SetTheme(t)
            if RealWindow and RealWindow.SetTheme then
                return RealWindow:SetTheme(t)
            end
        end
        setmetatable(WrapperWindow, {
            __index = function(_, k)
                if RealWindow and RealWindow[k] then
                    return function(self, ...)
                        return RealWindow[k](RealWindow, ...)
                    end
                end
            end
        })

        local function formatModuleName(str)
            if type(str) ~= "string" then return str end
            local clean = str:gsub("%s*%([Tt][Rr]%)", ""):gsub("%s*%[[Tt][Rr]%]", ""):gsub("^%s*[Tt][Rr]%s+", "")
            clean = clean:gsub("(%a)([%w_']*)", function(first, rest)
                return first:upper() .. rest:lower()
            end)
            clean = clean:gsub("Pvp", "PvP"):gsub("Esp", "ESP"):gsub("Fov", "FOV"):gsub("Fps", "FPS"):gsub("R6", "R6"):gsub("Tp", "TP"):gsub("Ui", "UI"):gsub("Ft", "FT")
            return clean
        end

        function WrapperWindow:CreateTab(nameArg, secondArg, thirdArg)
            local tabName, tabIcon, tabSettings
            if type(nameArg) == "table" then
                tabName = formatModuleName(nameArg.Name or "Tab")
                tabIcon = nameArg.Icon
                tabSettings = nameArg.IsSettings
            else
                tabName = formatModuleName(tostring(nameArg or "Tab"))
                if type(secondArg) == "string" and thirdArg == nil then
                    tabIcon = secondArg
                elseif type(thirdArg) == "string" then
                    tabIcon = thirdArg
                elseif type(secondArg) == "string" then
                    tabIcon = secondArg
                end
                tabSettings = false
            end

            local RealTab = RealWindow:CreateTab({ Name = tabName, Icon = tabIcon, IsSettings = tabSettings == true })

            local WrapperTab = {}
            function WrapperTab:CreateBlock(blockCfg)
                blockCfg = type(blockCfg) == "table" and blockCfg or { Name = tostring(blockCfg or "Block") }
                local bName = formatModuleName(blockCfg.Name or "Block")
                local RealBlock = RealTab:CreateBlock({ Name = bName, Side = blockCfg.Side or "Left", Icon = blockCfg.Icon })

                local WrapperBlock = {}

                function WrapperBlock:CreateToggle(tglCfg)
                    local api
                    local value = tglCfg.Default and true or false
                    local tName = formatModuleName(tglCfg.Name)
                    local realApi = RealBlock:CreateToggle({
                        Name = tName,
                        Default = tglCfg.Default,
                        Callback = function(state)
                            value = state and true or false
                            if tglCfg.Callback then tglCfg.Callback(state) end
                        end,
                    })
                    api = {}
                    api.Value = value
                    function api:Set(v)
                        value = v and true or false
                        api.Value = value
                        if realApi and realApi.Set then realApi:Set(value) end
                    end
                    function api:SetValue(v) return api:Set(v) end
                    function api:GetValue() return value end
                    function api:Get() return value end
                    register(tglCfg, api)
                    return api
                end

                function WrapperBlock:CreateSlider(sldCfg)
                    local decimals = tonumber(sldCfg.Rounding) or 0
                    if sldCfg.Rounding == nil then
                        local function decOf(x)
                            local s = tostring(x or "")
                            local d = s:match("%.(%d+)")
                            return d and #d or 0
                        end
                        decimals = math.max(decOf(sldCfg.Default), decOf(sldCfg.Min), decOf(sldCfg.Max))
                    end
                    local step = 10 ^ (-math.clamp(decimals, 0, 4))
                    local value = sldCfg.Default
                    local sName = formatModuleName(sldCfg.Name)
                    local realApi = RealBlock:CreateSlider({
                        Name = sName,
                        Min = sldCfg.Min,
                        Max = sldCfg.Max,
                        Default = sldCfg.Default,
                        Step = step,
                        Callback = function(v)
                            value = v
                            if sldCfg.Callback then sldCfg.Callback(v) end
                        end,
                    })
                    local api = {}
                    function api:Set(v)
                        value = v
                        if realApi and realApi.Set then realApi:Set(v) end
                    end
                    function api:SetValue(v) return api:Set(v) end
                    function api:GetValue() return value end
                    function api:Get() return value end
                    register(sldCfg, api)
                    return api
                end

                function WrapperBlock:CreateDropdown(drpCfg)
                    local options = drpCfg.Items or drpCfg.List or drpCfg.Options or {}
                    local defaultValue = drpCfg.Default
                    if type(defaultValue) == "number" then
                        defaultValue = options[defaultValue]
                    end
                    local value = defaultValue
                    local dName = formatModuleName(drpCfg.Name)
                    local realApi = RealBlock:CreateDropdown({
                        Name = dName,
                        Options = options,
                        Default = defaultValue,
                        Multi = drpCfg.Multi,
                        Callback = function(v)
                            if type(v) == "table" and not drpCfg.Multi then
                                v = v[1] or v.Value or v
                            end
                            value = v
                            if drpCfg.Callback then drpCfg.Callback(v) end
                        end,
                    })
                    local api = {}
                    api.Value = value
                    function api:Set(v)
                        if realApi then
                            if realApi.Set then
                                pcall(function() realApi:Set(v) end)
                            elseif realApi.SetValue then
                                pcall(function() realApi:SetValue(v) end)
                            end
                        end
                        value = v
                        api.Value = v
                    end
                    function api:SetValue(v) return api:Set(v) end
                    function api:GetValue() return value end
                    function api:Get() return value end
                    function api:Refresh(newOptions)
                        if type(newOptions) == "table" then
                            options = newOptions
                            api.Options = newOptions
                            if realApi then
                                if realApi.Refresh then
                                    pcall(function() realApi:Refresh(newOptions) end)
                                elseif realApi.SetOptions then
                                    pcall(function() realApi:SetOptions(newOptions) end)
                                elseif realApi.SetItems then
                                    pcall(function() realApi:SetItems(newOptions) end)
                                elseif realApi.Update then
                                    pcall(function() realApi:Update(newOptions) end)
                                end
                            end
                        end
                    end
                    api.SetOptions = function(self, opt) return api:Refresh(opt) end
                    api.SetItems = function(self, opt) return api:Refresh(opt) end
                    api.SetValues = function(self, opt) return api:Refresh(opt) end
                    api.Update = function(self, opt) return api:Refresh(opt) end
                    function api:SetItems(newOptions) return api:Refresh(newOptions) end
                    function api:SetOptions(newOptions) return api:Refresh(newOptions) end
                    function api:SetValues(newOptions) return api:Refresh(newOptions) end
                    function api:Update(newOptions) return api:Refresh(newOptions) end
                    register(drpCfg, api)
                    return api
                end

                function WrapperBlock:CreateInput(inpCfg)
                    local iName = formatModuleName(inpCfg.Name)
                    local realApi = nil
                    if RealBlock then
                        if type(RealBlock.CreateInput) == "function" then
                            pcall(function()
                                realApi = RealBlock:CreateInput({
                                    Name = iName,
                                    Default = inpCfg.Default,
                                    Placeholder = inpCfg.Placeholder or "...",
                                    Callback = function(v)
                                        if inpCfg.Callback then inpCfg.Callback(v) end
                                    end,
                                })
                            end)
                        elseif type(RealBlock.CreateBox) == "function" then
                            pcall(function()
                                realApi = RealBlock:CreateBox({
                                    Name = iName,
                                    Default = inpCfg.Default,
                                    Placeholder = inpCfg.Placeholder or "...",
                                    Callback = function(v)
                                        if inpCfg.Callback then inpCfg.Callback(v) end
                                    end,
                                })
                            end)
                        elseif type(RealBlock.CreateTextBox) == "function" then
                            pcall(function()
                                realApi = RealBlock:CreateTextBox({
                                    Name = iName,
                                    Default = inpCfg.Default,
                                    Placeholder = inpCfg.Placeholder or "...",
                                    Callback = function(v)
                                        if inpCfg.Callback then inpCfg.Callback(v) end
                                    end,
                                })
                            end)
                        end
                    end
                    local api = realApi or {}
                    if type(api) == "table" then
                        local rawSetText = api.SetText
                        function api:SetText(v)
                            if rawSetText then return rawSetText(api, v) end
                        end
                        function api:SetValue(v) return api:SetText(v) end
                        function api:GetText() return inpCfg.Default or "" end
                        function api:GetValue() return api:GetText() end
                    end
                    register(inpCfg, api)
                    return api
                end

                function WrapperBlock:CreateLabel(lblCfg)
                    local text = type(lblCfg) == "table" and (lblCfg.Text or lblCfg.Name or "") or tostring(lblCfg or "")
                    if RealBlock.CreateLabel then
                        return RealBlock:CreateLabel(formatModuleName(text))
                    end
                end

                function WrapperBlock:CreatePicture(picCfg)
                    if RealBlock.CreatePicture then
                        return RealBlock:CreatePicture({
                            Name = formatModuleName(picCfg.Name or "Picture"),
                            Image = picCfg.Image or "",
                            Description = picCfg.Description or "",
                            Size = picCfg.Size,
                        })
                    end
                end

                function WrapperBlock:CreateButton(btnCfg)
                    local bName = formatModuleName(btnCfg.Name)
                    local realApi = RealBlock:CreateButton({
                        Name = bName,
                        Callback = function()
                            if btnCfg.Callback then btnCfg.Callback() end
                        end,
                    })
                    register(btnCfg, realApi)
                    return realApi
                end

                function WrapperBlock:CreateKeybind(keyCfg)
                    local kName = formatModuleName(keyCfg.Name)
                    local def = keyCfg.Default
                    if def == "None" or def == "NONE" or def == "" or def == nil then
                        def = Enum.KeyCode.Unknown
                    elseif type(def) == "string" and Enum.KeyCode[def] then
                        def = Enum.KeyCode[def]
                    end

                    local currentBind = def
                    local realApi = RealBlock:CreateKeybind({
                        Name = kName,
                        Default = def,
                        Callback = function(newBind)
                            currentBind = newBind
                            if keyCfg.OnKeyChanged then
                                pcall(function() keyCfg.OnKeyChanged(newBind) end)
                            end
                            if keyCfg.OnChanged then
                                pcall(function() keyCfg.OnChanged(newBind) end)
                            end
                        end,
                    })

                    -- Universal direct UserInputService bridge for keyboard & mouse button keybinds
                    -- Debounce prevents rapid double-toggling and guarantees exactly 1 clean toggle per press
                    local UIS = game:GetService("UserInputService")
                    local lastTrigger = 0
                    local conn = UIS.InputBegan:Connect(function(input, gpe)
                        if gpe then return end
                        if not currentBind or currentBind == Enum.KeyCode.Unknown then return end
                        if input.KeyCode == currentBind or input.UserInputType == currentBind then
                            local now = tick()
                            if now - lastTrigger < 0.2 then return end
                            lastTrigger = now
                            if keyCfg.Callback then
                                pcall(function() keyCfg.Callback(currentBind) end)
                            end
                        end
                    end)

                    local api = realApi or {}
                    api._InputConn = conn
                    function api:SetKey(k)
                        currentBind = k
                        if keyCfg.OnKeyChanged then pcall(function() keyCfg.OnKeyChanged(k) end) end
                        if realApi and realApi.SetKey then pcall(function() realApi:SetKey(k) end) end
                    end
                    register(keyCfg, api)
                    return api
                end

                return WrapperBlock
            end

            return WrapperTab
        end

        return WrapperWindow
    end

    return WrapperLibrary
end

local function LoadUILibrary()
    local ok, result = pcall(function()
        local source = game:HttpGet("https://raw.githubusercontent.com/sladkoeshkaogg-svg/XOCU/refs/heads/main/XOCU%20FAKELIBRORY.lua")
        local chunk = loadstring(source)
        assert(chunk, "library loadstring failed")
        local lib = chunk()
        assert(type(lib) == "table" and type(lib.CreateWindow) == "function", "library invalid")
        return lib
    end)
    if ok and result then
        return result
    end

    print("[Ranax FTAP] Loading UI Library...")
    local source = game:HttpGet("https://raw.githubusercontent.com/katnaa-debug/AxiomUI/refs/heads/main/Library.lua")
    local chunk = assert(loadstring(source), "AxiomUI loadstring failed")
    local realLibrary = chunk()
    assert(type(realLibrary) == "table" and type(realLibrary.CreateWindow) == "function", "AxiomUI invalid")
    return AdaptUILibrary(realLibrary)
end

