-- Guncelleme kontrolu: yeni surum yuklenirse acik olan herkese otomatik rejoin
do
    local TR_BUILD = "4"
    local TR_VER_URL = ""
    task.spawn(function()
        task.wait(20)
        while true do
            local ok, res = pcall(function() return game:HttpGet(TR_VER_URL) end)
            if ok and res then
                local v = tostring(res):gsub("%s+", "")
                if v ~= "" and v ~= TR_BUILD then
                    local TS = game:GetService("TeleportService")
                    local plr = game:GetService("Players").LocalPlayer
                    pcall(function()
                        if game.JobId and game.JobId ~= "" then
                            TS:TeleportToPlaceInstance(game.PlaceId, game.JobId, plr)
                        else
                            TS:Teleport(game.PlaceId, plr)
                        end
                    end)
                    return
                end
            end
            task.wait(45)
        end
    end)
end
