        "ShZGF3vFdvQjtnd8dI/Eb7MHP1mTM6evD6qeQDhaFKTyZ3mh/szH/06HkLf+G8qnh9EAI53e1T8yl/rOAe70B/yhi+TlFS79cj3H",
        "6RLv6at8ye+8+5++PvLB4vR1+oKozSuVi76n8KPxUYtN4cfs9wtP3/tT8V7IY1NC6VR+Kj9q25b0Mfv9pI/Aews/evdCDsuZf/gR",
        "PRmGp8hrnOq7/8m+T+Epdt/Ck/CzpZ/zWuGH93OLmICngeCnr9PXx7MGEASjwyWni4Afr+v0x/2xv1TeIs08vf9/rK7TH/fpDOD0",
        "LnD6On19nDOA0xiQ09fp62OcAZxOAU5fp6+PbwA4res+fZ2+PsYBIHy3GUD4q/5v0VkI3/1LfCBX+C6/N/yZf/Xz7mT47n9i+P69",
        "y/AdflD4K//88Od+0y/9nMP3+Mm8p9sV/saev/CkP22/4N9GD+Kv/u7e9p0h/P+kgR19AMprDgAAAABJRU5ErkJggg==",
        })
        local function b64decode(data)
            local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
            data = tostring(data):gsub('%s', '')
            data = data:gsub('[^' .. b .. '=]', '')
            return (data:gsub('.', function(x)
                if x == '=' then return '' end
                local r, f = '', (b:find(x) - 1)
                for i = 6, 1, -1 do r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and '1' or '0') end
                return r
            end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
                if #x ~= 8 then return '' end
                local c = 0
                for i = 1, 8 do c = c + (x:sub(i, i) == '1' and 2 ^ (8 - i) or 0) end
                return string.char(c)
            end))
        end

        if type(writefile) == "function" and type(getcustomasset) == "function" then
            pcall(function() writefile("XOCU_SkeletonMoon.png", b64decode(b64data)) end)
            local ok, result = pcall(function() return getcustomasset("XOCU_SkeletonMoon.png") end)
            if ok and result then logoAsset = result end
        end

        local old = game:GetService("CoreGui"):FindFirstChild("XOCUSkeletonMoonGui")
        if old then old:Destroy() end

        -- Iskelet+Ay artik menunun icinde: sol ustte (Sidebar > LogoContainer)
        task.spawn(function()
            local core = game:GetService("CoreGui")
            local dash = nil
            for _ = 1, 50 do
                dash = core:FindFirstChild("ModernDashboardGui")
                if dash and dash:FindFirstChild("LogoContainer", true) then break end
                task.wait(0.1)
            end
            if not dash then return end
            local logoContainer = dash:FindFirstChild("LogoContainer", true)
            if not logoContainer then return end

            -- Destroy Axiom's default LogoLabel and LogoImage so no white artifacts remain
            local defaultLogoLabel = logoContainer:FindFirstChild("LogoLabel")
            if defaultLogoLabel then
                pcall(function() defaultLogoLabel:Destroy() end)
            end

            local oldLogo = logoContainer:FindFirstChild("LogoImage")
            if oldLogo then pcall(function() oldLogo:Destroy() end) end
            local oldSkel = logoContainer:FindFirstChild("SkeletonMoon")
            if oldSkel then pcall(function() oldSkel:Destroy() end) end

            -- Remove any stray UIStrokes, separators or white box artifacts inside logoContainer
            for _, child in ipairs(logoContainer:GetChildren()) do
                if child:IsA("UIStroke") or (child:IsA("Frame") and child.Name ~= "RanaxHeaderBox") then
                    pcall(function() child:Destroy() end)
                end
            end
            logoContainer.BackgroundTransparency = 1
            logoContainer.BorderSizePixel = 0

            -- Reconfigure logoContainer for clean left-to-right alignment with proper padding
            local logoLayout = logoContainer:FindFirstChildOfClass("UIListLayout")
            if logoLayout then
                logoLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
                logoLayout.VerticalAlignment = Enum.VerticalAlignment.Center
                logoLayout.Padding = UDim.new(0, 8)
            end
            local logoPadding = logoContainer:FindFirstChildOfClass("UIPadding")
            if logoPadding then
                logoPadding.PaddingLeft = UDim.new(0, 10)
                logoPadding.PaddingRight = UDim.new(0, 8)
            end

            -- SkeletonMoon icon
            local img = Instance.new("ImageLabel")
            img.Name = "SkeletonMoon"
            img.Size = UDim2.new(0, 36, 0, 36)
            img.BackgroundTransparency = 1
            img.BorderSizePixel = 0
            img.LayoutOrder = 1
            img.Image = logoAsset or "rbxthumb://type=Asset&id=17007876976&w=420&h=420"
            img.ImageColor3 = Color3.fromRGB(255, 255, 255)
            img.Parent = logoContainer

            -- Watermark logosunu menudeki logoyla ve rengiyle birebir esitle (Accent rengi degil, menudeki logonun rengi)
            local function syncWatermarkLogo()
                pcall(function()
                    local wmLogo = dash:FindFirstChild("WMLogo", true)
                    if wmLogo and img then
                        wmLogo.Visible = true
                        wmLogo.Image = img.Image
                        wmLogo.ImageColor3 = img.ImageColor3
                    end
                end)
            end
            _G.Ranax_SyncWatermarkLogo = syncWatermarkLogo
            syncWatermarkLogo()
            task.spawn(function()
                while dash and dash.Parent do
                    syncWatermarkLogo()
                    task.wait(0.5)
                end
            end)

            -- Clean old dev/prem labels if present in sidebar
            local sidebar = logoContainer.Parent
            local TweenService = game:GetService("TweenService")
            local oldDev = sidebar:FindFirstChild("DevLabel")
            if oldDev then oldDev:Destroy() end
            local oldPrem = sidebar:FindFirstChild("PremiumLabel")
            if oldPrem then oldPrem:Destroy() end

            -- HeaderBox: Brand Title cleanly centered (Category text removed as requested)
            local oldBox = logoContainer:FindFirstChild("RanaxHeaderBox")
            if oldBox then oldBox:Destroy() end

            local headerBox = Instance.new("Frame")
            headerBox.Name = "RanaxHeaderBox"
            headerBox.Size = UDim2.new(1, -50, 0, 36)
            headerBox.BackgroundTransparency = 1
            headerBox.BorderSizePixel = 0
            headerBox.LayoutOrder = 2
            headerBox.ClipsDescendants = false
            headerBox.Parent = logoContainer

            local brandLabel = Instance.new("TextLabel")
            brandLabel.Name = "BrandLabel"
            brandLabel.Size = UDim2.new(1, 0, 1, 0)
            brandLabel.Position = UDim2.new(0, 0, 0, 0)
            brandLabel.BackgroundTransparency = 1
            brandLabel.Text = "Ranax FTAP"
            brandLabel.TextSize = 18
            brandLabel.Font = Enum.Font.GothamBold
            brandLabel.TextColor3 = Color3.fromRGB(20, 23, 35)
            brandLabel.TextXAlignment = Enum.TextXAlignment.Left
            brandLabel.TextYAlignment = Enum.TextYAlignment.Center
            brandLabel.TextTruncate = Enum.TextTruncate.None
            brandLabel.Parent = headerBox

            -- Category indicator under title completely disabled as requested
            _G.Ranax_UpdateCategory = function(name) end

            -- ============================================================
            -- ULTRA SMOOTH CINEMATIC MOTION & TRANSITION ENGINE
            -- Sekme/Sayfa gecisleri: Spring-scale, akici slide, kademeli (staggered) kart girisleri
            -- ============================================================
            local function animatePageEntrance(page)
                if not page or not page.Parent or page:GetAttribute("RanaxTransitionRunning") then return end
                page:SetAttribute("RanaxTransitionRunning", true)

                pcall(function()
                    local pageScale = page:FindFirstChild("RanaxPageScale")
                    if not pageScale then
                        pageScale = Instance.new("UIScale")
                        pageScale.Name = "RanaxPageScale"
                        pageScale.Parent = page
                    end

                    -- Sayfa baslangic konumu: hafif asagidan ve kucukten yaylanarak gelir
                    pageScale.Scale = 0.95
                    page.Position = UDim2.new(0, 0, 0, 14)

                    local pageTween = TweenService:Create(page, TweenInfo.new(0.32, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                        Position = UDim2.new(0, 0, 0, 0)
                    })
                    local scaleTween = TweenService:Create(pageScale, TweenInfo.new(0.36, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                        Scale = 1.0
                    })
                    pageTween:Play()
                    scaleTween:Play()

                    -- Kademeli (Staggered) Kart & Blok Dalgalanmasi
                    local cards = {}
                    for _, desc in ipairs(page:GetDescendants()) do
                        if desc:IsA("Frame") and (desc.Name == "LeftColumn" or desc.Name == "RightColumn") then
                            for _, child in ipairs(desc:GetChildren()) do
                                if child:IsA("Frame") and child.Visible and child.Name ~= "columnsLayout" then
                                    table.insert(cards, child)
                                end
                            end
                        end
                    end

                    for idx, card in ipairs(cards) do
                        local cardScale = card:FindFirstChild("RanaxCardScale")
                        if not cardScale then
                            cardScale = Instance.new("UIScale")
                            cardScale.Name = "RanaxCardScale"
                            cardScale.Parent = card
                        end
                        cardScale.Scale = 0.93

                        task.delay(math.min(idx * 0.024, 0.22), function()
                            if not page.Visible then return end
                            TweenService:Create(cardScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                                Scale = 1.0
                            }):Play()
                        end)
                    end
                end)

                task.delay(0.35, function()
                    pcall(function() page:SetAttribute("RanaxTransitionRunning", false) end)
                end)
            end

            local function hookPageTransitions()
                pcall(function()
                    for _, obj in ipairs(dash:GetDescendants()) do
                        if (obj:IsA("Frame") or obj:IsA("CanvasGroup")) and obj.Name:find("^Page_") and not obj:GetAttribute("RanaxPageHooked") then
                            obj:SetAttribute("RanaxPageHooked", true)
                            obj:GetPropertyChangedSignal("Visible"):Connect(function()
                                if obj.Visible then
                                    animatePageEntrance(obj)
                                end
                            end)
                            if obj.Visible then
                                animatePageEntrance(obj)
                            end
                        end
                    end
                end)
            end

            -- Butonlar, Tab tuslari ve interaktif ogeler icin elastik dokunmatik animasyonlar
            local function hookInteractiveAnimations()
                pcall(function()
                    hookPageTransitions()

                    for _, btn in ipairs(dash:GetDescendants()) do
                        if (btn:IsA("TextButton") or btn:IsA("ImageButton")) and not btn:GetAttribute("RanaxAnimHooked") then
                            btn:SetAttribute("RanaxAnimHooked", true)
                            local origScale = btn:FindFirstChildOfClass("UIScale")
                            if not origScale then
                                origScale = Instance.new("UIScale")
                                origScale.Parent = btn
                            end

                            btn.MouseEnter:Connect(function()
                                pcall(function()
                                    TweenService:Create(origScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                                        Scale = 1.04
                                    }):Play()
                                end)
                            end)

                            btn.MouseLeave:Connect(function()
                                pcall(function()
                                    TweenService:Create(origScale, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                                        Scale = 1.0
                                    }):Play()
                                end)
                            end)

                            btn.MouseButton1Down:Connect(function()
                                pcall(function()
                                    TweenService:Create(origScale, TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                                        Scale = 0.94
                                    }):Play()
                                end)
                            end)

                            btn.MouseButton1Up:Connect(function()
                                pcall(function()
                                    TweenService:Create(origScale, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                                        Scale = 1.04
                                    }):Play()
                                end)
                            end)

                            -- Tab tusuna basildiginda: Ikon hafif yaylanir, kategori guncellenir, baslik akar
                            local tabParent = btn.Parent
                            if tabParent and (tabParent.Name:find("Tab") or btn.Name:find("Tab") or btn:FindFirstChild("TabTitle")) then
                                btn.Activated:Connect(function()
                                    local labelObj = btn:FindFirstChild("TabTitle") or btn:FindFirstChildOfClass("TextLabel")
                                    local tName = labelObj and labelObj.Text or btn.Name:gsub("TabButton_", "")
                                    if _G.Ranax_UpdateCategory then
                                        _G.Ranax_UpdateCategory(tName)
                                    end

                                    -- Tab ikonu mikro-donus ve sicrama
                                    local tabIcon = btn:FindFirstChild("TabIcon") or btn:FindFirstChildOfClass("ImageLabel")
                                    if tabIcon then
                                        pcall(function()
                                            TweenService:Create(tabIcon, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                                                Rotation = -10
                                            }):Play()
                                            task.delay(0.18, function()
                                                TweenService:Create(tabIcon, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                                                    Rotation = 0
                                                }):Play()
                                            end)
                                        end)
                                    end
                                end)
                            end
                        end
                    end
                end)
            end

            hookInteractiveAnimations()
            task.spawn(function()
                while dash and dash.Parent do
                    hookInteractiveAnimations()
                    task.wait(1.2)
                end
            end)
        end)
    end)
end

-- ============================================================
-- WATERMARK MENU CONTROLLER (RX Butonu Silindi -> Watermarka Tiklayinca Acilir/Kapanir)
-- Menuyu kapatsan bile Watermark ekranda her zaman acik kalir!
-- Watermarka tiklayinca menu su gibi akar ve acilir/kapanir.
-- ============================================================
do
    pcall(function()
        local CoreGuiSvc = game:GetService("CoreGui")
        local UISvc = game:GetService("UserInputService")
        local TweenService = game:GetService("TweenService")

        -- Eski RX butonlarini tamamen temizle
        local oldBtn = CoreGuiSvc:FindFirstChild("TRFtapMenuToggleGui")
        if oldBtn then pcall(function() oldBtn:Destroy() end) end
        local oldRx = CoreGuiSvc:FindFirstChild("RanaxMenuToggleGui")
        if oldRx then pcall(function() oldRx:Destroy() end) end

        task.spawn(function()
            local dash, wmBar, wmHolder
            for _ = 1, 80 do
                dash = CoreGuiSvc:FindFirstChild("ModernDashboardGui")
                wmBar = dash and dash:FindFirstChild("WatermarkBar", true)
                wmHolder = dash and dash:FindFirstChild("WatermarkHolder", true)
                if dash and wmBar and wmHolder then break end
                task.wait(0.1)
            end
            if not dash or not wmBar or not wmHolder then return end

            -- ModernDashboardGui'nin kendisi kapandiginda Watermark kaybolmasin diye Enabled daima true kalir
            dash.Enabled = true
            dash:GetPropertyChangedSignal("Enabled"):Connect(function()
                if not dash.Enabled then
                    dash.Enabled = true
                end
            end)

            local wrapper = dash:FindFirstChild("Wrapper", true)

            -- Eski RanaxWMTrigger veya RanaxWMScale kalintilarini temizle (Watermark boyutunu bozmasin)
            local oldTrigger = wmBar:FindFirstChild("RanaxWMTrigger")
            if oldTrigger then pcall(function() oldTrigger:Destroy() end) end
            local oldScale = wmBar:FindFirstChild("RanaxWMScale")
            if oldScale then pcall(function() oldScale:Destroy() end) end
            local oldHolderTrigger = wmHolder:FindFirstChild("RanaxWMTrigger")
            if oldHolderTrigger then pcall(function() oldHolderTrigger:Destroy() end) end

            -- Watermark boyutunu ve yapisini orijinal kompakt haline dondur
            pcall(function()
                wmBar.Size = UDim2.new(0, 0, 1, 0)
                wmBar.AutomaticSize = Enum.AutomaticSize.X
            end)

            -- Watermarka TIKLAYINCA: Menu yumusak animasyonla acilir/kapanir, Watermark ise ASLA kapanmaz!
            local isAnimating = false
            local function toggleMenu()
                if isAnimating then return end
                isAnimating = true
                pcall(function()
                    if not wrapper then
                        wrapper = dash:FindFirstChild("Wrapper", true)
                    end
                    if not wrapper then
                        isAnimating = false
                        return
                    end

                    local contentWrapper = wrapper:FindFirstChild("ContentWrapper", true) or wrapper

                    if wrapper.Visible then
                        -- Menuyu kapat (Watermark ekranda kalir)
                        local tOut = TweenService:Create(contentWrapper, TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
                            Position = UDim2.new(0, 0, 0, 16)
                        })
                        tOut:Play()
                        tOut.Completed:Connect(function()
                            wrapper.Visible = false
                            isAnimating = false
                        end)
                    else
                        -- Menuyu ac
                        wrapper.Visible = true
                        contentWrapper.Position = UDim2.new(0, 0, 0, 16)
                        local tIn = TweenService:Create(contentWrapper, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            Position = UDim2.new(0, 0, 0, 0)
                        })
                        tIn:Play()
                        tIn.Completed:Connect(function()
                            isAnimating = false
                        end)
                    end
                end)
                task.delay(0.35, function() isAnimating = false end)
            end

            -- Watermark tiklama algilayici:
            -- wmBar veya wmHolder icine yeni obje sokmadan InputEnded ile tiklamayi yakalar.
            -- Boylece UIListLayout veya boyut asla sismez, orijinal kompakt halinde kalir.
            local pressStartPos = nil
            local pressStartTime = 0

            local function onInputBegan(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    pressStartPos = input.Position
                    pressStartTime = tick()
                end
            end

            local function onInputEnded(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    if pressStartPos then
                        local moveDist = (Vector2.new(input.Position.X, input.Position.Y) - Vector2.new(pressStartPos.X, pressStartPos.Y)).Magnitude
                        local elapsed = tick() - pressStartTime
                        pressStartPos = nil
                        -- Surukleme degilse (5 pikselden az hareket ve 0.5 saniyeden kisa tiklama)
                        if moveDist < 6 and elapsed < 0.5 then
                            toggleMenu()
                        end
                    end
                end
            end

            wmBar.InputBegan:Connect(onInputBegan)
            wmBar.InputEnded:Connect(onInputEnded)
            wmHolder.InputBegan:Connect(onInputBegan)
            wmHolder.InputEnded:Connect(onInputEnded)

            for _, child in ipairs(wmBar:GetChildren()) do
                if child:IsA("GuiObject") then
                    child.InputBegan:Connect(onInputBegan)
                    child.InputEnded:Connect(onInputEnded)
                end
            end
            wmBar.ChildAdded:Connect(function(child)
                if child:IsA("GuiObject") then
                    child.InputBegan:Connect(onInputBegan)
                    child.InputEnded:Connect(onInputEnded)
                end
            end)

            -- Sag shift tusu da ayni mantikla menuyu acar/kapatir (Watermark kapanmaz)
            UISvc.InputBegan:Connect(function(input, gpe)
                if not gpe and input.KeyCode == Enum.KeyCode.RightShift then
                    toggleMenu()
                end
            end)
        end)
    end)
end

-- ============================================================
-- MOBIL DUZELTME: telefonda menu ekranina tam oturacak sekilde
-- dinamik boyutlandirilir. Joystick ve ziplama tusu bos kalir.
-- ============================================================
do
    task.spawn(function()
        local UISvc = game:GetService("UserInputService")
        local core = game:GetService("CoreGui")
        local dash, wrapper
        for _ = 1, 60 do
            dash = core:FindFirstChild("ModernDashboardGui")
            wrapper = dash and dash:FindFirstChild("Wrapper", true)
            if wrapper then break end
            task.wait(0.1)
        end
        if not wrapper then return end

        local function applyMobileLayout(full)
            pcall(function()
                local cam = workspace.CurrentCamera
                local vp = cam and cam.ViewportSize or Vector2.new(800, 600)
                local kbHud = dash and dash:FindFirstChild("KeybindsHUD", true)
                if kbHud then kbHud.Visible = false end

                local sc = wrapper:FindFirstChildOfClass("UIScale")
                if not sc then
                    sc = Instance.new("UIScale")
                    sc.Parent = wrapper
                end

                -- Telefona gore dinamik olceklendirme
                local isSmallPhone = (vp.Y < 500 or vp.X < 900)
                local dynamicScale = isSmallPhone and math.clamp(vp.Y / 620, 0.52, 0.65) or 0.72
                sc.Scale = dynamicScale

                local scaleVal = sc.Scale
                local targetW = math.clamp((vp.X * 0.88) / scaleVal, 460, 960)
                local targetH = math.clamp((vp.Y * 0.78) / scaleVal, 340, 620)

                wrapper.Size = UDim2.new(0, targetW, 0, targetH)
                if full or not wrapper.Position then
                    wrapper.Position = UDim2.new(0.5, 0, 0.42, 0)
                end
                wrapper.Active = false
            end)
        end

        local function applyPCLayout()
            pcall(function()
                local sc = wrapper:FindFirstChildOfClass("UIScale")
                if sc then sc.Scale = 1.0 end
                wrapper.Size = UDim2.new(0, 800, 0, 520)
                wrapper.Position = UDim2.new(0.5, 0, 0.5, 0)
                wrapper.Active = true
            end)
        end

        _G.Ranax_ApplyMobileLayout = applyMobileLayout
        _G.Ranax_ApplyPCLayout = applyPCLayout

        if _G.Ranax_SelectedLayout == "mobile" or UISvc.TouchEnabled then
            applyMobileLayout(true)
            task.spawn(function()
                while wrapper.Parent and (_G.Ranax_SelectedLayout == "mobile" or UISvc.TouchEnabled) do
                    applyMobileLayout(false)
                    task.wait(2)
                end
            end)
        else
            applyPCLayout()
        end

        local cam = workspace.CurrentCamera
        if cam then
            cam:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                if _G.Ranax_SelectedLayout == "mobile" or UISvc.TouchEnabled then
                    applyMobileLayout(false)
                end
            end)
        end
    end)
end




