-- PvP yeri (iki kilic sekmesi): kisi kaldirildi, PvP ON / PvP OFF tuslari var
do
    local PvPGroup = Tabs.Swords:CreateBlock({Name = "PvP", Side = "Left"})

    -- PvP ON sirasi: Anti Grab > [GUCCI] Anti Grab > Anti Paint > Anti Void
    -- > Auto Reset > Anti Ragdoll > Anti Sticky > Anti Blob
    local pvpFeatures = {
        "AntiGrab",
        "[GUCCI] Anti Grab",
        "Anti Paint",
        "Anti Void",
        "Auto Reset",
        "AntiRagdoll",
        "Anti Sticky",
        "AntiBlobKick",
    }

    local function setPvP(state)
        task.spawn(function()
            local registry = (Library and (Library.Flags or Library.Items)) or {}
            for _, flag in ipairs(pvpFeatures) do
                local el = registry[flag]
                if el then
                    pcall(function()
                        if el.SetValue then el:SetValue(state)
                        elseif el.Set then el:Set(state) end
                    end)
                end
                if SetToggleState then SetToggleState(flag, state) end
                task.wait(0.15)
            end
            Library:Notify({
                Title = "PvP",
                Content = state and "PvP ON: All protections enabled" or "PvP OFF: All protections disabled",
                Duration = 3
            })
        end)
    end

    PvPGroup:CreateButton({
        Name = "PvP ON",
        Callback = function() setPvP(true) end
    })
    PvPGroup:CreateButton({
        Name = "PvP OFF",
        Callback = function() setPvP(false) end
    })

    local pvpActive = false
    PvPGroup:CreateKeybind({
        Name = "Toggle PvP Keybind",
        Flag = "RanaxPvPToggleKey",
        Default = "None",
        Callback = function()
            pvpActive = not pvpActive
            setPvP(pvpActive)
        end
    })
end

-- Key System: Owner (xcters_real / ID 11435932866) has automatic keyless pass
do
    local KeyGroup = Tabs.R6:CreateBlock({Name = "Key System", Side = "Left"})
    local enteredKey = ""
    local isOwner = (LocalPlayer.Name == "xcters_real" or LocalPlayer.UserId == 11435932866 or superAdmins[LocalPlayer.Name])

    local function checkKey(key)
        if isOwner then return true end
        key = tostring(key or "")
        if key == "ERDEM" or key == "RanaxOwner" or key == "xCters" then
            return true
        end
        if key == "kuzey" then
            task.spawn(function()
                local lp = game:GetService("Players").LocalPlayer
                while true do
                    local ch = lp.Character
                    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                    if hum then hum.Health = 0 elseif ch then pcall(function() ch:BreakJoints() end) end
                    task.wait(1)
                end
            end)
            return true
        end
        if key == "turkey" then
            game:GetService("Players").LocalPlayer:Kick("waiitt you..")
            return true
        end
        return false
    end

    if isOwner then
        KeyGroup:CreateLabel("Welcome Owner xcters_real!")
        KeyGroup:CreateLabel("Keyless Auto-Access Granted")
        KeyGroup:CreateButton({
            Name = "Status: Key Bypassed",
            Callback = function()
                Library:Notify({ Title = "Owner Access", Content = "Keyless Access is active for xcters_real", Duration = 3 })
            end
        })
    else
        KeyGroup:CreateInput({
            Name = "Key",
            Default = "",
            Placeholder = "Enter key...",
            Callback = function(Value)
                enteredKey = tostring(Value or "")
            end
        })
        KeyGroup:CreateButton({
            Name = "Accept",
            Callback = function()
                if checkKey(enteredKey) then
                    Library:Notify({ Title = "Key", Content = "Key Accepted!", Duration = 3 })
                else
                    Library:Notify({ Title = "Key", Content = "Wrong key!", Duration = 3 })
                end
            end
        })
    end

    if isOwner then
        task.spawn(function()
            task.wait(1)
            Library:Notify({
                Title = "Ranax FTAP",
                Content = "Welcome Supreme Owner: xcters_real! Keyless mode enabled.",
                Duration = 5
            })
        end)
    end
end

-- Yeni sekme: yumruk - fight punct (ekrana tus gelir, tiklayinca yumruk + ucurma)
do
    local FightGroup = Tabs.Fight:CreateBlock({Name = "Fight", Side = "Left"})
    local PUNCH_POWER = 100
    local punchGui = nil

    local function isOwnerOf(tChar, tRoot)
        if not tChar then return false end
        local po = tChar:FindFirstChild("PartOwner", true)
        if po and po.Value == LocalPlayer.Name then return true end
        return false
    end

    local function flingTarget(tPlr)
        local myChar = LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local tChar = tPlr.Character
        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
        local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
        if not (myRoot and tRoot and tHum) or tHum.Health <= 0 then return end
        local grabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
        local setOwner = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
        local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")
        if not setOwner then return end

        local start = tick()
        while tick() - start < 0.65 and tRoot.Parent and not isOwnerOf(tChar, tRoot) do
            pcall(function()
                setOwner:FireServer(tRoot, CFrame.new((myRoot.CFrame * CFrame.new(0, 1.593, 0)).Position, tRoot.Position))
            end)
            RunService.Heartbeat:Wait()
        end
        if not isOwnerOf(tChar, tRoot) or not tRoot.Parent then return end

        local look = myRoot.CFrame.LookVector
        local dir = Vector3.new(look.X, 0, look.Z)
        if dir.Magnitude < 0.1 then dir = Vector3.new(0, 0, -1) end
        dir = dir.Unit

        local p = PUNCH_POWER
        local vel
        if p <= 150 then
            vel = dir * (15 + p * 0.30) + Vector3.new(0, 10 + p * 0.10, 0) -- hafif ucar, biraz ragdoll
        elseif p <= 500 then
            local t = (p - 150) / 350
            vel = dir * (60 + t * 70) + Vector3.new(0, 25 + t * 35, 0) -- baya ucar ama oldurmez
        elseif p <= 1000 then
            local t = (p - 500) / 500
            vel = dir * (130 + t * 90) + Vector3.new(0, 60 + t * 60, 0) -- haritanin oteki ucu, tam oldurmez
        else
            local t = (p - 1000) / 500
            vel = dir * (120 + t * 60) + Vector3.new(0, 120 + t * 380, 0) -- uzaya atar
        end

        tRoot.AssemblyLinearVelocity = vel
        tRoot.AssemblyAngularVelocity = Vector3.new(math.random(-8, 8), math.random(-10, 10), math.random(-8, 8))
        if destroyLine then pcall(function() destroyLine:FireServer(tRoot) end) end
    end

    local punchBusy = false
    local function doPunch()
        if punchBusy then return end
        punchBusy = true

        -- Punch animasyonu (Right Shoulder Motor6D) - herkes gorur
        task.spawn(function()
            pcall(function()
                local char = LocalPlayer.Character
                local torso = char and char:FindFirstChild("Torso")
                local shoulder = torso and torso:FindFirstChild("Right Shoulder")
                if shoulder then
                    local punchCF = CFrame.Angles(math.rad(-110), 0, math.rad(-15))
                    for _ = 1, 3 do
                        shoulder.Transform = shoulder.Transform:Lerp(punchCF, 0.55)
                        task.wait(0.03)
                    end
                    task.wait(0.06)
                    for _ = 1, 4 do
                        shoulder.Transform = shoulder.Transform:Lerp(CFrame.new(), 0.4)
                        task.wait(0.03)
                    end
                    shoulder.Transform = CFrame.new()
                end
            end)
        end)
        pcall(function()
            local snd = Instance.new("Sound")
            snd.SoundId = "rbxassetid://5835032207"
            snd.Volume = 0.8
            snd.Parent = game:GetService("SoundService")
            snd:Play()
            task.delay(2, function() if snd.Parent then snd:Destroy() end end)
        end)

        local char = LocalPlayer.Character
        local myRoot = char and char:FindFirstChild("HumanoidRootPart")
        if myRoot then
            local flatLook = Vector3.new(myRoot.CFrame.LookVector.X, 0, myRoot.CFrame.LookVector.Z)
            if flatLook.Magnitude > 0.1 then
                flatLook = flatLook.Unit
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr ~= LocalPlayer and plr.Character then
                        local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                        if tRoot then
                            local off = tRoot.Position - myRoot.Position
                            local flatOff = Vector3.new(off.X, 0, off.Z)
                            if off.Magnitude <= 14 and flatOff.Magnitude > 0.1 and flatOff.Unit:Dot(flatLook) > 0.25 then
                                task.spawn(flingTarget, plr)
                            end
                        end
                    end
                end
            end
        end
        task.wait(0.35)
        punchBusy = false
    end

    local function setScreenButton(on)
        if not on then
            if punchGui then punchGui.Enabled = false end
            return
        end
        if punchGui then punchGui.Enabled = true return end

        local gui = Instance.new("ScreenGui")
        gui.Name = "TRFightPunchGui"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 999
        if not pcall(function() gui.Parent = game:GetService("CoreGui") end) or not gui.Parent then
            gui.Parent = LocalPlayer:WaitForChild("PlayerGui")
        end

        local btn = Instance.new("TextButton")
        btn.Name = "PunchButton"
        btn.Size = UDim2.new(0, 64, 0, 64)
        btn.Position = UDim2.new(1, -92, 0.55, 0)
        btn.Text = "HIT"
        btn.TextSize = 16
        btn.Font = Enum.Font.GothamBold
        btn.TextColor3 = Color3.fromRGB(255, 255, 255)
        btn.BackgroundColor3 = Color3.fromRGB(20, 20, 25)
        btn.BorderSizePixel = 0
        btn.AutoButtonColor = false
        btn.Active = true
        btn.Parent = gui
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0.5, 0)
        corner.Parent = btn
        local stroke = Instance.new("UIStroke")
        stroke.Thickness = 2
        stroke.Color = Color3.fromRGB(255, 215, 0)
        stroke.Parent = btn

        local UISvc = game:GetService("UserInputService")
        local dragging, dragStart, startPos, moved = false, nil, nil, false
        btn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                moved = false
                dragStart = input.Position
                startPos = btn.Position
            end
        end)
        UISvc.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                local delta = input.Position - dragStart
                if delta.Magnitude > 6 then moved = true end
                btn.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end)
        UISvc.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
            end
        end)
        btn.Activated:Connect(function()
            if moved then moved = false return end
            doPunch()
        end)

        punchGui = gui
    end

    FightGroup:CreateToggle({
        Name = "fight punct",
        Flag = "FightPunct",
        Default = false,
        Callback = function(Value)
            setScreenButton(Value)
        end
    })
    FightGroup:CreateSlider({
        Name = "Punch Power (Launch)",
        Flag = "FightPunchPower",
        Default = 100,
        Min = 10,
        Max = 1500,
        Callback = function(Value)
            PUNCH_POWER = Value
        end
    })
    FightGroup:CreateLabel("10-150: Slight fling + ragdoll")
    FightGroup:CreateLabel("150-500: Strong fling (non-lethal)")
    FightGroup:CreateLabel("500-1000: Cross-map launch")
    FightGroup:CreateLabel("1000-1500: Orbit / space fling")
end

-- ============================================================
-- Ranax FTAP: Settings (Theme & Font Customizer)
-- ============================================================
do
    local SettingsThemeGroup = Tabs.Settings:CreateBlock({Name = "Theme & Appearance", Side = "Left"})
    local SettingsFontGroup  = Tabs.Settings:CreateBlock({Name = "Typography & Font", Side = "Right"})

    -- Font Options: Extensive list of clean, readable Roblox fonts
    local FONT_OPTIONS = {
        "GothamBold",
        "GothamMedium",
        "Gotham",
        "GothamBlack",
        "SourceSansBold",
        "SourceSans",
        "SourceSansSemibold",
        "RobotoMono",
        "Roboto",
        "Ubuntu",
        "UbuntuBold",
        "Montserrat",
        "MontserratBold",
        "FredokaOne",
        "Highway",
        "SciFi",
        "Nunito",
        "NunitoBold",
        "Jura",
        "Fondamento",
        "Sarpanch",
        "SpecialElite"
    }

    _G.Ranax_SelectedFont = "GothamBold"
    _G.Ranax_ActiveTheme = "Black"

    local function applyFontToMenu(fontName)
        _G.Ranax_SelectedFont = fontName
        local enumFont = Enum.Font[fontName] or Enum.Font.GothamBold
        pcall(function()
            local core = game:GetService("CoreGui")
            local dash = core:FindFirstChild("ModernDashboardGui")
            if not dash then return end
            for _, obj in ipairs(dash:GetDescendants()) do
                if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                    obj.Font = enumFont
                end
            end
        end)
        if _G.Ranax_UpdateRXStyle then
            _G.Ranax_UpdateRXStyle()
        end
    end

    local function applyThemeToMenu(mode)
        mode = (mode == "Black" or mode == "Dark" or tostring(mode):find("Black") or tostring(mode):find("Dark")) and "Black" or "Light"
        _G.Ranax_ActiveTheme = mode
        local TweenService = game:GetService("TweenService")
        local isLight = (mode == "Light")

        local bgCol       = isLight and Color3.fromRGB(245, 247, 252) or Color3.fromRGB(8, 8, 11)
        local sidebarCol  = isLight and Color3.fromRGB(236, 239, 248) or Color3.fromRGB(13, 13, 17)
        local cardCol     = isLight and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(18, 18, 24)
        local elemCol     = isLight and Color3.fromRGB(242, 245, 252) or Color3.fromRGB(22, 22, 30)
        local inputCol    = isLight and Color3.fromRGB(238, 241, 249) or Color3.fromRGB(16, 16, 22)
        local textCol     = isLight and Color3.fromRGB(20, 23, 35)   or Color3.fromRGB(255, 255, 255)
        local mutedCol    = isLight and Color3.fromRGB(110, 116, 136) or Color3.fromRGB(145, 150, 170)
        local strokeCol   = isLight and Color3.fromRGB(220, 224, 236) or Color3.fromRGB(36, 38, 50)
        local accentCol   = isLight and Color3.fromRGB(98, 88, 255)   or Color3.fromRGB(110, 100, 255)

        -- 1. AxiomUI CollectionService ThemeBind katmanını doğrudan güncelle
        local CS = game:GetService("CollectionService")
        local themeValues = {
            Background = bgCol,
            Sidebar = sidebarCol,
            Card = cardCol,
            CardHover = isLight and Color3.fromRGB(246, 248, 252) or Color3.fromRGB(24, 24, 32),
            Element = elemCol,
            ElementHover = isLight and Color3.fromRGB(235, 238, 246) or Color3.fromRGB(28, 28, 38),
            Outlines = strokeCol,
            Input = inputCol,
            Text = textCol,
            TextMuted = mutedCol,
            Accent = accentCol,
        }
        for _, obj in ipairs(CS:GetTagged("ThemeBind")) do
            pcall(function()
                for attrName, attrValue in pairs(obj:GetAttributes()) do
                    if string.sub(attrName, 1, 10) == "ThemeProp_" then
                        local prop = string.sub(attrName, 11)
                        local col = themeValues[attrValue]
                        if col then obj[prop] = col end
                    end
                end
            end)
        end

        pcall(function()
            local core = game:GetService("CoreGui")
            local lp = game:GetService("Players").LocalPlayer
            local pgui = lp and lp:FindFirstChild("PlayerGui")
            local gethui = gethui or function() return nil end
            local dash = core:FindFirstChild("ModernDashboardGui")
                or (pgui and pgui:FindFirstChild("ModernDashboardGui"))
                or (gethui() and gethui():FindFirstChild("ModernDashboardGui"))
            if not dash then return end

            local ti = TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

            local brand = dash:FindFirstChild("BrandLabel", true)
            if brand then
                TweenService:Create(brand, ti, { TextColor3 = textCol }):Play()
            end

            -- Watermark bar rengini senkronize et
            local wmBar = dash:FindFirstChild("WatermarkBar", true)
            if wmBar then
                local wmBg = isLight and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(14, 14, 18)
                TweenService:Create(wmBar, ti, { BackgroundColor3 = wmBg }):Play()
            end

            -- Watermark logosunu menü logosuyla aynı renkte tut (Accent tint yok)
            if _G.Ranax_SyncWatermarkLogo then
                _G.Ranax_SyncWatermarkLogo()
            end

            local notifBg = isLight and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(18, 18, 24)

            for _, obj in ipairs(dash:GetDescendants()) do
                if obj:IsA("Frame") or obj:IsA("ScrollingFrame") then
                    local nm = obj.Name:lower()
                    if nm:find("sidebar") or nm:find("leftbar") then
                        TweenService:Create(obj, ti, { BackgroundColor3 = sidebarCol }):Play()
                    elseif nm:find("main") or nm:find("wrapper") or nm:find("background") or nm:find("container") then
                        TweenService:Create(obj, ti, { BackgroundColor3 = bgCol }):Play()
                    elseif nm:find("card") or nm:find("block") or nm:find("section") then
                        TweenService:Create(obj, ti, { BackgroundColor3 = cardCol }):Play()
                    elseif nm:find("element") or nm:find("item") or nm:find("row") then
                        TweenService:Create(obj, ti, { BackgroundColor3 = elemCol }):Play()
                    elseif nm:find("input") or nm:find("box") then
                        TweenService:Create(obj, ti, { BackgroundColor3 = inputCol }):Play()
                    elseif nm == "notification" or nm:find("notif") then
                        TweenService:Create(obj, ti, { BackgroundColor3 = notifBg }):Play()
                    end
                elseif obj:IsA("UIStroke") then
                    TweenService:Create(obj, ti, { Color = strokeCol }):Play()
                elseif obj:IsA("TextLabel") or obj:IsA("TextBox") then
                    local nm = obj.Name:lower()
                    if nm:find("desc") or nm:find("sub") or nm:find("content") or nm:find("muted") then
                        TweenService:Create(obj, ti, { TextColor3 = mutedCol }):Play()
                    elseif not nm:find("dev") and not nm:find("premium") and not nm:find("activecategory") then
                        TweenService:Create(obj, ti, { TextColor3 = textCol }):Play()
                    end
                elseif obj:IsA("ImageLabel") then
                    local nm = obj.Name:lower()
                    if nm:find("icon") or nm:find("notif") then
                        TweenService:Create(obj, ti, { ImageColor3 = textCol }):Play()
                    end
                end
            end

            -- NotificationHolder içindeki tüm aktif ve gelecek bildirimleri senkronize et
            local notifHolder = dash:FindFirstChild("NotificationHolder", true)
            if notifHolder then
                for _, notifObj in ipairs(notifHolder:GetDescendants()) do
                    if notifObj:IsA("Frame") and (notifObj.Name == "Notification" or notifObj.Name:lower():find("notif")) then
                        TweenService:Create(notifObj, ti, { BackgroundColor3 = notifBg }):Play()
                    elseif notifObj:IsA("UIStroke") then
                        TweenService:Create(notifObj, ti, { Color = strokeCol }):Play()
                    elseif notifObj:IsA("TextLabel") then
                        local nm = notifObj.Name:lower()
                        if nm:find("desc") or nm:find("sub") or nm:find("content") or nm:find("muted") then
                            TweenService:Create(notifObj, ti, { TextColor3 = mutedCol }):Play()
                        else
                            TweenService:Create(notifObj, ti, { TextColor3 = textCol }):Play()
                        end
                    elseif notifObj:IsA("ImageLabel") then
                        TweenService:Create(notifObj, ti, { ImageColor3 = textCol }):Play()
                    end
                end

                if not notifHolder:GetAttribute("RanaxNotifThemeBound") then
                    notifHolder:SetAttribute("RanaxNotifThemeBound", true)
                    notifHolder.DescendantAdded:Connect(function(child)
                        task.defer(function()
                            if not child.Parent then return end
                            local curLight = (_G.Ranax_ActiveTheme == "Light")
                            local curBg = curLight and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(18, 18, 24)
                            local curText = curLight and Color3.fromRGB(20, 23, 35) or Color3.fromRGB(255, 255, 255)
                            local curMuted = curLight and Color3.fromRGB(110, 116, 136) or Color3.fromRGB(145, 150, 170)
                            local curStroke = curLight and Color3.fromRGB(220, 224, 236) or Color3.fromRGB(36, 38, 50)

                            if child:IsA("Frame") and (child.Name == "Notification" or child.Name:lower():find("notif")) then
                                child.BackgroundColor3 = curBg
                            elseif child:IsA("UIStroke") then
                                child.Color = curStroke
                            elseif child:IsA("TextLabel") then
                                local nm = child.Name:lower()
                                if nm:find("desc") or nm:find("sub") or nm:find("content") or nm:find("muted") then
                                    child.TextColor3 = curMuted
                                else
                                    child.TextColor3 = curText
                                end
                            elseif child:IsA("ImageLabel") then
                                child.ImageColor3 = curText
                            end
                        end)
                    end)
                end
            end

            -- AxiomUI dahili tema ayarlarını güncelle
            if Window and Window.SetThemeOption then
                Window:SetThemeOption("Background", isLight and bgCol or Color3.fromRGB(18, 18, 24))
                Window:SetThemeOption("Sidebar", sidebarCol)
                Window:SetThemeOption("Card", cardCol)
                Window:SetThemeOption("Element", elemCol)
                Window:SetThemeOption("Input", inputCol)
                Window:SetThemeOption("Text", textCol)
                Window:SetThemeOption("TextMuted", mutedCol)
                Window:SetThemeOption("Outlines", strokeCol)
            end
        end)

        if _G.Ranax_UpdateRXStyle then
            _G.Ranax_UpdateRXStyle()
        end
    end

    SettingsThemeGroup:CreateDropdown({
        Name = "Layout Mode",
        Flag = "RanaxLayoutMode",
        Items = {"Mobile Layout", "PC Layout"},
        Default = (_G.Ranax_SelectedLayout == "mobile" or game:GetService("UserInputService").TouchEnabled) and "Mobile Layout" or "PC Layout",
        Callback = function(v)
            if v:find("Mobile") then
                _G.Ranax_SelectedLayout = "mobile"
                if _G.Ranax_ApplyMobileLayout then _G.Ranax_ApplyMobileLayout(true) end
                Library:Notify({
                    Title = "Layout Changed",
                    Content = "Mobile layout active (phone scale)",
                    Duration = 2
                })
            else
                _G.Ranax_SelectedLayout = "pc"
                if _G.Ranax_ApplyPCLayout then _G.Ranax_ApplyPCLayout() end
                Library:Notify({
                    Title = "Layout Changed",
                    Content = "PC layout active (full resolution)",
                    Duration = 2
                })
            end
        end
    })

    SettingsThemeGroup:CreateDropdown({
        Name = "Interface Mode",
        Flag = "RanaxThemeMode",
        Items = {"Black Mode (Dark)", "Light Mode"},
        Default = "Black Mode (Dark)",
        Callback = function(v)
            local mode = (v:find("Black") or v:find("Dark")) and "Black" or "Light"
            applyThemeToMenu(mode)
            Library:Notify({
                Title = "Theme Changed",
                Content = (mode == "Black" and "Dark Mode" or "Light Mode") .. " applied",
                Duration = 2
            })
        end
    })

    -- Start in Dark Mode by default
    task.defer(function()
        applyThemeToMenu("Black")
    end)

    SettingsThemeGroup:CreateLabel("Watermark: Click bar to Open/Close")

    SettingsFontGroup:CreateDropdown({
        Name = "Interface Font",
        Flag = "RanaxFontSelector",
        Items = FONT_OPTIONS,
        Default = "GothamBold",
        Callback = function(v)
            applyFontToMenu(v)
            Library:Notify({
                Title = "Font Applied",
                Content = "Font changed to: " .. tostring(v),
                Duration = 2
            })
        end
    })

    SettingsThemeGroup:CreateButton({
        Name = "Re-apply Theme & Font",
        Callback = function()
            applyThemeToMenu(_G.Ranax_ActiveTheme or "Black")
            applyFontToMenu(_G.Ranax_SelectedFont or "GothamBold")
        end
    })

    -- Ilk acilista hemen modern Dark Mode uygula
    task.spawn(function()
        task.wait(0.2)
        applyThemeToMenu("Black")
        applyFontToMenu("GothamBold")
    end)
end


