-- FAST MISSILE (Main): only while the grabbed object is a missile.
-- Throw power is forced to FastMissilePower (default 500); right-click release launches it instantly.
FastMissileEnabled = false
FastMissilePower = 500

function isMissilePart(part)
    local cur = part
    while cur and cur ~= workspace do
        if cur.Name:find("Missile") then return true end
        cur = cur.Parent
    end
    return false
end

do
    local UIS = game:GetService("UserInputService")
    local Debris = game:GetService("Debris")
    local fastMissileConn = nil

    local function onGrabParts(model)
        if not FastMissileEnabled or model.Name ~= "GrabParts" then return end
        local grabPart = model:WaitForChild("GrabPart", 1)
        local weld = grabPart and grabPart:WaitForChild("WeldConstraint", 1)
        local part1 = weld and weld.Part1
        if not (part1 and isMissilePart(part1)) then return end

        model:GetPropertyChangedSignal("Parent"):Connect(function()
            if model.Parent or not FastMissileEnabled then return end
            local rmb = UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
                or UIS:GetLastInputType() == Enum.UserInputType.MouseButton2
            if not rmb or not part1.Parent then return end

            local dir = workspace.CurrentCamera.CFrame.LookVector
            local old = part1:FindFirstChild("FastMissileBV")
            if old then old:Destroy() end
            local bv = Instance.new("BodyVelocity")
            bv.Name = "FastMissileBV"
            bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
            bv.Velocity = dir * FastMissilePower
            bv.Parent = part1
            part1.AssemblyLinearVelocity = dir * FastMissilePower
            Debris:AddItem(bv, 1)
        end)
    end

    MainL:CreateToggle({
        Name = "Fast Missile",
        Flag = "FastMissile",
        Default = false,
        Tooltip = "Only when you are holding a missile: throw power becomes 500 and right-click launches it instantly.",
        Callback = function(v)
            FastMissileEnabled = v
            if v then
                if not fastMissileConn then
                    fastMissileConn = workspace.ChildAdded:Connect(onGrabParts)
                end
            elseif fastMissileConn then
                fastMissileConn:Disconnect()
                fastMissileConn = nil
            end
        end
    })

    MainL:CreateSlider({
        Name = "Fast Missile Power",
        Flag = "FastMissilePower",
        Default = 500,
        Min = 50,
        Max = 3000,
        Rounding = 0,
        Callback = function(v)
            FastMissilePower = v
        end
    })
end

