local DefenseGroup = Tabs.Defense:CreateBlock({Name = "Defense Main", Side = "Left"})

-- ============================================================================
-- ANTI-SHAKE & TOUCH IMMUNITY (Zero impulse, zero tilt, zero screen shake)
-- ============================================================================
local TouchImmunityActive = false
local touchImmunityConn = nil

local function updateTouchImmunity()
    if TouchImmunityActive then
        if not touchImmunityConn then
            touchImmunityConn = RunService.Stepped:Connect(function()
                if not TouchImmunityActive then return end
                local myChar = LocalPlayer.Character
                local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")

                if myHum then
                    pcall(function()
                        myHum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
                        myHum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
                    end)
                end
                if myHRP then
                    -- Stabilize upright orientation: eliminate collision wobble and tilt
                    local av = myHRP.AssemblyAngularVelocity
                    if math.abs(av.X) > 0.05 or math.abs(av.Z) > 0.05 then
                        myHRP.AssemblyAngularVelocity = Vector3.new(0, av.Y, 0)
                    end
                end

                -- Make all other players pass through without applying collision impulses
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer and p.Character then
                        for _, part in ipairs(p.Character:GetChildren()) do
                            if part:IsA("BasePart") then
                                if part.CanCollide then
                                    part.CanCollide = false
                                end
                                if part.CanTouch then
                                    part.CanTouch = false
                                end
                            end
                        end
                    end
                end
            end)
        end
    else
        if touchImmunityConn then
            touchImmunityConn:Disconnect()
            touchImmunityConn = nil
        end
    end
end

DefenseGroup:CreateToggle({
