    Callback = function(val)
        TouchImmunityActive = val
        updateTouchImmunity()
        if notify then
            notify("Defense", val and "Touch Immunity: ACTIVE (No-Shake)" or "Touch Immunity: OFF", 1.5)
        end
    end
})
