local antiGrabExplosionConn, antiGrabHeldConn, antiGrabStruggleConn, antiGrabHumConn, antiGrabAnchorConn
local antiGrabRootCF, antiGrabRootPos, antiGrabHardFreeze = nil, nil, false
local function antiGrabUnfreeze(char)
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if hrp then
		hrp.Anchored = false
		if hrp:FindFirstChild("FreezeJoint") then
			hrp.FreezeJoint:Destroy()
		end
	end
	antiGrabHardFreeze = false
	if antiGrabAnchorConn then
		antiGrabAnchorConn:Disconnect()
		antiGrabAnchorConn = nil
	end
end
function antiGrabFreezeInPlace(char)
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end
	antiGrabRootCF = hrp.CFrame
	antiGrabRootPos = hrp.Position
	antiGrabHardFreeze = true
	if not hrp:FindFirstChild("FreezeJoint") then
		local align = Instance.new("AlignPosition")
		align.Name = "FreezeJoint"
		align.Mode = Enum.PositionAlignmentMode.OneAttachment
		align.MaxForce = 1e6
		align.MaxVelocity = 0
		align.Responsiveness = 200
		local att = Instance.new("Attachment", hrp)
		align.Attachment0 = att
		align.Position = antiGrabRootPos
		align.Parent = hrp
	end
	antiGrabAnchorConn = R.Heartbeat:Connect(function()
		if antiGrabHardFreeze and hrp then
			hrp.AssemblyLinearVelocity = Vector3.zero
			hrp.AssemblyAngularVelocity = Vector3.zero
			hrp.CFrame = antiGrabRootCF
		end
	end)
end
function antiGrabReconnect()
	local char = Player.Character or Player.CharacterAdded:Wait()
	local hum = char:WaitForChild("Humanoid")
	local hrp = char:WaitForChild("HumanoidRootPart")
	local fp = hrp:FindFirstChild("FirePlayerPart")
	if fp then
		fp:Destroy()
	end
	if antiGrabHumConn then
		antiGrabHumConn:Disconnect()
	end
	antiGrabHumConn = hum.Changed:Connect(function(p)
		if p == "Sit" and hum.Sit then
			if not (hum.SeatPart and tostring(hum.SeatPart.Parent) == "CreatureBlobman") then
				hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
				hum.Sit = false
			end
		end
	end)
end
do
    local Players = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local ContextActionService = game:GetService("ContextActionService")
    local LocalPlayer = Players.LocalPlayer

    -- Localized state management (replaces getgenv and ACGE)
    local antiGrabActive = false
    local antiGrabConnection = nil
    local spawnTick = nil

    DefenseGroup:CreateToggle({
        Name = "Seatless Gucci (Anti Grab)",
        Flag = "SeatlessGucciAntiGrab",
        Default = false,
        Callback = function(Value)
            if SetToggleState then SetToggleState("SeatlessGucciAntiGrab", Value) end
            antiGrabActive = Value

            if Value then
                if not antiGrabConnection then
                    antiGrabConnection = RunService.RenderStepped:Connect(function()
                        if not antiGrabActive then return end
                        
                        local char = LocalPlayer.Character
                        if not char then return end

                        local hum = char:FindFirstChild("Humanoid")
                        local root = char:FindFirstChild("HumanoidRootPart")
                        local myToys = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                        local ocarina = myToys and myToys:FindFirstChild("InstrumentWoodwindOcarina")
                        
                        if ocarina then
                            -- Check if we are currently being grabbed
                            for _, prt in ipairs(char:GetChildren()) do
                                local owner = prt:FindFirstChild("PartOwner")
                                if owner and owner.Value ~= "" then
                                    local holdPart = ocarina:FindFirstChild("HoldPart")
                                    local holdFunc = holdPart and holdPart:FindFirstChild("HoldItemRemoteFunction")
                                    
                                    if holdFunc then
                                        task.spawn(function()
                                            pcall(function() holdFunc:InvokeServer(ocarina, char) end)
                                        end)

                                        local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
                                        local destroyToy = menuToys and menuToys:FindFirstChild("DestroyToy")
                                        if destroyToy then
                                            pcall(function() destroyToy:FireServer(ocarina) end)
                                        end
                                        
                                        if hum then
                                            hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                                            hum.AutoRotate = true
                                            if hum.Sit then
                                                hum.Sit = false
                                            end
                                        end

                                        pcall(function()
                                            ContextActionService:UnbindAction("Escape")
                                            ContextActionService:UnbindAction("JumpRemover")
                                        end)
                                        
                                        owner.Value = ""
                                    end
                                end
                            end
                        else
                            -- Spawn logic if Ocarina doesn't exist
                            local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
                            if canSpawn and canSpawn.Value and not spawnTick then
                                spawnTick = tick()
                                task.spawn(function()
                                    local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
                                    local spawnFunc = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction")
                                    if spawnFunc then
                                        pcall(function()
                                            spawnFunc:InvokeServer(
                                                "InstrumentWoodwindOcarina",
                                                CFrame.new(1e5, 1e5, 1e5),
                                                Vector3.zero
                                            )
                                        end)
                                    end
                                end)
                            elseif spawnTick and tick() - spawnTick > 1 and not (myToys and myToys:FindFirstChild("InstrumentWoodwindOcarina")) then
                                spawnTick = nil
                            end

                            -- Grab escape fallback
                            local grabbed = false
                            for _, prt in ipairs(char:GetChildren()) do
                                local owner = prt:FindFirstChild("PartOwner")
                                if owner and owner.Value ~= "" then
                                    grabbed = true
                                    break
                                end
                            end

                            if grabbed then
                                local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
                                if charEvents then
                                    local struggle = charEvents:FindFirstChild("Struggle")
                                    local ragdollRemote = charEvents:FindFirstChild("RagdollRemote")
                                    
                                    if struggle then pcall(function() struggle:FireServer(LocalPlayer) end) end
                                    if ragdollRemote and root then pcall(function() ragdollRemote:FireServer(root, 0) end) end
                                end
                                
                                if hum and type(stopOcarinaAnim) == "function" then
                                    pcall(stopOcarinaAnim, hum)
                                end
                            end
                        end

                        if hum and type(stopOcarinaAnim) == "function" then
                            pcall(stopOcarinaAnim, hum)
                        end
                    end)
                end
            else
                if antiGrabConnection then
                    antiGrabConnection:Disconnect()
                    antiGrabConnection = nil
                end
            end
        end
    })
end
local autoStruggleConn = nil
local AntiGrabEnabled = false
local HeldConnection = nil

do
    local RunService = game:GetService("RunService")
    local ContextActionService = game:GetService("ContextActionService")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local AntiGrab = false
    local AntiGrabType = "Normal" -- "Normal", "No Ragdoll", "Anti-Kill", "Escapes Anything, but buggy"
    local AntiGrabActive = false
    local AntiGrabConnection = nil
    local AntiGrabListeners = {}

    local LimbOffsetsRL = {
        Head = CFrame.new(0, 1.5, 0),
        ["Left Arm"] = CFrame.new(-1.5, 0, 0),
        ["Right Arm"] = CFrame.new(1.5, 0, 0),
        ["Left Leg"] = CFrame.new(-0.5, -2, 0),
        ["Right Leg"] = CFrame.new(0.5, -2, 0),
        Torso = CFrame.new(),
    }

    local LightPhysicalProperties = PhysicalProperties.new(0.01, 0.01, 0.01, 0.01, 0.01)

    local function ResetVelocity(part)
        if not part or not part:IsA("BasePart") then return false end
        if part.AssemblyAngularVelocity ~= Vector3.zero then
            part.AssemblyAngularVelocity = Vector3.zero
        end
        if part.AssemblyLinearVelocity ~= Vector3.zero then
            part.AssemblyLinearVelocity = Vector3.zero
        end
        return true
    end

    local function ToggleCollisions(char, canCollide)
        if canCollide == nil then canCollide = false end
        if not char then return end
        for _, child in pairs(char:GetChildren()) do
            if child:IsA("BasePart") then
                local shouldCollide
                if canCollide then
                    shouldCollide = (child.Name == "Torso" or child.Name == "Head")
                else
                    shouldCollide = false
                end
                if child.CanCollide ~= shouldCollide then
                    child.CanCollide = shouldCollide
                end
                if not canCollide then
                    local ragdollLimbPart = child:FindFirstChild("RagdollLimbPart")
                    if ragdollLimbPart and ragdollLimbPart.CanCollide then
                        ragdollLimbPart.CanCollide = false
                    end
                end
                if child.Name ~= "HumanoidRootPart" and child.CustomPhysicalProperties ~= LightPhysicalProperties then
                    child.CustomPhysicalProperties = LightPhysicalProperties
                end
            end
        end
    end

    local function RepositionLimbs(char, resetVel)
        if not char then return end
        local humanoidRootPart = char:FindFirstChild("HumanoidRootPart")
        local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
        if not humanoidRootPart or not torso then return end
        local neck = torso:FindFirstChild("Neck")
        if neck and neck.Enabled then return end
        local lookVector = humanoidRootPart.CFrame.LookVector
        local vector = Vector3.new(lookVector.X, 0, lookVector.Z)
        if vector.Magnitude < 0.001 then return end
        local baseCF = CFrame.lookAt(humanoidRootPart.Position, humanoidRootPart.Position + vector.Unit)
        for limbName, offset in pairs(LimbOffsetsRL) do
            local limb = char:FindFirstChild(limbName)
            if limb and limb:IsA("BasePart") then
                local targetCF = baseCF * offset
                if limb.CFrame ~= targetCF then
                    limb.CFrame = targetCF
                end
                if resetVel then
                    ResetVelocity(limb)
                end
            end
        end
    end

    local isEscaping = false
    local function ExtraEscape()
        local char = LocalPlayer.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hum or not hrp or hum.Health <= 0 or isEscaping then return end
        local inPlot = LocalPlayer:FindFirstChild("InPlot")
        if inPlot and inPlot.Value then return end

        isEscaping = true
        local spawnRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("SpawnToyRemoteFunction")
        local destroyToyRemote = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")

        local tudor = workspace:FindFirstChild("Waypoints") and workspace.Waypoints:FindFirstChild("TudorHouse")
        local spawnCF = tudor and tudor.CFrame or hrp.CFrame * CFrame.new(0, 50, 0)

        local tractor = nil
        if spawnRF then
            pcall(function()
                tractor = spawnRF:InvokeServer("TractorGreen", spawnCF, Vector3.zero)
            end)
        end
        if not tractor then
            local myToys = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            tractor = myToys and myToys:FindFirstChild("TractorGreen")
        end

        if not tractor then
            isEscaping = false
            return
        end

        local vehicleSeat = tractor:WaitForChild("VehicleSeat", 1)
        if not vehicleSeat then
            isEscaping = false
            if destroyToyRemote then pcall(function() destroyToyRemote:FireServer(tractor) end) end
            return
        end

        local seatWeldBroken = false
        local startT = tick()
        hum.Sit = false
        vehicleSeat:Sit(hum)

        local conn = vehicleSeat.ChildAdded:Connect(function(child)
            if child.Name == "SeatWeld" then
                child.Enabled = false
                seatWeldBroken = true
                child:Destroy()
            end
        end)

        while not (seatWeldBroken or tick() - startT > 0.7) do
            task.wait()
        end

        conn:Disconnect()
        hum.Sit = false
        isEscaping = false
        if destroyToyRemote then
            pcall(function() destroyToyRemote:FireServer(tractor) end)
        end
    end

    local function IsPlayerHeld()
        local isHeldObj = LocalPlayer:FindFirstChild("IsHeld")
        if isHeldObj and isHeldObj.Value then
            return true
        end
        local char = LocalPlayer.Character
        if char then
            local beingHeld = char:FindFirstChild("BeingHeld")
            if beingHeld and beingHeld.Value then return true end
            for _, p in ipairs(char:GetChildren()) do
                local owner = p:FindFirstChild("PartOwner")
                if owner and owner.Value and owner.Value ~= "" then
                    return true
                end
            end
        end
        return false
    end

    local function ResonanceAntiGrab()
        if not AntiGrab then return end
        if AntiGrabActive then return end
        if not IsPlayerHeld() then return end

        local char = LocalPlayer.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
        local neck = torso and torso:FindFirstChild("Neck")
        if not (hum and torso and hrp) then return end

        local struggle = ReplicatedStorage:FindFirstChild("CharacterEvents") and ReplicatedStorage.CharacterEvents:FindFirstChild("Struggle")
        local ragdollRemote = ReplicatedStorage:FindFirstChild("CharacterEvents") and ReplicatedStorage.CharacterEvents:FindFirstChild("RagdollRemote")

        if struggle then
            pcall(function() struggle:FireServer(LocalPlayer) end)
        end

        hum.RequiresNeck = false
        hum.AutoRotate = false
        ResetVelocity(hrp)
        ResetVelocity(torso)

        local position = torso.Position
        local lookVector = torso.CFrame.LookVector
        local unit = Vector3.new(lookVector.X, 0, lookVector.Z).Unit

        AntiGrabActive = true

        local flagBuggy = (AntiGrabType == "Escapes Anything, but buggy")
        local flagSit = (AntiGrabType == "Anti-Kill")
        local flagNoRagdoll = (AntiGrabType == "No Ragdoll")

        if flagBuggy then
            task.spawn(ExtraEscape)
        end

        local now3 = tick()
        local n36 = tick() + 0.033333333333333333
        local n37 = 0

        pcall(function()
            local heldTimer = LocalPlayer:FindFirstChild("HeldTimer")
            if heldTimer then heldTimer.Value = 0 end
            ContextActionService:UnbindAction("Escape")
            ContextActionService:UnbindAction("JumpRemover")
        end)

        if AntiGrabConnection then
            AntiGrabConnection:Disconnect()
            AntiGrabConnection = nil
        end

        AntiGrabConnection = RunService.RenderStepped:Connect(function(deltaTime)
            local now4 = tick()

            -- Struggle spam (30 Hz)
            if now4 >= n36 then
                if struggle then
                    pcall(function() struggle:FireServer(LocalPlayer) end)
                end
                n36 = now4 + 0.033333333333333333
            end

            -- Ragdoll remote spam (0s for normal, 0.11s + Sit for Anti-Kill godmode)
            if hrp and not flagBuggy and not flagNoRagdoll and now4 >= n37 then
                if ragdollRemote then
                    local n38 = flagSit and 0.11 or 0
                    pcall(function() ragdollRemote:FireServer(hrp, n38) end)
                end
                n37 = now4 + 0.033333333333333333
            end

            -- Periodic ExtraEscape in buggy mode
            if flagBuggy and tick() - now3 > 2 then
                task.spawn(ExtraEscape)
                now3 = tick()
            end

            -- Smooth WASD movement calculation
            local moveDirection = hum.MoveDirection
            local walkSpeed = 16
            if hum.WalkSpeed and hum.WalkSpeed > 16 then
                walkSpeed = hum.WalkSpeed
            end

            if moveDirection.Magnitude > 0 then
                position = position + moveDirection * walkSpeed * deltaTime
            end

            local cam = workspace.CurrentCamera
            if cam and (cam.CFrame.Position - cam.Focus.Position).Magnitude < 1 then
                moveDirection = cam.CFrame.LookVector
            end

            local vector = Vector3.new(moveDirection.X, 0, moveDirection.Z)
            if vector.Magnitude > 0 then
                unit = unit:Lerp(vector.Unit, math.min(deltaTime * 12, 1)).Unit
            end

            ResetVelocity(hrp)
            ResetVelocity(torso)

            torso.CFrame = CFrame.lookAt(position, position + unit)

            hum.Sit = flagSit

            if not neck or not neck.Enabled then
                ToggleCollisions(char, false)
                RepositionLimbs(char, true)
            end

            -- Stop struggle animation track
            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
                if track.Animation and track.Animation.AnimationId == "rbxassetid://7047322890" then
                    track:Stop()
                end
            end

            -- Mute scream sound
            local scream = hrp:FindFirstChild("Scream") or torso:FindFirstChild("Scream")
            if scream and scream.Playing then
                scream.Playing = false
            end

            -- Exit condition
            if not IsPlayerHeld() or not AntiGrab or not char.Parent or hum.Health <= 0 then
                AntiGrabActive = false

                if flagSit then
                    task.delay(0.1, function()
                        if hum and not hum.SeatPart then
                            hum.Sit = false
                            hum:ChangeState(Enum.HumanoidStateType.Running)
                        end
                    end)
                end

                hum.AutoRotate = true
                ToggleCollisions(char, true)
                if AntiGrabConnection then
                    AntiGrabConnection:Disconnect()
                    AntiGrabConnection = nil
                end
            end
        end)
    end

    local function SetupAntiGrabListeners()
        for _, conn in pairs(AntiGrabListeners) do
            if conn then conn:Disconnect() end
        end
        table.clear(AntiGrabListeners)

        local isHeldObj = LocalPlayer:FindFirstChild("IsHeld") or LocalPlayer:WaitForChild("IsHeld", 5)
        if isHeldObj then
            AntiGrabListeners["IsHeld"] = isHeldObj:GetPropertyChangedSignal("Value"):Connect(function()
                if isHeldObj.Value and AntiGrab then
                    ResonanceAntiGrab()
                end
            end)
        end

        local function HookChar(char)
            if not char then return end
            AntiGrabListeners["DescAdded"] = char.DescendantAdded:Connect(function(desc)
                if desc.Name == "PartOwner" and AntiGrab then
                    task.wait()
                    if IsPlayerHeld() then
                        ResonanceAntiGrab()
                    end
                end
            end)
        end

        HookChar(LocalPlayer.Character)
        AntiGrabListeners["CharAdded"] = LocalPlayer.CharacterAdded:Connect(function(char)
            AntiGrabActive = false
            if AntiGrabConnection then
                AntiGrabConnection:Disconnect()
                AntiGrabConnection = nil
            end
            HookChar(char)
        end)
    end

    -- Setup persistent listener right away
    SetupAntiGrabListeners()

    DefenseGroup:CreateToggle({
        Name = "Anti Grab [Resonance]",
        Flag = "AntiGrab",
        Tooltip = "Resonance Anti-Grab: 30Hz Struggle spam, zero-ragdoll bypass, and smooth WASD walk.",
        Default = false,
        Callback = function(Value)
            AntiGrab = Value
            if SetToggleState then SetToggleState("AntiGrab", Value) end
            if Value then
                SetupAntiGrabListeners()
                ResonanceAntiGrab()
            else
                AntiGrabActive = false
                if AntiGrabConnection then
                    AntiGrabConnection:Disconnect()
                    AntiGrabConnection = nil
                end
                local char = LocalPlayer.Character
                if char then
                    ToggleCollisions(char, true)
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if hum then hum.AutoRotate = true end
                end
            end
        end
    })

    DefenseGroup:CreateDropdown({
        Name = "Anti-Grab Type",
        Flag = "AntiGrabType",
        Items = { "Normal", "No Ragdoll", "Anti-Kill", "Escapes Anything, but buggy" },
        Default = "Normal",
        Callback = function(val)
            AntiGrabType = val or "Normal"
        end
    })

    DefenseGroup:CreateButton({
        Name = "Escape Any Grab (Instant)",
        Callback = function()
            task.spawn(ExtraEscape)
            if Library and Library.Notify then
                Library:Notify({
                    Title = "Anti Grab",
                    Content = "Executed ExtraEscape (Force Sever Welds)",
                    Duration = 2
                })
            end
        end
    })
end

