})

local RunService = game:GetService("RunService")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local rs = game:GetService("ReplicatedStorage")

local notifyCooldowns = {}
local AntiBlobConnection = nil
local AntiBlobPhysicsConnection = nil
local AntiBlobT = false
local lastSafeCFrame = nil
local lastSafeUpdate = 0

local function releaseBlobGrab(blob, myHRP, myChar, weld, detector, source)
    if not myHRP then return end
    local now = tick()
    local msg = (source or "Enemy") .. " Blobman Kick Blocked!"
    if not notifyCooldowns[msg] or (now - notifyCooldowns[msg]) >= 1.5 then
        notifyCooldowns[msg] = now
        pcall(function() notify("[ DEFENSE ]", msg, 3) end)
    end

    -- 1. Server Remote Release
    pcall(function()
        local script = blob and blob:FindFirstChild("BlobmanSeatAndOwnerScript")
        if script then
            local drop = script:FindFirstChild("CreatureDrop")
            local release = script:FindFirstChild("CreatureRelease")
            if drop and weld then drop:FireServer(weld, myHRP) end
            if release and weld then release:FireServer(weld, myHRP) end
        end
    end)

    -- 2. Network Ownership Reclamation
    pcall(function()
        local grabEvents = rs:FindFirstChild("GrabEvents")
        local setNetOwner = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
        if setNetOwner then
            setNetOwner:FireServer(myHRP, myHRP.CFrame)
        end
    end)

    -- 3. Destroy constraint on client
    pcall(function()
        if weld then
            weld.Enabled = false
            if weld:IsA("AlignPosition") or weld:IsA("AlignOrientation") then
                weld.Attachment0 = nil
                weld.Attachment1 = nil
            elseif weld:IsA("JointInstance") or weld:IsA("WeldConstraint") then
                weld.Part0 = nil
                weld.Part1 = nil
            end
            weld:Destroy()
        end
        if detector then
            detector.CanTouch = false
        end
    end)

    -- 4. Reset Ragdoll & Physics
    pcall(function()
        if rs:FindFirstChild("CharacterEvents") and rs.CharacterEvents:FindFirstChild("RagdollRemote") then
            rs.CharacterEvents.RagdollRemote:FireServer(myHRP, 0)
        end
        local hum = myChar:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.PlatformStand = false
            hum.Sit = false
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
        end
        for _, p in ipairs(myChar:GetDescendants()) do
            if p:IsA("BasePart") then
                p.AssemblyLinearVelocity = Vector3.zero
                p.AssemblyAngularVelocity = Vector3.zero
            end
        end
    end)
end

local function scanAndNeutralizeBlobmans()
    local myChar = LocalPlayer.Character
    if not myChar then return end
    local myHRP = myChar:FindFirstChild("HumanoidRootPart")
    local myAttach = myHRP and myHRP:FindFirstChild("RootAttachment")
    if not myHRP then return end

    -- Safe CFrame tracking
    local now = tick()
    if now - lastSafeUpdate > 0.15 then
        local pos = myHRP.Position
        if pos == pos and pos.Y > -50 and pos.Y < 500 and myHRP.AssemblyLinearVelocity.Magnitude < 80 then
            lastSafeCFrame = myHRP.CFrame
            lastSafeUpdate = now
        end
    end

    -- Physics kick protection: Extreme velocity or fling out of bounds
    local currentPos = myHRP.Position
    local vel = myHRP.AssemblyLinearVelocity
    local isFling = (vel.Magnitude > 250) or (vel ~= vel)
    local isOutOfBounds = (currentPos ~= currentPos) or (currentPos.Y > 2000) or (currentPos.Y < -150)

    if isFling or isOutOfBounds then
        for _, p in ipairs(myChar:GetDescendants()) do
            if p:IsA("BasePart") then
                p.AssemblyLinearVelocity = Vector3.zero
                p.AssemblyAngularVelocity = Vector3.zero
            end
        end
        if lastSafeCFrame then
            myHRP.CFrame = lastSafeCFrame
        end
        pcall(function()
            local grabEvents = rs:FindFirstChild("GrabEvents")
            local setNetOwner = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
            if setNetOwner then
                setNetOwner:FireServer(myHRP, myHRP.CFrame)
            end
        end)
    end

    -- Check character descendants for hostile welds/constraints attached to a Blobman
    for _, item in ipairs(myChar:GetDescendants()) do
        if item:IsA("Constraint") or item:IsA("JointInstance") then
            local p0 = item.Part0
            local p1 = item.Part1
            local b0 = p0 and p0:FindFirstAncestor("CreatureBlobman")
            local b1 = p1 and p1:FindFirstAncestor("CreatureBlobman")
            local hostileBlob = b0 or b1
            if hostileBlob then
                releaseBlobGrab(hostileBlob, myHRP, myChar, item, nil, hostileBlob.Name)
            end
        end
    end

    -- Scan all Blobmans in workspace
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj.Name == "CreatureBlobman" and obj:IsA("Model") then
            local vehicleSeat = obj:FindFirstChild("VehicleSeat")
            local occupantName = "Enemy"
            if vehicleSeat and vehicleSeat.Occupant then
                local occChar = vehicleSeat.Occupant.Parent
                local occPlr = occChar and Players:GetPlayerFromCharacter(occChar)
                if occPlr then
                    occupantName = occPlr.DisplayName or occPlr.Name
                end
            end

            -- Disallow sitting in enemy blobman seat
            local hum = myChar:FindFirstChildOfClass("Humanoid")
            if hum and hum.SeatPart and hum.SeatPart:IsDescendantOf(obj) and occupantName ~= LocalPlayer.Name and occupantName ~= LocalPlayer.DisplayName then
                hum.Sit = false
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end

            for _, side in ipairs({"Left", "Right"}) do
                local detector = obj:FindFirstChild(side .. "Detector")
                if detector then
                    -- Anti-contact: if detector is dangerously close to us (< 18 studs), suppress its touch
                    local dist = (detector.Position - myHRP.Position).Magnitude
                    if dist < 18 then
                        detector.CanTouch = false
                    end

                    for _, child in ipairs(detector:GetChildren()) do
                        local isAttached = false
                        if child:IsA("AlignPosition") or child:IsA("AlignOrientation") then
                            if myAttach and (child.Attachment0 == myAttach or child.Attachment1 == myAttach) then
                                isAttached = true
                            end
                        elseif child:IsA("JointInstance") or child:IsA("WeldConstraint") then
                            if child.Part0 == myHRP or child.Part1 == myHRP or (child.Part0 and child.Part0:IsDescendantOf(myChar)) or (child.Part1 and child.Part1:IsDescendantOf(myChar)) then
                                isAttached = true
                            end
                        end

                        if isAttached then
                            releaseBlobGrab(obj, myHRP, myChar, child, detector, occupantName)
                        end
                    end
                end
            end
        end
    end
end

function AntiBlobF()
    if AntiBlobConnection then
        AntiBlobConnection:Disconnect()
        AntiBlobConnection = nil
    end
    if AntiBlobPhysicsConnection then
        AntiBlobPhysicsConnection:Disconnect()
        AntiBlobPhysicsConnection = nil
    end

    local myChar = LocalPlayer.Character
    local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if myHRP then
        lastSafeCFrame = myHRP.CFrame
        lastSafeUpdate = tick()
    end

    AntiBlobConnection = RunService.Heartbeat:Connect(function()
        if not AntiBlobT then
            if AntiBlobConnection then AntiBlobConnection:Disconnect(); AntiBlobConnection = nil end
            return
        end
        pcall(scanAndNeutralizeBlobmans)
    end)

    AntiBlobPhysicsConnection = RunService.Stepped:Connect(function()
        if not AntiBlobT then
            if AntiBlobPhysicsConnection then AntiBlobPhysicsConnection:Disconnect(); AntiBlobPhysicsConnection = nil end
            return
        end
        local c = LocalPlayer.Character
        local root = c and c:FindFirstChild("HumanoidRootPart")
        if root then
            -- Pre-physics clamp on extreme velocity
            local v = root.AssemblyLinearVelocity
            if v.Magnitude > 300 or v ~= v then
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end
        end
    end)
end

DefenseGroup:CreateToggle({
    Name = "Anti Blobman Kick",
    Flag = "AntiBlobKick",
    Default = false,
    Callback = function(Value)
        AntiBlobT = Value
        if AntiBlobT then
            AntiBlobF()
        else
            if AntiBlobConnection then
                AntiBlobConnection:Disconnect()
                AntiBlobConnection = nil
            end
            if AntiBlobPhysicsConnection then
                AntiBlobPhysicsConnection:Disconnect()
                AntiBlobPhysicsConnection = nil
            end
        end
    end,
})

-- ==================== RESONANCE ANTI-BLOBMAN ROOT DESYNC ====================
do
    local antiBlobmanDesync = false
    local originalRootAttachment = nil
    local dummyRootAttachment = nil

    local function toggleResonanceAntiBlobman(val)
        antiBlobmanDesync = val
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")

        if not val then
            if originalRootAttachment and originalRootAttachment.Parent and hrp then
                pcall(function() originalRootAttachment.Parent = hrp end)
            end
            if dummyRootAttachment and dummyRootAttachment.Parent then
                pcall(function() dummyRootAttachment:Destroy() end)
                dummyRootAttachment = nil
            end
            return
        end

        task.spawn(function()
            while antiBlobmanDesync do
                local c = LocalPlayer.Character
                local root = c and c:FindFirstChild("HumanoidRootPart")
                local hum = c and c:FindFirstChildOfClass("Humanoid")
                if root and hum and hum.Health > 0 then
                    local realAttach = root:FindFirstChild("RootAttachment")
                    if realAttach and realAttach:IsA("Attachment") then
                        originalRootAttachment = realAttach
                        pcall(function()
                            realAttach.Parent = game:GetService("ReplicatedStorage")
                        end)
                        if not root:FindFirstChild("RootAttachment") then
                            local dummy = Instance.new("BoolValue")
                            dummy.Name = "RootAttachment"
                            dummy.Parent = root
                            dummyRootAttachment = dummy
                        end
                    end
                    if root.Massless then
                        root.Massless = false
                    end
                    -- If sitting in any Blobman seat, force unseat immediately
                    if hum.SeatPart and hum.SeatPart.Parent and tostring(hum.SeatPart.Parent.Name):find("Blobman") then
                        hum.Sit = false
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    end
                end
                task.wait(0.2)
            end
        end)
    end

    DefenseGroup:CreateToggle({
        Name = "Anti Blobman (Resonance Root Desync)",
        Default = false,
        Callback = function(val)
            toggleResonanceAntiBlobman(val)
        end
    })
end

Players = game:GetService("Players")
RunService = game:GetService("RunService")
ReplicatedStorage = game:GetService("ReplicatedStorage")
LocalPlayer = Players.LocalPlayer

-- Fix 1: Pull helper functions OUTSIDE the callback to prevent memory leaks
function OAA_getCharacter(player)
    return player.Character
end

function OAA_getHumanoidRootPart(character)
    return character and character:FindFirstChild("HumanoidRootPart")
end

function OAA_getHumanoid(character)
    return character and character:FindFirstChild("Humanoid")
end

function OAA_getDistance(part1, part2)
    return (part1.Position - part2.Position).Magnitude
end

function OAA_setNetworkOwner(part, cframe)
    task.spawn(function()
        -- Use FindFirstChild/WaitForChild safely
        local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
        if grabEvents then
            local setNetworkOwnerRemote = grabEvents:FindFirstChild("SetNetworkOwner")
            if setNetworkOwnerRemote then
                setNetworkOwnerRemote:FireServer(part, cframe)
            end
        end
    end)
end

-- Fix 2: Prevent DescendantAdded from stacking multiple connections
local antiBlob1T = false
local blobConnection = nil

function antiBlob1F()
    antiBlob1T = true
    if not blobConnection then
        blobConnection = workspace.DescendantAdded:Connect(function(toy)
            if toy.Name == "CreatureBlobman" and antiBlob1T then
                -- Wait for child prevents errors if the detectors haven't loaded the exact microsecond the model spawns
                local leftDetector = toy:WaitForChild("LeftDetector", 3)
                local rightDetector = toy:WaitForChild("RightDetector", 3)
                
                if leftDetector then leftDetector:Destroy() end
                if rightDetector then rightDetector:Destroy() end
            end
        end)
    end
end

-- Fix 3: Use a connection variable to cleanly start/stop the Aura loop
local auraConnection = nil

DefenseGroup:CreateToggle({
    Name = "Anti-Blobman Aura",
    Flag = "Anti-Blobman Aura",
    Default = false,
    Callback = function(enabled)
        -- Fix 4: Changed 'Value' to 'enabled'
        if SetToggleState then
            SetToggleState("Anti-Blobman Aura", enabled)
        end

        if enabled then
            -- Clean up old loop just in case
            if auraConnection then auraConnection:Disconnect() end
            
            -- Use Heartbeat for smooth, constant checking without freezing the UI thread
            auraConnection = RunService.Heartbeat:Connect(function()
                local myCharacter = OAA_getCharacter(LocalPlayer)
                local myRootPart = OAA_getHumanoidRootPart(myCharacter)

                if not myRootPart then return end -- Skip if we are dead/respawning

                for _, player in pairs(Players:GetPlayers()) do
                    if player ~= LocalPlayer then
                        local playerCharacter = OAA_getCharacter(player)
                        local playerRootPart = OAA_getHumanoidRootPart(playerCharacter)
                        local playerHumanoid = OAA_getHumanoid(playerCharacter)

                        if playerRootPart and playerHumanoid and playerHumanoid.SeatPart then
                            local seatParent = playerHumanoid.SeatPart.Parent
                            
                            -- Check if riding Blobman and within range
                            if seatParent and seatParent.Name == "CreatureBlobman" then
                                if OAA_getDistance(playerRootPart, myRootPart) <= 19 then
                                    OAA_setNetworkOwner(playerRootPart, playerRootPart.CFrame)
                                end
                            end
                        end
                    end
                end
            end)
        else
            -- Disconnect the loop cleanly when toggled off
            if auraConnection then
                auraConnection:Disconnect()
                auraConnection = nil
            end
        end
    end,
})
local antiExplosionConn = nil
local antiExplodeT = false

local function resetCharVelocity(root)
	if not root or not root:IsA("BasePart") then return end
	root.AssemblyLinearVelocity = Vector3.zero
	root.AssemblyAngularVelocity = Vector3.zero
end

local function setupAntiExplosion()
	if antiExplosionConn then
		antiExplosionConn:Disconnect()
		antiExplosionConn = nil
	end
	antiExplosionConn = workspace.ChildAdded:Connect(function(child)
		if not antiExplodeT then return end
		-- Resonance detects both standalone 'Part' and missile models/parts
		local isExploPart = (child.Name == "Part") or (child.Name:find("Missile") ~= nil)
		if not isExploPart then return end

		local char = (LocalPlayer and LocalPlayer.Character) or (Player and Player.Character)
		if not char then return end
		local hrp = char:FindFirstChild("HumanoidRootPart")
		local hum = char:FindFirstChildOfClass("Humanoid")
		if not hrp or not hum or hum.Health <= 0 then return end

		local childPos = child:IsA("BasePart") and child.Position or (child:IsA("Model") and (child:GetPivot().Position))
		if not childPos then return end

		if (childPos - hrp.Position).Magnitude <= 35 then
			-- 1:1 Resonance anchor lock + velocity cancel (prevents being flung into sky)
			hrp.Anchored = true
			resetCharVelocity(hrp)

			-- Cancel ragdoll limb collisions so explosion physics shockwave cannot impart impulse
			for _, desc in ipairs(char:GetDescendants()) do
				if desc.Name == "RagdollLimbPart" and desc:IsA("BasePart") then
					desc.CanCollide = false
				end
			end

			task.wait(0.03)

			if not hum.SeatPart then
				hum.Sit = false
			end

			resetCharVelocity(hrp)
			hrp.Anchored = false
		end
	end)
end

DefenseGroup:CreateToggle({
	Name = "Anti Explosion",
	Flag = "Anti Explosion",
	Tooltip = "Resonance Anti-Explosion: Prevents being launched into sky/space by Missiles & Bombs",
	Default = false,
	Callback = function(on)
		SetToggleState("Anti Explosion", on)
		antiExplodeT = on
		if on then
			setupAntiExplosion()
		else
			if antiExplosionConn then
				antiExplosionConn:Disconnect()
				antiExplosionConn = nil
			end
			local char = (LocalPlayer and LocalPlayer.Character) or (Player and Player.Character)
			local hrp = char and char:FindFirstChild("HumanoidRootPart")
			if hrp then hrp.Anchored = false end
		end
	end
})
local hookBurnConn
function hookBurn(char)
	local hum = char:WaitForChild("Humanoid")
	local hrp = char:WaitForChild("HumanoidRootPart")
	char.PrimaryPart = hrp
	if hookBurnConn then
		hookBurnConn:Disconnect()
	end
	hookBurnConn = hum.FireDebounce.Changed:Connect(function(isBurning)
		if isBurning then
			local me = char
			local oldCF = hrp.CFrame
			local plots = workspace:FindFirstChild("Plots")
			if plots and plots:FindFirstChild("Plot2") then
				local plot2 = plots.Plot2
				local barrier = plot2:FindFirstChild("Barrier")
				local pb = barrier and barrier:FindFirstChild("PlotBarrier")
				if pb and pb:IsA("BasePart") then
					local safeCF = pb.CFrame * CFrame.new(0, 6, 0)
					me:SetPrimaryPartCFrame(safeCF)
					task.wait(0.3)
					local firePart = me:FindFirstChild("FirePlayerPart", true)
					if firePart then
						for _, obj in ipairs(firePart:GetChildren()) do
							if obj:IsA("Sound") then
								obj:Stop()
							end
							if obj:IsA("Light") or obj:IsA("ParticleEmitter") then
								obj.Enabled = false
							end
						end
						if firePart:FindFirstChild("CanBurn") then
							firePart.CanBurn.Value = false
						end
						if hum:FindFirstChild("FireDebounce") then
							hum.FireDebounce.Value = false
						end
					end
					task.wait(0.6)
					if me and me.PrimaryPart then
						me:SetPrimaryPartCFrame(oldCF)
					end
				end
			end
		end
	end)
end
DefenseGroup:CreateToggle({
	Name = "Anti Burn",
        Flag = "Anti Burn",
	Default = false,
	Callback = function(on)
        SetToggleState("Anti Burn", on)
		if on then
			hookBurn(Player.Character)
		elseif hookBurnConn then
			hookBurnConn:Disconnect()
		end
	end
})

