-- [Kick Aura OP PREMIUM removed]
do
    -- // Services & Variables \\ --
    local playersService = game:GetService("Players")
    local workspaceService = game:GetService("Workspace")
    local debrisService = game:GetService("Debris")
    local localPlayer = playersService.LocalPlayer

    -- Remote Events required for network ownership
    local setNetworkOwnerEvent = game:GetService("ReplicatedStorage"):WaitForChild("GrabEvents"):WaitForChild("SetNetworkOwner")

    -- Global Variables used by the Fling Aura UI
    _G.FlingAura = false
    _G.FlingStrength = 400
    _G.FlingTarget = 1 -- 1 = Players, 2 = Objects, 3 = Players and Objects

    -- // Helper Functions \\ --
    
    -- Calculates the CFrame needed to point the fling velocity at the target
    local function lookAt(startPosition, targetPosition)
        local directionVector = (targetPosition - startPosition).Unit
        local rightVector = directionVector:Cross((Vector3.new(0, 1, 0)))
        local upVector = rightVector:Cross(directionVector)
        return CFrame.fromMatrix(startPosition, rightVector, upVector)
    end

    local function GetPlayerCharacter()
        if localPlayer.Character and (localPlayer.Character:FindFirstChild("HumanoidRootPart") and localPlayer.Character:FindFirstChildOfClass("Humanoid")) then
            return localPlayer.Character
        end
    end

    local function GetPlayerRoot()
        local playerHumanoidRootPart = GetPlayerCharacter()
        if playerHumanoidRootPart then
            return playerHumanoidRootPart.HumanoidRootPart
        end
    end

    -- Network Ownership Checks
    local function CheckNetworkOwnerShipOnPart(potentialPart, condition)
        if typeof(potentialPart) == "Instance" and (potentialPart:FindFirstChild("PartOwner") and potentialPart.PartOwner.Value == localPlayer.Name) then
            return not condition and true or potentialPart.PartOwner
        end
    end

    local function CheckNetworkOwnerShipOnPlayer(potentialPlayer, condition)
        if typeof(potentialPlayer) == "Instance" and (potentialPlayer:IsA("Player") and potentialPlayer.Character) and (potentialPlayer.Character:FindFirstChild("Head") and (potentialPlayer.Character.Head:FindFirstChild("PartOwner") and potentialPlayer.Character.Head.PartOwner.Value == localPlayer.Name)) then
            return not condition and true or potentialPlayer.Character.Head.PartOwner
        end
    end

    local function SNOWshipPlayer(otherPlayer, callbackFunction)
        if localPlayer.Character and (localPlayer.Character:FindFirstChild("HumanoidRootPart") and (typeof(otherPlayer) == "Instance" and (otherPlayer:IsA("Player") and otherPlayer.Character)) and otherPlayer.Character:FindFirstChild("HumanoidRootPart")) then
            local otherPlayerHumanoidRootPart = otherPlayer.Character.HumanoidRootPart
            local distanceFromOtherPlayer = localPlayer:DistanceFromCharacter(otherPlayerHumanoidRootPart.Position)
            if CheckNetworkOwnerShipOnPlayer(otherPlayer) then
                if type(callbackFunction) == "function" then
                    callbackFunction()
                end
                return true
            end
            if distanceFromOtherPlayer <= 30 then
                setNetworkOwnerEvent:FireServer(otherPlayerHumanoidRootPart, lookAt(localPlayer.Character.HumanoidRootPart.Position, otherPlayerHumanoidRootPart.Position))
            end
        end
    end

    local function SNOWshipTrack(targetPart)
        if targetPart.Parent and targetPart.Parent:IsA("Model") then
            local targetModel = targetPart.Parent
            local isOwnershipTrackConnected = targetModel:GetAttribute("OwnershipTrackConnected")
            local isCreatedConnected2 = targetModel:GetAttribute("CreatedConnected2")
            if localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart") then
                local distanceFromCharacter = localPlayer:DistanceFromCharacter(targetPart.Position)
                if isCreatedConnected2 then
                    if isOwnershipTrackConnected then
                        return true
                    end
                    if distanceFromCharacter <= 30 then
                        setNetworkOwnerEvent:FireServer(targetPart, lookAt(localPlayer.Character.HumanoidRootPart.Position, targetPart.Position))
                    end
                else
                    targetModel:SetAttribute("CreatedConnected2", true)
                    targetModel.DescendantAdded:Connect(function(attribute)
                        if attribute.Name ~= "PartOwner" or attribute.Value ~= localPlayer.Name then
                            if attribute.Name == "PartOwner" and attribute.Value ~= localPlayer.Name then
                                targetModel:SetAttribute("OwnershipTrackConnected", false)
                            end
                        else
                            targetModel:SetAttribute("OwnershipTrackConnected", true)
                        end
                    end)
                end
            end
        end
    end

    -- Target Validation Checks
    local function CheckPlayer(potentialPlayer)
        if typeof(potentialPlayer) == "Instance" and (potentialPlayer ~= localPlayer and potentialPlayer.Character) and (potentialPlayer.Character:IsDescendantOf(workspaceService) and (potentialPlayer.Character:FindFirstChild("HumanoidRootPart") and (potentialPlayer.Character:FindFirstChildOfClass("Humanoid") and potentialPlayer.Character.Humanoid.Health > 0))) then
            return true
        end
    end

    local function CheckPlayerAuras(potentialKickedPlayer1)
        if CheckPlayer(potentialKickedPlayer1) and not potentialKickedPlayer1.Character:GetAttribute("Kicking") then
            return true
        end
    end

    -- Spatial parameters for finding loose objects
    local COAroundPParams = OverlapParams.new()
    COAroundPParams.FilterType = Enum.RaycastFilterType.Exclude

    local function CheckObjectsAroundPlayer()
        -- Ensure this list dynamically updates locally within the function
        COAroundPParams.FilterDescendantsInstances = {
            GetPlayerCharacter(),
            workspaceService.Map,
            workspaceService.Plots,
            workspaceService.Waypoints,
            workspaceService.Slots
        }
        
        local playerRoot = GetPlayerRoot()
        if playerRoot then
            local connectedPartsList = {}
            local teslaCoil = nil
            local function isPartConnectable(part)
                if not part:IsDescendantOf(workspaceService.Map) and (not part:IsDescendantOf(workspaceService.Plots) and (not part:IsDescendantOf(workspaceService.Waypoints) and (not part:IsDescendantOf(workspaceService.Slots) and part.Parent))) and (part.Parent:IsA("Model") and (part.Parent:FindFirstChildOfClass("BasePart") or (part.Parent:FindFirstChildOfClass("Part") or part.Parent:FindFirstChildOfClass("MeshPart")))) then
                    local partParent = part.Parent
                    local isConnected2 = partParent:GetAttribute("Connected2")
                    
                    local playerFromCharacter
                    if partParent:FindFirstChildOfClass("Humanoid") then
                        playerFromCharacter = playersService:GetPlayerFromCharacter(partParent)
                    else
                        playerFromCharacter = nil
                    end
                    if not (playerFromCharacter or isConnected2) then
                        return true
                    end
                end
            end
            local partsInRadius = workspaceService:GetPartBoundsInRadius(playerRoot.Position, 28, COAroundPParams)
            local iterator, partIndex, index = pairs(partsInRadius)
            while true do
                local instance
                index, instance = iterator(partIndex, index)
                if index == nil then
                    break
                end
                if isPartConnectable(instance) then
                    local instanceParent = instance.Parent
                    if not table.find(connectedPartsList, instanceParent) then
                        table.insert(connectedPartsList, instanceParent)
                    end
                end
            end
            return connectedPartsList, teslaCoil
        end
    end

    -- // TelekinesisGroup UI Mapping \\ --

    TelekinesisGroup:CreateToggle({
        Name = "Fling Aura",
        Flag = "flingaura_toggle",
        Default = false,
        Callback = function(flingAuraEnabled)
            -- Apply typical UI State mapping
            if SetToggleState then SetToggleState("flingaura_toggle", flingAuraEnabled) end
            
            _G.FlingAura = flingAuraEnabled
            if flingAuraEnabled then
                -- Wrap in task.spawn to prevent yielding the main UI thread
                task.spawn(function()
                    while _G.FlingAura do
                        -- FLING OBJECTS
                        if _G.FlingTarget == 2 or _G.FlingTarget == 3 then
                            local objectsAroundPlayer, flingTargetPart = CheckObjectsAroundPlayer()
                            if objectsAroundPlayer then
                                local pairsIterator, pairsState, pairsIndex = pairs(objectsAroundPlayer)
                                while true do
                                    local childObject
                                    pairsIndex, childObject = pairsIterator(pairsState, pairsIndex)
                                    if pairsIndex == nil then
                                        break
                                    end
                                    local retryCount1 = 0
                                    if childObject then
                                        local headPart = childObject:FindFirstChild("Head")
                                        local childPairsIterator, iteratorValue7, childPairsIndex = pairs(childObject:GetChildren())
                                        while true do
                                            local childPart
                                            childPairsIndex, childPart = childPairsIterator(iteratorValue7, childPairsIndex)
                                            if childPairsIndex == nil then
                                                break
                                            end
                                            if childPart:IsA("BasePart") and childPart.CanQuery then
                                                local networkOwnership = SNOWshipTrack(childPart)
                                                local playerRootPart = GetPlayerRoot()
                                                if not networkOwnership and headPart then
                                                    networkOwnership = CheckNetworkOwnerShipOnPart(headPart)
                                                end
                                                if networkOwnership and playerRootPart then
                                                    if flingTargetPart then
                                                        local currentPosition = flingTargetPart.Position
                                                        flingTargetPart.Position = childPart.Position
                                                        task.wait()
                                                        flingTargetPart.Position = currentPosition
                                                    elseif not childPart:FindFirstChild("FlingAuraVelocity") then
                                                        local lookAtCFrame = lookAt(playerRootPart.Position, childPart.Position)
                                                        local flingBodyVelocity = Instance.new("BodyVelocity", childPart)
                                                        flingBodyVelocity.Name = "FlingAuraVelocity"
                                                        flingBodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                                        flingBodyVelocity.Velocity = Vector3.new(lookAtCFrame.lookVector.X, 0.5, lookAtCFrame.lookVector.Z) * math.clamp(_G.FlingStrength, 400, 600)
                                                        debrisService:AddItem(flingBodyVelocity)
                                                    end
                                                    retryCount1 = retryCount1 + 1
                                                end
                                                if retryCount1 >= 3 then
                                                    break
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end

                        -- FLING PLAYERS
                        if _G.FlingTarget == 1 or _G.FlingTarget == 3 then
                            local playerPairsIterator, iteratorValue8, playerPairsIndex = pairs(playersService:GetPlayers())
                            while true do
                                local otherPlayer
                                playerPairsIndex, otherPlayer = playerPairsIterator(iteratorValue8, playerPairsIndex)
                                if playerPairsIndex == nil then
                                    break
                                end
                                if CheckPlayerAuras(otherPlayer) then
                                    local otherPlayerRootPart = otherPlayer.Character:FindFirstChild("HumanoidRootPart")
                                    local snowshipPlayer = SNOWshipPlayer(otherPlayer)
                                    local localPlayerCharacter = GetPlayerCharacter()
                                    if otherPlayerRootPart and (snowshipPlayer and (localPlayerCharacter and not otherPlayerRootPart:FindFirstChild("FlingAuraVelocity"))) then
                                        local flingDirectionCFrame = lookAt(localPlayerCharacter.HumanoidRootPart.Position, otherPlayerRootPart.Position)
                                        local flingBodyVelocity = Instance.new("BodyVelocity", otherPlayerRootPart)
                                        flingBodyVelocity.Name = "FlingAuraVelocity"
                                        flingBodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                        flingBodyVelocity.Velocity = Vector3.new(flingDirectionCFrame.lookVector.X, 0.5, flingDirectionCFrame.lookVector.Z) * _G.FlingStrength
                                        debrisService:AddItem(flingBodyVelocity)
                                    end
                                end
                            end
                        end
                        task.wait(0.1)
                    end
                end)
            end
        end
    })

    TelekinesisGroup:CreateSlider({
        Name = "Strength",
        Flag = "flingstrengthvalue_toggle",
        Min = 400,
        Max = 10000,
        Default = 400,
        Rounding = 0,
        Callback = function(flingStrength)
            _G.FlingStrength = flingStrength
        end
    })

    TelekinesisGroup:CreateDropdown({
        Name = "Target",
        Flag = "flingtarget_dropdown",
        Items = {
            "Players",
            "Objects",
            "Players and Objects"
        },
        Default = "Players",
        Callback = function(flingTargetType)
            if flingTargetType == "Players" then
                _G.FlingTarget = 1
            elseif flingTargetType == "Objects" then
                _G.FlingTarget = 2
            elseif flingTargetType == "Players and Objects" then
                _G.FlingTarget = 3
            end
        end
    })
end
-- ==============================================================================
-- ==============================================================================
-- PURE RESONANCE TOYS AURA & TOY TORNADO ENGINE (Ported 1:1 for VertexUI)
-- ==============================================================================
do
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local RunService = game:GetService("RunService")
    local Workspace = game:GetService("Workspace")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local StarterGui = game:GetService("StarterGui")

    local function notify(title, desc, duration)
        title = title or "Ranax FTAP"
        pcall(function()
            if Library and Library.Notify then
                Library:Notify({
                    Title = title,
                    Content = desc or "",
                    Duration = duration or 3
                })
            else
                StarterGui:SetCore("SendNotification", {
                    Title = title,
                    Text = desc or "",
                    Duration = duration or 3
                })
            end
        end)
    end

    local GrabEvents = ReplicatedStorage:WaitForChild("GrabEvents", 5)
    local SetNetworkOwnerRemote = GrabEvents and GrabEvents:WaitForChild("SetNetworkOwner", 5)
    local DestroyGrabLineRemote = GrabEvents and GrabEvents:WaitForChild("DestroyGrabLine", 5)

    -- Configuration
    local ToyAuraConfig = {
        Enabled = false,
        Shape = "Tornado",
        Radius = 25,
        Height = 20,
        Spacing = 1.0,
        Rows = 1,
        Rotations = 3,
        AutoRotate = true,
        RotationSpeed = 4.0,
        AutoMove = true,
        MoveSpeed = 4.0,
        Bob = true,
        BobHeight = 2.5,
        BobSpeed = 2.0,
        FaceCenter = true,
        HeightOffset = 4,
        PosType = "You", -- "You", "Players", "Camera Aim Point", "Custom Pos", "Lobby Spawn"
        SelectedPlayer = nil,
        AimDistance = 45,
        Source = "All Toys (Game + Players + Plot)",
        LimitEnabled = true,
        ToyLimit = 75,
        FlingPower = 500,
        CustomPos = nil,
        Responsiveness = 60,
        XOffset = 0,
        YOffset = 0,
        ZOffset = 0,
        XRotation = 0,
        YRotation = 0,
        ZRotation = 0,
        IncludeBaseplate = false
    }

    local function isBaseplateOrTerrain(inst)
        if not inst then return false end
        if inst:IsA("Terrain") then return true end
        local name = string.lower(inst.Name)
        if name:find("baseplate") or name:find("terrain") or name:find("floor") or name:find("ground") or name:find("map") or name:find("spawn") or name:find("island") then
            return true
        end
        if inst:IsA("BasePart") then
            if inst.Size.X > 45 or inst.Size.Y > 45 or inst.Size.Z > 45 or inst.Size.Magnitude > 60 then
                return true
            end
        end
        return false
    end

    local activeToys = {}
    local movers = {}
    local originalCollisions = {}
    local heartbeatConn = nil
    local manuallyAddedToys = {}

    local function addToyToTornado(obj)
        if not obj or not obj.Parent then return end
        local root = getToyRoot(obj)
        if not root or not root.Parent then return end
        for _, e in ipairs(manuallyAddedToys) do
            if e.Root == root or e.Model == obj then return end
        end
        local entry = { Model = obj, Root = root, Manual = true }
        table.insert(manuallyAddedToys, entry)
        table.insert(cachedToys, entry)
        claimOwnership(root)
    end

    local function hookCharacterTouches(char)
        if not char then return end
        for _, part in ipairs(char:GetChildren()) do
            if part:IsA("BasePart") then
                part.Touched:Connect(function(hit)
                    if not ToyAuraConfig.Enabled or not hit or not hit.Parent then return end
                    if hit:IsDescendantOf(char) then return end
                    if Players:GetPlayerFromCharacter(hit.Parent) or (hit.Parent and Players:GetPlayerFromCharacter(hit.Parent.Parent)) then return end
                    local targetModel = hit:FindFirstAncestorOfClass("Model") or hit
                    if targetModel and targetModel ~= Workspace and not targetModel:FindFirstChildOfClass("Humanoid") then
                        addToyToTornado(targetModel)
                    end
                end)
            end
        end
    end

    LocalPlayer.CharacterAdded:Connect(function(char)
        task.wait(0.5)
        hookCharacterTouches(char)
    end)
    if LocalPlayer.Character then
        hookCharacterTouches(LocalPlayer.Character)
    end

    -- Hook GrabParts so whatever the player grabs while Toy Tornado is active instantly joins the tornado
    Workspace.ChildAdded:Connect(function(child)
        if child.Name == "GrabParts" and ToyAuraConfig.Enabled then
            task.defer(function()
                local grabPart = child:WaitForChild("GrabPart", 1)
                local weld = grabPart and grabPart:WaitForChild("WeldConstraint", 1)
                local part1 = weld and weld.Part1
                if part1 and part1.Parent and not Players:GetPlayerFromCharacter(part1.Parent) then
                    local model = part1:FindFirstAncestorOfClass("Model") or part1
                    addToyToTornado(model)
                end
            end)
        end
    end)
    local shapePhase = 0
    local movePhase = 0
    local bobPhase = 0
    local lastOwnerRefresh = 0

    -- Root Character
    local function getMyChar()
        local char = LocalPlayer.Character
        local hrp = char and (char:FindFirstChild("realHrp") or char:FindFirstChild("HumanoidRootPart"))
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        return char, hrp, hum
    end

    local function isPartOwner(part)
        if not (part and part:IsA("BasePart")) then return false end
        local po = part:FindFirstChild("PartOwner")
        if po and po.Value == LocalPlayer.Name then return true end
        local head = part.Parent and part.Parent:FindFirstChild("Head")
        local hpo = head and head:FindFirstChild("PartOwner")
        if hpo and hpo.Value == LocalPlayer.Name then return true end
        return false
    end

    local function claimOwnership(part)
        if not part or not part.Parent or not part:IsA("BasePart") then return false end
        if isPartOwner(part) then return true end
        local _, myHRP, myHum = getMyChar()
        if not (myHRP and myHum and myHum.Health > 0) then return false end

        local eyePos = myHRP.Position + Vector3.new(0, 1.5, 0)
        local targetCF = CFrame.new(eyePos, part.Position)

        pcall(function()
            if SetNetworkOwnerRemote then
                SetNetworkOwnerRemote:FireServer(part, targetCF)
            end
        end)
        return isPartOwner(part)
    end

    local function getToyRoot(obj)
        if not obj or not obj.Parent then return nil end
        if Players:GetPlayerFromCharacter(obj) or (obj.Parent and Players:GetPlayerFromCharacter(obj.Parent)) then
            return nil
        end
        if obj:FindFirstChildOfClass("Humanoid") then return nil end
        if obj.Name:find("RSC") or obj.Name:find("GrabParts") then return nil end

        if not ToyAuraConfig.IncludeBaseplate and isBaseplateOrTerrain(obj) then
            return nil
        end

        local primaryPart = nil
        if obj:IsA("BasePart") then
            primaryPart = obj
        elseif obj:IsA("Model") then
            primaryPart = obj:FindFirstChild("HoldPart")
                or obj:FindFirstChild("SoundPart")
                or obj:FindFirstChild("Main")
                or obj.PrimaryPart
                or obj:FindFirstChildWhichIsA("BasePart")
        end
        if not primaryPart or not primaryPart.Parent then return nil end

        if not ToyAuraConfig.IncludeBaseplate and isBaseplateOrTerrain(primaryPart) then
            return nil
        end

        local root = primaryPart.AssemblyRootPart or primaryPart
        if not ToyAuraConfig.IncludeBaseplate and isBaseplateOrTerrain(root) then
            return nil
        end

        if root.Anchored then
            if not ToyAuraConfig.IncludeBaseplate and isBaseplateOrTerrain(root) then
                return nil
            end
            pcall(function() root.Anchored = false end)
        end
        return root
    end

    local disabledCollisions = {}
    local function setModelCollisions(model, canCollide)
        if not model or not model.Parent then return end
        if canCollide then
            restoreModelCollisions(model)
            disabledCollisions[model] = nil
            return
        end
        if disabledCollisions[model] then return end
        disabledCollisions[model] = true
        for _, p in ipairs(model:GetDescendants()) do
            if p:IsA("BasePart") then
                if originalCollisions[p] == nil then
                    originalCollisions[p] = p.CanCollide
                end
                p.CanCollide = false
                p.CanQuery = false
            end
        end
        if model:IsA("BasePart") then
            if originalCollisions[model] == nil then
                originalCollisions[model] = model.CanCollide
            end
            model.CanCollide = false
            model.CanQuery = false
        end
    end

    local function restoreModelCollisions(model)
        if not model then return end
        disabledCollisions[model] = nil
        for _, p in ipairs(model:GetDescendants()) do
            if p:IsA("BasePart") and originalCollisions[p] ~= nil then
                p.CanCollide = originalCollisions[p]
                p.CanQuery = true
                originalCollisions[p] = nil
            end
        end
        if model:IsA("BasePart") and originalCollisions[model] ~= nil then
            model.CanCollide = originalCollisions[model]
            model.CanQuery = true
            originalCollisions[model] = nil
        end
    end

    local function ensureMovers(root, model)
        if not root or not root.Parent then return nil end
        local existing = movers[model]
        if existing and existing.Root == root and existing.Attachment.Parent == root and existing.Position.Parent == root and existing.Orientation.Parent == root then
            return existing
        end

        if existing then
            pcall(function() existing.Position:Destroy() end)
            pcall(function() existing.Orientation:Destroy() end)
            pcall(function() existing.Attachment:Destroy() end)
            movers[model] = nil
        end

        local att = root:FindFirstChild("AuraAttachment") or Instance.new("Attachment")
        att.Name = "AuraAttachment"
        att.Parent = root

        local pos = root:FindFirstChild("AuraAlignPos") or Instance.new("AlignPosition")
        pos.Name = "AuraAlignPos"
        pos.Attachment0 = att
        pos.Mode = Enum.PositionAlignmentMode.OneAttachment
        pos.ApplyAtCenterOfMass = true
        pos.MaxForce = math.huge
        pos.MaxVelocity = math.huge
        pos.Responsiveness = 35
        pos.RigidityEnabled = true
        pos.Parent = root

        local ori = root:FindFirstChild("AuraAlignOri") or Instance.new("AlignOrientation")
        ori.Name = "AuraAlignOri"
        ori.Attachment0 = att
        ori.Mode = Enum.OrientationAlignmentMode.OneAttachment
        ori.MaxTorque = math.huge
        ori.MaxAngularVelocity = math.huge
        ori.Responsiveness = 30
        ori.RigidityEnabled = true
        ori.Parent = root

        local entry = { Root = root, Attachment = att, Position = pos, Orientation = ori }
        movers[model] = entry
        return entry
    end

    local function removeMovers(model)
        local mover = movers[model]
        if mover then
            pcall(function() mover.Position:Destroy() end)
            pcall(function() mover.Orientation:Destroy() end)
            pcall(function() mover.Attachment:Destroy() end)
            movers[model] = nil
        end
        restoreModelCollisions(model)
    end

    local function clearAllMovers()
        for model in pairs(movers) do
            removeMovers(model)
        end
        table.clear(movers)
        table.clear(activeToys)
        table.clear(disabledCollisions)
        table.clear(cachedToys)
        lastToyScanTime = 0
    end

    -- Shapes Library (All 32 Resonance Shapes)
    local Shapes = {
        ["Tornado"] = function(i, n, rows, rot)
            local u = (i - 1) / math.max(n - 1, 1)
            local angle = u * math.pi * 2 * (rot or 3)
            local radiusFactor = (1 - u * 0.75)
            return Vector3.new(math.cos(angle) * radiusFactor, -1 + 2 * u, math.sin(angle) * radiusFactor)
        end,
        ["Funnel Tornado"] = function(i, n, rows, rot)
            local u = (i - 1) / math.max(n - 1, 1)
            local angle = u * math.pi * 2 * (rot or 3)
            local radiusFactor = (0.2 + 0.8 * u)
            return Vector3.new(math.cos(angle) * radiusFactor, -1 + 2 * u, math.sin(angle) * radiusFactor)
        end,
        ["Circle"] = function(i, n)
            local angle = (i - 1) / n * math.pi * 2
            return Vector3.new(math.cos(angle), 0, math.sin(angle))
        end,
        ["Sphere"] = function(i, n)
            local y = 1 - 2 * (i - 0.5) / n
            local r = math.sqrt(math.max(0, 1 - y * y))
            local phi = 2.3999632297286531 * i
            return Vector3.new(math.cos(phi) * r, y, math.sin(phi) * r)
        end,
        ["Dome"] = function(i, n)
            local y = (i - 0.5) / n
            local r = math.sqrt(math.max(0, 1 - y * y))
            local phi = 2.3999632297286531 * i
            return Vector3.new(math.cos(phi) * r, y, math.sin(phi) * r)
        end,
        ["Helix"] = function(i, n, rows, rot)
            local u = (i - 1) / math.max(n - 1, 1)
            local angle = u * math.pi * 2 * (rot or 3)
            return Vector3.new(math.cos(angle), -1 + 2 * u, math.sin(angle))
        end,
        ["Double Helix"] = function(i, n, rows, rot)
            local half = math.ceil(n / 2)
            local isSecond = i > half
            local localIdx = isSecond and (i - half) or i
            local total = isSecond and (n - half) or half
            local u = (localIdx - 1) / math.max(total - 1, 1)
            local angle = u * math.pi * 2 * (rot or 3) + (isSecond and math.pi or 0)
            return Vector3.new(math.cos(angle), -1 + 2 * u, math.sin(angle))
        end,
        ["Cylinder"] = function(i, n, rows)
            local rCount = math.clamp(rows or 3, 1, math.max(n, 1))
            local perRow = math.ceil(n / rCount)
            local rowIndex = math.floor((i - 1) / perRow)
            local inRowIdx = (i - 1) % perRow
            local y = (rCount == 1) and 0 or (-1 + 2 * (rowIndex / (rCount - 1)))
            local angle = inRowIdx / perRow * math.pi * 2
            return Vector3.new(math.cos(angle), y, math.sin(angle))
        end,
        ["Ring Stack"] = function(i, n, rows)
            local rCount = math.clamp(rows or 3, 1, math.max(n, 1))
            local perRow = math.ceil(n / rCount)
            local rowIndex = math.floor((i - 1) / perRow)
            local inRowIdx = (i - 1) % perRow
            local y = (rCount == 1) and 0 or (-1 + 2 * (rowIndex / (rCount - 1)))
            local angle = inRowIdx / perRow * math.pi * 2
            local waist = 1 - math.abs(y) * 0.22
            return Vector3.new(math.cos(angle) * waist, y, math.sin(angle) * waist)
        end,
        ["Torus"] = function(i, n, rows, rot)
            local theta = (i - 1) / n * math.pi * 2
            local phi = theta * math.max(1, math.floor(rot or 3))
            local rad = 0.72 + 0.28 * math.cos(phi)
            return Vector3.new(rad * math.cos(theta), 0.28 * math.sin(phi), rad * math.sin(theta))
        end,
        ["Galaxy"] = function(i, n, rows, rot)
            local arms = math.clamp(rows or 3, 2, 8)
            local arm = (i - 1) % arms
            local t = math.sqrt((math.floor((i - 1) / arms) + 0.5) / (math.floor((n - arm - 1) / arms) + 1))
            local angle = t * math.pi * 2 * (rot or 3) + (arm / arms) * math.pi * 2
            return Vector3.new(math.cos(angle) * t, math.sin(t * math.pi * 4 + arm) * 0.15, math.sin(angle) * t)
        end,
        ["Cone"] = function(i, n, rows, rot)
            local u = (i - 1) / math.max(n - 1, 1)
            local angle = u * math.pi * 2 * (rot or 3)
            local rad = 1 - u
            return Vector3.new(math.cos(angle) * rad, -1 + 2 * u, math.sin(angle) * rad)
        end,
        ["Pyramid"] = function(i, n)
            local u = (i - 1) / math.max(n - 1, 1)
            local y = -1 + 2 * u
            local s = (1 - u)
            local side = (i % 4)
            local x, z
            if side == 0 then x = s; z = -s + 2*s*u
            elseif side == 1 then x = s - 2*s*u; z = s
            elseif side == 2 then x = -s; z = s - 2*s*u
            else x = -s + 2*s*u; z = -s end
            return Vector3.new(x, y, z)
        end,
        ["Box"] = function(i, n)
            local u = (i - 1) / n * 4
            local side = math.floor(u)
            local frac = u - side
            local x, z
            if side == 0 then x = -1 + 2 * frac; z = -1
            elseif side == 1 then x = 1; z = -1 + 2 * frac
            elseif side == 2 then x = 1 - 2 * frac; z = 1
            else x = -1; z = 1 - 2 * frac end
            local y = math.sin((i / n) * math.pi * 2) * 0.5
            return Vector3.new(x, y, z)
        end,
        ["Spiral"] = function(i, n, rows, rot)
            local u = (i - 1) / math.max(n - 1, 1)
            local angle = u * math.pi * 2 * (rot or 3)
            return Vector3.new(math.cos(angle) * u, 0, math.sin(angle) * u)
        end,
        ["Wave"] = function(i, n, rows, rot)
            local u = (i - 1) / math.max(n - 1, 1)
            return Vector3.new(-1 + 2 * u, math.sin(u * math.pi * 2 * (rot or 3)) * 0.5, 0)
        end,
        ["Heart"] = function(i, n)
            local t = (i - 1) / n * math.pi * 2
            local x = 16 * (math.sin(t) ^ 3) / 17
            local z = -(13 * math.cos(t) - 5 * math.cos(2 * t) - 2 * math.cos(3 * t) - math.cos(4 * t)) / 17
            return Vector3.new(x, 0, z)
        end,
        ["Star"] = function(i, n)
            local t = (i - 1) / 10 * math.pi * 2 - math.pi / 2
            local r = (i % 2 == 1) and 1 or 0.42
            return Vector3.new(math.cos(t) * r, 0, math.sin(t) * r)
        end,
        ["Diamond"] = function(i, n)
            local u = (i - 1) / n * 4
            local side = math.floor(u)
            local frac = u - side
            if side == 0 then return Vector3.new(frac, 0, -(1 - frac))
            elseif side == 1 then return Vector3.new(1 - frac, 0, frac)
            elseif side == 2 then return Vector3.new(-frac, 0, 1 - frac)
            else return Vector3.new(-(1 - frac), 0, -frac) end
        end,
        ["Triangle"] = function(i, n)
            local t = (i - 1) / n * math.pi * 2 - math.pi / 2
            return Vector3.new(math.cos(t), 0, math.sin(t))
        end,
        ["Square"] = function(i, n)
            local angle = (i - 1) / n * math.pi * 2 - math.pi / 4
            return Vector3.new(math.cos(angle), 0, math.sin(angle))
        end,
        ["Line"] = function(i, n)
            local u = (n == 1) and 0.5 or ((i - 1) / (n - 1))
            return Vector3.new(-1 + 2 * u, 0, 0)
        end
    }

    local ShapeNamesList = {
        "Tornado", "Funnel Tornado", "Circle", "Sphere", "Dome", "Helix", "Double Helix",
        "Cylinder", "Ring Stack", "Torus", "Galaxy", "Cone", "Pyramid", "Box",
        "Spiral", "Wave", "Heart", "Star", "Diamond", "Triangle", "Square", "Line"
    }

    local function getPointOnShape(shapeName, index, totalCount)
        local gen = Shapes[shapeName] or Shapes["Tornado"] or Shapes["Circle"]
        return gen(index, totalCount, ToyAuraConfig.Rows or 1, ToyAuraConfig.Rotations or 3)
    end

    local function getCenterPosition()
        local _, myHRP = getMyChar()
        local posType = ToyAuraConfig.PosType
        local offset = Vector3.new(ToyAuraConfig.XOffset or 0, ToyAuraConfig.YOffset or 0, ToyAuraConfig.ZOffset or 0)

        if posType == "Camera Aim Point" then
            local cam = Workspace.CurrentCamera
            if cam then
                return cam.CFrame.Position + (cam.CFrame.LookVector * (ToyAuraConfig.AimDistance or 45)) + offset
            end
        elseif posType == "Players" and ToyAuraConfig.SelectedPlayer then
            local pChar = ToyAuraConfig.SelectedPlayer.Character
            local pHRP = pChar and (pChar:FindFirstChild("realHrp") or pChar:FindFirstChild("HumanoidRootPart"))
            if pHRP then
                return pHRP.Position + Vector3.new(0, ToyAuraConfig.HeightOffset, 0) + offset
            end
        elseif posType == "Custom Pos" and ToyAuraConfig.CustomPos then
            return ToyAuraConfig.CustomPos.Position + offset
        elseif posType == "Lobby Spawn" then
            local sp = Workspace:FindFirstChildWhichIsA("SpawnLocation", true) or Workspace:FindFirstChild("SpawnLocation")
            if sp and sp:IsA("BasePart") then
                return sp.Position + Vector3.new(0, ToyAuraConfig.HeightOffset, 0) + offset
            end
        end

        return (myHRP and (myHRP.Position + Vector3.new(0, ToyAuraConfig.HeightOffset, 0)) or Vector3.zero) + offset
    end

    local function collectAvailableToys()
        local list = {}
        local src = ToyAuraConfig.Source
        local limit = ToyAuraConfig.LimitEnabled and math.clamp(ToyAuraConfig.ToyLimit or 75, 5, 200) or 100
        local seenRoots = {}

        local function checkItem(m)
            if not m or not m.Parent then return end
            if #list >= limit then return end
            if not ToyAuraConfig.IncludeBaseplate and isBaseplateOrTerrain(m) then return end
            if m.Name:find("SpawnSign") or m.Name:find("PlotSign") or m.Name == "RotateOrientPart" then return end
            if Players:GetPlayerFromCharacter(m) or (m.Parent and Players:GetPlayerFromCharacter(m.Parent)) then return end
            if m:FindFirstChildOfClass("Humanoid") then return end

            local root = getToyRoot(m)
            if root and root.Parent and not seenRoots[root] then
                if not ToyAuraConfig.IncludeBaseplate and isBaseplateOrTerrain(root) then return end
                seenRoots[root] = true
                table.insert(list, { Model = m, Root = root })
            end
        end

        -- 1. Always prioritize manually grabbed or touched items
        for idx = #manuallyAddedToys, 1, -1 do
            local e = manuallyAddedToys[idx]
            if e.Model and e.Model.Parent and e.Root and e.Root.Parent then
                if not seenRoots[e.Root] then
                    seenRoots[e.Root] = true
                    table.insert(list, e)
                end
            else
                table.remove(manuallyAddedToys, idx)
            end
        end

        local myFolder = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
        local GAME_FOLDERS = {
            "Balloons", "Cave", "Cubes", "Drawers", "Farm", "Food",
            "Furniture", "Glass Boxes", "Ladders", "Large Animals",
            "Lincoln Planks", "Music", "NOT New", "Other", "Pallets",
            "Robloxians", "Rollers"
        }

        if src == "My Spawned Toys Only" then
            if myFolder then
                for _, child in ipairs(myFolder:GetChildren()) do checkItem(child) end
            end
        elseif src == "Game & Map Toys Only" then
            for _, folderName in ipairs(GAME_FOLDERS) do
                local f = Workspace:FindFirstChild(folderName)
                if f then
                    for _, toy in ipairs(f:GetChildren()) do checkItem(toy) end
                end
            end
            if Workspace:FindFirstChild("PlotItems") then
                for _, plotFolder in ipairs(Workspace.PlotItems:GetChildren()) do
                    for _, toy in ipairs(plotFolder:GetChildren()) do checkItem(toy) end
                end
            end
            for _, child in ipairs(Workspace:GetChildren()) do
                if child ~= myFolder and not child.Name:find("SpawnedInToys") and child.Name ~= "Plots" and child.Name ~= "Terrain" and child.Name ~= "Camera" then
                    if child:IsA("Model") and not child:FindFirstChildOfClass("Humanoid") then
                        checkItem(child)
                    elseif child:IsA("BasePart") and not child.Anchored then
                        checkItem(child)
                    end
                end
            end
        else
            -- All toys (Game + Players + Plot) — Full Resonance Map Harvesting
            -- A. Game & Map Spawned Toy Folders (Resonance 1:1)
            for _, folderName in ipairs(GAME_FOLDERS) do
                local f = Workspace:FindFirstChild(folderName)
                if f then
                    for _, toy in ipairs(f:GetChildren()) do checkItem(toy) end
                end
            end

            -- B. My Spawned Toys
            if myFolder then
                for _, child in ipairs(myFolder:GetChildren()) do checkItem(child) end
            end

            -- C. Other Players' Spawned Toys
            for _, folder in ipairs(Workspace:GetChildren()) do
                if folder.Name:find("SpawnedInToys") and folder ~= myFolder then
                    for _, toy in ipairs(folder:GetChildren()) do checkItem(toy) end
                end
            end

            -- D. PlotItems (all plots in workspace)
            local plotItems = Workspace:FindFirstChild("PlotItems")
            if plotItems then
                for _, plotFolder in ipairs(plotItems:GetChildren()) do
                    for _, toy in ipairs(plotFolder:GetChildren()) do checkItem(toy) end
                end
            end

            -- E. Loose unanchored Models and Parts in Workspace
            for _, child in ipairs(Workspace:GetChildren()) do
                if #list >= limit then break end
                if child ~= myFolder and not child.Name:find("SpawnedInToys") and child.Name ~= "Plots" and child.Name ~= "Terrain" and child.Name ~= "Camera" then
                    if child:IsA("Model") and not child:FindFirstChildOfClass("Humanoid") then
                        checkItem(child)
                    elseif child:IsA("BasePart") and not child.Anchored then
                        checkItem(child)
                    end
                end
            end
        end        return list
    end

    local function flingAllToys()
        local items = collectAvailableToys()
        local _, myHRP = getMyChar()
        local center = myHRP and myHRP.Position or Vector3.zero
        local power = ToyAuraConfig.FlingPower or 500

        for _, entry in ipairs(items) do
            local root = entry.Root
            if root and root.Parent then
                removeMovers(entry.Model)
                pcall(function()
                    root.Anchored = false
                    claimOwnership(root)
                    local dir = (root.Position - center).Unit
                    if dir.Magnitude < 0.1 then
                        dir = Vector3.new(math.random() - 0.5, 0.5, math.random() - 0.5).Unit
                    end
                    root.AssemblyLinearVelocity = (dir * power) + Vector3.new(0, power * 0.4, 0)
                    root.AssemblyAngularVelocity = Vector3.new(math.random(-50, 50), math.random(-50, 50), math.random(-50, 50))
                end)
            end
        end
        notify("Toys Aura", string.format("Flung %d toys outward!", #items), 2)
    end

    local cachedToys = {}
    local lastToyScanTime = 0
    local netRefreshIdx = 1

    local function getCachedAvailableToys()
        local now = tick()
        if now - lastToyScanTime > 1.5 or #cachedToys == 0 then
            lastToyScanTime = now
            cachedToys = collectAvailableToys()
        else
            local valid = {}
            for _, item in ipairs(cachedToys) do
                if item.Model and item.Model.Parent and item.Root and item.Root.Parent then
                    table.insert(valid, item)
                end
            end
            cachedToys = valid
        end
        return cachedToys
    end

    local function updateToysAuraPhysics(dt)
        local items = getCachedAvailableToys()
        activeToys = items
        local count = #items
        if count == 0 then return end

        local centerPos = getCenterPosition()
        local radius = ToyAuraConfig.Radius or 25
        local height = ToyAuraConfig.Height or 20
        local spacing = ToyAuraConfig.Spacing or 1.0
        local shapeName = ToyAuraConfig.Shape or "Tornado"
        local now = tick()

        if ToyAuraConfig.AutoRotate then
            shapePhase = (shapePhase + (ToyAuraConfig.RotationSpeed or 4.0) * dt) % (math.pi * 2)
        end
        if ToyAuraConfig.AutoMove then
            movePhase = (movePhase + (ToyAuraConfig.MoveSpeed or 4.0) * dt) % count
        else
            movePhase = 0
        end
        if ToyAuraConfig.Bob then
            bobPhase = (bobPhase + (ToyAuraConfig.BobSpeed or 2.0) * dt) % (math.pi * 2)
        else
            bobPhase = 0
        end

        local rotCFrame = CFrame.Angles(
            math.rad(ToyAuraConfig.XRotation or 0),
            shapePhase + math.rad(ToyAuraConfig.YRotation or 0),
            math.rad(ToyAuraConfig.ZRotation or 0)
        )
        local bobOffset = ToyAuraConfig.Bob and Vector3.new(0, math.sin(bobPhase) * (ToyAuraConfig.BobHeight or 2.5), 0) or Vector3.zero

        -- Round-robin ownership refresh: only 2 toys per frame to prevent network spikes
        if count > 0 then
            for _ = 1, 2 do
                netRefreshIdx = ((netRefreshIdx - 1) % count) + 1
                local entry = items[netRefreshIdx]
                if entry and entry.Root and entry.Root.Parent then
                    claimOwnership(entry.Root)
                end
                netRefreshIdx = netRefreshIdx + 1
            end
        end

        for i, entry in ipairs(items) do
            local model = entry.Model
            local root = entry.Root
            if root and root.Parent then
                setModelCollisions(model, false)
                if root.Anchored then root.Anchored = false end

                -- Path interpolation for smooth cycling
                local normPoint
                if ToyAuraConfig.AutoMove and count > 1 then
                    local virtualIdx = i + movePhase
                    local idx1 = (math.floor(virtualIdx - 1) % count) + 1
                    local idx2 = (idx1 % count) + 1
                    local alpha = virtualIdx - math.floor(virtualIdx)
                    local pt1 = getPointOnShape(shapeName, idx1, count)
                    local pt2 = getPointOnShape(shapeName, idx2, count)
                    normPoint = pt1:Lerp(pt2, alpha)
                else
                    normPoint = getPointOnShape(shapeName, i, count)
                end

                if ToyAuraConfig.AutoRotate then
                    normPoint = rotCFrame * normPoint
                end

                local offset = Vector3.new(normPoint.X * radius * spacing, normPoint.Y * height, normPoint.Z * radius * spacing)
                local targetPos = centerPos + offset + bobOffset

                local targetOri
                if ToyAuraConfig.FaceCenter then
                    local lookDir = centerPos - targetPos
                    if lookDir.Magnitude > 0.1 then
                        targetOri = CFrame.lookAt(targetPos, centerPos)
                    else
                        targetOri = rotCFrame
                    end
                else
                    targetOri = rotCFrame
                end

                local mover = ensureMovers(root, model)
                if mover then
                    mover.Position.Position = targetPos
                    mover.Orientation.CFrame = targetOri
                end
            end
        end
    end

    local function startToyAura()
        if heartbeatConn then heartbeatConn:Disconnect() end
        heartbeatConn = RunService.Heartbeat:Connect(function(dt)
            if ToyAuraConfig.Enabled then
                pcall(updateToysAuraPhysics, dt)
            end
        end)
    end

    local function stopToyAura()
        if heartbeatConn then
            heartbeatConn:Disconnect()
            heartbeatConn = nil
        end
        clearAllMovers()
    end

    -- ==============================================================================
    -- UI CONSTRUCTION: Tabs.Grab / Tabs.Toy
    -- ==============================================================================
    local targetTab = (Tabs.Grab and Tabs.Grab.CreateBlock and Tabs.Grab) or Tabs.Toy
    if targetTab and targetTab.CreateBlock then
        local AuraBox = targetTab:CreateBlock({ Name = "Toys Aura & Tornado (Resonance)", Side = "Right" })

        AuraBox:CreateToggle({
            Name = "Toys Aura / Tornado Active",
            Default = false,
            Callback = function(val)
                ToyAuraConfig.Enabled = val
                if val then
                    startToyAura()
                    notify("Toys Aura", "Toy Tornado & Aura: ACTIVE!", 2)
                else
                    stopToyAura()
                    notify("Toys Aura", "Toy Tornado: Stopped", 2)
                end
            end
        })

        AuraBox:CreateDropdown({
            Name = "Formation Shape",
            Options = ShapeNamesList,
            Default = "Tornado",
            Callback = function(v)
                ToyAuraConfig.Shape = v
            end
        })

        AuraBox:CreateDropdown({
            Name = "Center Position",
            Options = { "You", "Players", "Camera Aim Point", "Custom Pos", "Lobby Spawn" },
            Default = "You",
            Callback = function(v)
                ToyAuraConfig.PosType = v
            end
        })

        local function getPlayerNamesList()
            local list = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then table.insert(list, p.Name) end
            end
            return list
        end

        local pDropdown = AuraBox:CreateDropdown({
            Name = "Target Player",
            Options = getPlayerNamesList(),
            Callback = function(name)
                ToyAuraConfig.SelectedPlayer = Players:FindFirstChild(name)
            end
        })

        AuraBox:CreateButton({
            Name = "Refresh Player List",
            Callback = function()
                local names = getPlayerNamesList()
                pDropdown:Refresh(names)
                notify("Toys Aura", "Players refreshed", 1.5)
            end
        })

        AuraBox:CreateButton({
            Name = "Set Custom Position (Current Pos)",
            Callback = function()
                local _, myHRP = getMyChar()
                if myHRP then
                    ToyAuraConfig.CustomPos = myHRP.CFrame
                    notify("Toys Aura", "Custom center position set!", 2)
                end
            end
        })

        AuraBox:CreateDropdown({
            Name = "Toy Source",
            Options = { "All Toys (Game + Players + Plot)", "My Spawned Toys Only", "Game & Map Toys Only" },
            Default = "All Toys (Game + Players + Plot)",
            Callback = function(v)
                ToyAuraConfig.Source = v
            end
        })

        AuraBox:CreateToggle({
            Name = "Auto Rotate Formation",
            Default = true,
            Callback = function(v)
                ToyAuraConfig.AutoRotate = v
            end
        })

        AuraBox:CreateSlider({
            Name = "Max Toys Limit (Anti-Lag: 35)",
            Min = 5,
            Max = 50,
            Default = 35,
            Rounding = 0,
            Callback = function(v)
                ToyAuraConfig.ToyLimit = v
            end
        })

        AuraBox:CreateToggle({
            Name = "Rip Baseplate",
            Default = false,
            Callback = function(v)
                ToyAuraConfig.IncludeBaseplate = v
            end
        })

        AuraBox:CreateButton({
            Name = "Force Grab All Toys Into Tornado",
            Callback = function()
                local items = collectAvailableToys()
                for _, entry in ipairs(items) do
                    if entry.Root then claimOwnership(entry.Root) end
                end
                notify("Toys Aura", string.format("Grabbed %d toys into tornado!", #items), 2)
            end
        })

        AuraBox:CreateButton({
            Name = "Fling All Toys Outward",
            Callback = function()
                flingAllToys()
            end
        })

        AuraBox:CreateButton({
            Name = "Release All Toys",
            Callback = function()
                ToyAuraConfig.Enabled = false
                stopToyAura()
                notify("Toys Aura", "All toys released from tornado", 2)
            end
        })
    end
end


-- HUMAN TORNADO (Player Orbit & Kasirga)
-- Placed directly below Toy Orbit in Tabs.Grab
-- ========================================================
do
    local HumanTornadoGroup = Tabs.Grab:CreateBlock({Name = "Human Tornado (Player Tornado)", Side = "Right"})

    local HumanTornadoConfig = {
        Enabled = false,
        Shape = "Tornado",
        Radius = 25,
        Height = 8,
        Speed = 4,
        FlingPower = 800,
        TargetMode = "All Players in Radius",
        SearchRadius = 80,
    }

    local HumanTornadoShapes = {
        ["Tornado"] = function(i, n, t, r, h)
            local angle = t + (i - 1) * ((math.pi * 2) / math.max(n, 1))
            local frac = i / math.max(n, 1)
            local curR = r * (0.35 + 0.65 * frac)
            local curH = h * frac + math.sin(t * 2 + i) * 1.5
            return Vector3.new(math.cos(angle) * curR, curH, math.sin(angle) * curR)
        end,
        ["Funnel Tornado"] = function(i, n, t, r, h)
            local angle = t + (i - 1) * ((math.pi * 2) / math.max(n, 1))
            local frac = 1 - (i / math.max(n, 1))
            local curR = r * (0.25 + 0.75 * frac)
            local curH = h * (i / math.max(n, 1)) + math.sin(t * 2 + i) * 1.5
            return Vector3.new(math.cos(angle) * curR, curH, math.sin(angle) * curR)
        end,
        ["Circle"] = function(i, n, t, r, h)
            local angle = t + (i - 1) * ((math.pi * 2) / math.max(n, 1))
            return Vector3.new(math.cos(angle) * r, h + math.sin(t * 3 + i) * 1.5, math.sin(angle) * r)
        end,
        ["Sphere"] = function(i, n, t, r, h)
            local phi = math.acos(-1 + (2 * (i - 1)) / math.max(n - 1, 1))
            local theta = math.sqrt(n * math.pi) * phi + t
            return Vector3.new(math.cos(theta) * math.sin(phi) * r, math.cos(phi) * r + h, math.sin(theta) * math.sin(phi) * r)
        end,
        ["Helix"] = function(i, n, t, r, h)
            local angle = t * 2 + (i - 1) * (math.pi / 2)
            local curH = ((i - 1) / math.max(n - 1, 1)) * h * 2 - h
            return Vector3.new(math.cos(angle) * r, curH + h, math.sin(angle) * r)
        end,
        ["Dome"] = function(i, n, t, r, h)
            local phi = (math.pi / 2) * (1 - (i / math.max(n, 1)))
            local theta = t + (i - 1) * ((math.pi * 2) / math.max(n, 1))
            return Vector3.new(math.cos(theta) * math.cos(phi) * r, math.sin(phi) * r + h, math.sin(theta) * math.cos(phi) * r)
        end,
    }

    local caughtPlayers = {}
    local humanTornadoThread = nil

    local function releaseHumanTornado()
        for _, plr in ipairs(caughtPlayers) do
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then
                local bp = hrp:FindFirstChild("HumanTornadoBP")
                local bg = hrp:FindFirstChild("HumanTornadoBG")
                local ap = hrp:FindFirstChild("HumanTornadoAP")
                local ao = hrp:FindFirstChild("HumanTornadoAO")
                if bp then bp:Destroy() end
                if bg then bg:Destroy() end
                if ap then ap:Destroy() end
                if ao then ao:Destroy() end
            end
        end
        table.clear(caughtPlayers)
    end

    local function getTargetsForTornado()
        local myChar = LocalPlayer.Character
        local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return {} end

        local targets = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer and plr.Character and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(plr)) then
                local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local dist = (hrp.Position - myHRP.Position).Magnitude
                    if HumanTornadoConfig.TargetMode == "Whole Server" or dist <= HumanTornadoConfig.SearchRadius then
                        table.insert(targets, plr)
                    end
                end
            end
        end
        return targets
    end

    local function updateHumanTornado()
        local myChar = LocalPlayer.Character
        local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return end

        local setNet = (ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner"))
            or ReplicatedStorage:FindFirstChild("SetNetworkOwner")
        local destroyLine = ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("DestroyGrabLine")
        local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
        local ragdollRemote = charEvents and charEvents:FindFirstChild("RagdollRemote")

        caughtPlayers = getTargetsForTornado()
        local count = #caughtPlayers
        if count == 0 then return end

        local t = tick() * HumanTornadoConfig.Speed
        local shapeFn = HumanTornadoShapes[HumanTornadoConfig.Shape] or HumanTornadoShapes["Tornado"]

        for i, plr in ipairs(caughtPlayers) do
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")

            if hrp and hum and hum.Health > 0 then
                pcall(function()
                    if setNet then
                        setNet:FireServer(hrp, hrp.CFrame)
                    end
                    if ragdollRemote then
                        ragdollRemote:FireServer(hrp, 0)
                    end
                    if destroyLine then
                        pcall(function() destroyLine:FireServer(hrp) end)
                    end

                    hum.PlatformStand = true
                    hum.AutoRotate = false

                    local offset = shapeFn(i, count, t, HumanTornadoConfig.Radius, HumanTornadoConfig.Height)
                    local targetPos = myHRP.Position + offset
                    local targetRot = CFrame.lookAt(targetPos, myHRP.Position) * CFrame.Angles(0, math.pi / 2, 0)

                    local bp = hrp:FindFirstChild("HumanTornadoBP") or Instance.new("BodyPosition", hrp)
                    bp.Name = "HumanTornadoBP"
                    bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
                    bp.P = 500000
                    bp.D = 250
                    bp.Position = targetPos

                    local bg = hrp:FindFirstChild("HumanTornadoBG") or Instance.new("BodyGyro", hrp)
                    bg.Name = "HumanTornadoBG"
                    bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
                    bg.P = 300000
                    bg.D = 180
                    bg.CFrame = targetRot

                    hrp.CFrame = targetRot
                    hrp.AssemblyLinearVelocity = Vector3.zero
                end)
            end
        end
    end

    local function setHumanTornado(active)
        HumanTornadoConfig.Enabled = active
        if active then
            if not humanTornadoThread then
                humanTornadoThread = task.spawn(function()
                    while HumanTornadoConfig.Enabled do
                        pcall(updateHumanTornado)
                        task.wait(0.04)
                    end
                    releaseHumanTornado()
                    humanTornadoThread = nil
                end)
            end
            notify("Ranax FTAP", "Human Tornado: ACTIVE!", 2)
        else
            HumanTornadoConfig.Enabled = false
            releaseHumanTornado()
            humanTornadoThread = nil
            notify("Ranax FTAP", "Human Tornado: Stopped", 2)
        end
    end

    HumanTornadoGroup:CreateToggle({
        Name = "Human Tornado Active",
        Default = false,
        Callback = function(val)
            setHumanTornado(val)
        end
    })

    HumanTornadoGroup:CreateDropdown({
        Name = "Tornado Shape",
        Items = {"Tornado", "Funnel Tornado", "Circle", "Sphere", "Helix", "Dome"},
        Default = "Tornado",
        Callback = function(val)
            HumanTornadoConfig.Shape = val or "Tornado"
        end
    })

    HumanTornadoGroup:CreateDropdown({
        Name = "Target Scope",
        Items = {"All Players in Radius", "Whole Server"},
        Default = "All Players in Radius",
        Callback = function(val)
            HumanTornadoConfig.TargetMode = val
        end
    })

    HumanTornadoGroup:CreateSlider({
        Name = "Tornado Radius",
        Min = 10,
        Max = 80,
        Default = 25,
        Callback = function(val)
            HumanTornadoConfig.Radius = val
        end
    })

    HumanTornadoGroup:CreateSlider({
        Name = "Tornado Height",
        Min = 0,
        Max = 60,
        Default = 8,
        Callback = function(val)
            HumanTornadoConfig.Height = val
        end
    })

    HumanTornadoGroup:CreateSlider({
        Name = "Rotation Speed",
        Min = 1,
        Max = 15,
        Default = 4,
        Callback = function(val)
            HumanTornadoConfig.Speed = val
        end
    })

    HumanTornadoGroup:CreateSlider({
        Name = "Detection Range",
        Min = 20,
        Max = 250,
        Default = 80,
        Callback = function(val)
            HumanTornadoConfig.SearchRadius = val
        end
    })

    HumanTornadoGroup:CreateButton({
        Name = "Force Grab All Players (Mass Grab)",
        Callback = function()
            task.spawn(function()
                local myChar = LocalPlayer.Character
                local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myHRP then return end
                local tgts = getTargetsForTornado()
                if #tgts == 0 then
                    notify("Human Tornado", "No targets found in scope!", 2)
                    return
                end
                for _, plr in ipairs(tgts) do
                    local char = plr.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local setNet = (ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner"))
                            or ReplicatedStorage:FindFirstChild("SetNetworkOwner")
                        local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
                        local ragdollRemote = charEvents and charEvents:FindFirstChild("RagdollRemote")
                        if setNet then pcall(function() setNet:FireServer(hrp, hrp.CFrame) end) end
                        if ragdollRemote then pcall(function() ragdollRemote:FireServer(hrp, 0) end) end
                        hrp.CFrame = myHRP.CFrame * CFrame.new(0, 5, -8)
                    end
                end
                setHumanTornado(true)
                notify("Human Tornado", string.format("Mass Grab: %d players caught!", #tgts), 2)
            end)
        end
    })

    HumanTornadoGroup:CreateButton({
        Name = "Fling All Caught Players (Burst)",
        Callback = function()
            task.spawn(function()
                local myChar = LocalPlayer.Character
                local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local pwr = HumanTornadoConfig.FlingPower or 800
                for _, plr in ipairs(caughtPlayers) do
                    local char = plr.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if hrp and myHRP then
                        local dir = (hrp.Position - myHRP.Position).Unit + Vector3.new(0, 0.4, 0)
                        hrp.AssemblyLinearVelocity = dir * pwr
                        local bp = hrp:FindFirstChild("HumanTornadoBP")
                        local bg = hrp:FindFirstChild("HumanTornadoBG")
                        if bp then bp:Destroy() end
                        if bg then bg:Destroy() end
                    end
                end
                setHumanTornado(false)
                notify("Ranax FTAP", "Flung all caught players!", 2)
            end)
        end
    })

    HumanTornadoGroup:CreateButton({
        Name = "Release All Players",
        Callback = function()
            setHumanTornado(false)
        end
    })
end

-- ==============================================================================
-- RESONANCE TARGET & BLOBMAN ENGINE (Ported 1:1 for VertexUI in trftap.lua)
-- ==============================================================================
do
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer
	local RunService = game:GetService("RunService")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local StarterGui = game:GetService("StarterGui")
	local UserInputService = game:GetService("UserInputService")
	local CurrentCamera = workspace.CurrentCamera

	local function notify(title, desc, duration)
		title = title or "Ranax FTAP"
		pcall(function()
			if Library and Library.Notify then
				Library:Notify({
					Title = title,
					Content = desc or "",
					Duration = duration or 3
				})
			else
				StarterGui:SetCore("SendNotification", {
					Title = title,
					Text = desc or "",
					Duration = duration or 3
				})
			end
		end)
	end

	-- Safe Remotes
	local GrabEvents = ReplicatedStorage:WaitForChild("GrabEvents", 5)
	local SetNetworkOwnerRemote = GrabEvents and GrabEvents:WaitForChild("SetNetworkOwner", 5)
	local DestroyGrabLineRemote = GrabEvents and GrabEvents:WaitForChild("DestroyGrabLine", 5)

	local MenuToys = ReplicatedStorage:FindFirstChild("MenuToys")
	local SpawnToyRemote = MenuToys and (MenuToys:FindFirstChild("SpawnToyFunction") or MenuToys:FindFirstChild("SpawnToyRemoteFunction"))
	local DestroyToyRemote = MenuToys and MenuToys:FindFirstChild("DestroyToy")

	-- Safe Platform Instance
	local SafePlatform = workspace:FindFirstChild("Safe Platform")
	if not SafePlatform then
		SafePlatform = Instance.new("Part")
		SafePlatform.Name = "Safe Platform"
		SafePlatform.Size = Vector3.new(250, 5, 250)
		SafePlatform.Position = Vector3.new(math.random(-25000, 25000), -500, math.random(-25000, 25000))
		SafePlatform.Anchored = true
		SafePlatform.CanCollide = true
		SafePlatform.Material = Enum.Material.Neon
		SafePlatform.Color = Color3.fromRGB(0, 255, 170)
		SafePlatform.Parent = workspace
	end

	-- Configuration & State
	local ResConfig = {
		TargetMethods = {
			["Kick"] = true,
			["Void"] = false,
			["Kill"] = false,
			["Bring"] = false,
			["Destroy Food"] = false,
			["Remove Gucci"] = false,
			["Remove Invisibility"] = false,
			["Delete Seatables"] = false
		},
		BlobMethod = "Kick",
		BlobKickMode = "New V2", -- "Classic" or "New V2"
		BKMethod = 1, -- 1: Grab-Drop, 2: Grab-Release
		NKDelayMode = "Normal",
		RagdollInNK = true,
		DeleteShurInNK = true,
		EKI = false,
		NKOffset = 15,
		KickServerMethod = "Circle + Lag",
		RagdollInRG = false,
		DeleteShurInBlobK = true,
		NetworkOwnerInKick = false,
		BKMethod = 1,
		BlobKickX = 0,
		BlobKickY = 25,
		BlobKickZ = 0,
		AutoSeatBlobman = false,
		FreezeBlobman = false,
		LoopTargetKick = false,
		LoopTokens = {},
		LoopApplyTargetSel = false,
		LoopApplyTargetServ = false,
		LoopApplyBlobSel = false,
		LoopApplyBlobServ = false
	}

	local SelectedTargets = {}
	local SelectedBlobTargets = {}
	local SelectedBlobTargetPlayer = nil

	-- Helper Functions
	local ResCore = {}
	local charCache = setmetatable({}, { __mode = "k" })

	function ResCore.Char(player)
		player = player or LocalPlayer
		if not player then return nil, nil, nil end
		if charCache[player] then
			local c = charCache[player].Character
			local r = charCache[player].RootPart
			local h = charCache[player].Humanoid
			if c and c.Parent and r and r.Parent and h and h.Parent then
				return c, r, h
			end
			charCache[player] = nil
		end
		local char = player.Character
		if char then
			local hrp = char:FindFirstChild("realHrp") or char:FindFirstChild("HumanoidRootPart")
			local hum = char:FindFirstChildOfClass("Humanoid")
			if hrp and hum then
				charCache[player] = { Character = char, RootPart = hrp, Humanoid = hum }
				return char, hrp, hum
			end
		end
		return char, nil, nil
	end

	function ResCore.ResetVelocity(part)
		if not part or not part:IsA("BasePart") then return false end
		if part.AssemblyAngularVelocity ~= Vector3.zero then
			part.AssemblyAngularVelocity = Vector3.zero
		end
		if part.AssemblyLinearVelocity ~= Vector3.zero then
			part.AssemblyLinearVelocity = Vector3.zero
		end
		return true
	end

	function ResCore.Teleport(part, cf, offset)
		if not part or not part:IsA("BasePart") or not cf then return false end
		if typeof(cf) == "CFrame" then
			if offset then cf = cf * offset end
			part.CFrame = cf
		elseif typeof(cf) == "Vector3" then
			part.CFrame = CFrame.new(cf)
		end
		ResCore.ResetVelocity(part)
		return true
	end

	function ResCore.IsNetworkOwner(part)
		if not (part and part:IsA("BasePart")) then return false end
		local root = part.AssemblyRootPart or part
		return not root.Anchored and root.ReceiveAge == 0
	end

	function ResCore.IsPartOwner(part)
		if not (part and part:IsA("BasePart")) then return false end
		local pOwner = part:FindFirstChild("PartOwner")
		if pOwner and pOwner.Value == LocalPlayer.Name then return true end
		local head = part.Parent and part.Parent:FindFirstChild("Head")
		local headOwner = head and head:FindFirstChild("PartOwner")
		if headOwner and headOwner.Value == LocalPlayer.Name then return true end
		return false
	end

	function ResCore.PredictCFrame(part)
		if not part or not part:IsA("BasePart") then return CFrame.new() end
		local ping = math.clamp(LocalPlayer:GetNetworkPing(), 0, 0.35)
		local vel = part.AssemblyLinearVelocity
		return part.CFrame + (vel * ping)
	end

	function ResCore.Grab(part, cf)
		local _, myHRP, myHum = ResCore.Char()
		if not myHRP or not myHum or myHum.Health <= 0 or not part or not part.Parent or not part:IsA("BasePart") then return end
		local eyeCF = (cf or myHRP.CFrame) * CFrame.new(0, 1.593, 0)
		local predCF = ResCore.PredictCFrame(part)
		local rayCF = CFrame.new(eyeCF.Position, predCF.Position)
		if SetNetworkOwnerRemote then
			pcall(function()
				SetNetworkOwnerRemote:FireServer(part, rayCF)
			end)
		end
	end

	function ResCore.RNO(part)
		if DestroyGrabLineRemote and part then
			pcall(function()
				DestroyGrabLineRemote:FireServer(part)
			end)
		end
	end

	function ResCore.SNO(part, duration)
		local myChar, myHRP, myHum = ResCore.Char()
		local myHead = myChar and myChar:FindFirstChild("Head")
		if not (myHRP and myHum and myHum.Health > 0 and part and part:IsA("BasePart")) then return false end
		if ResCore.IsPartOwner(part) then return true end

		local endTime = tick() + (duration or 0.65)
		local distance = (myHRP.Position - part.Position).Magnitude
		local far = distance >= 31

		local savedCF = myHRP.CFrame
		local savedHeadCF = myHead and myHead.CFrame or savedCF

		if far then
			pcall(function()
				RunService:BindToRenderStep("ResClientCamLock", Enum.RenderPriority.Camera.Value - 1, function()
					if myHRP and myHRP.Parent then myHRP.CFrame = savedCF end
					if myHead and myHead.Parent then myHead.CFrame = savedHeadCF end
				end)
			end)
		end

		while tick() < endTime and part.Parent and not ResCore.IsPartOwner(part) and myHum.Health > 0 do
			local predCF = ResCore.PredictCFrame(part)
			local grabUnderCF = predCF - Vector3.new(0, 22, 0)
			if far and myHRP.Parent then
				myHRP.CFrame = grabUnderCF
			end
			ResCore.Grab(part, grabUnderCF)
			RunService.Heartbeat:Wait()
		end

		if far then
			pcall(function() RunService:UnbindFromRenderStep("ResClientCamLock") end)
			if myHRP and myHRP.Parent then
				myHRP.CFrame = savedCF
				myHRP.AssemblyLinearVelocity = Vector3.zero
			end
			if myHead and myHead.Parent then
				myHead.CFrame = savedHeadCF
			end
		end

		return ResCore.IsPartOwner(part)
	end

	function ResCore.CreateAlign(part, withOrientation)
		if not part or not part:IsA("BasePart") then return nil, nil end
		local att = Instance.new("Attachment")
		att.Name = "ResAttachment"
		att.Parent = part

		local pos = Instance.new("AlignPosition")
		pos.Mode = Enum.PositionAlignmentMode.OneAttachment
		pos.MaxForce = math.huge
		pos.Responsiveness = 200
		pos.Attachment0 = att
		pos.Parent = part

		pos.Destroying:Once(function()
			pcall(function() att:Destroy() end)
		end)

		if withOrientation then
			local ori = Instance.new("AlignOrientation")
			ori.Mode = Enum.OrientationAlignmentMode.OneAttachment
			ori.MaxTorque = math.huge
			ori.Responsiveness = 200
			ori.Attachment0 = att
			ori.Parent = part

			ori.Destroying:Once(function()
				pcall(function() att:Destroy() end)
			end)
			return pos, ori
		end
		return pos
	end

	function ResCore.RemoveSticky(char)
		if not char then return end
		for _, child in ipairs(char:GetDescendants()) do
			if child:IsA("BasePart") and (child.Name == "PartHitDetector" or child.Name:find("Shuriken") or child.Name:find("Sticky")) then
				pcall(function() child:Destroy() end)
			end
		end
	end

	local LimbOffsetsRL = {
		Head = CFrame.new(0, 1.5, 0),
		["Left Arm"] = CFrame.new(-1.5, 0, 0),
		["Right Arm"] = CFrame.new(1.5, 0, 0),
		["Left Leg"] = CFrame.new(-0.5, -2, 0),
		["Right Leg"] = CFrame.new(0.5, -2, 0),
		Torso = CFrame.new()
	}

	function ResCore.ToggleMotor6D(char, enabled, toggleSockets)
		if not char then return end
		local hum = char:FindFirstChild("Humanoid")
		local torso = char:FindFirstChild("Torso")
		local rag = hum and hum:FindFirstChild("Ragdolled")
		if not torso or not rag then return end

		if not rag.Value then
			for _, m in ipairs(torso:GetChildren()) do
				if m:IsA("Motor6D") then
					m.Enabled = enabled
				end
			end
		end

		if toggleSockets and (enabled == false or rag.Value) then
			for _, limbName in ipairs({ "Left Leg", "Right Leg", "Left Arm", "Right Arm", "Head" }) do
				local limb = char:FindFirstChild(limbName)
				local bsc = limb and limb:FindFirstChild("BallSocketConstraint")
				if bsc then
					bsc.Enabled = enabled
				end
			end
		end
	end

	function ResCore.RepositionLimbs(char, resetVel)
		local hrp = char:FindFirstChild("HumanoidRootPart")
		local torso = char:FindFirstChild("Torso")
		if not hrp or not torso then return end
		local neck = torso:FindFirstChild("Neck")
		if neck and neck.Enabled then return end
		local look = hrp.CFrame.LookVector
		local planar = Vector3.new(look.X, 0, look.Z)
		if planar.Magnitude < 0.001 then return end
		local cf = CFrame.lookAt(hrp.Position, hrp.Position + planar.Unit)

		for limbName, offset in pairs(LimbOffsetsRL) do
			local limb = char:FindFirstChild(limbName)
			if limb and limb:IsA("BasePart") then
				local targetCF = cf * offset
				if limb.CFrame ~= targetCF then
					limb.CFrame = targetCF
				end
				if resetVel then
					ResCore.ResetVelocity(limb)
				end
			end
		end
	end

	function ResCore.ToggleCollisions(char, canCollide)
		if canCollide == nil then canCollide = false end
		for _, child in ipairs(char:GetChildren()) do
			if child:IsA("BasePart") then
				local flag
				if canCollide then
					flag = (child.Name == "Torso" or child.Name == "Head")
				else
					flag = canCollide
				end
				if flag then
					if child.CanCollide ~= canCollide then child.CanCollide = canCollide end
				elseif not canCollide then
					if child.CanCollide ~= canCollide then child.CanCollide = canCollide end
					local ragPart = child:FindFirstChild("RagdollLimbPart")
					if ragPart and ragPart.CanCollide then ragPart.CanCollide = false end
				end
			end
		end
	end

	function ResCore.SpawnToy(toyName, cframe)
		if not SpawnToyRemote then return nil end
		local _, myHRP = ResCore.Char()
		local spawnCF = cframe or (myHRP and myHRP.CFrame + Vector3.new(0, 15, 0)) or CFrame.new(0, 25, 0)
		local spawnedToy = nil
		local spawnedToysFolder = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys") or workspace

		local conn = spawnedToysFolder.ChildAdded:Connect(function(child)
			if child.Name == toyName then
				spawnedToy = child
			end
		end)

		task.spawn(function()
			pcall(function()
				SpawnToyRemote:InvokeServer(toyName, spawnCF, Vector3.zero)
			end)
		end)

		local t0 = tick()
		while not spawnedToy and (tick() - t0 < 1.5) do
			RunService.Heartbeat:Wait()
		end
		pcall(function() conn:Disconnect() end)
		return spawnedToy
	end

	function ResCore.DestroyToy(toy)
		if DestroyToyRemote and toy and toy:IsA("Model") then
			pcall(function()
				DestroyToyRemote:FireServer(toy)
			end)
		end
	end

	function ResCore.GetInventory(player)
		if not player then return nil, nil end
		local spawnedToys = workspace:FindFirstChild(player.Name .. "SpawnedInToys")
		local plotItems = nil
		if workspace:FindFirstChild("Plots") then
			for _, plot in ipairs(workspace.Plots:GetChildren()) do
				local sign = plot:FindFirstChild("PlotSign")
				local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
				if owners then
					for _, ownerVal in ipairs(owners:GetChildren()) do
						if ownerVal:IsA("StringValue") and ownerVal.Value == player.Name then
							plotItems = workspace:FindFirstChild("PlotItems") and workspace.PlotItems:FindFirstChild(plot.Name)
							break
						end
					end
				end
			end
		end
		return spawnedToys, plotItems
	end

	function ResCore.BreakHoldable(model, timeout)
		local myChar, _, myHum = ResCore.Char()
		local leftArm = myChar and myChar:FindFirstChild("Left Arm")
		local leftGrip = leftArm and leftArm:FindFirstChild("LeftGripAttachment")
		local holdPart = model and model:FindFirstChild("HoldPart")
		local holdRemote = holdPart and holdPart:WaitForChild("HoldItemRemoteFunction", 0.5)
		local dropRemote = holdRemote and holdPart:WaitForChild("DropItemRemoteFunction", 0.5)
		local rigid = dropRemote and holdPart:WaitForChild("RigidConstraint", 0.5)
		if not (myChar and myHum and leftGrip and holdRemote and dropRemote and rigid) then return false end

		rigid.Enabled = false
		local t0 = tick()
		while tick() - t0 < (timeout or 0.6) do
			pcall(function() holdRemote:InvokeServer(model, myChar) end)
			task.wait()
			if rigid.Attachment1 == leftGrip then break end
		end

		pcall(function() dropRemote:InvokeServer(model) end)
		pcall(function() dropRemote:Destroy() end)
		return true
	end

	-- ==============================================================================
	-- BLOBMAN ENGINE (tbl14 1:1)
	-- ==============================================================================
	local ResBlobman = {
		Frozen = false,
		FreezeBP = nil,
		FreezeBG = nil,
		FreezeConn = nil,
		KickServerCooldowns = setmetatable({}, { __mode = "k" })
	}

	function ResBlobman.GetBlobman()
		local _, _, myHum = ResCore.Char()
		if myHum and myHum.SeatPart and myHum.SeatPart.Parent and myHum.SeatPart.Parent.Name == "CreatureBlobman" then
			return myHum.SeatPart.Parent
		end
		local spawnedFolder = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
		if spawnedFolder then
			local b = spawnedFolder:FindFirstChild("CreatureBlobman")
			if b then return b end
		end
		return workspace:FindFirstChild("CreatureBlobman")
	end

	function ResBlobman.GetComponents()
		local blob = ResBlobman.GetBlobman()
		if not blob then return nil end
		local bsaos = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
		local rightDet = blob:FindFirstChild("RightDetector")
		local leftDet = blob:FindFirstChild("LeftDetector")
		return {
			Blobman = blob,
			BSAOS = bsaos,
			CreatureGrab = bsaos and bsaos:FindFirstChild("CreatureGrab"),
			CreatureDrop = bsaos and bsaos:FindFirstChild("CreatureDrop"),
			CreatureRelease = bsaos and bsaos:FindFirstChild("CreatureRelease"),
			RightDetector = rightDet,
			RightWeld = rightDet and rightDet:FindFirstChild("RightWeld"),
			RightOri = rightDet and rightDet:FindFirstChild("RightAlignOrientation"),
			LeftDetector = leftDet,
			LeftWeld = leftDet and leftDet:FindFirstChild("LeftWeld"),
			LeftOri = leftDet and leftDet:FindFirstChild("LeftAlignOrientation")
		}
	end

	function ResBlobman.SetFrozen(enabled)
		ResConfig.FreezeBlobman = enabled
		if ResBlobman.FreezeConn then
			ResBlobman.FreezeConn:Disconnect()
			ResBlobman.FreezeConn = nil
		end
		if ResBlobman.FreezeBP then
			pcall(function() ResBlobman.FreezeBP:Destroy() end)
			ResBlobman.FreezeBP = nil
		end
		if ResBlobman.FreezeBG then
			pcall(function() ResBlobman.FreezeBG:Destroy() end)
			ResBlobman.FreezeBG = nil
		end

		if not enabled then return end
		local blob = ResBlobman.GetBlobman()
		local hrp = blob and blob:FindFirstChild("HumanoidRootPart")
		if not hrp then return end

		ResBlobman.FreezeBP = Instance.new("BodyPosition")
		ResBlobman.FreezeBP.Name = "FreezeBP"
		ResBlobman.FreezeBP.Position = hrp.Position
		ResBlobman.FreezeBP.MaxForce = Vector3.one * math.huge
		ResBlobman.FreezeBP.D = 500
		ResBlobman.FreezeBP.Parent = hrp

		ResBlobman.FreezeBG = Instance.new("BodyGyro")
		ResBlobman.FreezeBG.Name = "FreezeBG"
		ResBlobman.FreezeBG.CFrame = hrp.CFrame
		ResBlobman.FreezeBG.MaxTorque = Vector3.one * math.huge
		ResBlobman.FreezeBG.D = 500
		ResBlobman.FreezeBG.Parent = hrp

		ResBlobman.FreezeConn = RunService.Heartbeat:Connect(function()
			if not ResConfig.FreezeBlobman or not hrp.Parent then
				ResBlobman.SetFrozen(false)
				return
			end
			ResCore.ResetVelocity(hrp)
		end)
	end

	function ResBlobman.Sit()
		local _, myHRP, myHum = ResCore.Char()
		if not (myHRP and myHum and myHum.Health > 0) then return end
		if myHum.Sit and myHum.SeatPart and myHum.SeatPart.Parent and myHum.SeatPart.Parent.Name == "CreatureBlobman" then
			return
		end

		local spawnedFolder = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
		local blob = (spawnedFolder and spawnedFolder:FindFirstChild("CreatureBlobman")) or workspace:FindFirstChild("CreatureBlobman")
		local seat = blob and blob:FindFirstChild("VehicleSeat")

		local isValidSeat = seat and (seat.Occupant == nil or seat.Occupant == myHum)
		if seat and not isValidSeat then
			ResCore.DestroyToy(blob)
		end

		if not (isValidSeat and blob) then
			blob = ResCore.SpawnToy("CreatureBlobman")
		end

		if not (isValidSeat and seat) then
			seat = blob and (blob:FindFirstChild("VehicleSeat") or blob:WaitForChild("VehicleSeat", 0.5))
		end

		if not seat then
			if blob then ResCore.DestroyToy(blob) end
			return
		end

		local savedCF = myHRP.CFrame
		local t0 = tick()
		while tick() - t0 < 1 do
			pcall(function() seat:Sit(myHum) end)
			task.wait()
			if myHum.SeatPart == seat then break end
		end

		if myHum.SeatPart == seat then
			ResCore.Teleport(myHRP, savedCF)
		end
	end

	function ResBlobman.EnsureSeated()
		local _, _, myHum = ResCore.Char()
		if not (myHum and myHum.SeatPart and myHum.SeatPart.Parent and myHum.SeatPart.Parent.Name == "CreatureBlobman") then
			ResBlobman.Sit()
			task.wait(0.15)
		end
		local _, _, hum = ResCore.Char()
		return hum and hum.SeatPart and hum.SeatPart.Parent and hum.SeatPart.Parent.Name == "CreatureBlobman"
	end

	function ResBlobman.TeleportBlob(targetCF)
		local blob = ResBlobman.GetBlobman()
		if not blob then return end
		local seat = blob:FindFirstChild("VehicleSeat")
		local bHRP = blob:FindFirstChild("HumanoidRootPart") or blob.PrimaryPart or seat
		local _, myHRP = ResCore.Char()

		pcall(function()
			blob:PivotTo(targetCF)
		end)
		if seat then
			seat.CFrame = targetCF
			seat.AssemblyLinearVelocity = Vector3.zero
			seat.AssemblyAngularVelocity = Vector3.zero
		end
		if bHRP and bHRP:IsA("BasePart") then
			bHRP.CFrame = targetCF
			bHRP.AssemblyLinearVelocity = Vector3.zero
			bHRP.AssemblyAngularVelocity = Vector3.zero
		end
		if myHRP then
			myHRP.CFrame = targetCF
			myHRP.AssemblyLinearVelocity = Vector3.zero
			myHRP.AssemblyAngularVelocity = Vector3.zero
		end
		if ResBlobman.FreezeBP and ResBlobman.FreezeBP.Parent then
			ResBlobman.FreezeBP.Position = targetCF.Position
		end
		if ResBlobman.FreezeBG and ResBlobman.FreezeBG.Parent then
			ResBlobman.FreezeBG.CFrame = targetCF
		end
	end

	function ResBlobman.FetchTarget(target, homeCF)
		if not target or TR_IsWhitelisted(target) then return false end
		if not ResBlobman.EnsureSeated() then return false end
		local comp = ResBlobman.GetComponents()
		if not (comp and comp.CreatureGrab and comp.CreatureRelease and comp.RightWeld and comp.Blobman) then return false end
		local _, myHRP, myHum = ResCore.Char()
		local tChar, tHRP, tHum = ResCore.Char(target)
		if not (myHRP and myHum and myHum.Health > 0 and tHRP and tHum and tHum.Health > 0) then return false end
		local rootAtt = tHRP:FindFirstChild("RootAttachment") or (tChar and tChar:FindFirstChild("RootAttachment"))
		if not rootAtt then return false end
		if rootAtt.Parent ~= tHRP then
			pcall(function() rootAtt.Parent = tHRP end)
		end

		local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
		local ragdollRemote = charEvents and (charEvents:FindFirstChild("Ragdoll") or charEvents:FindFirstChild("RagdollRemote"))

		comp.RightWeld.Enabled = false
		if comp.RightOri then comp.RightOri.Enabled = false end

		-- 1:1 Resonance tbl14.Release ownership acquisition loop
		local t0 = tick()
		while tick() - t0 < 0.65 and tHRP.Parent and myHum.Health > 0 and tHum.Health > 0 and not ResCore.IsNetworkOwner(tHRP) do
			local predCF = ResCore.PredictCFrame(tHRP)
			local approachCF = predCF * CFrame.new(0, 0, -3.2) * CFrame.Angles(0, math.pi, 0)
			ResBlobman.TeleportBlob(approachCF)
			comp.RightWeld.Enabled = false
			if ragdollRemote then
				pcall(function() ragdollRemote:FireServer(tHRP, 0) end)
			end
			ResCore.Grab(tHRP)
			task.wait(0.012)
			pcall(function()
				comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld)
			end)
			task.wait(0.012)
			pcall(function()
				comp.CreatureRelease:FireServer(comp.RightWeld)
			end)
		end

		-- Teleport victim to kickCF WHILE we hold network ownership, then return Blobman home
		local kickCF = homeCF * CFrame.new(ResConfig.BlobKickX, ResConfig.BlobKickY, ResConfig.BlobKickZ)
		ResCore.Teleport(tHRP, kickCF)
		ResBlobman.TeleportBlob(homeCF)
		tHRP.CFrame = kickCF
		ResCore.ResetVelocity(tHRP)
		-- Clear GrabLine (PartOwner) immediately so FTAP server does NOT exempt player from Flying kick!
		ResCore.RNO(tHRP)

		return ResCore.IsNetworkOwner(tHRP) or (tHRP.Position - kickCF.Position).Magnitude < 35
	end

	function ResBlobman.Grab(target, duration)
		if not ResBlobman.EnsureSeated() then return false end
		local comp = ResBlobman.GetComponents()
		if not (comp and comp.CreatureGrab and comp.RightWeld) then return false end
		local _, myHRP, myHum = ResCore.Char()
		local _, tHRP, tHum = ResCore.Char(target)
		if not (myHRP and myHum and myHum.Health > 0 and tHRP and tHum and tHum.Health > 0) then return false end

		local rootAtt = tHRP:FindFirstChild("RootAttachment")
		if not rootAtt then return false end

		local dist = (myHRP.Position - tHRP.Position).Magnitude
		if dist > 15 then
			local savedCF = myHRP.CFrame
			local approachCF = tHRP.CFrame * CFrame.new(0, 0, -3.2) * CFrame.Angles(0, math.pi, 0)
			ResBlobman.TeleportBlob(approachCF)
			task.wait(0.03)
			pcall(function() comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld) end)
			ResCore.Grab(tHRP)
			ResBlobman.TeleportBlob(savedCF)
		else
			pcall(function() comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld) end)
			ResCore.Grab(tHRP)
			task.wait(0.03)
		end

		return comp.RightWeld.Attachment0 == rootAtt or ResCore.IsNetworkOwner(tHRP)
	end

	function ResBlobman.Release(target, duration)
		if not ResBlobman.EnsureSeated() then return false end
		local comp = ResBlobman.GetComponents()
		if not (comp and comp.CreatureGrab and comp.CreatureRelease and comp.RightWeld) then return false end
		local _, myHRP, myHum = ResCore.Char()
		local _, tHRP, tHum = ResCore.Char(target)
		if not (myHRP and myHum and myHum.Health > 0 and tHRP and tHum and tHum.Health > 0) then return false end
		if ResCore.IsNetworkOwner(tHRP) then return true end

		comp.RightWeld.Enabled = false
		local savedCF = myHRP.CFrame
		local t0 = tick()
		local maxWait = duration or 0.65

		while tick() - t0 < maxWait and tHRP.Parent and myHum.Health > 0 and tHum.Health > 0 and not ResCore.IsNetworkOwner(tHRP) do
			local predCF = ResCore.PredictCFrame(tHRP)
			if (myHRP.Position - tHRP.Position).Magnitude >= 25 then
				ResBlobman.TeleportBlob(predCF - Vector3.new(0, 15, 0))
			end
			comp.RightWeld.Enabled = false
			task.wait(0.0111)
			pcall(function() comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld) end)
			task.wait(0.0111)
			pcall(function() comp.CreatureRelease:FireServer(comp.RightWeld) end)
		end

		if myHRP.Parent then
			ResBlobman.TeleportBlob(savedCF)
		end

		task.delay(0.1, function()
			pcall(function()
				if comp.RightWeld and comp.RightWeld.Parent then
					comp.RightWeld.Attachment0 = nil
					comp.RightWeld.Enabled = true
				end
			end)
		end)

		return ResCore.IsNetworkOwner(tHRP)
	end

	function ResBlobman.KickClassic(target)
		if not target or TR_IsWhitelisted(target) then return false end
		if not ResBlobman.EnsureSeated() then return false end
		local comp = ResBlobman.GetComponents()
		local _, myHRP, myHum = ResCore.Char()
		if not (comp and comp.CreatureGrab and comp.CreatureDrop and comp.RightWeld and myHRP and myHum and myHum.Health > 0) then return false end

		local tChar, tHRP, tHum = ResCore.Char(target)
		if not (tHRP and tHum and tHum.Health > 0 and not tHum.SeatPart) then return false end
		if (tHRP.AssemblyRootPart or tHRP).Massless then return false end

		pcall(function() comp.CreatureDrop:FireServer(comp.RightWeld) end)

		local homeCF = ResBlobman.SavedHomeCF or myHRP.CFrame

		-- Fetch target from wherever they are and bring back to homeCF immediately
		ResBlobman.FetchTarget(target, homeCF)

		comp.RightWeld.Enabled = false
		local kickCF = homeCF * CFrame.new(ResConfig.BlobKickX, ResConfig.BlobKickY, ResConfig.BlobKickZ)
		ResCore.Teleport(tHRP, kickCF)
		local alignPos, alignOri = ResCore.CreateAlign(tHRP, true)
		if alignPos then alignPos.Position = kickCF.Position end
		if alignOri then alignOri.CFrame = kickCF - kickCF.Position end

		task.wait(0.03)

		if tHRP.Parent then
			ResCore.Grab(tHRP)
			ResCore.RNO(tHRP)
			pcall(function()
				comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld)
				task.wait(0.02)
				comp.CreatureDrop:FireServer(comp.RightWeld)
			end)

			if ResConfig.DeleteShurInBlobK then
				task.spawn(ResCore.RemoveSticky, tChar)
			end
		end

		pcall(function() comp.CreatureGrab:FireServer(nil, myHRP, comp.RightWeld) end)

		pcall(function()
			if comp.RightWeld and comp.RightWeld.Parent then
				comp.RightWeld.Attachment0 = nil
				comp.RightWeld.Enabled = true
			end
			if alignOri and alignOri.Parent then alignOri:Destroy() end
			if alignPos and alignPos.Parent then alignPos:Destroy() end
		end)

		return true
	end

	function ResBlobman.KickV2(target)
		if not target or TR_IsWhitelisted(target) then return false end
		if not ResBlobman.EnsureSeated() then return false end
		local comp = ResBlobman.GetComponents()
		local _, myHRP, myHum = ResCore.Char()
		if not (comp and comp.CreatureGrab and comp.CreatureDrop and comp.RightWeld and myHRP and myHum and myHum.Health > 0) then return false end

		local tChar, tHRP, tHum = ResCore.Char(target)
		local rootAtt = tHRP and (tHRP:FindFirstChild("RootAttachment") or (tChar and tChar:FindFirstChild("RootAttachment")))
		if not (tHRP and tHum and tHum.Health > 0) then return false end
		if rootAtt and rootAtt.Parent ~= tHRP then
			pcall(function() rootAtt.Parent = tHRP end)
		end

		pcall(function() comp.CreatureDrop:FireServer(comp.RightWeld) end)

		local homeCF = ResBlobman.SavedHomeCF or myHRP.CFrame
		-- 1. Acquire true network ownership via Blobman Release & bring target to homeCF
		ResBlobman.FetchTarget(target, homeCF)

		comp.RightWeld.Enabled = false
		if comp.RightOri then comp.RightOri.Enabled = false end

		local weldHRP = tHRP:FindFirstChild("WeldHRP")
		if weldHRP then weldHRP.Enabled = false end

		-- 2. 1:1 Resonance tbl14.KickTargets: position at (0, 5, -20) or offset, align & wait 0.35s WITHOUT grab spam
		local kickCF = homeCF * CFrame.new(ResConfig.BlobKickX, math.max(5, ResConfig.BlobKickY), -20)
		ResCore.Teleport(tHRP, kickCF)
		local alignPos, alignOri = ResCore.CreateAlign(tHRP, true)
		if alignPos then alignPos.Position = kickCF.Position end
		if alignOri then alignOri.CFrame = kickCF - kickCF.Position end

		task.wait(0.35)

		if tHRP.Parent then
			ResCore.Grab(tHRP)
			ResCore.RNO(tHRP)
			pcall(function()
				comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld)
			end)
			if ResConfig.DeleteShurInBlobK then
				task.spawn(ResCore.RemoveSticky, tChar)
			end
			task.wait()
		end

		-- 3. Switch RightWeld to myHRP (leaves victim airborne with PartOwner == nil so server flags "Flying" -> BlackHoleKick)
		pcall(function() comp.CreatureGrab:FireServer(nil, myHRP, comp.RightWeld) end)
		if sethiddenproperty and ResCore.IsNetworkOwner(tHRP) then
			pcall(sethiddenproperty, tHRP, "PhysicsRepRootPart", tHRP)
		end

		local endClock = os.clock() + 2.0
		while os.clock() < endClock and target.Parent and tHRP.Parent and tHum.Parent and tHum.Health > 0 do
			tHRP.CFrame = kickCF
			ResCore.ResetVelocity(tHRP)
			RunService.Heartbeat:Wait()
		end

		pcall(function()
			if sethiddenproperty and tHRP and tHRP.Parent then
				pcall(sethiddenproperty, tHRP, "PhysicsRepRootPart", nil)
			end
			if weldHRP and weldHRP.Parent and tHum and tHum:FindFirstChild("Ragdolled") and tHum.Ragdolled.Value then
				weldHRP.Enabled = true
			end
			if comp.RightWeld and comp.RightWeld.Parent then
				comp.RightWeld.Attachment0 = nil
				comp.RightWeld.Enabled = true
			end
			if alignOri and alignOri.Parent then alignOri:Destroy() end
			if alignPos and alignPos.Parent then alignPos:Destroy() end
		end)

		return true
	end

	function ResBlobman.Kick(target)
		if ResConfig.BlobKickMode == "Classic" then
			return ResBlobman.KickClassic(target)
		end
		return ResBlobman.KickV2(target)
	end

	function ResBlobman.LoopKickClassic(target)
		if not target or TR_IsWhitelisted(target) then return end
		if not ResBlobman.EnsureSeated() then return end
		local comp = ResBlobman.GetComponents()
		local _, myHRP, myHum = ResCore.Char()
		if not (comp and comp.CreatureGrab and comp.CreatureDrop and comp.CreatureRelease and comp.RightWeld and comp.RightOri and myHRP and myHum and myHum.Health > 0) then return end

		local tChar, tHRP, tHum = ResCore.Char(target)
		local rootAtt = tHRP and tHRP:FindFirstChild("RootAttachment")
		if not (tHRP and tHum and tHum.Health > 0 and rootAtt) then return end
		if (tHRP.AssemblyRootPart or tHRP).Massless then return end

		comp.RightWeld.Enabled = false
		comp.RightOri.Enabled = false

		if not ResBlobman.SavedHomeCF then
			ResBlobman.SavedHomeCF = myHRP.CFrame
		end
		local homeCF = ResBlobman.SavedHomeCF

		-- Fetch target to home location
		ResBlobman.FetchTarget(target, homeCF)

		tHum.Sit = true
		task.delay(0.5, function()
			if tHum and tHum.Parent then tHum.Sit = false end
		end)

		local kickOffset = CFrame.new(ResConfig.BlobKickX, ResConfig.BlobKickY, ResConfig.BlobKickZ)
		local kickCF = homeCF * kickOffset
		ResCore.Teleport(tHRP, kickCF)
		local alignPos, alignOri = ResCore.CreateAlign(tHRP, true)
		if alignPos then alignPos.Position = kickCF.Position end

		task.delay(0.2, function()
			ResCore.Grab(tHRP)
			ResCore.RNO(tHRP)
		end)

		pcall(function()
			comp.CreatureDrop:FireServer(comp.RightWeld)
			if comp.LeftWeld then comp.CreatureDrop:FireServer(comp.LeftWeld) end
		end)
		task.wait(0.06)
		rootAtt.Parent = tChar

		while target.Parent and tHRP.Parent and tHum.Parent and tHum.Health > 0
			and myHum.SeatPart and ResConfig.LoopTargetKick and not TR_IsWhitelisted(target) and ResConfig.BlobKickMode == "Classic" do

			task.spawn(function()
				tHum.RequiresNeck = false
				ResCore.ToggleMotor6D(tChar, false, true)
				ResCore.RepositionLimbs(tChar)
			end)
			task.spawn(ResCore.ToggleCollisions, tChar, false)

			comp.RightOri.Enabled = false
			comp.RightWeld.Enabled = false
			comp.RightOri.Attachment0 = nil
			comp.RightWeld.Attachment0 = nil

			local curPos = (homeCF * kickOffset).Position
			if alignPos and alignPos.Parent then alignPos.Position = curPos end
			ResCore.ResetVelocity(tHRP)

			if ResConfig.DeleteShurInBlobK then
				task.spawn(ResCore.RemoveSticky, tChar)
			end

			if ResConfig.BKMethod == 1 then
				pcall(function()
					comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld)
					task.wait()
					comp.CreatureDrop:FireServer(comp.RightWeld)
					task.wait()
				end)
				if ResConfig.NetworkOwnerInKick then
					ResCore.Grab(tHRP)
					ResCore.RNO(tHRP)
				end
			else
				pcall(function()
					comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld)
					task.wait()
					comp.CreatureRelease:FireServer(comp.RightWeld)
					ResCore.Grab(tHRP)
					task.wait()
				end)
			end
		end

		pcall(function()
			if rootAtt and rootAtt.Parent then rootAtt.Parent = tHRP end
			task.spawn(ResCore.ToggleMotor6D, tChar, true)
			task.spawn(ResCore.ToggleCollisions, tChar, true)
			if alignOri and alignOri.Parent then alignOri:Destroy() end
			if alignPos and alignPos.Parent then alignPos:Destroy() end
			if comp.RightWeld and comp.RightWeld.Parent then
				comp.RightWeld.Attachment0 = nil
				comp.RightWeld.Enabled = true
			end
		end)
	end

	function ResBlobman.LoopKickV2(target)
		if not target or TR_IsWhitelisted(target) then return end
		if not ResBlobman.EnsureSeated() then return end
		local comp = ResBlobman.GetComponents()
		local _, myHRP, myHum = ResCore.Char()
		if not (comp and comp.CreatureGrab and comp.CreatureDrop and comp.CreatureRelease and comp.RightWeld and comp.RightOri and myHRP and myHum and myHum.Health > 0) then return end

		local tChar, tHRP, tHum = ResCore.Char(target)
		local rootAtt = tHRP and (tHRP:FindFirstChild("RootAttachment") or (tChar and tChar:FindFirstChild("RootAttachment")))
		if not (tHRP and tHum and tHum.Health > 0 and rootAtt) then return end
		if (tHRP.AssemblyRootPart or tHRP).Massless then return end

		local firePlayerPart = tHRP:FindFirstChild("FirePlayerPart")
		local fireWeld = firePlayerPart and firePlayerPart:FindFirstChild("WeldConstraint")
		local weldHRP = tHRP:FindFirstChild("WeldHRP")
		if weldHRP then weldHRP.Enabled = false end

		local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
		local ragdollRemote = charEvents and (charEvents:FindFirstChild("Ragdoll") or charEvents:FindFirstChild("RagdollRemote"))

		comp.RightWeld.Enabled = false
		comp.RightOri.Enabled = false

		if not ResBlobman.SavedHomeCF then
			ResBlobman.SavedHomeCF = myHRP.CFrame
		end
		local homeCF = ResBlobman.SavedHomeCF

		-- Step 1: Run KickV2 (Resonance 2s Self-Weld BlackHoleKick) first!
		ResBlobman.KickV2(target)
		if not (target.Parent and tHRP.Parent and tHum.Parent and tHum.Health > 0 and ResConfig.LoopTargetKick) then
			return
		end

		-- Step 2: If target survived (anti-kick / high ping), run 1:1 Resonance LoopKick + EKI PhysicsRepRootPart
		ResBlobman.FetchTarget(target, homeCF)

		tHum.Sit = true
		task.delay(0.5, function()
			if tHum and tHum.Parent then tHum.Sit = false end
		end)

		local kickOffset = CFrame.new(ResConfig.BlobKickX, ResConfig.BlobKickY, ResConfig.BlobKickZ)
		local kickCF = homeCF * kickOffset
		ResCore.Teleport(tHRP, kickCF)
		local alignPos, alignOri = ResCore.CreateAlign(tHRP, true)
		if alignPos then alignPos.Position = kickCF.Position end

		task.delay(0.2, function()
			if tHRP and tHRP.Parent then
				ResCore.Grab(tHRP)
				ResCore.RNO(tHRP)
			end
		end)

		task.delay(0.6, function()
			if sethiddenproperty and tHRP and tHRP.Parent and ResCore.IsNetworkOwner(tHRP) then
				pcall(sethiddenproperty, tHRP, "PhysicsRepRootPart", tHRP)
			end
		end)

		pcall(function()
			comp.CreatureDrop:FireServer(comp.RightWeld)
			if comp.LeftWeld then comp.CreatureDrop:FireServer(comp.LeftWeld) end
		end)
		task.wait(0.06)
		rootAtt.Parent = tChar

		local loopStart = os.clock()

		while target.Parent and tHRP.Parent and tHum.Parent and tHum.Health > 0
			and myHum.SeatPart and ResConfig.LoopTargetKick and not TR_IsWhitelisted(target) and ResConfig.BlobKickMode ~= "Classic" do

			kickOffset = CFrame.new(ResConfig.BlobKickX, ResConfig.BlobKickY, ResConfig.BlobKickZ)
			kickCF = homeCF * kickOffset

			-- Re-fetch if target dropped out of 41-stud ownership range
			if (myHRP.Position - tHRP.Position).Magnitude > 41 then
				pcall(function() rootAtt.Parent = tHRP end)
				ResBlobman.FetchTarget(target, homeCF)
				ResCore.Teleport(tHRP, kickCF)
				task.wait(0.05)
				pcall(function() rootAtt.Parent = tChar end)
			end

			-- Every 4.5s re-trigger the 2s Self-Weld airborne window so PartOwner is 100% nil for Flying detection
			if os.clock() - loopStart > 4.5 then
				break
			end

			if weldHRP then weldHRP.Enabled = false end

			task.spawn(function()
				tHum.RequiresNeck = false
				ResCore.ToggleMotor6D(tChar, false, true)
				ResCore.RepositionLimbs(tChar, true)
			end)
			task.spawn(ResCore.ToggleCollisions, tChar, false)

			comp.RightOri.Enabled = false
			comp.RightWeld.Enabled = false
			comp.RightOri.Attachment0 = nil
			comp.RightWeld.Attachment0 = nil

			-- Update AlignPosition ONLY (do NOT overwrite tHRP.CFrame directly so AlignPosition physics replicate!)
			if alignPos and alignPos.Parent then alignPos.Position = kickCF.Position end
			ResCore.ResetVelocity(tHRP)

			if ResConfig.DeleteShurInBlobK then
				task.spawn(ResCore.RemoveSticky, tChar)
			end

			if ResConfig.BKMethod == 1 then
				pcall(function()
					comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld)
					task.wait()
					comp.CreatureDrop:FireServer(comp.RightWeld)
					task.wait()
				end)
				if ResConfig.NetworkOwnerInKick then
					ResCore.Grab(tHRP)
					ResCore.RNO(tHRP)
				end
			else
				pcall(function()
					comp.CreatureGrab:FireServer(nil, tHRP, comp.RightWeld)
					task.wait()
					comp.CreatureRelease:FireServer(comp.RightWeld)
					ResCore.Grab(tHRP)
					if ragdollRemote then
						task.spawn(function() pcall(function() ragdollRemote:FireServer(tHRP, 0.5) end) end)
					end
					if not fireWeld or fireWeld.Enabled then
						ResCore.RNO(tHRP)
					end
					task.wait()
				end)
			end
		end

		pcall(function()
			if sethiddenproperty and tHRP and tHRP.Parent then
				pcall(sethiddenproperty, tHRP, "PhysicsRepRootPart", nil)
			end
			if weldHRP and weldHRP.Parent and tHum and tHum:FindFirstChild("Ragdolled") and tHum.Ragdolled.Value then
				weldHRP.Enabled = true
			end
			if rootAtt and rootAtt.Parent and tHRP and tHRP.Parent then rootAtt.Parent = tHRP end
			task.spawn(ResCore.ToggleMotor6D, tChar, true)
			task.spawn(ResCore.ToggleCollisions, tChar, true)
			if alignOri and alignOri.Parent then alignOri:Destroy() end
			if alignPos and alignPos.Parent then alignPos:Destroy() end
			if comp.RightWeld and comp.RightWeld.Parent then
				comp.RightWeld.Attachment0 = nil
				comp.RightWeld.Enabled = true
			end
		end)
	end

	function ResBlobman.LoopKick(target)
		if ResConfig.BlobKickMode == "Classic" then
			return ResBlobman.LoopKickClassic(target)
		end
		return ResBlobman.LoopKickV2(target)
	end

	function ResBlobman.Bring(target)
		if TR_IsWhitelisted(target) then return false end
		local _, tHRP, tHum = ResCore.Char(target)
		local _, myHRP = ResCore.Char()
		if tHRP and myHRP and tHum and tHum.Health > 0 then
			ResCore.Grab(tHRP)
			ResCore.Teleport(tHRP, myHRP.CFrame * CFrame.new(0, 0, -5))
			ResCore.ResetVelocity(tHRP)
			return true
		end
		return false
	end

	function ResBlobman.Kill(target)
		if TR_IsWhitelisted(target) then return false end
		local _, tHRP, tHum = ResCore.Char(target)
		if not (tHRP and tHum and tHum.Health > 0) then return end
		tHum.BreakJointsOnDeath = false
		tHum:ChangeState(Enum.HumanoidStateType.Dead)
		ResCore.Grab(tHRP)
		ResTarget.Void(target)
		return true
	end

	function ResBlobman.RemoveGucci(target)
		if TR_IsWhitelisted(target) then return false end
		local _, tHRP, tHum = ResCore.Char(target)
		if not (tHRP and tHum and tHum.Health > 0 and not tHum.SeatPart) then return end
		tHum.Sit = true
		task.delay(0.1, function()
			if tHum and tHum.Parent then tHum.Sit = false end
		end)
		return true
	end

	function ResBlobman.Lock(target)
		if TR_IsWhitelisted(target) then return end
		if not ResBlobman.EnsureSeated() then return end
		local comp = ResBlobman.GetComponents()
		if not (comp and comp.RightWeld) then return end
		local _, _, myHum = ResCore.Char()
		local _, tHRP = ResCore.Char(target)
		if not (myHum and tHRP) then return end

		comp.RightWeld.Attachment0 = nil
		task.wait(0.1)
		comp.RightWeld.Attachment0 = tHRP:FindFirstChild("RootAttachment")
	end

	function ResBlobman.Follow(target)
		if TR_IsWhitelisted(target) then return end
		local _, myHRP = ResCore.Char()
		local _, tHRP, tHum = ResCore.Char(target)
		if not (myHRP and tHRP and tHum) then return end

		task.spawn(function()
			while myHRP.Parent and tHRP.Parent and tHum.Health > 0 and not TR_IsWhitelisted(target) do
				if (tHRP.Position - myHRP.Position).Magnitude > 50 then
					ResCore.Teleport(tHRP, myHRP.CFrame * CFrame.new(0, 10, 0))
				end
				tHum.WalkToPoint = myHRP.Position
				task.wait(0.1)
			end
		end)
	end

	function ResBlobman.LoopLock(target, loopKey)
		local comp = ResBlobman.GetComponents()
		local _, myHRP, myHum = ResCore.Char()
		local _, tHRP, tHum = ResCore.Char(target)
		if not (comp and comp.BSAOS and comp.LeftWeld and myHRP and tHRP and tHum and tHum.Health > 0) then return end

		if ResBlobman.Release(target) then
			ResCore.Teleport(tHRP, myHRP.CFrame * CFrame.new(0, 0, -5))
			local bp = Instance.new("BodyPosition")
			bp.Name = "BlobLockBP"
			bp.MaxForce = Vector3.one * math.huge
			bp.D = 250
			bp.Position = myHRP.Position + Vector3.new(ResConfig.BlobKickX, ResConfig.BlobKickY, ResConfig.BlobKickZ)
			bp.Parent = tHRP
			ResCore.ResetVelocity(tHRP)

			comp.LeftWeld.Enabled = false
			while target.Parent and tHRP.Parent and tHum.Health > 0 and ResConfig[loopKey] and ResConfig.BlobMethod == "Lock" and (myHRP.Position - tHRP.Position).Magnitude < 45 do
				bp.Position = (myHRP.CFrame * CFrame.new(0, 0, -5)).Position
				ResCore.ResetVelocity(tHRP)
				pcall(function()
					comp.CreatureGrab:FireServer(nil, tHRP, comp.LeftWeld)
					task.wait(0.02)
					comp.CreatureRelease:FireServer(comp.LeftWeld)
					task.wait(0.02)
				end)
			end

			pcall(function() bp:Destroy() end)
			if comp.LeftWeld then comp.LeftWeld.Enabled = true end
		end
	end

	-- ==============================================================================
	-- TARGET METHODS ENGINE (tbl12 1:1)
	-- ==============================================================================
	local ResTarget = {
		KickServerState = { Running = false },
		KickServerCooldowns = setmetatable({}, { __mode = "k" })
	}

	function ResTarget.Void(player)
		local tChar, tHRP, tHum = ResCore.Char(player)
		if not (tChar and tHRP and tHum and tHum.Health > 0) then return end
		if ResCore.SNO(tHRP) then
			local voidCF = CFrame.new(0, 9e9, 0)
			pcall(function()
				tChar:PivotTo(voidCF * tHRP.CFrame:Inverse() * tChar:GetPivot())
			end)
			ResCore.Teleport(tHRP, voidCF)
			tHRP.Velocity = Vector3.new(0, 9e9, 0)
			tHRP.AssemblyLinearVelocity = Vector3.new(0, 9e9, 0)
			task.delay(0.35, ResCore.RNO, tHRP)
		end
	end

	function ResTarget.Kill(player)
		local tChar, tHRP, tHum = ResCore.Char(player)
		if not (tChar and tHRP and tHum and tHum.Health > 0) then return end
		tHum.BreakJointsOnDeath = false
		tHum:ChangeState(Enum.HumanoidStateType.Dead)
		ResTarget.Void(player)
	end

	function ResTarget.Bring(player)
		local _, myHRP, myHum = ResCore.Char()
		local tChar, tHRP, tHum = ResCore.Char(player)
		if not (myHRP and myHum and myHum.Health > 0 and tHRP and tHum and tHum.Health > 0) then return end
		if not ResCore.IsNetworkOwner(tHRP) and not ResCore.SNO(tHRP) then return end

		local targetCF = myHRP.CFrame * CFrame.new(0, 0, -5)
		for i = 1, 3 do
			if tHRP.Parent and tHum.Health > 0 then
				ResCore.Teleport(tHRP, targetCF)
				ResCore.ResetVelocity(tHRP)
				RunService.Heartbeat:Wait()
			end
		end
		if tHRP.Parent then ResCore.RNO(tHRP) end
	end

	function ResTarget.EatAntiInput(player)
		local tChar = ResCore.Char(player)
		local leftArm = tChar and tChar:FindFirstChild("Left Arm")
		if not leftArm then return end
		for _, part in ipairs(leftArm:GetConnectedParts()) do
			if part.Name == "HoldPart" and part.Parent then
				ResCore.BreakHoldable(part.Parent, 1)
			end
		end
	end

	function ResTarget.RemoveGucci(player)
		local myChar, myHRP, myHum = ResCore.Char()
		local tChar, tHRP, tHum = ResCore.Char(player)
		local spawnedToys, plotItems = ResCore.GetInventory(player)
		if not (myChar and myHRP and myHum and myHum.Health > 0 and spawnedToys) then return false end

		local function cleanSeat(seat)
			if not seat or not seat:IsA("Seat") and not seat:IsA("VehicleSeat") or seat.Occupant then return end
			if ResConfig.RagdollInRG and tHRP then
				ResCore.SNO(tHRP, 1.5)
			end
			if myHum.Sit then
				myHum.Sit = false
				task.wait(0.1)
			end

			local seatWeldBroken = false
			local controlScriptBroken = false

			local conn1 = myChar.ChildAdded:Connect(function(child)
				if child:IsA("LocalScript") and child.Name:lower():find("control") then
					child.Enabled = false
					pcall(function() child:Destroy() end)
					controlScriptBroken = true
				end
			end)

			local conn2 = seat.ChildAdded:Connect(function(child)
				if child.Name == "SeatWeld" then
					child.Enabled = false
					pcall(function() child:Destroy() end)
					seatWeldBroken = true
				end
			end)

			local t0 = tick()
			while tick() - t0 < 0.5 do
				pcall(function() seat:Sit(myHum) end)
				task.wait()
				if seatWeldBroken or not seat.Parent or myHum.Health <= 0 then break end
			end

			myHum.Sit = false
			pcall(function() conn1:Disconnect() end)
			pcall(function() conn2:Disconnect() end)
		end

		for _, item in ipairs(spawnedToys:GetChildren()) do
			if item:IsA("Model") then
				local seat = item:FindFirstChildWhichIsA("VehicleSeat") or item:FindFirstChildWhichIsA("Seat")
				if seat then cleanSeat(seat) end
			end
		end

		if plotItems then
			for _, item in ipairs(plotItems:GetChildren()) do
				if item:IsA("Model") then
					local seat = item:FindFirstChildWhichIsA("VehicleSeat") or item:FindFirstChildWhichIsA("Seat")
					if seat then cleanSeat(seat) end
				end
			end
		end
	end

	function ResTarget.DeleteSeatables(player)
		local spawnedToys = ResCore.GetInventory(player)
		if not spawnedToys then return end
		for _, item in ipairs(spawnedToys:GetChildren()) do
			if item:IsA("Model") then
				local seat = item:FindFirstChild("VehicleSeat") or item:FindFirstChild("Seat")
				if seat and not seat.Occupant then
					ResCore.DestroyToy(item)
				end
			end
		end
	end

	function ResTarget.KickServer(isLoop)
		if ResTarget.KickServerState.Running then return false end
		local now = os.clock()
		local victims = {}
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= LocalPlayer then
				local canRun = true
				if isLoop then
					canRun = (now - (ResTarget.KickServerCooldowns[p] or -math.huge)) >= 15
				end
				if canRun then
					local _, tHRP, tHum = ResCore.Char(p)
					if tHRP and tHum and tHum.Health > 0 then
						table.insert(victims, p)
					end
				end
			end
		end

		if #victims == 0 then return false end
		ResTarget.KickServerState.Running = true
		local _, myHRP, myHum = ResCore.Char()
		if not (myHRP and myHum and myHum.Health > 0) then
			ResTarget.KickServerState.Running = false
			return false
		end

		local center = myHRP.Position
		local caughtRoots = {}
		local targetCFrames = {}

		local conn = RunService.Heartbeat:Connect(function()
			for part, cf in pairs(targetCFrames) do
				if part.Parent then
					part.CFrame = cf
					ResCore.ResetVelocity(part)
				else
					targetCFrames[part] = nil
				end
			end
		end)

		for i, p in ipairs(victims) do
			local _, tHRP, tHum = ResCore.Char(p)
			if tHRP and tHum and tHum.Health > 0 then
				if isLoop then ResTarget.KickServerCooldowns[p] = os.clock() end
				if ResCore.SNO(tHRP) then
					local angle = (i / #victims) * math.pi * 2
					local cf = CFrame.new(center + Vector3.new(math.cos(angle) * 15, ResConfig.NKOffset, math.sin(angle) * 15))
					table.insert(caughtRoots, tHRP)
					targetCFrames[tHRP] = cf
					ResCore.Teleport(tHRP, cf)
				end
			end
		end

		task.delay(3, function()
			if conn then conn:Disconnect(); conn = nil end
		end)

		task.wait(0.15)
		for _, root in ipairs(caughtRoots) do
			if root.Parent then ResCore.RNO(root) end
		end

		if ResConfig.DeleteShurInNK then
			for _, root in ipairs(caughtRoots) do
				if root.Parent and root.Parent.Parent then
					task.spawn(ResCore.RemoveSticky, root.Parent)
				end
			end
		end

		task.wait(2)
		if conn then conn:Disconnect(); conn = nil end
		ResTarget.KickServerState.Running = false
		return true
	end

	function ResTarget.ProcessPlayer(player, isLoop, isServer, isBlobman, loopKey)
		if not player or player == LocalPlayer or TR_IsWhitelisted(player) then return end
		local _, tHRP, tHum = ResCore.Char(player)
		if not (tHRP and tHum and tHum.Health > 0) then return end

		if isBlobman then
			local method = ResConfig.BlobMethod
			if method == "Bring" then
				ResBlobman.Bring(player)
			elseif method == "Kill" then
				ResBlobman.Kill(player)
			elseif method == "Follow" then
				ResBlobman.Follow(player)
			elseif method == "Remove Gucci" then
				ResBlobman.RemoveGucci(player)
			elseif method == "Lock" then
				if isLoop then
					ResBlobman.LoopLock(player, loopKey)
				else
					ResBlobman.Lock(player)
				end
			elseif method == "Kick" and not isServer then
				if isLoop then
					ResBlobman.LoopKick(player)
				else
					ResBlobman.Kick(player)
				end
			end
			return
		end

		local methods = ResConfig.TargetMethods
		if methods["Remove Invisibility"] and tHRP then
			tHRP.Massless = false
		end
		if methods["Bring"] then
			ResTarget.Bring(player)
		end
		if methods["Kick"] then
			ResTarget.Void(player)
		end
		if methods["Kill"] then
			ResTarget.Kill(player)
		end
		if methods["Void"] then
			ResTarget.Void(player)
		end
		if methods["Remove Gucci"] then
			ResTarget.RemoveGucci(player)
		end
		if methods["Destroy Food"] then
			ResTarget.EatAntiInput(player)
		end
		if methods["Delete Seatables"] then
			ResTarget.DeleteSeatables(player)
		end
	end

	local function GetTargetList(isServer, selectedDict)
		local targets = {}
		if isServer then
			for _, p in ipairs(Players:GetPlayers()) do
				if p ~= LocalPlayer and not TR_IsWhitelisted(p) then table.insert(targets, p) end
			end
		else
			for p, sel in pairs(selectedDict) do
				if sel and p and p.Parent and p ~= LocalPlayer and not TR_IsWhitelisted(p) then
					table.insert(targets, p)
				end
			end
		end
		return targets
	end

	-- ==============================================================================
	-- UI CONSTRUCTION: Tabs.Target
	-- ==============================================================================
	if Tabs.Target and Tabs.Target.CreateBlock then
		local TargetBox = Tabs.Target:CreateBlock({ Name = "Target", Side = "Left" })
		local ApplyBox = Tabs.Target:CreateBlock({ Name = "Apply", Side = "Left" })
		local MethodSettingsBox = Tabs.Target:CreateBlock({ Name = "Method Settings", Side = "Right" })

		local function GetPlayerListNames()
			local list = {}
			for _, p in ipairs(Players:GetPlayers()) do
				if p ~= LocalPlayer and not TR_IsWhitelisted(p) then table.insert(list, p.Name) end
			end
			return list
		end

		local playerDropdown = TargetBox:CreateDropdown({
			Name = "Targets",
			Options = GetPlayerListNames(),
			Multi = true,
			Callback = function(values)
				table.clear(SelectedTargets)
				if type(values) == "table" then
					for pName, isSel in pairs(values) do
						if isSel then
							local pl = Players:FindFirstChild(pName)
							if pl and not TR_IsWhitelisted(pl) then SelectedTargets[pl] = true end
						end
					end
				elseif type(values) == "string" and values ~= "" then
					local pl = Players:FindFirstChild(values)
					if pl and not TR_IsWhitelisted(pl) then SelectedTargets[pl] = true end
				end
			end
		})

		TargetBox:CreateButton({
			Name = "Refresh Player List",
			Callback = function()
				local names = GetPlayerListNames()
				playerDropdown:Refresh(names)
				notify("Target", "Player list refreshed (" .. #names .. " players)", 2)
			end
		})

		TargetBox:CreateButton({
			Name = "Select All Players",
			Callback = function()
				local names = GetPlayerListNames()
				local all = {}
				for _, n in ipairs(names) do
					all[n] = true
					local pl = Players:FindFirstChild(n)
					if pl and not TR_IsWhitelisted(pl) then SelectedTargets[pl] = true end
				end
				pcall(function() playerDropdown:Set(all) end)
				notify("Target", "Selected all players", 2)
			end
		})

		TargetBox:CreateButton({
			Name = "Deselect All",
			Callback = function()
				table.clear(SelectedTargets)
				pcall(function() playerDropdown:Set({}) end)
				notify("Target", "Deselected all players", 2)
			end
		})

		-- Apply Box
		local loopTargetSelToken = 0
		ApplyBox:CreateToggle({
			Name = "Loop Apply (Selected Players)",
			Default = false,
			Callback = function(enabled)
				ResConfig.LoopApplyTargetSel = enabled
				loopTargetSelToken = loopTargetSelToken + 1
				local token = loopTargetSelToken
				if enabled then
					task.spawn(function()
						local activeVictimBPs = {}
						local conn
						conn = RunService.Heartbeat:Connect(function()
							if not ResConfig.LoopApplyTargetSel or loopTargetSelToken ~= token then
								if conn then conn:Disconnect(); conn = nil end
								for _, bp in pairs(activeVictimBPs) do
									if bp and bp.Parent then pcall(function() bp:Destroy() end) end
								end
								return
							end
							local _, myHRP = ResCore.Char()
							if not myHRP then return end

							local targets = GetTargetList(false, SelectedTargets)
							for idx, p in ipairs(targets) do
								if p.Parent and not TR_IsWhitelisted(p) then
									local _, tHRP, tHum = ResCore.Char(p)
									if tHRP and tHum and tHum.Health > 0 then
										local targetCF = myHRP.CFrame * CFrame.new((idx - (#targets + 1) / 2) * 5, 14, -12)
										tHRP.CFrame = targetCF
										tHum.PlatformStand = true
										tHum.Sit = true

										local bp = activeVictimBPs[tHRP]
										if not (bp and bp.Parent) then
											bp = Instance.new("BodyPosition", tHRP)
											bp.Name = "TargetHoldBP"
											bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
											bp.P = 50000
											bp.D = 400
											activeVictimBPs[tHRP] = bp
										end
										bp.Position = targetCF.Position
										tHRP.AssemblyLinearVelocity = Vector3.zero

										ResCore.Grab(tHRP, targetCF)
									end
								end
							end
						end)

						while ResConfig.LoopApplyTargetSel and loopTargetSelToken == token do
							local targets = GetTargetList(false, SelectedTargets)
							for _, p in ipairs(targets) do
								if not ResConfig.LoopApplyTargetSel or loopTargetSelToken ~= token then break end
								ResTarget.ProcessPlayer(p, true, false, false, "LoopApplyTargetSel")
							end
							task.wait(0.12)
						end
					end)
				end
			end
		})

		local loopTargetServToken = 0
		ApplyBox:CreateToggle({
			Name = "Loop Apply (Whole Server)",
			Default = false,
			Callback = function(enabled)
				ResConfig.LoopApplyTargetServ = enabled
				loopTargetServToken = loopTargetServToken + 1
				local token = loopTargetServToken
				if enabled then
					task.spawn(function()
						local activeVictimBPs = {}
						local conn
						conn = RunService.Heartbeat:Connect(function()
							if not ResConfig.LoopApplyTargetServ or loopTargetServToken ~= token then
								if conn then conn:Disconnect(); conn = nil end
								for _, bp in pairs(activeVictimBPs) do
									if bp and bp.Parent then pcall(function() bp:Destroy() end) end
								end
								return
							end
							local _, myHRP = ResCore.Char()
							if not myHRP then return end

							local targets = GetTargetList(true)
							local numTargets = math.max(#targets, 1)
							for idx, p in ipairs(targets) do
								if p.Parent and not TR_IsWhitelisted(p) then
									local _, tHRP, tHum = ResCore.Char(p)
									if tHRP and tHum and tHum.Health > 0 then
										local angle = (idx / numTargets) * math.pi * 2
										local targetCF = CFrame.new(myHRP.Position + Vector3.new(math.cos(angle) * 16, ResConfig.NKOffset or 18, math.sin(angle) * 16))
										tHRP.CFrame = targetCF
										tHum.PlatformStand = true
										tHum.Sit = true

										local bp = activeVictimBPs[tHRP]
										if not (bp and bp.Parent) then
											bp = Instance.new("BodyPosition", tHRP)
											bp.Name = "ServerLoopHoldBP"
											bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
											bp.P = 50000
											bp.D = 400
											activeVictimBPs[tHRP] = bp
										end
										bp.Position = targetCF.Position
										tHRP.AssemblyLinearVelocity = Vector3.zero

										ResCore.Grab(tHRP, targetCF)
									end
								end
							end
						end)

						while ResConfig.LoopApplyTargetServ and loopTargetServToken == token do
							local targets = GetTargetList(true)
							for _, p in ipairs(targets) do
								if not ResConfig.LoopApplyTargetServ or loopTargetServToken ~= token then break end
								ResTarget.ProcessPlayer(p, true, true, false, "LoopApplyTargetServ")
							end
							task.wait(0.12)
						end
					end)
				end
			end
		})

