    -- ============================================================
    -- Throw / Hold Distance Toggle + Slider (10 to 500 Studs) + Mouse Scroll Wheel
    -- Slider value stays at 500 (never resets to 10 on grab/release).
    -- Mouse Scroll Wheel moves the held player/object forward & backward freely!
    -- ============================================================
    do
        local throwDistanceEnabled = false
        local throwDistance = 500
        local currentHoldDist = 15
        local throwSliderApi = nil
        local currentGrabModel = nil
        local currentCustomDragPart = nil
        local currentVanillaDragPart = nil
        local dragStepConn = nil
        local savedMinZoom = nil
        local savedMaxZoom = nil

        local function restoreCameraZoom()
            if savedMinZoom ~= nil and savedMaxZoom ~= nil then
                pcall(function()
                    LocalPlayer.CameraMinZoomDistance = savedMinZoom
                    LocalPlayer.CameraMaxZoomDistance = savedMaxZoom
                end)
                savedMinZoom = nil
                savedMaxZoom = nil
            end
        end

        local function cleanupGrabSession()
            if dragStepConn then
                dragStepConn:Disconnect()
                dragStepConn = nil
            end
            if currentVanillaDragPart and currentVanillaDragPart.Parent then
                pcall(function()
                    if currentVanillaDragPart:FindFirstChild("AlignPosition") then
                        currentVanillaDragPart.AlignPosition.Enabled = true
                    end
                end)
            end
            if currentCustomDragPart and currentCustomDragPart.Parent then
                pcall(function()
                    currentCustomDragPart:Destroy()
                end)
            end
            currentVanillaDragPart = nil
            currentCustomDragPart = nil
            currentGrabModel = nil
            restoreCameraZoom()
        end

        -- Mouse Scroll Wheel: Move grabbed player/object forward & backward (5 to throwDistance studs)
        UserInputService.InputChanged:Connect(function(input)
            if not throwDistanceEnabled then return end
            if input.UserInputType ~= Enum.UserInputType.MouseWheel then return end
            if UserInputService:GetFocusedTextBox() then return end
            if not (currentGrabModel and currentGrabModel.Parent and currentCustomDragPart) then return end

            local maxDist = math.clamp(tonumber(throwDistance) or 500, 10, 500)
            local step = math.clamp(currentHoldDist * 0.12, 4, 22)

            if input.Position.Z > 0 then
                currentHoldDist = math.clamp(currentHoldDist + step, 5, maxDist)
            elseif input.Position.Z < 0 then
                currentHoldDist = math.clamp(currentHoldDist - step, 5, maxDist)
            end
        end)

        local function attachCustomThrowToGrabParts(child)
            if not throwDistanceEnabled or not child or not child.Parent then return end
            local dragPart = child:WaitForChild("DragPart", 1)
            local grabPart = child:WaitForChild("GrabPart", 1)
            if not dragPart or not grabPart or not throwDistanceEnabled then return end

            local cam = workspace.CurrentCamera
            if not cam then return end

            cleanupGrabSession()

            -- Lock camera zoom during grab so Mouse Scroll moves the held player without zooming camera
            pcall(function()
                savedMinZoom = LocalPlayer.CameraMinZoomDistance
                savedMaxZoom = LocalPlayer.CameraMaxZoomDistance
                local curZoom = math.clamp((cam.CFrame.Position - cam.Focus.Position).Magnitude, 0.5, 400)
                LocalPlayer.CameraMinZoomDistance = curZoom
                LocalPlayer.CameraMaxZoomDistance = curZoom
            end)

            -- Start hold distance at natural grab distance, NEVER reset throwDistance slider!
            local maxDist = math.clamp(tonumber(throwDistance) or 500, 10, 500)
            currentHoldDist = math.clamp((dragPart.Position - cam.CFrame.Position).Magnitude, 5, maxDist)

            currentGrabModel = child
            currentVanillaDragPart = dragPart
            local clone = dragPart:Clone()
            clone.Name = "CustomDragPart"
            if clone:FindFirstChild("AlignPosition") and clone:FindFirstChild("DragAttach") then
                clone.AlignPosition.Attachment1 = clone.DragAttach
            end
            if clone:FindFirstChild("AlignOrientation") then
                clone.AlignOrientation.Enabled = false
            end
            clone.Parent = child
            currentCustomDragPart = clone

            -- Disable the vanilla game's 20-stud clamped AlignPosition
            if dragPart:FindFirstChild("AlignPosition") then
                dragPart.AlignPosition.Enabled = false
            end

            local CAS = game:GetService("ContextActionService")
            local btnIn = nil
            local btnOut = nil
            pcall(function()
                btnIn = CAS:GetButton("ZoomIn")
                btnOut = CAS:GetButton("ZoomOut")
            end)

            child:GetPropertyChangedSignal("Parent"):Connect(function()
                if not child.Parent then
                    cleanupGrabSession()
                end
            end)

            dragStepConn = RunService.RenderStepped:Connect(function()
                if not throwDistanceEnabled or not (child.Parent and clone.Parent and currentCustomDragPart == clone) then
                    cleanupGrabSession()
                    return
                end
                local maxD = math.clamp(tonumber(throwDistance) or 500, 10, 500)
                if btnOut and btnOut.GuiState == Enum.GuiState.Press then
                    currentHoldDist = math.clamp(currentHoldDist + 4, 5, maxD)
                elseif btnIn and btnIn.GuiState == Enum.GuiState.Press then
                    currentHoldDist = math.clamp(currentHoldDist - 4, 5, maxD)
                end
                if currentHoldDist > maxD then
                    currentHoldDist = maxD
                end
                local curCam = workspace.CurrentCamera
                if curCam then
                    clone.Position = curCam.CFrame.Position + curCam.CFrame.LookVector * currentHoldDist
                end
            end)
        end

        workspace.ChildAdded:Connect(function(child)
            if child.Name ~= "GrabParts" or not throwDistanceEnabled then return end
            task.defer(function()
                attachCustomThrowToGrabParts(child)
            end)
        end)

        GrabGroup:CreateToggle({
            Name = "Throw Distance",
            Flag = "ThrowDistanceToggle",
            Tooltip = "Enable/Disable custom Throw Distance & Mouse Scroll Wheel hold distance control.",
            Default = false,
            Callback = function(enabled)
                throwDistanceEnabled = enabled
                if SetToggleState then SetToggleState("ThrowDistanceToggle", enabled) end
                if enabled then
                    local existing = workspace:FindFirstChild("GrabParts")
                    if existing then
                        task.spawn(attachCustomThrowToGrabParts, existing)
                    end
                else
                    cleanupGrabSession()
                end
            end
        })

        throwSliderApi = GrabGroup:CreateSlider({
            Name = "Throw Distance Limit",
            Flag = "ThrowDistance",
            Tooltip = "Max hold/throw distance (10 - 500 studs). Use Mouse Scroll Wheel in-game to move grabbed target forward & backward.",
            Min = 10,
            Max = 500,
            Default = 500,
            Rounding = 0,
            Callback = function(v)
                throwDistance = v
                if currentHoldDist > v then
                    currentHoldDist = v
                end
                if SetToggleState then SetToggleState("ThrowDistance", v) end
            end
        })
    end

local killGrabEnabled = false
function killGrabFunction()
	workspace.ChildAdded:Connect(function(v)
		if v:IsA("Model") and v.Name == "GrabParts" and killGrabEnabled then
			task.wait(0.05)
			local grabPart = v:FindFirstChild("GrabPart")
			if grabPart and grabPart:FindFirstChild("WeldConstraint") then
				local part1 = grabPart.WeldConstraint.Part1
				if part1 and part1.Parent and part1.Parent ~= Player.Character then
					local targetChar = part1.Parent
					local targetHum = targetChar:FindFirstChildOfClass("Humanoid")
					if targetHum and targetChar then
						pcall(function()
							targetHum.Health = 0
							targetChar:BreakJoints()
						end)
					end
				end
			end
		end
	end)
end

killGrabFunction()
GrabGroup:CreateToggle({
	Name = "Kill Grab",
        Flag = "Kill Grab",
	Default = false,
	Callback = function(Value)
        SetToggleState("Kill Grab", Value)
		killGrabEnabled = Value
	end
})

GrabGroup:CreateToggle({
        Name = "Kick Grab",
        Default = false,
        Callback = function(state)
            if not state then
                getgenv().KickGrabActive = false
                getgenv().FKeyAttackActive = false
                if getgenv().FKeyInputConnection then
                    getgenv().FKeyInputConnection:Disconnect()
                    getgenv().FKeyInputConnection = nil
                end
                return
            end
            if getgenv().KickGrabActive then return end

            getgenv().KickGrabActive = true
            getgenv().FKeyAttackActive = false

            local GrabEvents = ReplicatedStorage:WaitForChild('GrabEvents')
            local CreateGrabLine = GrabEvents:WaitForChild('CreateGrabLine')
            local SetNetworkOwner = GrabEvents:WaitForChild('SetNetworkOwner')
            local DestroyGrabLine = GrabEvents:WaitForChild('DestroyGrabLine')

            task.spawn(function()
                while getgenv().KickGrabActive do
                    local grabParts = workspace:FindFirstChild('GrabParts')
                    if not grabParts then task.wait() continue end

                    local gp = grabParts:FindFirstChild('GrabPart')
                    local weld = gp and gp:FindFirstChildOfClass('WeldConstraint')
                    local part1 = weld and weld.Part1

                    if part1 then
                        local ownerPlayer = nil
                        for _, pl in ipairs(Players:GetPlayers()) do
                            if pl.Character and part1:IsDescendantOf(pl.Character) then
                                ownerPlayer = pl
                                break
                            end
                        end

                        if not ownerPlayer then task.wait() continue end

                        while getgenv().KickGrabActive and workspace:FindFirstChild('GrabParts') do
                            if ownerPlayer then
                                local tgtTorso = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('HumanoidRootPart')
                                local tgtHead = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('Head')
                                local myTorso = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

                                if tgtTorso and myTorso and tgtHead then
                                    pcall(function()
                                        SetNetworkOwner:FireServer(tgtTorso, CFrame.lookAt(myTorso.Position, tgtTorso.Position))
                                    end)
                                    task.wait()
                                    pcall(function()
                                        DestroyGrabLine:FireServer(tgtHead)
                                    end)
                                end
                            end
                            task.wait()
                        end
                    end
                    task.wait()
                end
            end)

            function getScreenCenterTarget()
                local screenCenter = Vector2.new(workspace.CurrentCamera.ViewportSize.X / 2, workspace.CurrentCamera.ViewportSize.Y / 2)
                local ray = workspace.CurrentCamera:ViewportPointToRay(screenCenter.X, screenCenter.Y)
                local raycastParams = RaycastParams.new()
                raycastParams.FilterType = Enum.RaycastFilterType.Exclude
                if LocalPlayer.Character then
                    raycastParams.FilterDescendantsInstances = {LocalPlayer.Character}
                end

                local result = workspace:Raycast(ray.Origin, ray.Direction * 1000, raycastParams)
                if result and result.Instance then
                    for _, pl in ipairs(Players:GetPlayers()) do
                        if pl ~= LocalPlayer and pl.Character and result.Instance:IsDescendantOf(pl.Character) then
                            return pl
                        end
                    end
                end
                return nil
            end

            local fAttackTarget = nil
            local fAttackConnection = nil

            function stopFKeyAttack()
                getgenv().FKeyAttackActive = false
                fAttackTarget = nil
                if fAttackConnection then
                    fAttackConnection:Disconnect()
                    fAttackConnection = nil
                end
            end

            function startFKeyAttack(targetPlayer)
                getgenv().FKeyAttackActive = true
                fAttackTarget = targetPlayer
                fAttackConnection = RunService.RenderStepped:Connect(function()
                    if not getgenv().FKeyAttackActive or not fAttackTarget then
                        stopFKeyAttack()
                        return
                    end

                    local myChar = LocalPlayer.Character
                    local myRoot = myChar and myChar:FindFirstChild('HumanoidRootPart')
                    local tgtChar = fAttackTarget.Character
                    local tgtRoot = tgtChar and tgtChar:FindFirstChild('HumanoidRootPart')

                    if not myRoot or not tgtRoot then return end

                    local camCF = workspace.CurrentCamera.CFrame
                    local teleportPos = camCF.Position + camCF.LookVector * 20

                    pcall(function()
                        tgtRoot.CFrame = CFrame.new(teleportPos)
                    end)

                    local grabCFrame = CFrame.new(-9.0301513671875E-2, 0.4190945625305176, 0.4999980926513672, 0.39632707834243774, 0, -0.9181094169616699, -1.0944717132588266E-7, 1, -4.7245869438938826E-8, 0.9181094169616699, 5.9604644775390625e-8, 0.39632707834243774)

                    pcall(function()
                        SetNetworkOwner:FireServer(tgtRoot, CFrame.lookAt(myRoot.Position, tgtRoot.Position))
                        DestroyGrabLine:FireServer(tgtRoot)
                    end)
                end)
            end

            getgenv().FKeyInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
                if gameProcessed then return end
                if input.KeyCode ~= Enum.KeyCode.F then return end
                if getgenv().FKeyAttackActive then
                    stopFKeyAttack()
                    return
                end

                local target = getScreenCenterTarget()
                if not target then return end

                local myChar = LocalPlayer.Character
                local myRoot = myChar and myChar:FindFirstChild('HumanoidRootPart')
                local tgtChar = target.Character
                local tgtRoot = tgtChar and tgtChar:FindFirstChild('HumanoidRootPart')

                if not myRoot or not tgtRoot then return end

                local distance = (myRoot.Position - tgtRoot.Position).Magnitude
                if distance > 25 then return end

                startFKeyAttack(target)
            end)

            if game.PlaceId == 6961824067 then
                local G = ReplicatedStorage:WaitForChild('GrabEvents')
                G:WaitForChild('EndGrabEarly'):Destroy()
                Instance.new('RemoteEvent', G).Name = 'EndGrabEarly'
            end
        end
    })


