local TbotGroup = Tabs.Grab:CreateBlock({Name = "Trigger Bot", Side = "Left"})
local AimGroup = Tabs.Grab:CreateBlock({Name = "Aimbot", Side = "Right"})

do

    local triggerEnabled = false
    local triggerDistance = 25
    local triggerDelay = 0.05

    local function getTargetsInRange()
        local targets = {}
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then return targets end

        for _, plr in pairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer and plr.Character then
                local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                local tHum = plr.Character:FindFirstChild("Humanoid")
                if tRoot and tHum and tHum.Health > 0 then
                    local dist = (tRoot.Position - root.Position).Magnitude
                    if dist <= triggerDistance then
                        table.insert(targets, plr)
                    end
                end
            end
        end
        return targets
    end

    local function triggerBot()
        if not triggerEnabled then return end
        
        local targets = getTargetsInRange()
        if #targets == 0 then return end

        local cam = workspace.CurrentCamera
        local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
        local closestTarget = nil
        local closestDist = math.huge

        for _, plr in ipairs(targets) do
            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
            if tRoot then
                local screenPos, onScreen = cam:WorldToViewportPoint(tRoot.Position)
                if onScreen then
                    local screenDist = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude
                    if screenDist < closestDist then
                        closestDist = screenDist
                        closestTarget = plr
                    end
                end
            end
        end

        if closestTarget then
            pcall(function()
                mouse1press()
                task.wait(0.05)
                mouse1release()
            end)
        end
    end

    TbotGroup:CreateToggle({
        Name = "Trigger Bot",
        Default = false,
        Callback = function(v)
            triggerEnabled = v
            if v then
                task.spawn(function()
                    while triggerEnabled do
                        triggerBot()
                        task.wait(triggerDelay)
                    end
                end)
            end
        end
    })

    TbotGroup:CreateSlider({
        Name = "Trigger Distance",
        Default = 25,
        Min = 5,
        Max = 50,
        Callback = function(v)
            triggerDistance = v
        end
    })

    TbotGroup:CreateSlider({
        Name = "Trigger Delay",
        Default = 0.05,
        Min = 0.01,
        Max = 0.5,
        Callback = function(v)
            triggerDelay = v
        end
    })
end

do
    -- ============================================================
    -- Ranax Fluid Aim Assist & Keybind Engine
    -- Accurate target tracking, R6/R15 part mapping, FOV centering,
    -- and universal Hold/Toggle keybind detection (keyboard & mouse).
    -- ============================================================
    local aimEnabled = false
    local aimAlwaysOn = false
    local aimKeyHeld = false
    local aimTargetPart = "Head"
    local aimDistance = 350
    local aimSmoothness = 0.25
    local aimFOVEnabled = false
    local aimFOVRadius = 180
    local aimLimitToFOV = true
    local aimWallCheck = false
    local aimIgnorePlots = false
    local aimKeybind = Enum.KeyCode.E
    local aimMode = "Hold"
    local aimToggled = false

    local aimRaycastParams = RaycastParams.new()
    aimRaycastParams.FilterType = Enum.RaycastFilterType.Exclude

    -- FOV cemberi (Drawing varsa Drawing, yoksa CoreGui Frame)
    local fovCircle, fovGuiCircle = nil, nil
    pcall(function()
        if Drawing and Drawing.new then
            fovCircle = Drawing.new("Circle")
            fovCircle.Thickness = 1.5
            fovCircle.NumSides = 64
            fovCircle.Filled = false
            fovCircle.Transparency = 1
            fovCircle.Color = Color3.fromRGB(255, 255, 255)
            fovCircle.Visible = false
        end
    end)
    if not fovCircle then
        pcall(function()
            local gui = Instance.new("ScreenGui")
            gui.Name = "ResoAimFOVGui"
            gui.ResetOnSpawn = false
            gui.IgnoreGuiInset = true
            gui.Parent = game:GetService("CoreGui")
            local img = Instance.new("Frame")
            img.Name = "FOVCircle"
            img.AnchorPoint = Vector2.new(0.5, 0.5)
            img.Position = UDim2.new(0.5, 0, 0.5, 0)
            img.BackgroundTransparency = 1
            img.Visible = false
            img.Parent = gui
            local st = Instance.new("UIStroke")
            st.Color = Color3.fromRGB(255, 255, 255)
            st.Thickness = 1.5
            st.Parent = img
            local c = Instance.new("UICorner")
            c.CornerRadius = UDim.new(0.5, 0)
            c.Parent = img
            fovGuiCircle = img
        end)
    end

    local function updateFOVCircle()
        local cam = workspace.CurrentCamera
        if not cam then return end
        local vp = cam.ViewportSize
        local center = Vector2.new(vp.X / 2, vp.Y / 2)
        if fovCircle then
            fovCircle.Visible = aimFOVEnabled
            if aimFOVEnabled then
                fovCircle.Radius = aimFOVRadius
                fovCircle.Position = center
            end
        elseif fovGuiCircle then
            fovGuiCircle.Visible = aimFOVEnabled
            if aimFOVEnabled then
                fovGuiCircle.Size = UDim2.new(0, aimFOVRadius * 2, 0, aimFOVRadius * 2)
                fovGuiCircle.Position = UDim2.new(0.5, 0, 0.5, 0)
            end
        end
    end

    local function getTargetPart(character)
        if not character then return nil end
        if aimTargetPart == "Head" then
            return character:FindFirstChild("Head") or character:FindFirstChild("HumanoidRootPart")
        elseif aimTargetPart == "Torso" then
            return character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart")
        elseif aimTargetPart == "HumanoidRootPart" then
            return character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("Head")
        end
        return character:FindFirstChild(aimTargetPart) or character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Head")
    end

    -- High-accuracy Wallcheck: Filters out character, target, and non-physical obstacles
    local function isPartVisible(fromPos, targetPartInstance, targetChar)
        if not targetPartInstance then return false end
        local char = LocalPlayer.Character
        if not char then return false end
        local dir = targetPartInstance.Position - fromPos

        local filterList = {char, targetChar}
        local gp = workspace:FindFirstChild("GrabParts")
        if gp then table.insert(filterList, gp) end
        local myToys = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
        if myToys then table.insert(filterList, myToys) end
        if workspace.CurrentCamera then table.insert(filterList, workspace.CurrentCamera) end

        aimRaycastParams.FilterDescendantsInstances = filterList
        local result = workspace:Raycast(fromPos, dir, aimRaycastParams)
        if not result then return true end

        local hit = result.Instance
        if not hit then return true end
        if hit:IsDescendantOf(char) or hit:IsDescendantOf(targetChar) then return true end
        if hit.Transparency >= 0.9 and not hit.CanCollide then return true end
        if hit.Name == "GrabPart" or hit.Name == "DragPart" or hit.Name == "BeamPart" then return true end
        return false
    end

    local function getAimTarget()
        local char = LocalPlayer.Character
        local myRoot = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso") or char:FindFirstChild("Head"))
        if not myRoot then return nil end
        local myHead = char:FindFirstChild("Head") or myRoot
        local cam = workspace.CurrentCamera
        if not cam then return nil end

        local camPos = cam.CFrame.Position
        local myPos = myRoot.Position
        local vp = cam.ViewportSize
        local center = Vector2.new(vp.X / 2, vp.Y / 2)

        local fovSq = aimFOVRadius * aimFOVRadius
        local distSqMax = aimDistance * aimDistance
        local best, bestScore = nil, math.huge
        local bestPart = nil

        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer and plr.Character then
                if aimIgnorePlots then
                    local inPlot = plr:FindFirstChild("InPlot")
                    if inPlot and inPlot.Value then
                        continue
                    end
                end

                local targetChar = plr.Character
                local hum = targetChar:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health <= 0 then continue end

                local preferredPart = getTargetPart(targetChar)
                if not preferredPart then continue end

                local sp, onScreen = cam:WorldToViewportPoint(preferredPart.Position)
                if not onScreen then continue end

                local screenDistSq = (Vector2.new(sp.X, sp.Y) - center).MagnitudeSquared
                if aimLimitToFOV and screenDistSq > fovSq then continue end

                local dVec = myPos - preferredPart.Position
                local dSq = dVec:Dot(dVec)
                if dSq > distSqMax then continue end

                local passWall = true
                local targetHitPart = preferredPart

                if aimWallCheck then
                    -- Dual Raycast: Check both Camera Line of Sight AND Character Line of Sight
                    local camVisible = isPartVisible(camPos, preferredPart, targetChar)
                    local charVisible = isPartVisible(myHead.Position, preferredPart, targetChar)

                    if camVisible and charVisible then
                        passWall = true
                        targetHitPart = preferredPart
                    else
                        -- Multi-Point Fallback: If primary part is hidden, check Head or Torso
                        local altPart = (preferredPart.Name == "Head") and (targetChar:FindFirstChild("Torso") or targetChar:FindFirstChild("UpperTorso")) or targetChar:FindFirstChild("Head")
                        if altPart then
                            local altCam = isPartVisible(camPos, altPart, targetChar)
                            local altChar = isPartVisible(myHead.Position, altPart, targetChar)
                            if altCam and altChar then
                                passWall = true
                                targetHitPart = altPart
                            else
                                passWall = false
                            end
                        else
                            passWall = false
                        end
                    end
                end

                if passWall then
                    local score = screenDistSq + (math.sqrt(dSq) * 2)
                    if score < bestScore then
                        bestScore = score
                        best = plr
                        bestPart = targetHitPart
                    end
                end
            end
        end
        return best, bestPart
    end
    local function onAimStep()
        if not aimEnabled and not aimFOVEnabled then return end
        if aimFOVEnabled then
            updateFOVCircle()
        end
        if not aimEnabled then return end
        if not (aimAlwaysOn or aimKeyHeld) then return end
        if UserInputService:GetFocusedTextBox() then return end

        local target, targetPart = getAimTarget()
        if not target or not target.Character then return end
        local part = targetPart or getTargetPart(target.Character)
        local cam = workspace.CurrentCamera
        if not part or not cam then return end

        local targetCF = CFrame.lookAt(cam.CFrame.Position, part.Position)
        local factor = math.clamp(aimSmoothness, 0.02, 1)
        if factor >= 0.98 then
            cam.CFrame = targetCF
        else
            cam.CFrame = cam.CFrame:Lerp(targetCF, factor)
        end
    end

    local aimRenderStepConn = nil
    local function refreshAimPipeline()
        local shouldRun = aimEnabled or aimFOVEnabled
        if shouldRun and not aimRenderStepConn then
            aimRenderStepConn = RunService.RenderStepped:Connect(onAimStep)
        elseif not shouldRun and aimRenderStepConn then
            aimRenderStepConn:Disconnect()
            aimRenderStepConn = nil
            if fovCircle then fovCircle.Visible = false end
            if fovGuiCircle then fovGuiCircle.Visible = false end
        end
    end

    local function parseBind(key)
        if not key then return nil end
        if typeof(key) == "EnumItem" then return key end
        if type(key) == "string" and key ~= "" and key ~= "None" then
            return Enum.KeyCode[key] or Enum.UserInputType[key]
        elseif type(key) == "table" and key.Key then
            return parseBind(key.Key)
        end
        return nil
    end

    local function isAimBind(input)
        if not aimKeybind or aimKeybind == Enum.KeyCode.Unknown or aimKeybind == "None" or aimKeybind == "" then return false end
        if typeof(aimKeybind) == "EnumItem" then
            if input.KeyCode == aimKeybind or input.UserInputType == aimKeybind then return true end
        elseif typeof(aimKeybind) == "string" then
            if input.KeyCode and input.KeyCode.Name == aimKeybind then return true end
            if input.UserInputType and input.UserInputType.Name == aimKeybind then return true end
        end
        return false
    end

    UserInputService.InputBegan:Connect(function(input, gpe)
        if UserInputService:GetFocusedTextBox() then return end
        if not isAimBind(input) then return end

        if aimMode == "Toggle" then
            aimToggled = not aimToggled
            aimKeyHeld = aimToggled
        else
            aimKeyHeld = true
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if isAimBind(input) and aimMode == "Hold" then
            aimKeyHeld = false
        end
    end)

    AimGroup:CreateToggle({
        Name = "Aim Assist",
        Flag = "ResoAimAssist",
        Default = false,
        Callback = function(v)
            aimEnabled = v
            if not v then
                aimKeyHeld = false
                aimToggled = false
            end
            refreshAimPipeline()
        end
    })

    AimGroup:CreateKeybind({
        Name = "Aim Keybind",
        Flag = "AimKeybind",
        Default = Enum.KeyCode.E,
        OnKeyChanged = function(key)
            local parsed = parseBind(key)
            if parsed then aimKeybind = parsed end
        end,
        Callback = function(key)
            local parsed = parseBind(key)
            if parsed then aimKeybind = parsed end
            if aimMode == "Toggle" then
                aimToggled = not aimToggled
                aimKeyHeld = aimToggled
            end
        end
    })

    AimGroup:CreateDropdown({
        Name = "Aim Key Mode",
        Items = {"Hold", "Toggle"},
        Default = "Hold",
        Callback = function(v)
            aimMode = v
            aimToggled = false
            aimKeyHeld = false
        end
    })

    AimGroup:CreateToggle({
        Name = "Aim Always On",
        Default = false,
        Callback = function(v) aimAlwaysOn = v end
    })

    AimGroup:CreateToggle({
        Name = "Aim FOV Circle",
        Default = false,
        Callback = function(v)
            aimFOVEnabled = v
            refreshAimPipeline()
            if v then updateFOVCircle() end
        end
    })

    AimGroup:CreateToggle({
        Name = "Limit to FOV",
        Default = true,
        Callback = function(v) aimLimitToFOV = v end
    })

    AimGroup:CreateToggle({
        Name = "Wall Check",
        Default = true,
        Callback = function(v) aimWallCheck = v end
    })

    AimGroup:CreateToggle({
        Name = "Ignore Players in Plots",
        Default = false,
        Callback = function(v) aimIgnorePlots = v end
    })

    AimGroup:CreateDropdown({
        Name = "Aim Target Part",
        Items = {"Head", "Torso", "HumanoidRootPart"},
        Default = "Head",
        Callback = function(v) aimTargetPart = v end
    })

    AimGroup:CreateSlider({
        Name = "Aim Distance",
        Default = 350, Min = 20, Max = 1500,
        Callback = function(v) aimDistance = v end
    })

    AimGroup:CreateSlider({
        Name = "Aim Smoothness",
        Default = 0.25, Min = 0.02, Max = 1,
        Callback = function(v) aimSmoothness = v end
    })

    AimGroup:CreateSlider({
        Name = "Aim FOV Radius",
        Default = 180, Min = 30, Max = 600,
        Callback = function(v)
            aimFOVRadius = v
            updateFOVCircle()
        end
    })
end



local VisL = Tabs.Player:CreateBlock({Name = "View & Movement", Side = "Left"})
local VisualR = Tabs.Player:CreateBlock({Name = "Notify", Side = "Right"})

KB_THRESHOLD = 10
BYTE_THRESHOLD = KB_THRESHOLD * 1024
COOLDOWN = 30
lastNotify = 0
connections = {}

function resolveSender(args)
    for _, v in ipairs(args) do
        if typeof(v) == "Instance" and v:IsA("Player") then return v end
        if typeof(v) == "Instance" and v:IsA("Model") then
            local plr = Players:GetPlayerFromCharacter(v)
            if plr then return plr end
        end
        if typeof(v) == "Instance" and v:IsA("BasePart") then
            local model = v:FindFirstAncestorOfClass("Model")
            if model then
                local plr = Players:GetPlayerFromCharacter(model)
                if plr then return plr end
            end
        end
    end
    return LocalPlayer
end

function shortenString(str)
    if #str <= 80 then return str end
    return str:sub(1, 80) .. "... (+" .. (#str - 80) .. " chars)"
end

function summarizeTable(tbl)
    local preview = {}
    local count = 0
    for _, v in pairs(tbl) do
        count = count + 1
        if count <= 5 then table.insert(preview, tostring(v)) end
    end
    return "table["..count.."] { "..table.concat(preview, ", ").." ... }"
end

 function compressArgs(args)
    local seen = {}
    local summary = {}
    for _, v in ipairs(args) do
        local key
        if typeof(v) == "string" then key = "str:"..shortenString(v)
        elseif typeof(v) == "Instance" then key = "inst:"..v.ClassName.."("..v.Name..")"
        elseif typeof(v) == "table" then key = "tbl:"..summarizeTable(v)
        else key = typeof(v)..":"..tostring(v) end
        seen[key] = (seen[key] or 0) + 1
    end
    for k, count in pairs(seen) do
        if count > 1 then table.insert(summary, k.." x"..count)
        else table.insert(summary, k) end
    end
    return summary
end

 function handleEvent(eventType, remoteName, ...)
    local args = {...}
    local totalBytes = 0
    for _, v in ipairs(args) do
        if typeof(v) == "string" then totalBytes = totalBytes + #v end
    end
    if totalBytes < BYTE_THRESHOLD then return end
    if tick() - lastNotify < COOLDOWN then return end
    lastNotify = tick()
    local sender = resolveSender(args)
    local senderName = sender.DisplayName
    if sender == LocalPlayer then senderName = senderName .. " (You)" end
    local mbSize = totalBytes / (1024 * 1024)
    local summarized = compressArgs(args)
   
    notify(string.format("[%s] %s", eventType, remoteName), string.format("Player: %s\nSize: %.3f MB\nArgs:\n%s", senderName, mbSize, table.concat(summarized, "\n")), 7)
end

function scanForBlobRemotes(parent)
    for _, child in ipairs(parent:GetChildren()) do
        if child:IsA("RemoteEvent") and child.Name == "RelayClientAnimation" and child.Parent and child.Parent.Name == "BlobmanAnimations" then
            table.insert(connections, child.OnClientEvent:Connect(function(...) handleEvent("Blob", child.Parent.Parent.Name, ...) end))
        end
        scanForBlobRemotes(child)
    end
end

function watchChildren(parent)
    table.insert(connections, parent.ChildAdded:Connect(function(child)
        scanForBlobRemotes(child)
        watchChildren(child)
    end))
    for _, child in ipairs(parent:GetChildren()) do watchChildren(child) end
end

function startDetector()
    if #connections > 0 then return end
    local GrabRemoteDetect = ReplicatedStorage:WaitForChild("GrabEvents"):WaitForChild("ExtendGrabLine")
    table.insert(connections, GrabRemoteDetect.OnClientEvent:Connect(function(...) handleEvent("Grab", "ExtendGrabLine", ...) end))
    scanForBlobRemotes(workspace)
    watchChildren(workspace)
end

function stopDetector()
    for _, conn in ipairs(connections) do conn:Disconnect() end
    connections = {}
end

    VisualR:CreateToggle({
        Name = "Packet Notify",
        Flag = "GrabRemoteDetector",
        Default = false,
        Callback = function(Value)
        if Value then startDetector()
        else stopDetector() end
    end,
})

    -- Third Person (Character visible fix)
    do
        local thirdPersonActive = false
        local thirdPersonConn = nil
        local plr = game:GetService("Players").LocalPlayer

        VisL:CreateToggle({
            Name = "Third Person",
            Default = false,
            Callback = function(Value)
                thirdPersonActive = Value
                if Value then
                    plr.CameraMode = Enum.CameraMode.Classic
                    plr.CameraMaxZoomDistance = 128
                    plr.CameraMinZoomDistance = 12
                    task.delay(0.05, function()
                        if thirdPersonActive then
                            plr.CameraMinZoomDistance = 0.5
                        end
                    end)

                    if thirdPersonConn then thirdPersonConn:Disconnect() end
                    thirdPersonConn = game:GetService("RunService").RenderStepped:Connect(function()
                        if not thirdPersonActive then return end
                        local char = plr.Character
                        if char then
                            for _, part in ipairs(char:GetDescendants()) do
                                if part:IsA("BasePart") then
                                    part.LocalTransparencyModifier = 0
                                end
                            end
                        end
                    end)
                else
                    if thirdPersonConn then
                        thirdPersonConn:Disconnect()
                        thirdPersonConn = nil
                    end
                    plr.CameraMode = Enum.CameraMode.LockFirstPerson
                end
            end
        })
    end

    -- Player (Resonance): Inf Jump + Fly
    VisL:CreateToggle({
        Name = "Inf Jump",
        Flag = "ResoInfJumpPlayer",
        Default = false,
        Callback = function(Value)
            infJumpEnabled = Value
        end
    })

    do
        -- Resonance StartFly/StopFly/UpdateFlight
        local flyEnabled = false
        local flySpeed = 1 -- Resonance FlightSpeed (x50)
        local flyBV, flyBG = nil, nil

        local function stopFly()
            if flyBV then flyBV:Destroy() flyBV = nil end
            if flyBG then flyBG:Destroy() flyBG = nil end
            local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.PlatformStand = false end
        end

        VisL:CreateToggle({
            Name = "Fly",
            Flag = "ResoFly",
            Default = false,
            Callback = function(Value)
                flyEnabled = Value
                if not Value then stopFly() end
            end
        })
        VisL:CreateSlider({
            Name = "Fly Speed",
            Default = 1, Min = 0.2, Max = 5,
            Callback = function(v) flySpeed = v end
        })

        RunService.RenderStepped:Connect(function()
            if not flyEnabled then return end
            local char = LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local cam = workspace.CurrentCamera
            if not (root and hum and cam) or hum.Health <= 0 then
                if flyBV or flyBG then stopFly() end
                return
            end
            if not flyBV or flyBV.Parent ~= root or not flyBG or flyBG.Parent ~= root then
                stopFly()
                flyBG = Instance.new("BodyGyro")
                flyBG.P = 90000
                flyBG.D = 1000
                flyBG.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
                flyBG.CFrame = root.CFrame
                flyBG.Parent = root
                flyBV = Instance.new("BodyVelocity")
                flyBV.MaxForce = Vector3.new(9e9, 9e9, 9e9)
                flyBV.Velocity = Vector3.zero
                flyBV.Parent = root
            end
            if not hum.Sit then hum.PlatformStand = true end

            local fwd, side, up = 0, 0, 0
            if UserInputService:IsKeyDown(Enum.KeyCode.W) then fwd = 1 end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then fwd = fwd - 1 end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then side = -1 end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then side = side + 1 end
            if UserInputService:IsKeyDown(Enum.KeyCode.Space) then up = 2 end
            if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then up = up - 2 end
            if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
                local mv = hum.MoveDirection
                if mv.Magnitude > 0 then
                    local flat = Vector3.new(mv.X, 0, mv.Z)
                    if flat.Magnitude > 0 then
                        local cf = CFrame.new(Vector3.zero, flat)
                        fwd = 1
                        side = 0
                        flyBV.Velocity = flyBV.Velocity:Lerp(cf.LookVector * flySpeed * 50 + Vector3.new(0, up * 25, 0), 0.22)
                        flyBG.CFrame = cam.CFrame
                        return
                    end
                end
                if hum.Jump then up = up + 2 end
            end

            local dir = cam.CFrame.RightVector * side + cam.CFrame.LookVector * fwd + Vector3.new(0, up, 0)
            if dir.Magnitude > 1 then dir = dir.Unit end
            local alpha = dir.Magnitude > 0 and 0.22 or 0.12
            flyBV.Velocity = flyBV.Velocity:Lerp(dir * flySpeed * 50, alpha)
            flyBG.CFrame = cam.CFrame
        end)
    end

    -- FOV Slider
    VisL:CreateSlider({
        Name = "Field of View",
        Min = 40,
        Max = 120,
        Default = 70,
        Callback = function(Value)
            local cam = workspace.CurrentCamera
            if cam then
                cam.FieldOfView = Value
            end
        end
    })

    -- ESP (yeni): avatarlar duvardan gozukur, altta kucuk mavi yazi:
    -- scripti acmayan = "player", TR acan = "TR player", rol varsa ustte rol yazar
    do
        local ESPGroup = Tabs.Player:CreateBlock({Name = "ESP", Side = "Right"})
        local espOn = false
        local espObjs = {}
        local espConns = {}

        local ROLE_COLORS = {
            OWNER = Color3.fromRGB(255, 215, 0),
            CREATOR = Color3.fromRGB(200, 120, 255),
            HELPER = Color3.fromRGB(80, 220, 255),
        }
        local function getRole(plr)
            if plr.Name == "xcters_real" or plr.UserId == 11435932866 then return "OWNER" end
            return nil
        end
        local function isTRPlayer(plr)
            if plr == LocalPlayer then return true end
            if getRole(plr) then return true end
            local ok, v = pcall(function() return plr:GetAttribute("TR_ftap") end)
            if ok and v then return true end
            local char = plr.Character
            local ok2, v2 = pcall(function() return char and char:GetAttribute("TR_ftap") end)
            return ok2 and v2 == true
        end
        -- Kendimizi TR kullanicisi olarak isaretle
        pcall(function() LocalPlayer:SetAttribute("TR_ftap", true) end)

        local function clearOne(plr)
            local o = espObjs[plr]
            if not o then return end
            for _, inst in ipairs(o) do pcall(function() inst:Destroy() end) end
            espObjs[plr] = nil
        end

        local function applyESP(plr)
            if not espOn or not plr.Character then return end
            clearOne(plr)
            local char = plr.Character
            local hrp = char:FindFirstChild("HumanoidRootPart")
            local head = char:FindFirstChild("Head")
            if not hrp then return end
            local objs = {}

            local hl = Instance.new("Highlight")
            hl.Name = "TR_ESP_Highlight"
            hl.Adornee = char
            hl.FillColor = Color3.fromRGB(70, 150, 255)
            hl.OutlineColor = Color3.fromRGB(120, 190, 255)
            hl.FillTransparency = 0.55
            hl.OutlineTransparency = 0.1
            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            hl.Parent = char
            table.insert(objs, hl)

            -- ESP below label removed as requested (no player / TR player text)

            -- Ustte rol (OWNER / CREATOR / HELPER)
            local role = getRole(plr)
            if role and head then
                local above = Instance.new("BillboardGui")
                above.Name = "TR_ESP_Role"
                above.Adornee = head
                above.Size = UDim2.new(0, 130, 0, 18)
                above.StudsOffset = Vector3.new(0, 2.2, 0)
                above.AlwaysOnTop = true
                above.Parent = head
                local rl = Instance.new("TextLabel")
                rl.Size = UDim2.new(1, 0, 1, 0)
                rl.BackgroundTransparency = 1
                rl.Text = role
                rl.TextColor3 = ROLE_COLORS[role] or Color3.fromRGB(255, 255, 255)
                rl.TextStrokeTransparency = 0.2
                rl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                rl.Font = Enum.Font.GothamBold
                rl.TextSize = 13
                rl.Parent = above
                table.insert(objs, above)
            end

            espObjs[plr] = objs
        end

        local function refreshAll()
            for plr in pairs(espObjs) do clearOne(plr) end
            if not espOn then return end
            for _, plr in ipairs(Players:GetPlayers()) do
                applyESP(plr)
            end
        end

        ESPGroup:CreateToggle({
            Name = "ESP",
            Flag = "TRESP",
            Default = false,
            Callback = function(Value)
                espOn = Value
                if Value then
                    refreshAll()
                    table.insert(espConns, Players.PlayerAdded:Connect(function(plr)
                        plr.CharacterAdded:Connect(function()
                            task.wait(0.6)
                            if espOn then applyESP(plr) end
                        end)
                        if plr.Character then applyESP(plr) end
                    end))
                    for _, plr in ipairs(Players:GetPlayers()) do
                        table.insert(espConns, plr.CharacterAdded:Connect(function()
                            task.wait(0.6)
                            if espOn then applyESP(plr) end
                            pcall(function() LocalPlayer.Character:SetAttribute("TR_ftap", true) end)
                        end))
                    end
                else
                    for _, c in ipairs(espConns) do pcall(function() c:Disconnect() end) end
                    espConns = {}
                    refreshAll()
                end
            end
        })

        Players.PlayerRemoving:Connect(function(plr) clearOne(plr) end)
    end

    -- PCLD ESP (Box)
    do
        pcldEnabled = false
        pcldBoxes = {}
        pcldColor = Color3.fromRGB(0, 255, 255)
        pcldRainbow = false
        pcldConnections = {}

        local targetNames = {"partesp", "playercharacterlocationdetector"}

        function IsTarget(obj)
            if not obj:IsA("BasePart") then
                return false
            end
            for _, name in ipairs(targetNames) do
                if string.lower(obj.Name) == string.lower(name) then
                    return true
                end
            end
            return false
        end

        function AddBoxESP(obj)
            if pcldBoxes[obj] then
                return
            end
            local box = Instance.new("BoxHandleAdornment")
            box.Adornee = obj
            box.AlwaysOnTop = true
            box.ZIndex = 5
            box.Color3 = pcldColor
            box.Transparency = 0.3
            box.Size = obj.Size
            box.Parent = game.CoreGui
            pcldBoxes[obj] = box
            
            local conn = obj.AncestryChanged:Connect(function(_, parent)
                if not parent and pcldBoxes[obj] then
                    if pcldBoxes[obj] then
                        pcldBoxes[obj]:Destroy()
                    end
                    pcldBoxes[obj] = nil
                end
            end)
            table.insert(pcldConnections, conn)
        end

        function RemoveAllBoxes()
            for obj, box in pairs(pcldBoxes) do
                if box then
                    box:Destroy()
                end
            end
            pcldBoxes = {}
            for _, conn in ipairs(pcldConnections) do
                pcall(function() conn:Disconnect() end)
            end
            pcldConnections = {}
        end

        function Scan()
            for _, obj in ipairs(workspace:GetDescendants()) do
                if pcldEnabled and IsTarget(obj) then
                    AddBoxESP(obj)
                end
            end
        end

        function UpdatePCLDColors()
            for _, box in pairs(pcldBoxes) do
                pcall(function()
                    box.Color3 = pcldColor
                end)
            end
        end

        VisL:CreateToggle({
            Name = "Rainbow PCLD",
            Default = false,
            Callback = function(v)
                pcldRainbow = v
                if v then
                    task.spawn(function()
                        while pcldRainbow do
                            local hue = tick() % 1
                            local color = Color3.fromHSV(hue, 1, 1)
                            for _, box in pairs(pcldBoxes) do
                                pcall(function()
                                    box.Color3 = color
                                end)
                            end
                            task.wait(0.05)
                        end
                    end)
                else
                    pcldColor = Color3.fromRGB(0, 255, 255)
                    UpdatePCLDColors()
                end
            end
        })

        VisL:CreateToggle({
            Name = "Enable PCLD",
            Default = false,
            Callback = function(v)
                pcldEnabled = v
                if pcldEnabled then
                    Scan()
                    local conn = workspace.DescendantAdded:Connect(function(obj)
                        if pcldEnabled and IsTarget(obj) then
                            AddBoxESP(obj)
                        end
                    end)
                    table.insert(pcldConnections, conn)
                else
                    RemoveAllBoxes()
                end
            end
        })
    end
end

local KB_THRESHOLD = 5
local BYTE_THRESHOLD = KB_THRESHOLD * 1024
COOLDOWN = 30
local lastNotify = 0
local packetConnections = {}
-- Utility Functions using Script 6 UI's notification style
function packetNotify(title, text)
    pcall(function()
        Library:Notify({
            Title = title or "Packet Detected",
            Content = text or "",
            Duration = 7
        })
    end)
end

ServerGroup = Tabs.Server:CreateBlock({Name = "Lags", Side = "Left"})

KickGroup = Tabs.Server:CreateBlock({Name = "Server", Side = "Right"})

selectedHeight = "Spawn"

function getAllPlayers()
    local players = {}
    local isWhitelisted = _G.TR_IsWhitelisted or TR_IsWhitelisted
    for _, plr in pairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer and not (isWhitelisted and isWhitelisted(plr)) then
            table.insert(players, plr)
        end
    end
    return players
end

GrabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")

function spamOwnership(hrp)
    if not GrabEvents then return end
    local setOwner = GrabEvents:FindFirstChild("SetNetworkOwner")
    if setOwner and hrp then pcall(function() setOwner:FireServer(hrp, hrp.CFrame) end) end
end

function teleportToPlayer(myHrp, targetHrp)
    if not myHrp or not targetHrp then return end
    pcall(function()
        myHrp.CFrame = targetHrp.CFrame * CFrame.new(0, 5, 5)
        myHrp.AssemblyLinearVelocity = Vector3.zero
    end)
end

function destroyLineOnPlayer(hrp)
    if not GrabEvents then return end
    local createLine = GrabEvents:FindFirstChild("CreateGrabLine")
    local destroyLine = GrabEvents:FindFirstChild("DestroyGrabLine")
    if not createLine or not destroyLine then return end
    pcall(function()
        createLine:FireServer(hrp, CFrame.new(0, 1e9, 0))
        task.wait()
        destroyLine:FireServer(hrp)
    end)
end

lineLagThread = nil
lineLagEnabled = false

function startLineLag()
    if lineLagEnabled then return end
    lineLagEnabled = true
    lineLagThread = coroutine.create(function()
        if not GrabEvents then return end
        local createLine = GrabEvents:FindFirstChild("CreateGrabLine")
        if not createLine then return end
        while lineLagEnabled do
            local spawnLocation = Workspace:FindFirstChild("SpawnLocation") or Workspace:FindFirstChild("Spawn") or (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart"))
            if spawnLocation then
                local randomX = math.random(-1e9, 1e9)
                local randomZ = math.random(-1e9, 1e9)
                local directions = {CFrame.new(randomX, 0, randomZ), CFrame.new(-randomX, 0, -randomZ), CFrame.new(randomX, 0, -randomZ), CFrame.new(-randomX, 0, randomZ)}
                for _, pos in pairs(directions) do createLine:FireServer(spawnLocation, pos) end
            end
            task.wait()
        end
    end)
    coroutine.resume(lineLagThread)
end

function stopLineLag()
    lineLagEnabled = false
    if lineLagThread then coroutine.close(lineLagThread); lineLagThread = nil end
end

KickGroup:CreateDropdown({
    Name = "Destroy Height",
    Flag = "DestroyHeight",
    Items = {"Spawn", "Heaven"},
    Default = "Spawn",
    Callback = function(Value)
        selectedHeight = Value
    end
})

-- Shared destroy pipeline: lag (optional) -> ownership spam -> send to height -> grab-line destroy x8
function runDestroyOn(list, withLag)
    local height = (selectedHeight == "Heaven") and 1e9 or 35
    if withLag then
        startLineLag()
        task.wait(1)
    end

    if #list == 0 then
        if withLag then stopLineLag() end
        return
    end

    local myChar = LocalPlayer.Character
    local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myHrp then
        if withLag then stopLineLag() end
        return
    end

    local playerData = {}
    local isWhitelisted = _G.TR_IsWhitelisted or TR_IsWhitelisted
    for _, plr in ipairs(list) do
        if not (isWhitelisted and isWhitelisted(plr)) then
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then table.insert(playerData, {player = plr, hrp = hrp}) end
        end
    end
    if #playerData == 0 then
        if withLag then stopLineLag() end
        return
    end

    for _, data in ipairs(playerData) do
        teleportToPlayer(myHrp, data.hrp)
        task.wait(0.2)
        spamOwnership(data.hrp)
        task.wait()
    end

    local radius = 40
    local angleStep = (math.pi * 2) / #playerData
    for idx, data in ipairs(playerData) do
        local angle = (idx - 1) * angleStep
        local x = math.cos(angle) * radius
        local z = math.sin(angle) * radius

        pcall(function()
            data.hrp.CFrame = CFrame.new(x, height, z)
            data.hrp.AssemblyLinearVelocity = Vector3.zero
        end)

        local bp = Instance.new("BodyPosition")
        bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
        bp.P = 40000000
        bp.Position = Vector3.new(x, height, z)
        bp.Parent = data.hrp
        task.delay(2, function() pcall(function() bp:Destroy() end) end)
        task.wait()
    end

    for i = 1, 8 do
        for _, data in ipairs(playerData) do destroyLineOnPlayer(data.hrp) end
        task.wait(0.3)
    end
end

KickGroup:CreateButton({
    Name = "Destroy Server",
    Callback = function()
        task.spawn(function()
            runDestroyOn(getAllPlayers(), true)
        end)
    end
})

