do
    ReplicatedStorage = game:GetService("ReplicatedStorage")
    R = ReplicatedStorage

    packetLagActive = false
    packetLagTask = nil
    packetLagStrength = 1
    packetLagSize = 1
    packetCustomText = "Ranax FTAP on top"
    packetSpamDelay = 0.5

    local function getPacketSize()
        return packetLagSize * 1000000
    end

    local function buildPacketPayload(targetBytes)
        local rawMsg = (packetCustomText and packetCustomText ~= "") and packetCustomText or "Ranax FTAP on top"
        local header = "[" .. LocalPlayer.Name .. "]: " .. rawMsg
        local targetSize = math.max(targetBytes or 6000, 6000) -- En az 6KB (diğer hilelerin 5KB eşiğini tetiklesin)
        if #header >= targetSize then
            return header
        end
        return header .. " " .. string.rep("A", targetSize - #header)
    end

    ServerGroup:CreateSlider({
        Name = "Packet Size (MB)",
        Flag = "PacketSize",
        Min = 1,
        Max = 20,
        Default = 1,
        Callback = function(v)
            packetLagSize = v
        end
    })

    ServerGroup:CreateInput({
        Name = "Packet Message Text",
        Placeholder = "Type packet text here...",
        Default = "Ranax FTAP on top",
        Callback = function(text)
            packetCustomText = text
        end
    })

    ServerGroup:CreateButton({
        Name = "Send Text Packet (Broadcast)",
        Callback = function()
            GrabEvents = R:FindFirstChild("GrabEvents")
            ExtendGrabLine = GrabEvents and GrabEvents:FindFirstChild("ExtendGrabLine")
            if not ExtendGrabLine then return end
            local payload = buildPacketPayload(6500)
            pcall(function()
                ExtendGrabLine:FireServer(payload)
            end)
            Library:Notify({
                Title = "Packet Broadcast",
                Content = "Packet sent with message: " .. (packetCustomText or "Ranax FTAP"),
                Duration = 3
            })
        end
    })

    ServerGroup:CreateButton({
        Name = "Send Packet Lag (Once)",
        Callback = function()
            GrabEvents = R:FindFirstChild("GrabEvents")
            ExtendGrabLine = GrabEvents and GrabEvents:FindFirstChild("ExtendGrabLine")
            if not ExtendGrabLine then return end
            local size = getPacketSize()
            local payload = buildPacketPayload(size)
            pcall(function()
                ExtendGrabLine:FireServer(payload)
            end)
            Library:Notify({
                Title = "Packet Lag",
                Content = "Packet sent! Size: " .. packetLagSize .. " MB",
                Duration = 3
            })
        end
    })

    ServerGroup:CreateSlider({
        Name = "Packet Spam Delay",
        Min = 0.05,
        Max = 2.0,
        Default = 0.5,
        Rounding = 2,
        Callback = function(v)
            packetSpamDelay = v
        end
    })

    ServerGroup:CreateToggle({
        Name = "Packet Lag (Loop)",
        Flag = "PacketLag",
        Default = false,
        Callback = function(Value)
            packetLagActive = Value
            if Value then
                packetLagTask = task.spawn(function()
                    GrabEvents = R:FindFirstChild("GrabEvents")
                    ExtendGrabLine = GrabEvents and GrabEvents:FindFirstChild("ExtendGrabLine")
                    if not ExtendGrabLine then
                        packetLagActive = false
                        return
                    end
                    while packetLagActive do
                        local size = getPacketSize()
                        local payload = buildPacketPayload(size)
                        pcall(function()
                            ExtendGrabLine:FireServer(payload)
                        end)
                        task.wait(packetSpamDelay or 0.5)
                    end
                end)
            else
                if packetLagTask then
                    task.cancel(packetLagTask)
                    packetLagTask = nil
                end
            end
        end
    })
end

_G.Brkhs = false
fbexpConn = nil

function fbexp()
    if fbexpConn then fbexpConn:Disconnect() fbexpConn = nil end
    fbexpConn = workspace.ChildAdded:Connect(function(child)
        if _G.Brkhs then
            if fbexpConn then fbexpConn:Disconnect() fbexpConn = nil end
            return
        end
        if child.Name == "Part" and (child.Position - Vector3.new(263.4, -4.79, 466.8)).Magnitude <= 2 then
            _G.Brkhs = true
            Library:Notify({Title = "Done!", Description = "Destroyed Houses Barrier", Duration = 3})
            for _, plot in pairs(workspace.Plots:GetChildren()) do
                barrier = plot:FindFirstChild("Barrier")
                if barrier then
                    for _, part in pairs(barrier:GetChildren()) do
                        if part:IsA("BasePart") and part.CanCollide == true then
                            part.CanCollide = false
                        end
                    end
                end
            end
            if fbexpConn then fbexpConn:Disconnect() fbexpConn = nil end
        end
    end)
end

function breakhouse(mode)
    if not mode then return end
    _G.Brkhs = false
    fbexp()
    startTime = tick()
    repeat
        pcall(function()
            game:GetService("ReplicatedStorage").MenuToys.SpawnToyRemoteFunction:InvokeServer(
                "BallSnowball",
                CFrame.new(263.5, -4.5, 486.9),
                Vector3.new(0, 0, 0)
            )
        end)
        wStart = tick()
        repeat task.wait() until not LocalPlayer:FindFirstChild("CanSpawnToy") or LocalPlayer.CanSpawnToy.Value or tick() - wStart > 2
    until _G.Brkhs or tick() - startTime >= 10
    if fbexpConn then fbexpConn:Disconnect() fbexpConn = nil end
end

