    char = plr.Character
    hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    pcall(function()
        game:GetService("ReplicatedStorage").MenuToys.SpawnToyRemoteFunction:InvokeServer(
