WingsGroup = Tabs.Toy:CreateBlock({Name = "Wings & Attachments", Side = "Left"})
BarrierGroup = Tabs.Toy:CreateBlock({Name = "Barriers", Side = "Left"})
SparklerGroup = Tabs.Toy:CreateBlock({Name = "Sparkler", Side = "Left"})
ExplosionConfigBox = Tabs.Toy:CreateBlock({Name = "Explosions (1:1 Resonance)", Side = "Right"})
ExplosionDefenseBox = Tabs.Toy:CreateBlock({Name = "Explosion Defense & Mouse", Side = "Right"})
ExplosionVisualBox = Tabs.Toy:CreateBlock({Name = "Visual Customization", Side = "Right"})

do
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local RunService = game:GetService("RunService")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local UserInputService = game:GetService("UserInputService")
    local Workspace = game:GetService("Workspace")

    local function notify(title, desc, duration)
        title = title or "Resonance Explosions"
        pcall(function()
            if Library and Library.Notify then
                Library:Notify({ Title = title, Content = desc or "", Duration = duration or 2.5 })
            else
                game:GetService("StarterGui"):SetCore("SendNotification", { Title = title, Text = desc or "", Duration = duration or 2.5 })
            end
        end)
    end

    -- =========================================================================
    -- RESONANCE 1:1 EXPLOSION STATE & CONFIG
    -- =========================================================================
    local ResExpConfig = {
        ExplosionMethod = "BombMissile",
        MissilesToFire = 1,
        AutoExplodeTarget = false,
        ExplodeInterval = 0.15,
        AntiExplosion = false,
        ImmunityAntiExplosion = false,
        ExplodeOnMouse = false,
        PredictMovement = true,
        SelectedTargets = {},
        Visuals = {
            ColorEnabled = false,
            CustomColor = Color3.fromRGB(255, 0, 0),
            Rainbow = false,
            Invert = false,
            Brightness = 10,
            Size = 1,
            Speed = 1,
            Lifetime = 1,
            Density = 1,
            Transparency = 0,
            CustomTransparency = false,
            BlendMode = "Default",
        }
    }

    -- Remotes resolution
    local MenuToys = ReplicatedStorage:WaitForChild("MenuToys", 5)
    local SpawnToyRF = MenuToys and (MenuToys:FindFirstChild("SpawnToyRemoteFunction") or MenuToys:FindFirstChild("SpawnToyFunction"))
    local DestroyToyRE = MenuToys and MenuToys:FindFirstChild("DestroyToy")
    local BombEvents = ReplicatedStorage:WaitForChild("BombEvents", 5)
    local BombExplodeRE = BombEvents and BombEvents:WaitForChild("BombExplode", 5)
    local GrabEvents = ReplicatedStorage:WaitForChild("GrabEvents", 5)
    local SetNetworkOwnerRE = GrabEvents and GrabEvents:WaitForChild("SetNetworkOwner", 5)
    local DestroyGrabLineRE = GrabEvents and GrabEvents:WaitForChild("DestroyGrabLine", 5)

    local ResExp = {}

    function ResExp.Char(p)
        p = p or LocalPlayer
        local char = p and p.Character
        local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        return char, hrp, hum
    end

    function ResExp.ResetVelocity(part)
        if not part or not part:IsA("BasePart") then return end
        pcall(function()
            part.AssemblyLinearVelocity = Vector3.zero
            part.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    local HitboxNames = {
        BombMissile = "PartHitDetector",
        BombDarkMatter = "PartHitDetector",
        FireworkMissile = "PartHitDetector",
        BombBalloon = "Balloon",
        BallSnowball = "SnowRagdollPart",
        PresentBig = "Box",
        PresentSmall = "Box",
    }

    local SetupParts = {
        BombMissile = "Body",
        BombDarkMatter = "Pyramid",
        FireworkMissile = "Hitbox",
        BombBalloon = "Balloon",
        BallSnowball = "SoundPart",
        PresentBig = "Box",
        PresentSmall = "Box",
    }

    function ResExp.SNO(part)
        if not part or not part:IsA("BasePart") or not SetNetworkOwnerRE then return false end
        local _, myHRP = ResExp.Char()
        local rayCF = myHRP and CFrame.new((myHRP.CFrame * CFrame.new(0, 1.593, 0)).Position, part.Position) or part.CFrame
        pcall(function()
            SetNetworkOwnerRE:FireServer(part, rayCF)
        end)
        return true
    end

    function ResExp.GetSpawnedToys()
        local inPlot = LocalPlayer:FindFirstChild("InPlot")
        if inPlot and inPlot.Value then
            local plots = Workspace:FindFirstChild("Plots")
            if plots then
                for i = 1, 5 do
                    local p = plots:FindFirstChild("Plot"..i)
                    if p and p:FindFirstChild("PlotSign") then
                        local sign = p.PlotSign
                        for _, name in ipairs({"ThisPlotsOwners","ThisPlotsOwner","ThisPlotOwners"}) do
                            local c = sign:FindFirstChild(name)
                            if c then
                                local owner = c:IsA("StringValue") and c or c:FindFirstChildOfClass("StringValue")
                                if owner and owner.Value == LocalPlayer.Name then
                                    local pi = Workspace:FindFirstChild("PlotItems")
                                    if pi and pi:FindFirstChild("Plot"..i) then
                                        return pi:FindFirstChild("Plot"..i)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        return Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
    end

    local lastSpawnedToyFolder = nil

    function ResExp.GetMyToyFolders()
        local list = {}
        local name = (LocalPlayer and LocalPlayer.Name) or (game.Players.LocalPlayer and game.Players.LocalPlayer.Name)

        local function addFolder(f)
            if f and f:IsA("Instance") and not table.find(list, f) then
                table.insert(list, f)
            end
        end

        if name then
            -- 1. Standard Lobby / Global folder
            addFolder(Workspace:FindFirstChild(name .. "SpawnedInToys"))

            -- 2. Any other folder ending with SpawnedInToys
            for _, child in ipairs(Workspace:GetChildren()) do
                if child.Name == name .. "SpawnedInToys" or (child.Name:find("SpawnedInToys") and child.Name:find(name)) then
                    addFolder(child)
                end
            end

            -- 3. Check Workspace.PlotItems for owned plots
            local plotItems = Workspace:FindFirstChild("PlotItems")
            local plots = Workspace:FindFirstChild("Plots")
            if plotItems and plots then
                for _, p in ipairs(plots:GetChildren()) do
                    local sign = p:FindFirstChild("PlotSign")
                    if sign then
                        for _, ownerBoxName in ipairs({"ThisPlotsOwners", "ThisPlotsOwner", "ThisPlotOwners"}) do
                            local box = sign:FindFirstChild(ownerBoxName)
                            if box then
                                for _, val in ipairs(box:GetChildren()) do
                                    if (val:IsA("StringValue") and val.Value == name) or val.Name == name then
                                        local pFolder = plotItems:FindFirstChild(p.Name)
                                        if pFolder then addFolder(pFolder) end
                                    end
                                end
                            end
                        end
                    end
                end
            end

            -- 4. If player character is near a plot, include that plot's folder
            if plotItems and plots then
                local char = (LocalPlayer and LocalPlayer.Character) or (game.Players.LocalPlayer and game.Players.LocalPlayer.Character)
                local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
                if hrp then
                    for _, p in ipairs(plots:GetChildren()) do
                        local sign = p:FindFirstChild("PlotSign")
                        local signPart = (sign and (sign:FindFirstChildWhichIsA("BasePart") or sign.PrimaryPart)) or p:FindFirstChildWhichIsA("BasePart")
                        if signPart and (signPart.Position - hrp.Position).Magnitude < 140 then
                            local pFolder = plotItems:FindFirstChild(p.Name)
                            if pFolder then addFolder(pFolder) end
                        end
                    end
                end
            end

            -- 5. Last known spawned toy folder (from InvokeServer result)
            if lastSpawnedToyFolder and lastSpawnedToyFolder.Parent then
                addFolder(lastSpawnedToyFolder)
            end

            -- 6. Fallback: if list is still empty, include all non-empty folders in PlotItems
            if #list == 0 and plotItems then
                for _, pFolder in ipairs(plotItems:GetChildren()) do
                    if #pFolder:GetChildren() > 0 then
                        addFolder(pFolder)
                    end
                end
            end
        end

        return list
    end

    function ResExp.GetAllBombs(method)
        local folders = ResExp.GetMyToyFolders()
        local methodType = method or ResExpConfig.ExplosionMethod or "BombMissile"
        local list = {}
        for _, folder in ipairs(folders) do
            for _, toy in ipairs(folder:GetChildren()) do
                if toy.Name == methodType or (methodType == "BombMissile" and toy.Name:find("Missile")) or (methodType == "BombDarkMatter" and toy.Name:find("DarkMatter")) then
                    table.insert(list, toy)
                end
            end
        end
        return list
    end

    function ResExp.DestroyToy(toy)
        if not toy then return end
        if DestroyToyRE then
            pcall(function() DestroyToyRE:FireServer(toy) end)
        else
            pcall(function() toy:Destroy() end)
        end
    end

    function ResExp.DeleteAllBombs(method)
        for _, bomb in ipairs(ResExp.GetAllBombs(method)) do
            ResExp.DestroyToy(bomb)
        end
    end

    function ResExp.SetupBomb(bomb)
        if not bomb then return end
        local primary = bomb.PrimaryPart or bomb:FindFirstChildWhichIsA("BasePart")
        if not primary then return end
        local partName = SetupParts[bomb.Name] or "PartHitDetector"
        local hitPart = bomb:FindFirstChild(partName) or bomb:FindFirstChild("PartHitDetector") or bomb:FindFirstChild("Body") or primary
        if hitPart then
            ResExp.SNO(hitPart)
        end
        pcall(function()
            for _, v in ipairs(primary:GetChildren()) do
                if v:IsA("BodyVelocity") or v.Name == "Stable" then
                    v:Destroy()
                end
            end
            local bodyVel = Instance.new("BodyVelocity")
            bodyVel.Velocity = Vector3.zero
            bodyVel.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
            bodyVel.Name = "Stable"
            bodyVel.Parent = primary
            bomb:PivotTo(CFrame.new(math.random(-500, 500), 10000, math.random(-500, 500)))
        end)
    end

    -- =========================================================================
    -- RESONANCE 1:1 EXPLODE MISSILE ENGINE (direct tracking + predictive movement)
    -- =========================================================================
    function ResExp.ExplodeMissile(target, explosionMethod, missilesToFire)
        local _, myHRP = ResExp.Char()
        if not myHRP or not target then return false end
        if not BombEvents or not BombEvents:FindFirstChild("BombExplode") then
            BombEvents = ReplicatedStorage:FindFirstChild("BombEvents") or ReplicatedStorage:WaitForChild("BombEvents", 3)
        end
        local explodeRemote = BombEvents and BombEvents:FindFirstChild("BombExplode")

        explosionMethod = explosionMethod or ResExpConfig.ExplosionMethod or "BombMissile"
        missilesToFire = math.clamp(missilesToFire or ResExpConfig.MissilesToFire or 1, 1, 17)

        -- Target resolution (Instance or Vector3)
        local targetPos
        local targetHRP = nil
        if typeof(target) == "Instance" then
            if target:IsA("Player") and target.Character then
                targetHRP = target.Character:FindFirstChild("HumanoidRootPart") or target.Character:FindFirstChild("Torso")
            elseif target:IsA("Model") then
                targetHRP = target:FindFirstChild("HumanoidRootPart") or target:FindFirstChild("Torso") or target.PrimaryPart or target:FindFirstChildWhichIsA("BasePart")
            elseif target:IsA("BasePart") then
                targetHRP = target
            end
            if not targetHRP then return false end
            targetPos = targetHRP.Position
            -- Predictive movement: calculate travel lead based on velocity and distance
            if ResExpConfig.PredictMovement and targetHRP.AssemblyLinearVelocity.Magnitude > 0.3 then
                local vel = targetHRP.AssemblyLinearVelocity
                local dist = (targetHRP.Position - myHRP.Position).Magnitude
                local leadTime = math.clamp(dist / 320 + 0.16, 0.12, 0.65)
                targetPos = targetPos + (vel * leadTime)
            end
        elseif typeof(target) == "Vector3" then
            targetPos = target
            targetHRP = { Position = target, AssemblyLinearVelocity = Vector3.zero }
        else
            return false
        end

        -- Delete old batch first to keep toy limit fresh
        ResExp.DeleteAllBombs(explosionMethod)
        task.wait(0.03)

        local function triggerInstantBomb(bomb)
            if not bomb or not bomb.Parent then return end
            local partName = HitboxNames[bomb.Name] or "PartHitDetector"
            local hitbox = bomb:FindFirstChild(partName) or bomb:FindFirstChild("PartHitDetector") or bomb:FindFirstChild("Hitbox") or bomb.PrimaryPart or bomb:FindFirstChildWhichIsA("BasePart")
            local wedge = bomb:FindFirstChild("Wedge") or bomb:FindFirstChild("Spinner") or bomb:FindFirstChild("SoundPart") or hitbox

            if hitbox and explodeRemote then
                pcall(function()
                    if wedge then ResExp.SNO(wedge) end
                    ResExp.SNO(hitbox)
                    hitbox.CFrame = CFrame.new(targetPos)
                    hitbox.AssemblyLinearVelocity = Vector3.zero
                    hitbox.AssemblyAngularVelocity = Vector3.zero
                end)
                pcall(function()
                    explodeRemote:FireServer({
                        Hitbox = hitbox,
                        PositionPart = (typeof(targetHRP) == "Instance" and targetHRP) or hitbox,
                    }, targetPos)
                end)
                task.delay(0.2, function()
                    ResExp.DestroyToy(bomb)
                end)
            end
        end

        -- Immediately fire any already existing bombs
        for _, b in ipairs(ResExp.GetAllBombs(explosionMethod)) do
            triggerInstantBomb(b)
        end

        -- Spawn requested missile batch with direct instance capture
        local spawnCF = myHRP.CFrame * CFrame.new(0, 15, 0)
        for i = 1, missilesToFire do
            task.spawn(function()
                local spawnedBomb = nil
                if SpawnToyRF then
                    pcall(function()
                        spawnedBomb = SpawnToyRF:InvokeServer(explosionMethod, spawnCF, Vector3.zero)
                    end)
                end
                if spawnedBomb and typeof(spawnedBomb) == "Instance" and spawnedBomb.Parent then
                    lastSpawnedToyFolder = spawnedBomb.Parent
                    triggerInstantBomb(spawnedBomb)
                else
                    task.wait(0.08)
                    for _, folder in ipairs(ResExp.GetMyToyFolders()) do
                        for _, child in ipairs(folder:GetChildren()) do
                            if child.Name == explosionMethod or (explosionMethod == "BombMissile" and child.Name:find("Missile")) or (explosionMethod == "BombDarkMatter" and child.Name:find("DarkMatter")) then
                                triggerInstantBomb(child)
                            end
                        end
                    end
                end
            end)
        end

        return true
    end

    -- =========================================================================
    -- RESONANCE 1:1 ANTI-EXPLOSION DEFENSE (lines 32964-32984 in Resonance)
    -- =========================================================================
    Workspace.ChildAdded:Connect(function(child)
        if child.Name == "Part" and ResExpConfig.AntiExplosion then
            local myChar, myHRP, myHum = ResExp.Char()
            if myHRP and myHum and (child.Position - myHRP.Position).Magnitude <= 20 then
                myHRP.Anchored = true
                task.wait(0.02)
                if not myHum.SeatPart then
                    myHum.Sit = false
                end
                for _, pt in ipairs(myChar:GetDescendants()) do
                    if pt:IsA("BasePart") and (pt.Name:find("Ragdoll") or pt.Name:find("Limb")) then
                        pt.CanCollide = false
                    end
                end
                ResExp.ResetVelocity(myHRP)
                myHRP.Anchored = false
            end
        end

        -- Resonance 1:1 Immunity Anti-Explosion for Whitelisted Friends (lines 34669-34685)
        if child.Name == "Part" and ResExpConfig.ImmunityAntiExplosion then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p)) then
                    local _, tHRP, tHum = ResExp.Char(p)
                    if tHRP and tHum and tHum.Health > 0 and (child.Position - tHRP.Position).Magnitude <= 20 then
                        tHRP.Anchored = true
                        task.wait(0.02)
                        ResExp.ResetVelocity(tHRP)
                        tHRP.Anchored = false
                    end
                end
            end
        end
    end)

    -- =========================================================================
    -- RESONANCE 1:1 AUTO EXPLODE TARGET LOOP (lines 34045-34080 in Resonance)
    -- =========================================================================
    task.spawn(function()
        while true do
            task.wait(math.max(ResExpConfig.ExplodeInterval or 0.45, 0.45))
            if ResExpConfig.AutoExplodeTarget and ResExpConfig.ExplosionMethod then
                local inPlot = LocalPlayer:FindFirstChild("InPlot")
                local inOwnedPlot = LocalPlayer:FindFirstChild("InOwnedPlot")
                local canFireInPlot = not (inPlot and inPlot.Value and not (inOwnedPlot and inOwnedPlot.Value))

                if canFireInPlot then
                    -- Collect valid targets based on dropdown selection
                    local targetList = {}
                    local selName = ResExpConfig.SelectedTargetName or "Closest Player"

                    if selName == "All Players (Spam)" then
                        for _, p in ipairs(Players:GetPlayers()) do
                            if p ~= LocalPlayer and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p)) then
                                table.insert(targetList, p)
                            end
                        end
                    elseif selName ~= "Closest Player" and selName ~= "" then
                        local p = Players:FindFirstChild(selName)
                        if p and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p)) then
                            table.insert(targetList, p)
                        end
                    else
                        -- Closest player fallback
                        local closestDist = 250
                        local closestP = nil
                        local _, myHRP = ResExp.Char()
                        if myHRP then
                            for _, p in ipairs(Players:GetPlayers()) do
                                if p ~= LocalPlayer and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p)) then
                                    local _, tHRP, tHum = ResExp.Char(p)
                                    if tHRP and tHum and tHum.Health > 0 then
                                        local d = (tHRP.Position - myHRP.Position).Magnitude
                                        if d < closestDist then
                                            closestDist = d
                                            closestP = p
                                        end
                                    end
                                end
                            end
                        end
                        if closestP then table.insert(targetList, closestP) end
                    end

                    for _, p in ipairs(targetList) do
                        if not ResExpConfig.AutoExplodeTarget then break end
                        if _G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p) then continue end

                        local targetInPlot = p:FindFirstChild("InPlot")
                        local skipPlot = false
                        if targetInPlot and targetInPlot.Value then
                            skipPlot = not ((inOwnedPlot and inOwnedPlot.Value) or ResExpConfig.ExplosionMethod == "BallSnowball")
                        end

                        if not skipPlot then
                            local _, tHRP, tHum = ResExp.Char(p)
                            if tHRP and tHum and tHum.Health > 0 then
                                ResExp.ExplodeMissile(tHRP, ResExpConfig.ExplosionMethod, ResExpConfig.MissilesToFire)
                            end
                        end
                    end
                end
            end
        end
    end)

    -- =========================================================================
    -- EXPLODE ON MOUSE CLICK ENGINE (lines 41346-41348 in Resonance)
    -- =========================================================================
    UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed then return end
        if ResExpConfig.ExplodeOnMouse and input.UserInputType == Enum.UserInputType.MouseButton1 then
            local mouse = LocalPlayer:GetMouse()
            if mouse and mouse.Hit then
                ResExp.ExplodeMissile(mouse.Hit.Position, ResExpConfig.ExplosionMethod, ResExpConfig.MissilesToFire)
            end
        end
    end)

    -- =========================================================================
    -- VISUAL CUSTOMIZATION ENGINE
    -- =========================================================================
    local origpresets = {}
    local origbrightness = {}
    local origsizes = {}
    local origspeeds = {}
    local origlifetimes = {}
    local origrates = {}

    local function getExplosionParticles()
        local list = {}
        if ReplicatedStorage:FindFirstChild("ExplosionMaker") and ReplicatedStorage.ExplosionMaker:FindFirstChild("ParticlePresets") then
            for _, pt in ipairs(ReplicatedStorage.ExplosionMaker.ParticlePresets:GetChildren()) do
                if pt:IsA("ParticleEmitter") then table.insert(list, pt) end
            end
        end
        return list
    end

    local function initParticlePresets()
        for _, pt in ipairs(getExplosionParticles()) do
            origpresets[pt] = pt.Color
            origbrightness[pt] = pt.Brightness
            origsizes[pt] = pt.Size
            origspeeds[pt] = pt.Speed
            origlifetimes[pt] = pt.Lifetime
            origrates[pt] = pt.Rate
        end
    end
    initParticlePresets()

    local function updateParticleVisuals()
        local v = ResExpConfig.Visuals
        for _, pt in ipairs(getExplosionParticles()) do
            -- Color
            if v.Rainbow then
                pt.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.new(1, 0, 0)),
                    ColorSequenceKeypoint.new(0.25, Color3.new(0, 1, 0)),
                    ColorSequenceKeypoint.new(0.5, Color3.new(0, 0, 1)),
                    ColorSequenceKeypoint.new(0.75, Color3.new(1, 1, 0)),
                    ColorSequenceKeypoint.new(1, Color3.new(1, 0, 0)),
                })
            elseif v.ColorEnabled then
                local col = v.Invert and Color3.new(1 - v.CustomColor.R, 1 - v.CustomColor.G, 1 - v.CustomColor.B) or v.CustomColor
                pt.Color = ColorSequence.new(col)
            elseif origpresets[pt] then
                pt.Color = origpresets[pt]
            end

            -- Brightness
            if origbrightness[pt] then
                pt.Brightness = (v.Brightness == 10) and origbrightness[pt] or (origbrightness[pt] * 2 * (v.Brightness - 9))
            end

            -- Size
            if origsizes[pt] then
                local kps = {}
                for _, kp in ipairs(origsizes[pt].Keypoints) do
                    table.insert(kps, NumberSequenceKeypoint.new(kp.Time, kp.Value * v.Size, kp.Envelope))
                end
                pt.Size = NumberSequence.new(kps)
            end

            -- Speed
            if origspeeds[pt] then
                pt.Speed = NumberRange.new(origspeeds[pt].Min * v.Speed, origspeeds[pt].Max * v.Speed)
            end

            -- Lifetime
            if origlifetimes[pt] then
                pt.Lifetime = NumberRange.new(origlifetimes[pt].Min * v.Lifetime, origlifetimes[pt].Max * v.Lifetime)
            end

            -- Rate
            if origrates[pt] then
                pt.Rate = origrates[pt] * v.Density
            end

            -- Transparency
            if v.CustomTransparency then
                pt.Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, v.Transparency),
                    NumberSequenceKeypoint.new(1, 1)
                })
            end

            -- Blend
            pcall(function() pt.LightEmission = (v.BlendMode == "Additive") and 1 or 0 end)
        end
    end

