local RanaxToyHelpers = nil

do
    local function _initWingsAndSexFeatures()
-- ============================================================
-- ============================================================
-- Unified Make Wings System (Resonance Coconut & Pallet Wings)
-- Select: "None", "Pallet", "Coconut"
-- ============================================================
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer or game.Players.LocalPlayer
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local Workspace = game:GetService("Workspace")
    local RunService = game:GetService("RunService")
    local HttpService = game:GetService("HttpService")
    local TweenService = game:GetService("TweenService")
    local lastSpawnedToyFolder = nil
    local function getToyFolder()
        local name = (LocalPlayer and LocalPlayer.Name) or (game.Players.LocalPlayer and game.Players.LocalPlayer.Name)
        if not name then return nil end
        return Workspace:FindFirstChild(name .. "SpawnedInToys")
    end

    local function getMyToyFolders()
        local list = {}
        local name = (LocalPlayer and LocalPlayer.Name) or (game.Players.LocalPlayer and game.Players.LocalPlayer.Name)

        local function addFolder(f)
            if f and f:IsA("Instance") and not table.find(list, f) then
                table.insert(list, f)
            end
        end

        if name then
            -- 1. Standard Lobby / Global folder
            addFolder(Workspace:FindFirstChild(name .. "SpawnedInToys"))

            -- 2. Any other folder ending with SpawnedInToys
            for _, child in ipairs(Workspace:GetChildren()) do
                if child.Name == name .. "SpawnedInToys" or (child.Name:find("SpawnedInToys") and child.Name:find(name)) then
                    addFolder(child)
                end
            end

            -- 3. Check Workspace.PlotItems for owned plots
            local plotItems = Workspace:FindFirstChild("PlotItems")
            local plots = Workspace:FindFirstChild("Plots")
            if plotItems and plots then
                for _, p in ipairs(plots:GetChildren()) do
                    local sign = p:FindFirstChild("PlotSign")
                    if sign then
                        for _, ownerBoxName in ipairs({"ThisPlotsOwners", "ThisPlotsOwner", "ThisPlotOwners"}) do
                            local box = sign:FindFirstChild(ownerBoxName)
                            if box then
                                for _, val in ipairs(box:GetChildren()) do
                                    if (val:IsA("StringValue") and val.Value == name) or val.Name == name then
                                        local pFolder = plotItems:FindFirstChild(p.Name)
                                        if pFolder then addFolder(pFolder) end
                                    end
                                end
                            end
                        end
                    end
                end
            end

            -- 4. If player character is near a plot, include that plot's folder
            if plotItems and plots then
                local char = (LocalPlayer and LocalPlayer.Character) or (game.Players.LocalPlayer and game.Players.LocalPlayer.Character)
                local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
                if hrp then
                    for _, p in ipairs(plots:GetChildren()) do
                        local sign = p:FindFirstChild("PlotSign")
                        local signPart = (sign and (sign:FindFirstChildWhichIsA("BasePart") or sign.PrimaryPart)) or p:FindFirstChildWhichIsA("BasePart")
                        if signPart and (signPart.Position - hrp.Position).Magnitude < 140 then
                            local pFolder = plotItems:FindFirstChild(p.Name)
                            if pFolder then addFolder(pFolder) end
                        end
                    end
                end
            end

            -- 5. Last known spawned toy folder (from InvokeServer result)
            if lastSpawnedToyFolder and lastSpawnedToyFolder.Parent then
                addFolder(lastSpawnedToyFolder)
            end

            -- 6. Fallback: if list is still empty, include all non-empty folders in PlotItems
            if #list == 0 and plotItems then
                for _, pFolder in ipairs(plotItems:GetChildren()) do
                    if #pFolder:GetChildren() > 0 then
                        addFolder(pFolder)
                    end
                end
            end
        end

        return list
    end

    -- ============================================================
    -- Resonance BreakHoldable + SNO + Toy Tornado Orbit Physics Engine
    -- ============================================================
    local breakHoldable, spawnSingleToy, setupPartPhysics, driveToyOrbitPart
    do
        local holdBreakMutex = false
        local LIGHT_PHYS = PhysicalProperties.new(0.01, 0, 0, 0, 0)

        local function destroyToyServer(item)
            if not item then return end
            pcall(function() item:SetAttribute("PendingDestroy", true) end)
            local mt = ReplicatedStorage:FindFirstChild("MenuToys")
            local dt = mt and mt:FindFirstChild("DestroyToy")
            if dt then
                pcall(function() dt:FireServer(item) end)
            end
        end

        local function isHoldableToyName(name)
            if not name then return false end
            return name == "FoodCoconut"
                or name == "ToolPencil"
                or name:find("Sparkler") ~= nil
                or name:find("Extinguisher") ~= nil
                or name:find("Food") ~= nil
                or name:find("Tool") ~= nil
        end

        local function getToyMainPart(item)
            if not item then return nil end
            if item:IsA("BasePart") then return item end
            if item.Name:find("FireworkSparkler") then
                local spk = item:FindFirstChild("Main") or item:FindFirstChild("SoundPart") or item.PrimaryPart
                if spk and spk:IsA("BasePart") then return spk end
            end
            local sp = item:FindFirstChild("SoundPart") or item:FindFirstChild("Main") or item.PrimaryPart
            if sp and sp:IsA("BasePart") then return sp end
            local bestPart = nil
            local maxVol = -1
            for _, p in ipairs(item:GetDescendants()) do
                if p:IsA("BasePart") and p.Name ~= "HoldPart" and p.Name ~= "StickyPart" and p.Name ~= "PartHitDetector" then
                    if (p.AssemblyRootPart or p) == p then
                        return p
                    end
                    local vol = p.Size.X * p.Size.Y * p.Size.Z
                    if vol > maxVol then
                        maxVol = vol
                        bestPart = p
                    end
                end
            end
            return bestPart or item:FindFirstChildWhichIsA("BasePart", true)
        end

        local function prepareToyParts(item, mainPart)
            if not item or not item.Parent then return end
            for _, d in ipairs(item:GetDescendants()) do
                if d:IsA("BasePart") then
                    d.CanCollide = false
                    d.CanQuery = false
                    d.CanTouch = false
                    d.Anchored = false
                    if mainPart and d ~= mainPart then
                        d.Massless = true
                    elseif d == mainPart then
                        d.Massless = false
                        pcall(function() d.CustomPhysicalProperties = LIGHT_PHYS end)
                    end
                elseif d.Name == "StickyWeld" and d:IsA("JointInstance") or d:IsA("WeldConstraint") then
                    if d.Name == "StickyWeld" and d.Part1 and not d.Part1:IsDescendantOf(item) then
                        pcall(function() d:Destroy() end)
                    end
                end
            end
        end

        local function cleanCompetingMovers(item, keepBP, keepBG)
            if not item or not item.Parent then return end
            for _, d in ipairs(item:GetDescendants()) do
                if (d:IsA("BodyPosition") and d ~= keepBP)
                    or (d:IsA("BodyGyro") and d ~= keepBG)
                    or d:IsA("BodyVelocity")
                    or d:IsA("BodyAngularVelocity") then
                    pcall(function() d:Destroy() end)
                end
            end
        end

        local function isPartOwner(part)
            if not part or not part:IsA("BasePart") or not part.Parent then return false end
            local lp = LocalPlayer or game.Players.LocalPlayer
            local lpName = lp and lp.Name
            local po = part:FindFirstChild("PartOwner")
            if not po and part.Parent then
                po = part.Parent:FindFirstChild("PartOwner", true)
            end
            if po and po:IsA("StringValue") then
                return po.Value == lpName
            end
            local root = part.AssemblyRootPart or part
            return not root.Anchored and root.ReceiveAge == 0
        end

        local function claimPartNetworkOwner(part, timeout)
            if not part or not part:IsA("BasePart") or not part.Parent then return false end
            if isPartOwner(part) then return true end
            local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
            local srf = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
            if not srf then return false end
            local lp = LocalPlayer or game.Players.LocalPlayer
            local char = lp and lp.Character
            local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
            if not hrp then return false end

            local maxWait = timeout or 0.45
            local t0 = tick()
            repeat
                if not part.Parent or not hrp.Parent then break end
                local eyePos = (hrp.CFrame * CFrame.new(0, 1.593, 0)).Position
                local rayCF = CFrame.new(eyePos, part.Position)
                pcall(function() srf:FireServer(part, rayCF) end)
                if isPartOwner(part) then return true end
                RunService.Heartbeat:Wait()
            until not part.Parent or isPartOwner(part) or (tick() - t0 >= maxWait)
            return isPartOwner(part)
        end

        local function breakHoldableSync(item)
            if not item or not item.Parent or item:GetAttribute("PendingDestroy") then return false end
            if item:GetAttribute("RanaxHoldBroken") then
                return true
            end
            if item:GetAttribute("RanaxHoldBreaking") then
                local tWait = tick()
                while item.Parent and item:GetAttribute("RanaxHoldBreaking") and (tick() - tWait < 0.6) do
                    RunService.Heartbeat:Wait()
                end
                return true
            end

            item:SetAttribute("RanaxHoldBreaking", true)

            local sp = item:FindFirstChild("SoundPart") or item:FindFirstChild("Main") or item:WaitForChild("SoundPart", 0.3)
            local holdPart = item:FindFirstChild("HoldPart")
            if not holdPart and isHoldableToyName(item.Name) then
                holdPart = item:WaitForChild("HoldPart", 0.3)
            end

            local mainPart = getToyMainPart(item) or sp
            prepareToyParts(item, mainPart)

            if holdPart then
                pcall(function()
                    local rigid = holdPart:FindFirstChild("RigidConstraint")
                    if rigid then
                        rigid.Enabled = false
                    end

                    local dropRF = holdPart:FindFirstChild("DropItemRemoteFunction")
                    if dropRF then
                        task.spawn(function()
                            pcall(dropRF.InvokeServer, dropRF, item)
                        end)
                    end

                    local holdRF = holdPart:FindFirstChild("HoldItemRemoteFunction")
                    local lp = LocalPlayer or game.Players.LocalPlayer
                    local char = lp and lp.Character
                    local leftArm = char and (char:FindFirstChild("Left Arm") or char:FindFirstChild("LeftHand") or char:FindFirstChild("LeftLowerArm"))
                    local leftGrip = leftArm and leftArm:FindFirstChild("LeftGripAttachment")
                    if holdRF and dropRF and char and leftGrip and rigid and rigid.Attachment1 == leftGrip then
                        task.spawn(function()
                            pcall(dropRF.InvokeServer, dropRF, item)
                        end)
                        pcall(function() dropRF:Destroy() end)
                    end
                end)
            end

            mainPart = getToyMainPart(item) or mainPart
            prepareToyParts(item, mainPart)

            if mainPart then
                claimPartNetworkOwner(mainPart, 0.25)
            end

            item:SetAttribute("RanaxHoldBreaking", false)
            item:SetAttribute("RanaxHoldBroken", true)
            item:SetAttribute("RanaxHoldReady", true)

            return true
        end

        breakHoldable = function(item)
            if not item or not item.Parent or item:GetAttribute("PendingDestroy") then return end
            local mainPart = getToyMainPart(item)
            prepareToyParts(item, mainPart)
            if not item:GetAttribute("RanaxHoldBroken") and not item:GetAttribute("RanaxHoldBreaking") then
                task.spawn(breakHoldableSync, item)
            end
        end

        setupPartPhysics = function(item, posName, gyroName)
            if not item or not item.Parent or item:GetAttribute("PendingDestroy") then return nil end
            local mainPart = getToyMainPart(item)
            if not mainPart then return nil end

            breakHoldable(item)
            prepareToyParts(item, mainPart)

            local posKey = posName or "ToyBodyPos"
            local gyroKey = gyroName or "ToyBodyGyro"

            local bp = mainPart:FindFirstChild(posKey) or Instance.new("BodyPosition", mainPart)
            bp.Name = posKey
            bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
            bp.P = 200000
            bp.D = 500
            bp.Position = mainPart.Position

            local bg = mainPart:FindFirstChild(gyroKey) or Instance.new("BodyGyro", mainPart)
            bg.Name = gyroKey
            bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
            bg.P = 150000
            bg.D = 400
            bg.CFrame = mainPart.CFrame

            cleanCompetingMovers(item, bp, bg)

            local srf = ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner")
            if srf then
                local lp = LocalPlayer or game.Players.LocalPlayer
                local char = lp and lp.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local eyePos = hrp and (hrp.Position + Vector3.new(0, 1.5, 0)) or mainPart.Position
                pcall(function() srf:FireServer(mainPart, CFrame.new(eyePos, mainPart.Position)) end)
            end

            return { Model = item, Main = mainPart, Sound = mainPart, BP = bp, BG = bg }
        end

        -- 1:1 Toy Tornado + Resonance Orbit Loop Driver (Single unified BodyPosition + BodyGyro + SNO + Self-Healing)
        driveToyOrbitPart = function(item, targetCF, posName, gyroName, eyePos, srf, shouldRefreshNet, useModelPivot)
            if not item or not item.Parent or item:GetAttribute("PendingDestroy") then return nil end
            breakHoldable(item)

            local mainPart = getToyMainPart(item)
            if not mainPart or not mainPart.Parent then return nil end
            prepareToyParts(item, mainPart)

            local posKey = posName or "ToyBodyPos"
            local gyroKey = gyroName or "ToyBodyGyro"

            local bp = mainPart:FindFirstChild(posKey) or Instance.new("BodyPosition", mainPart)
            bp.Name = posKey
            bp.P = 200000
            bp.D = 500

            local bg = mainPart:FindFirstChild(gyroKey) or Instance.new("BodyGyro", mainPart)
            bg.Name = gyroKey
            bg.P = 150000
            bg.D = 400

            cleanCompetingMovers(item, bp, bg)

            local holdPart = item:FindFirstChild("HoldPart")
            local rigid = holdPart and holdPart:FindFirstChild("RigidConstraint")
            if rigid and rigid.Enabled then
                rigid.Enabled = false
            end

            local mainTargetCF = targetCF
            if useModelPivot and item:IsA("Model") then
                local okPiv, pivCF = pcall(function() return item:GetPivot() end)
                if okPiv and pivCF then
                    local pivotToMain = pivCF:ToObjectSpace(mainPart.CFrame)
                    mainTargetCF = targetCF * pivotToMain
                end
            end

            local nowT = tick()
            local lastTry = mainPart:GetAttribute("LastSNOTry") or 0
            if srf and (shouldRefreshNet or (nowT - lastTry >= 0.1)) then
                mainPart:SetAttribute("LastSNOTry", nowT)
                local rayCF = CFrame.new(eyePos, mainPart.Position)
                pcall(function() srf:FireServer(mainPart, rayCF) end)
            end

            local dist = (mainPart.Position - mainTargetCF.Position).Magnitude
            if not item:GetAttribute("RanaxInitialSnapped") or dist > 20 then
                item:SetAttribute("RanaxInitialSnapped", true)
                mainPart.CFrame = mainTargetCF
                mainPart.AssemblyLinearVelocity = Vector3.zero
                mainPart.AssemblyAngularVelocity = Vector3.zero
            end

            bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
            bp.Position = mainTargetCF.Position

            bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
            bg.CFrame = mainTargetCF

            return mainPart
        end

        spawnSingleToy = function(toyName, cf, roleAttr)
            local mt = ReplicatedStorage:FindFirstChild("MenuToys")
            local spawnRF = mt and (mt:FindFirstChild("SpawnToyRemoteFunction") or mt:WaitForChild("SpawnToyRemoteFunction", 3))
            if not spawnRF then return nil end
            local lp = LocalPlayer or game.Players.LocalPlayer
            local canSpawn = lp and lp:FindFirstChild("CanSpawnToy")
            if canSpawn then
                local startWait = tick()
                while not canSpawn.Value and (tick() - startWait < 3.5) do
                    task.wait(0.03)
                end
            end
            local char = lp and lp.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local spawnCF = cf
            if not spawnCF then
                spawnCF = hrp and (hrp.CFrame * CFrame.new(math.random(-2, 2), 8, math.random(-2, 2))) or CFrame.new(0, 20, 0)
            end

            local capturedToy = nil
            local conns = {}
            local function watchFolder(f)
                if not f then return end
                local c = f.ChildAdded:Connect(function(ch)
                    if ch.Name == toyName or ch.Name:find(toyName, 1, true) then
                        if roleAttr and not ch:GetAttribute("CharRole") then
                            ch:SetAttribute("CharRole", roleAttr)
                        end
                        capturedToy = ch
                    end
                end)
                table.insert(conns, c)
            end

            if lp then
                watchFolder(workspace:FindFirstChild(lp.Name .. "SpawnedInToys"))
            end
            for _, f in ipairs(getMyToyFolders()) do
                watchFolder(f)
            end
            local pi = workspace:FindFirstChild("PlotItems")
            if pi then
                watchFolder(pi)
                for _, pf in ipairs(pi:GetChildren()) do
                    watchFolder(pf)
                end
            end

            local res = nil
            task.spawn(function()
                pcall(function()
                    res = spawnRF:InvokeServer(toyName, spawnCF, Vector3.zero)
                end)
                if res and typeof(res) == "Instance" then
                    if roleAttr and not res:GetAttribute("CharRole") then
                        res:SetAttribute("CharRole", roleAttr)
                    end
                    capturedToy = capturedToy or res
                end
            end)

            local waitStart = tick()
            while not capturedToy and (tick() - waitStart < 1.2) do
                RunService.Heartbeat:Wait()
            end

            for _, c in ipairs(conns) do
                pcall(function() c:Disconnect() end)
            end

            local finalToy = capturedToy or res
            if finalToy and typeof(finalToy) == "Instance" and finalToy.Parent then
                lastSpawnedToyFolder = finalToy.Parent
                if roleAttr then
                    finalToy:SetAttribute("CharRole", roleAttr)
                end
                breakHoldable(finalToy)
            else
                task.wait(0.08)
            end
            return finalToy
        end
    end

