    local function refreshActiveWingPallets()
        local folders = getMyToyFolders()
        if #folders == 0 then return {} end

        local valid = {}
        for _, entry in ipairs(activeWingPallets) do
            if entry.Model and entry.Model.Parent and entry.Main and entry.Main.Parent then
                table.insert(valid, entry)
            end
        end

        for _, folder in ipairs(folders) do
            for _, item in ipairs(folder:GetChildren()) do
                if item.Name:find("Pallet") then
                    local exists = false
                    for _, v in ipairs(valid) do
                        if v.Model == item then exists = true; break end
                    end
                    if not exists then
                        local entry = setupPartPhysics(item, "WingBP", "WingBG")
                        if entry then
                            table.insert(valid, entry)
                        end
                    end
                end
            end
        end

        activeWingPallets = valid
        return activeWingPallets
    end

    local function refreshActiveWingCoconuts()
        local folders = getMyToyFolders()
        if #folders == 0 then return {} end

        local valid = {}
        for _, item in ipairs(activeWingCoconuts) do
            if item and item.Parent and not item:GetAttribute("PendingDestroy") then
                table.insert(valid, item)
            end
        end

        for _, folder in ipairs(folders) do
            for _, item in ipairs(folder:GetChildren()) do
                if item.Name == "FoodCoconut" and not item:GetAttribute("PendingDestroy") then
                    local role = item:GetAttribute("CharRole")
                    if role == "Wings" or not role then
                        item:SetAttribute("CharRole", "Wings")
                        local exists = false
                        for _, v in ipairs(valid) do
                            if v == item then exists = true; break end
                        end
                        if not exists then
                            breakHoldable(item)
                            table.insert(valid, item)
                        end
                    end
                end
            end
        end

        activeWingCoconuts = valid
        return activeWingCoconuts
    end

