    local function spawnWingTipSparklers()
        refreshActiveWingSparklers()
        local needed = 4 - #activeWingSparklers
        if needed <= 0 then return end

        local lp = LocalPlayer or game.Players.LocalPlayer
        for i = 1, needed do
            local char = lp and lp.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local baseCF = hrp and (hrp.CFrame * CFrame.new(0, 10, 0)) or CFrame.new(0, 20, 0)
            local spawnCF = baseCF * CFrame.new((i - 2.5) * 2.5, 0, 0)
            spawnSingleToy("FireworkSparkler", spawnCF, "WingTipSparkler")
            refreshActiveWingSparklers()
            task.wait(0.12)
        end
        refreshActiveWingSparklers()
    end

    local function clearAllWings()
        local destroyRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
        local myFolders = getMyToyFolders()

        for _, f in ipairs(myFolders) do
            for _, item in ipairs(f:GetChildren()) do
                if item.Name:find("Pallet") or
                   (item.Name == "FoodCoconut" and item:GetAttribute("CharRole") == "Wings") or
                   (item.Name:find("FireworkSparkler") and item:GetAttribute("CharRole") == "WingTipSparkler") then
                    pcall(function()
                        if destroyRF then destroyRF:FireServer(item) end
                    end)
                end
            end
        end

        activeWingPallets = {}
        activeWingCoconuts = {}
        activeWingSparklers = {}
    end

    local function spawnWingsBatch()
        if isSpawningWings then return end
        if WingsConfig.Type == "None" or not WingsConfig.Enabled then
            clearAllWings()
            return
        end
        isSpawningWings = true

        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then isSpawningWings = false; return end

        if WingsConfig.Type == "Pallet" then
            local needed = WingsConfig.PalletsPerSide * 2
            refreshActiveWingPallets()
            local currentCount = #activeWingPallets
            local toSpawn = needed - currentCount

            if toSpawn > 0 then
                for i = 1, toSpawn do
                    if not WingsConfig.Enabled or WingsConfig.Type ~= "Pallet" or not isSpawningWings then break end
                    local curChar = LocalPlayer.Character
                    local curHRP = (curChar and curChar:FindFirstChild("HumanoidRootPart")) or hrp
                    local offset = (i % 2 == 0 and 1 or -1) * 3
                    local spawnCF = curHRP.CFrame * CFrame.new(offset, 10, 0)
                    spawnSingleToy("PalletLightBrown", spawnCF)
                    refreshActiveWingPallets()
                    task.wait(0.08)
                end
                refreshActiveWingPallets()
            end
        elseif WingsConfig.Type == "Coconut" then
            local needed = WingsConfig.CoconutsPerSide * 2
            refreshActiveWingCoconuts()
            local currentCount = #activeWingCoconuts
            local toSpawn = needed - currentCount

            if toSpawn > 0 then
                for i = 1, toSpawn do
                    if not WingsConfig.Enabled or WingsConfig.Type ~= "Coconut" or not isSpawningWings then break end
                    local curChar = LocalPlayer.Character
                    local curHRP = (curChar and curChar:FindFirstChild("HumanoidRootPart")) or hrp
                    local offset = (i % 2 == 0 and 1 or -1) * 2
                    local spawnCF = curHRP.CFrame * CFrame.new(offset, 10, 0)
                    spawnSingleToy("FoodCoconut", spawnCF, "Wings")
                    refreshActiveWingCoconuts()
                    task.wait(0.08)
                end
                refreshActiveWingCoconuts()
            end
        end

        if WingsConfig.TipSparklers then
            task.spawn(spawnWingTipSparklers)
        end

        isSpawningWings = false
    end

