        local folders = getMyToyFolders()
        if #folders == 0 then return {} end

        local valid = {}
        for _, entry in ipairs(activeCharPencils) do
            if entry.Model and entry.Model.Parent and entry.Main and entry.Main.Parent and not entry.Model:GetAttribute("PendingDestroy") then
                table.insert(valid, entry)
            end
        end

        for _, folder in ipairs(folders) do
            for _, item in ipairs(folder:GetChildren()) do
                if item.Name == "ToolPencil" and not item:GetAttribute("PendingDestroy") then
                    local exists = false
                    for _, v in ipairs(valid) do
                        if v.Model == item then exists = true; break end
                    end
                    if not exists then
                        local entry = setupPartPhysics(item, "CharPencilBP", "CharPencilBG")
                        if entry then
                            table.insert(valid, entry)
                        end
                    end
                end
            end
        end

        activeCharPencils = valid
        return activeCharPencils
    end

    local function refreshActiveCharCoconuts()
        local folders = getMyToyFolders()
        if #folders == 0 then return {} end

        local valid = {}
        for _, item in ipairs(activeCharCoconuts) do
            if item and item.Parent and not item:GetAttribute("PendingDestroy") then
                table.insert(valid, item)
            end
        end

        for _, folder in ipairs(folders) do
            for _, item in ipairs(folder:GetChildren()) do
                if item.Name == "FoodCoconut" and not item:GetAttribute("PendingDestroy") then
                    local role = item:GetAttribute("CharRole")
                    if role == "Dih" or (not role and CharAttachConfig.DihType == "Coconut") then
                        item:SetAttribute("CharRole", "Dih")
                        local exists = false
                        for _, v in ipairs(valid) do
                            if v == item then exists = true; break end
                        end
                        if not exists then
                            breakHoldable(item)
                            table.insert(valid, item)
                        end
                    end
                end
            end
        end

        activeCharCoconuts = valid
        return activeCharCoconuts
    end

    local function refreshActiveCharAss()
        local folders = getMyToyFolders()
        if #folders == 0 then return {} end

        local valid = {}
        for _, item in ipairs(activeCharAss) do
            if item and item.Parent and not item:GetAttribute("PendingDestroy") then
                table.insert(valid, item)
            end
        end

        for _, folder in ipairs(folders) do
            for _, item in ipairs(folder:GetChildren()) do
                if item.Name == "FoodCoconut" and not item:GetAttribute("PendingDestroy") then
                    local role = item:GetAttribute("CharRole")
                    if role == "Ass" or (not role and CharAttachConfig.AssType == "Coconut Ass") then
                        item:SetAttribute("CharRole", "Ass")
                        local exists = false
                        for _, v in ipairs(valid) do
                            if v == item then exists = true; break end
                        end
                        if not exists then
                            breakHoldable(item)
                            table.insert(valid, item)
                        end
                    end
                end
            end
        end

        activeCharAss = valid
        return activeCharAss
    end

    local function spawnCharDihBatch()
        if isSpawningCharDih then return end
        isSpawningCharDih = true

        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then isSpawningCharDih = false; return end

        if CharAttachConfig.DihType == "Pencil" then
            local needed = math.clamp(CharAttachConfig.PencilCount, 1, 6)
            refreshActiveCharPencils()
            local toSpawn = needed - #activeCharPencils
            for i = 1, toSpawn do
                if CharAttachConfig.DihType ~= "Pencil" or not isSpawningCharDih then break end
                local curChar = LocalPlayer.Character
                local curHRP = (curChar and curChar:FindFirstChild("HumanoidRootPart")) or hrp
                spawnSingleToy("ToolPencil", curHRP.CFrame * CFrame.new((i - 2) * 1.5, 10, 0), "PencilDih")
                refreshActiveCharPencils()
                task.wait(0.08)
            end
            refreshActiveCharPencils()
        elseif CharAttachConfig.DihType == "Coconut" then
            local needed = math.clamp(CharAttachConfig.CoconutAmount, 3, 15)
            refreshActiveCharCoconuts()
            local toSpawn = needed - #activeCharCoconuts
            for i = 1, toSpawn do
                if CharAttachConfig.DihType ~= "Coconut" or not isSpawningCharDih then break end
                local curChar = LocalPlayer.Character
                local curHRP = (curChar and curChar:FindFirstChild("HumanoidRootPart")) or hrp
                spawnSingleToy("FoodCoconut", curHRP.CFrame * CFrame.new((i % 2 == 0 and 1.5 or -1.5), 10, 0), "Dih")
                refreshActiveCharCoconuts()
                task.wait(0.08)
            end
            refreshActiveCharCoconuts()
        end

        isSpawningCharDih = false
    end

    local function spawnCharAssBatch()
        if isSpawningCharAss then return end
        isSpawningCharAss = true

        pcall(function()
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then isSpawningCharAss = false; return end

            local needed = 4 -- 2 for Ass cheeks, 2 for Boobs
            refreshActiveCharAss()
            local toSpawn = needed - #activeCharAss
            for i = 1, toSpawn do
                local curChar = LocalPlayer.Character
                local curHRP = (curChar and curChar:FindFirstChild("HumanoidRootPart")) or hrp
                spawnSingleToy("FoodCoconut", curHRP.CFrame * CFrame.new((i - 2.5) * 1.5, 10, 0), "Ass")
                refreshActiveCharAss()
                task.wait(0.08)
            end
            refreshActiveCharAss()
        end)
        isSpawningCharAss = false
    end

    local function clearCharDih()
        local destroyRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
        local myFolders = getMyToyFolders()
        for _, f in ipairs(myFolders) do
            for _, item in ipairs(f:GetChildren()) do
                if item.Name == "ToolPencil" or (item.Name == "FoodCoconut" and item:GetAttribute("CharRole") == "Dih") then
                    pcall(function()
                        if destroyRF then destroyRF:FireServer(item) end
                    end)
                end
            end
        end
        activeCharPencils = {}
        activeCharCoconuts = {}
    end

    local function clearCharAss()
        local destroyRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
        local myFolders = getMyToyFolders()
        for _, f in ipairs(myFolders) do
            for _, item in ipairs(f:GetChildren()) do
                if item.Name == "FoodCoconut" and item:GetAttribute("CharRole") == "Ass" then
                    pcall(function()
                        if destroyRF then destroyRF:FireServer(item) end
                    end)
                end
            end
        end
        activeCharAss = {}
    end

    local function releaseBlowPlayer()
        local target = CharAttachConfig.BlowTargetPlayer
        if target and target.Character then
            local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
            local tHum = target.Character:FindFirstChildOfClass("Humanoid")
            if tHRP then
                local bp = tHRP:FindFirstChild("BlowHoldBP")
                local bg = tHRP:FindFirstChild("BlowHoldBG")
                if bp then pcall(function() bp:Destroy() end) end
                if bg then pcall(function() bg:Destroy() end) end
            end
            if tHum then
                tHum.Sit = false
                tHum.PlatformStand = false
            end
            for _, pt in ipairs(target.Character:GetDescendants()) do
                if pt:IsA("BasePart") then
                    pt.CanCollide = true
                    pt.CanQuery = true
                end
            end
        end
        CharAttachConfig.BlowTargetPlayer = nil
    end

    local function releaseTrappedPlayers()
        local destroyLine = ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("DestroyGrabLine")
        local function cleanPlayer(p)
            if not p or not p.Character then return end
            pcall(function()
                local char = p.Character
                local hrp = char:FindFirstChild("HumanoidRootPart")
                local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
                local hum = char:FindFirstChildOfClass("Humanoid")

                if hrp then
                    local bp = hrp:FindFirstChild("DihSuckBP")
                    local bg = hrp:FindFirstChild("DihSuckBG")
                    if bp then bp:Destroy() end
                    if bg then bg:Destroy() end
                end

                if torso then
                    local bp = torso:FindFirstChild("DihSuckBP")
                    local bg = torso:FindFirstChild("DihSuckBG")
                    if bp then bp:Destroy() end
                    if bg then bg:Destroy() end
                    for _, m in ipairs(torso:GetChildren()) do
                        if m:IsA("Motor6D") then m.Enabled = true end
                    end
                    if destroyLine then
                        destroyLine:FireServer(torso)
                    end
                elseif hrp and destroyLine then
                    destroyLine:FireServer(hrp)
                end
                for _, m in ipairs(char:GetDescendants()) do
                    if m:IsA("Motor6D") then m.Enabled = true end
                end

                if hum then
                    hum.Sit = false
                    hum.PlatformStand = false
                    hum.AutoRotate = true
                end

                for _, pt in ipairs(char:GetDescendants()) do
                    if pt:IsA("BasePart") then
                        pt.CanCollide = true
                        pt.CanQuery = true
                        pt.CanTouch = true
                    elseif pt:IsA("BallSocketConstraint") then
                        pt.LimitsEnabled = true
                        pt.TwistLimitsEnabled = true
                    end
                end
            end)
        end

        if CharAttachConfig.TrappedPlayer then
            pcall(function()
                local destroyLine = ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("DestroyGrabLine")
                if destroyLine and CharAttachConfig.TrappedPlayer.Character then
                    local hrp = CharAttachConfig.TrappedPlayer.Character:FindFirstChild("HumanoidRootPart")
                    local torso = CharAttachConfig.TrappedPlayer.Character:FindFirstChild("Torso")
                    if hrp then destroyLine:FireServer(hrp) end
                    if torso then destroyLine:FireServer(torso) end
                end
            end)
            cleanPlayer(CharAttachConfig.TrappedPlayer)
            CharAttachConfig.TrappedPlayer = nil
        end

        if CharAttachConfig.TrappedPlayers then
            for player, _ in pairs(CharAttachConfig.TrappedPlayers) do
                cleanPlayer(player)
            end
            table.clear(CharAttachConfig.TrappedPlayers)
        end

        CharAttachConfig.TrapLineCreated = false
    end

    local function resetAllAttachments()
        clearAllWings()
        clearCharDih()
        clearCharAss()
        releaseTrappedPlayers()
        CharAttachConfig.DihType = "None"
        CharAttachConfig.AssType = "None"
        WingsConfig.Type = "None"
        WingsConfig.Enabled = false
    end

