    -- SPAWN DIH (Glass Box & Drawer Structure)
    -- 3 Glass Boxes base (1 center, 2 sides)
    -- 2 Glass Boxes center shaft upwards
    -- 1 Drawer on top
    -- ========================================================
    local DihConfig = {
        Active = false,
        CircleOrbit = false, -- Orbit is OFF by default; will NEVER rotate when off!
        CircleRadius = 25,
        CircleSpeed = 1.0,
        StructureCount = 1,
        HeightOffset = 3,
        Orientation = "Upright (Facing Center)",
        TargetLocation = "Lobby (Spawn Point)",
        TargetPlayer = nil,
        FixedOrigin = nil,
    }

    local function getSpawnLocationCFrame()
        local spawnLoc = Workspace:FindFirstChildWhichIsA("SpawnLocation", true)
            or Workspace:FindFirstChild("SpawnLocation")
            or Workspace:FindFirstChild("Spawn")
        if spawnLoc and spawnLoc:IsA("BasePart") then
            return spawnLoc.CFrame
        end
        return CFrame.new(0, -5, 0)
    end

    local function getDihEffectiveRadius(total)
        total = total or math.clamp(DihConfig.StructureCount or 1, 1, 10)
        -- Width of 1 Dih is ~14 studs. A minimum 12-stud gap between each structure is guaranteed
        local minCollisionFreeRadius = 14 + (total * 8)
        return math.max(DihConfig.CircleRadius or 25, minCollisionFreeRadius)
    end

    local function getDihStructureOrigin(s, total)
        total = total or math.clamp(DihConfig.StructureCount or 1, 1, 10)
        s = s or 1

        local centerPos
        if DihConfig.TargetLocation == "Target Player" then
            local tPlr = DihConfig.TargetPlayer
            local tChar = tPlr and tPlr.Character
            local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
            if tHRP then
                centerPos = tHRP.Position
            else
                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                centerPos = hrp and hrp.Position or Vector3.zero
            end
        elseif DihConfig.TargetLocation == "Around Me (My Position)" or DihConfig.TargetLocation == "My Position" then
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            centerPos = hrp and hrp.Position or Vector3.zero
        else
            -- "Lobby (Spawn Point)"
            local spawnCF = getSpawnLocationCFrame()
            centerPos = spawnCF.Position + Vector3.new(0, 4, 0)
        end

        -- STRICT ORBIT CHECK: When CircleOrbit is FALSE, baseAngle is strictly 0 and DOES NOT ROTATE AT ALL!
        local baseAngle = 0
        if DihConfig.CircleOrbit == true then
            baseAngle = (tick() * (DihConfig.CircleSpeed or 1.0))
        end
        local angle = baseAngle + (s - 1) * (2 * math.pi / total)
        local rad = getDihEffectiveRadius(total)
        local x = math.cos(angle) * rad
        local z = math.sin(angle) * rad
        local structPos = centerPos + Vector3.new(x, DihConfig.HeightOffset, z)

        local lookTarget
        if DihConfig.Orientation == "Forward (Facing Outward)" then
            lookTarget = structPos + Vector3.new(x, 0, z)
        else
            lookTarget = Vector3.new(centerPos.X, structPos.Y, centerPos.Z)
        end

        return CFrame.lookAt(structPos, lookTarget)
    end

    local function getDihCircleOrigin()
        return getDihStructureOrigin(1, math.clamp(DihConfig.StructureCount or 1, 1, 10))
    end

    local function assembleDih(optionalOriginCF)
        local folders = getMyToyFolders()
        if #folders == 0 then return end

        local glassBoxes = {}
        local drawers = {}
        local extinguishers = {}

        for _, folder in ipairs(folders) do
            for _, child in ipairs(folder:GetChildren()) do
                local isHeart = child:GetAttribute("IsHeartGlass") or (child:FindFirstChild("SoundPart") and child.SoundPart:GetAttribute("IsHeartGlass")) or child:FindFirstChild("HeartBP")
                if child.Name == "GlassBoxGray" and not isHeart then
                    table.insert(glassBoxes, child)
                elseif child.Name == "DrawerLightBrown" or child.Name:find("Drawer") then
                    table.insert(drawers, child)
                elseif child.Name:find("Extinguisher") or (child.Name:find("Fire") and not child.Name:find("Firework") and not child.Name:find("Sparkler")) then
                    table.insert(extinguishers, child)
                end
            end
        end

        local sampleGlass = glassBoxes[1]
        local sampleDrawer = drawers[1]
        local boxSize = sampleGlass and sampleGlass:GetExtentsSize() or Vector3.new(4.5, 4.5, 4.5)
        local drawerSize = sampleDrawer and sampleDrawer:GetExtentsSize() or Vector3.new(4.0, 3.5, 3.0)

        local boxW = boxSize.X > 1 and boxSize.X or 4.5
        local boxH = boxSize.Y > 1 and boxSize.Y or 4.5
        local drawerH = drawerSize.Y > 1 and drawerSize.Y or 3.5

        local offsets = {}
        -- 1 orta base, 2 yan base, ortadan üste çıkan 2 glass block, tepede 1 drawer (Dikey / Upright)
        offsets[1] = CFrame.new(0, 0, 0) -- 1 orta base
        offsets[2] = CFrame.new(-boxW, 0, 0) -- ortanın solundaki yan base
        offsets[3] = CFrame.new(boxW, 0, 0) -- ortanın sağındaki yan base
        offsets[4] = CFrame.new(0, boxH, 0) -- ortadan üste çıkan 1. glass block
        offsets[5] = CFrame.new(0, boxH * 2, 0) -- ortadan üste çıkan 2. glass block
        local drawerOffset = CFrame.new(0, boxH * 2.5 + drawerH * 0.5 + 0.8, 0) -- en tepedeki drawer (camin tam ustunde, hafif yukarida)
        local srf = ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner")
        local char = LocalPlayer and LocalPlayer.Character
        local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
        local myPos = hrp and (hrp.CFrame * CFrame.new(0, 1.5, 0)).Position or Vector3.zero

        local totalStructures = math.clamp(DihConfig.StructureCount or 1, 1, 10)

        local lastDihNetRefresh = DihConfig._lastNetRefresh or 0
        local nowDih = tick()
        local shouldRefreshDihNet = (nowDih - lastDihNetRefresh > 0.4)
        if shouldRefreshDihNet then
            DihConfig._lastNetRefresh = nowDih
        end

        for s = 1, totalStructures do
            local structCF = (totalStructures == 1 and optionalOriginCF and not DihConfig.CircleOrbit) and optionalOriginCF or getDihStructureOrigin(s, totalStructures)
            if structCF then
                local startBoxIdx = (s - 1) * 5 + 1
                for k = 1, 5 do
                    local box = glassBoxes[startBoxIdx + (k - 1)]
                    if box then
                        local targetCF = structCF * offsets[k]
                        driveToyOrbitPart(box, targetCF, "DihBP", "DihBG", myPos, srf, shouldRefreshDihNet, true)
                    end
                end

                local drawer = drawers[s]
                if drawer then
                    local targetCF = structCF * drawerOffset
                    driveToyOrbitPart(drawer, targetCF, "DihBP", "DihBG", myPos, srf, shouldRefreshDihNet, true)
                end

                local ext = extinguishers[s]
                if ext then
                    local extOffset = drawerOffset * CFrame.new(0, drawerH * 0.5 + 1.2, 0)
                    -- Yangin tupu donecek sperm gibi (High speed spinning)
                    local spinAngle = (tick() * 15) % (math.pi * 2)
                    local spinCF = CFrame.Angles(0, spinAngle, 0) * CFrame.Angles(math.rad(35), 0, 0)
                    local targetCF = structCF * extOffset * spinCF
                    driveToyOrbitPart(ext, targetCF, "DihBP", "DihBG", myPos, srf, shouldRefreshDihNet, true)
                end
            end
        end
    end

    local isSpawningDih = false
    local function spawnDihBatch()
        if isSpawningDih then return end
        isSpawningDih = true

        DihConfig.Active = true
        local totalCount = math.clamp(DihConfig.StructureCount or 1, 1, 10)
        local neededGlass = totalCount * 5
        local neededDrawers = totalCount
        local neededExtinguishers = totalCount

        local folders = getMyToyFolders()
        local currentGlass = 0
        local currentDrawer = 0
        local currentExtinguisher = 0

        for _, folder in ipairs(folders) do
            for _, child in ipairs(folder:GetChildren()) do
                local isHeart = child:GetAttribute("IsHeartGlass") or (child:FindFirstChild("SoundPart") and child.SoundPart:GetAttribute("IsHeartGlass")) or child:FindFirstChild("HeartBP")
                if child.Name == "GlassBoxGray" and not isHeart then
                    currentGlass = currentGlass + 1
                elseif child.Name == "DrawerLightBrown" or child.Name:find("Drawer") then
                    currentDrawer = currentDrawer + 1
                elseif child.Name:find("Extinguisher") or (child.Name:find("Fire") and not child.Name:find("Firework") and not child.Name:find("Sparkler")) then
                    currentExtinguisher = currentExtinguisher + 1
                end
            end
        end

        local toSpawnGlass = neededGlass - currentGlass
        local toSpawnDrawers = neededDrawers - currentDrawer
        local toSpawnExtinguishers = neededExtinguishers - currentExtinguisher

        for i = 1, toSpawnGlass do
            if not DihConfig.Active or not isSpawningDih then break end
            local sIdx = math.min(math.ceil((currentGlass + i) / 5), totalCount)
            local spawnOrigin = getDihStructureOrigin(sIdx, totalCount)
            -- Spawn safely above the orbit position so it never clips into ground or other models
            spawnSingleToy("GlassBoxGray", spawnOrigin * CFrame.new(0, 5, 0))
            local lp = LocalPlayer or game.Players.LocalPlayer
            local canSpawn = lp and lp:FindFirstChild("CanSpawnToy")
            if canSpawn then
                local t0 = tick()
                while not canSpawn.Value and (tick() - t0 < 3.0) do
                    task.wait(0.05)
                end
            end
        end

        for i = 1, toSpawnDrawers do
            if not DihConfig.Active or not isSpawningDih then break end
            local sIdx = math.min(currentDrawer + i, totalCount)
            local spawnOrigin = getDihStructureOrigin(sIdx, totalCount)
            spawnSingleToy("DrawerLightBrown", spawnOrigin * CFrame.new(0, 5, 0))
            local lp = LocalPlayer or game.Players.LocalPlayer
            local canSpawn = lp and lp:FindFirstChild("CanSpawnToy")
            if canSpawn then
                local t0 = tick()
                while not canSpawn.Value and (tick() - t0 < 3.0) do
                    task.wait(0.05)
                end
            end
        end

        local function spawnExtinguisherToy(cf)
            local toyNames = { "ToolFireExtinguisher", "FireExtinguisher", "Fire Extinguisher", "Tool_FireExtinguisher" }
            for _, tName in ipairs(toyNames) do
                local r = spawnSingleToy(tName, cf)
                if r then return r end
            end
            return nil
        end

        for i = 1, toSpawnExtinguishers do
            if not DihConfig.Active or not isSpawningDih then break end
            local sIdx = math.min(currentExtinguisher + i, totalCount)
            local spawnOrigin = getDihStructureOrigin(sIdx, totalCount)
            spawnExtinguisherToy(spawnOrigin * CFrame.new(0, 5, 0))
            local lp = LocalPlayer or game.Players.LocalPlayer
            local canSpawn = lp and lp:FindFirstChild("CanSpawnToy")
            if canSpawn then
                local t0 = tick()
                while not canSpawn.Value and (tick() - t0 < 3.0) do
                    task.wait(0.05)
                end
            end
        end

        task.wait(0.3)
        assembleDih()
        isSpawningDih = false
    end

    local function clearAllDih()
        DihConfig.Active = false
        DihConfig.CircleOrbit = false
        isSpawningDih = false -- Immediately stops background spawn loop!

        local folders = getMyToyFolders()
        local mt = ReplicatedStorage:FindFirstChild("MenuToys")
        local dt = mt and mt:FindFirstChild("DestroyToy")
        for _, folder in ipairs(folders) do
            if folder and dt then
                for _, child in ipairs(folder:GetChildren()) do
                    local isHeart = child:GetAttribute("IsHeartGlass") or (child:FindFirstChild("SoundPart") and child.SoundPart:GetAttribute("IsHeartGlass")) or child:FindFirstChild("HeartBP")
                    local isDihPart = (child.Name == "GlassBoxGray" and not isHeart) or child.Name == "DrawerLightBrown" or child.Name:find("Drawer") or child.Name:find("Extinguisher") or (child.Name:find("Fire") and not child.Name:find("Firework") and not child.Name:find("Sparkler"))
                    if isDihPart then
                        pcall(function()
                            local bp = child:FindFirstChild("DihBP", true)
                            local bg = child:FindFirstChild("DihBG", true)
                            if bp then bp:Destroy() end
                            if bg then bg:Destroy() end
                            dt:FireServer(child)
                        end)
                    end
                end
            end
        end
        notify("Ranax FTAP", "All Dih Structures Cleared & Stopped!", 2)
    end

