    local function getFS()
        local g = (type(getgenv) == "function" and getgenv()) or _G or {}
        local env = (type(getfenv) == "function" and getfenv()) or {}
        return {
            isfolder = isfolder or env.isfolder or g.isfolder,
            makefolder = makefolder or env.makefolder or g.makefolder,
            listfiles = listfiles or listdir or env.listfiles or env.listdir or g.listfiles or g.listdir,
            readfile = readfile or env.readfile or g.readfile,
            writefile = writefile or env.writefile or g.writefile,
            isfile = isfile or env.isfile or g.isfile,
            delfile = delfile or deletefile or env.delfile or env.deletefile or g.delfile or g.deletefile,
        }
    end

    local BUILDS_FOLDER = "vertex_builds"
    local inMemoryBuilds = {} -- [cleanName] = payload table (guarantees builds are always in list regardless of executor file permissions)

    local PlotStealConfig = {
        SelectedPlotOwner = "",
        SaveName = "plot1.build",
        SelectedSavedBuild = "None",
        BuildPacing = 0.08,
        IsBuilding = false,
        SavedFiles = {},
    }

    local function ensureBuildsFolder()
        local fs = getFS()
        if fs.isfolder and fs.makefolder then
            local ok, exists = pcall(fs.isfolder, BUILDS_FOLDER)
            if not ok or not exists then
                pcall(fs.makefolder, BUILDS_FOLDER)
            end
        end
    end

    local function getPlotOwnerName(plotInstance)
        if not plotInstance then return nil end
        local sign = plotInstance:FindFirstChild("PlotSign")
        if sign then
            for _, name in ipairs({"ThisPlotsOwners", "ThisPlotsOwner", "ThisPlotOwners"}) do
                local c = sign:FindFirstChild(name)
                if c then
                    -- 1. Check if folder with child values
                    local children = c:GetChildren()
                    if #children > 0 then
                        for _, ch in ipairs(children) do
                            if ch:IsA("StringValue") and ch.Value ~= "" and ch.Value ~= "None" then
                                return ch.Value
                            elseif ch:IsA("ObjectValue") and ch.Value and ch.Value.Name then
                                return ch.Value.Name
                            elseif ch.Value and tostring(ch.Value) ~= "" and tostring(ch.Value) ~= "None" then
                                return tostring(ch.Value)
                            end
                        end
                    end
                    -- 2. Direct StringValue / ObjectValue
                    if c:IsA("StringValue") and c.Value and c.Value ~= "" and c.Value ~= "None" then
                        return c.Value
                    elseif c:IsA("ObjectValue") and c.Value and c.Value.Name then
                        return c.Value.Name
                    elseif c:FindFirstChildOfClass("StringValue") then
                        local sv = c:FindFirstChildOfClass("StringValue")
                        if sv.Value and sv.Value ~= "" and sv.Value ~= "None" then
                            return sv.Value
                        end
                    elseif c:FindFirstChildOfClass("ObjectValue") then
                        local ov = c:FindFirstChildOfClass("ObjectValue")
                        if ov.Value and ov.Value.Name then
                            return ov.Value.Name
                        end
                    end
                end
            end
            -- Check SurfaceGui or TextLabels on PlotSign
            local txt = sign:FindFirstChildWhichIsA("TextLabel", true)
            if txt and txt.Text and txt.Text ~= "" then
                local parsed = txt.Text:match("([%w_]+)'s%s*Plot") or txt.Text:match("Owned%s*by:?%s*([%w_]+)") or txt.Text:match("^([%w_]+)$")
                if parsed and parsed ~= "Plot" and parsed ~= "None" then
                    return parsed
                end
            end
        end

        -- Check PlayersInPlots
        local plotItems = workspace:FindFirstChild("PlotItems")
        local pip = plotItems and plotItems:FindFirstChild("PlayersInPlots")
        if pip then
            for _, pVal in ipairs(pip:GetChildren()) do
                if pVal.Name == plotInstance.Name or (pVal.Value and tostring(pVal.Value) == plotInstance.Name) then
                    return pVal.Name
                end
            end
        end
        return nil
    end

    local function getPlotBaseCF(plotInstance)
        if not plotInstance then return nil end
        -- 1. Try PlotSign first because every plot in FTAP has a PlotSign at the exact entrance!
        local sign = plotInstance:FindFirstChild("PlotSign")
        if sign then
            local p = (sign:IsA("BasePart") and sign) or sign:FindFirstChild("Main") or sign:FindFirstChildWhichIsA("BasePart", true)
            if p then return p.CFrame end
        end
        -- 2. Try PlotArea / Barrier / Floor / Base
        local area = plotInstance:FindFirstChild("PlotArea") or plotInstance:FindFirstChild("Area") or plotInstance:FindFirstChild("Barrier") or plotInstance:FindFirstChild("Floor")
        if area then
            local p = (area:IsA("BasePart") and area) or area:FindFirstChildWhichIsA("BasePart", true)
            if p then return p.CFrame end
        end
        -- 3. Model GetPivot
        if plotInstance.GetPivot then
            local ok, cf = pcall(function() return plotInstance:GetPivot() end)
            if ok and cf then return cf end
        end
        local primary = plotInstance.PrimaryPart or plotInstance:FindFirstChildWhichIsA("BasePart", true)
        return primary and primary.CFrame or CFrame.new(0, 0, 0)
    end

    local function getPlotList()
        local list = {}
        local plots = workspace:FindFirstChild("Plots")
        if plots then
            local children = plots:GetChildren()
            table.sort(children, function(a, b)
                local numA = tonumber(a.Name:match("%d+")) or 999
                local numB = tonumber(b.Name:match("%d+")) or 999
                return numA < numB
            end)
            for _, p in ipairs(children) do
                local i = tonumber(p.Name:match("%d+")) or p.Name
                local owner = getPlotOwnerName(p)
                if owner then
                    table.insert(list, string.format("Plot %s: %s", tostring(i), owner))
                else
                    table.insert(list, string.format("Plot %s: [Online]", tostring(i)))
                end
            end
        end
        if #list == 0 then
            table.insert(list, "No Plots Found")
        end
        return list
    end

    local function getPlotUnderCharacter()
        local plots = workspace:FindFirstChild("Plots")
        if not plots then return nil, nil end

        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil, nil end

        local closestPlot, closestIdx, closestDist = nil, nil, 300
        for _, p in ipairs(plots:GetChildren()) do
            local idx = tonumber(p.Name:match("%d+")) or 1
            local baseCF = getPlotBaseCF(p)
            if baseCF then
                local center = baseCF.Position
                local dist = (Vector3.new(center.X, 0, center.Z) - Vector3.new(hrp.Position.X, 0, hrp.Position.Z)).Magnitude
                if dist < closestDist then
                    closestDist = dist
                    closestPlot = p
                    closestIdx = idx
                end
            end
        end
        return closestPlot, closestIdx
    end

    local function getLocalOwnedPlot()
        local plots = workspace:FindFirstChild("Plots")
        if not plots then return nil, nil end

        -- 1. Check by player owner name
        for _, p in ipairs(plots:GetChildren()) do
            local owner = getPlotOwnerName(p)
            if owner and (owner == LocalPlayer.Name or owner:lower() == LocalPlayer.Name:lower()) then
                local idx = tonumber(p.Name:match("%d+")) or 1
                return p, idx
            end
        end

        -- 2. Check InOwnedPlot / InPlot value on player
        local inOwned = LocalPlayer:FindFirstChild("InOwnedPlot")
        local inPlot = LocalPlayer:FindFirstChild("InPlot")
        if (inOwned and inOwned.Value) or (inPlot and inPlot.Value) then
            local p, idx = getPlotUnderCharacter()
            if p then return p, idx end
        end

        -- 3. Fallback: closest plot to character
        return getPlotUnderCharacter()
    end

    local function getPlotItemsFolder(plotIndex)
        local plotItems = workspace:FindFirstChild("PlotItems")
        if plotItems then
            return plotItems:FindFirstChild("Plot" .. tostring(plotIndex)) or plotItems:FindFirstChild(tostring(plotIndex))
        end
        return nil
    end

    local function refreshSavedFilesList()
        ensureBuildsFolder()
        local list = {}
        local seen = {}

        -- 1. Read in-memory cache first
        for name, _ in pairs(inMemoryBuilds) do
            if not seen[name] then
                seen[name] = true
                table.insert(list, name)
            end
        end

        -- 2. Read persistent index file
        local fs = getFS()
        if fs.readfile then
            pcall(function()
                local idxContent = fs.readfile(BUILDS_FOLDER .. "/_index.json")
                if idxContent and idxContent ~= "" then
                    local names = game:GetService("HttpService"):JSONDecode(idxContent)
                    if type(names) == "table" then
                        for _, n in ipairs(names) do
                            local clean = tostring(n):gsub("%.build$", ""):gsub("%.json$", "")
                            if clean ~= "" and not seen[clean] then
                                seen[clean] = true
                                table.insert(list, clean)
                            end
                        end
                    end
                end
            end)
        end

        -- 3. Read filesystem files via listfiles
        if fs.listfiles then
            local files = {}
            pcall(function() files = fs.listfiles(BUILDS_FOLDER) or {} end)
            if #files == 0 then
                pcall(function() files = fs.listfiles(BUILDS_FOLDER .. "/") or {} end)
            end
            for _, f in ipairs(files) do
                local filename = tostring(f):match("([^\\/]+)%.build$") or tostring(f):match("([^\\/]+)%.json$")
                if filename and filename ~= "_index" and not seen[filename] then
                    seen[filename] = true
                    table.insert(list, filename)
                end
            end
        end

        table.sort(list)
        if #list == 0 then
            table.insert(list, "None")
        end
        PlotStealConfig.SavedFiles = list
        return list
    end

