    local function executeStealOperation(forceUnderCharacter)
        local plots = workspace:FindFirstChild("Plots")
        local targetPlot = nil
        local plotNum = nil
        local ownerName = nil

        if not forceUnderCharacter then
            local sel = PlotStealConfig.SelectedPlotOwner or ""
            plotNum = tonumber(sel:match("Plot%s*(%d+)"))
            if plotNum and plots then
                targetPlot = plots:FindFirstChild("Plot" .. plotNum)
                if targetPlot then
                    ownerName = getPlotOwnerName(targetPlot)
                end
            end
        end

        -- If not selected from dropdown or forced under character, detect plot currently under player
        if not targetPlot then
            local pUnder, idxUnder = getPlotUnderCharacter()
            if pUnder then
                targetPlot = pUnder
                plotNum = idxUnder
                ownerName = getPlotOwnerName(targetPlot)
            end
        end

        if not targetPlot or not plotNum then
            notify("Ranax FTAP", "Please stand on a plot or select one from dropdown!", 3)
            return
        end

        local originCF = getPlotBaseCF(targetPlot)
        if not originCF then
            notify("Ranax FTAP", "Could not resolve plot origin CFrame!", 3)
            return
        end

        local plotCenter = originCF.Position
        local stolenToys = {}
        local seenParts = {}

        local function isIgnoredSystem(instance)
            if not instance then return true end
            if Players:GetPlayerFromCharacter(instance) or (instance.Parent and Players:GetPlayerFromCharacter(instance.Parent)) then
                return true
            end
            local nm = instance.Name:lower()
            if nm == "baseplate" or nm == "terrain" or nm == "base" or nm == "ground" or nm == "spawnlocation"
                or nm == "plotsign" or nm == "plotarea" or nm == "barrier" or nm == "plotbarrier"
                or nm == "humanoidrootpart" or nm == "head" or nm == "torso" or nm == "upper_torso" then
                return true
            end
            return false
        end

        local function checkAndAddToy(item, customName)
            if not item or not item.Parent or isIgnoredSystem(item) then return end

            local mainPart = (item:IsA("BasePart") and item)
                or item:FindFirstChild("Main")
                or item:FindFirstChild("SoundPart")
                or item.PrimaryPart
                or item:FindFirstChildWhichIsA("BasePart", true)

            if not mainPart or seenParts[mainPart] or isIgnoredSystem(mainPart) then return end

            -- Verify part falls within plot perimeter (or belongs to PlotItems folder)
            local isDirectPlotItem = targetItems and mainPart:IsDescendantOf(targetItems)
            local diff = mainPart.Position - plotCenter
            local inBounds = isDirectPlotItem or (math.abs(diff.X) <= 250 and math.abs(diff.Z) <= 250) or (diff.Magnitude <= 260)
            if inBounds then
                seenParts[mainPart] = true
                local toyName = customName or item.Name
                -- Clean clone tags: e.g. "WoodBlock (1)" -> "WoodBlock", "Part_2" -> "Part"
                toyName = toyName:gsub("%s*%(%d+%)", ""):gsub("_%d+$", ""):gsub("%.%d+$", "")

                local relativeCF = originCF:ToObjectSpace(mainPart.CFrame)
                local x, y, z = relativeCF.Position.X, relativeCF.Position.Y, relativeCF.Position.Z
                local r00, r01, r02, r10, r11, r12, r20, r21, r22 = relativeCF:GetComponents()
                table.insert(stolenToys, {
                    toy = toyName,
                    cf = {x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22}
                })
            end
        end

        -- 1. Harvest from Workspace.PlotItems.PlotX
        local targetItems = getPlotItemsFolder(plotNum)
        if targetItems then
            for _, ch in ipairs(targetItems:GetChildren()) do
                checkAndAddToy(ch)
            end
        end

        -- 2. Harvest from targetPlot itself (any items placed inside plot model)
        for _, ch in ipairs(targetPlot:GetChildren()) do
            if ch.Name ~= "PlotSign" and ch.Name ~= "Barrier" and ch.Name ~= "PlotArea" then
                checkAndAddToy(ch)
            end
        end

        -- 3. Harvest from ALL SpawnedInToys folders across workspace
        for _, child in ipairs(workspace:GetChildren()) do
            if child.Name:find("SpawnedInToys$") then
                for _, toy in ipairs(child:GetChildren()) do
                    checkAndAddToy(toy)
                end
            end
        end

        -- 4. Harvest from game toy folders and loose models in Workspace within this plot
        local gameFolderNames = { "Toys", "MapToys", "GameToys", "Items", "Props", "Debris" }
        for _, fName in ipairs(gameFolderNames) do
            local gf = workspace:FindFirstChild(fName)
            if gf then
                for _, toy in ipairs(gf:GetChildren()) do
                    checkAndAddToy(toy)
                end
            end
        end

        for _, child in ipairs(workspace:GetChildren()) do
            if child:IsA("Model") and not child.Name:find("SpawnedInToys$") and not child.Name:find("Plots") then
                if child.Name ~= "Map" and child.Name ~= "Terrain" then
                    checkAndAddToy(child)
                end
            end
        end

        if #stolenToys == 0 then
            notify("Ranax FTAP", "No blocks or toys found in Plot " .. tostring(plotNum), 3)
            return
        end

        local fileName = PlotStealConfig.SaveName or "plot1.build"
        local cleanName = fileName:gsub("%.build$", ""):gsub("%.json$", "")
        if cleanName == "" then cleanName = "plot1" end
        local fileWithExt = cleanName .. ".build"

        local payload = {
            version = 1,
            sourcePlot = plotNum,
            sourceOwner = ownerName or ("Plot " .. tostring(plotNum)),
            totalItems = #stolenToys,
            items = stolenToys
        }

        -- Store in-memory immediately (guarantees presence in dropdown list even with restricted FS)
        inMemoryBuilds[cleanName] = payload

        -- Save to disk
        local jsonString = game:GetService("HttpService"):JSONEncode(payload)
        local fs = getFS()
        ensureBuildsFolder()

        local savedToDisk = false
        if fs.writefile then
            pcall(function()
                fs.writefile(BUILDS_FOLDER .. "/" .. fileWithExt, jsonString)
                savedToDisk = true
            end)
            pcall(function()
                local currentList = refreshSavedFilesList()
                fs.writefile(BUILDS_FOLDER .. "/_index.json", game:GetService("HttpService"):JSONEncode(currentList))
            end)
        end

        notify("Ranax FTAP", string.format("Stole %d items from Plot %s -> Saved as %s!", #stolenToys, tostring(plotNum), cleanName), 4)

        -- Update dropdown list and immediately select newly saved build
        local updatedFiles = refreshSavedFilesList()
        PlotStealConfig.SelectedSavedBuild = cleanName
        if SavedBuildsDropdownRef then
            if SavedBuildsDropdownRef.SetOptions then
                SavedBuildsDropdownRef:SetOptions(updatedFiles)
            elseif SavedBuildsDropdownRef.Refresh then
                SavedBuildsDropdownRef:Refresh(updatedFiles)
            elseif SavedBuildsDropdownRef.SetItems then
                SavedBuildsDropdownRef:SetItems(updatedFiles)
            end
            if SavedBuildsDropdownRef.Set then
                SavedBuildsDropdownRef:Set(cleanName)
            end
        end
    end

