    local function executeBuildOperation(chosenFile)
        if PlotStealConfig.IsBuilding then
            notify("Ranax FTAP", "Build is already in progress!", 3)
            return
        end

        local myPlot, myPlotIdx = getLocalOwnedPlot()
        if not myPlot then
            notify("Ranax FTAP", "You must own and be in a Plot to build!", 3)
            return
        end

        local targetOriginCF = getPlotBaseCF(myPlot)
        if not targetOriginCF then
            notify("Ranax FTAP", "Could not locate your plot origin!", 3)
            return
        end

        local cleanName = chosenFile or PlotStealConfig.SelectedSavedBuild
        if not cleanName or cleanName == "None" or cleanName == "Select Build" then
            cleanName = (PlotStealConfig.SaveName or "plot1"):gsub("%.build$", ""):gsub("%.json$", "")
        else
            cleanName = cleanName:gsub("%.build$", ""):gsub("%.json$", "")
        end

        -- 1. Check in-memory build cache first
        local data = inMemoryBuilds[cleanName]

        -- 2. If not in memory, read from disk
        if not data then
            local fs = getFS()
            local fileWithExt = cleanName .. ".build"
            local readPath = BUILDS_FOLDER .. "/" .. fileWithExt
            local content = nil

            if fs.readfile then
                pcall(function() content = fs.readfile(readPath) end)
                if not content or content == "" then
                    pcall(function() content = fs.readfile(fileWithExt) end)
                end
                if not content or content == "" then
                    pcall(function() content = fs.readfile(BUILDS_FOLDER .. "/" .. cleanName .. ".json") end)
                end
            end

            if content and content ~= "" then
                pcall(function() data = game:GetService("HttpService"):JSONDecode(content) end)
            end
        end

        if not data or not data.items or #data.items == 0 then
            notify("Ranax FTAP", "Build file not found or empty: " .. tostring(cleanName), 3)
            return
        end

        local spawnRemote = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("SpawnToyRemoteFunction")
        if not spawnRemote then
            notify("Ranax FTAP", "SpawnToyRemoteFunction not found!", 3)
            return
        end

        PlotStealConfig.IsBuilding = true
        notify("Ranax FTAP", string.format("Building %d items into Plot %s...", #data.items, tostring(myPlotIdx or 1)), 3)

        task.spawn(function()
            local total = #data.items
            for idx, itemData in ipairs(data.items) do
                if not PlotStealConfig.IsBuilding then break end

                local toyName = itemData.toy
                local relativeCF = CFrame.new(table.unpack(itemData.cf))
                local worldCF = targetOriginCF:ToWorldSpace(relativeCF)

                -- Wait for toy spawn readiness
                local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
                if canSpawn and not canSpawn.Value then
                    local timeout = tick() + 1
                    repeat task.wait() until canSpawn.Value or tick() > timeout
                end

                pcall(function()
                    spawnRemote:InvokeServer(toyName, worldCF, Vector3.zero)
                end)

                task.wait(PlotStealConfig.BuildPacing or 0.08)
            end

            PlotStealConfig.IsBuilding = false
            notify("Ranax FTAP", string.format("Build Finished! Placed %d items.", total), 3)
        end)
    end

