    LocalPlayer.Chatted:Connect(function(msg)
        local clean = msg:lower():match("^%s*(.-)%s*$")
        if clean == "/build" or clean:sub(1, 7) == "/build " then
            local arg = clean:sub(8):match("^%s*(.-)%s*$")
            if arg and arg ~= "" then
                executeBuildOperation(arg)
            else
                executeBuildOperation(PlotStealConfig.SelectedSavedBuild)
            end
        end
    end)


    -- ========================================================
    -- Continuous Tracking & Auto-Rebuild Loop
    -- ========================================================
    local lastWingsRecheck = 0
    local lastDickRecheck = 0
    local lastOwnerRefresh = 0

    RunService.Heartbeat:Connect(function()
        local anyFeatureActive = (WingsConfig and WingsConfig.Enabled and WingsConfig.Type ~= "None")
            or (CharAttachConfig and (
                CharAttachConfig.DihType ~= "None"
                or CharAttachConfig.AssType ~= "None"
                or CharAttachConfig.TrapOnTouch
                or CharAttachConfig.BlowActive
                or CharAttachConfig.Sperm
            ))
            or (SexConfig and SexConfig.Enabled)
            or (DihConfig and (DihConfig.Active or DihConfig.CircleOrbit))

        if not anyFeatureActive then
            return
        end

        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local eyePos = hrp.Position + Vector3.new(0, 1.5, 0)

        local t = tick()
        local srf = ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner")
        local shouldRefreshNet = false
        if t - lastOwnerRefresh > 0.35 then
            lastOwnerRefresh = t
            shouldRefreshNet = true
        end
        -- Velocity prediction (0.09s lead) so BodyPosition/BodyGyro orbit tracks tightly on server
        local predOffset = hrp.AssemblyLinearVelocity * 0.09
        local predHRPCF = hrp.CFrame + predOffset

        -- 1. MAKE WINGS TRACKING & AUTO-RESPAWN (Coconut & Pallet)
        if WingsConfig.Enabled and WingsConfig.Type ~= "None" then
            local now3 = os.clock()
            local dt = math.min(now3 - (WingsConfig.WingClock or now3), 0.1)
            WingsConfig.WingClock = now3
            WingsConfig.WingPhase = (WingsConfig.WingPhase or 0) + dt * (WingsConfig.FlapSpeed or 4.0)

            -- Auto-respawn check
            if t - lastWingsRecheck > 0.6 then
                lastWingsRecheck = t
                if WingsConfig.Type == "Pallet" then
                    refreshActiveWingPallets()
                    local needed = WingsConfig.PalletsPerSide * 2
                    if #activeWingPallets < needed and not isSpawningWings then
                        task.spawn(spawnWingsBatch)
                    end
                elseif WingsConfig.Type == "Coconut" then
                    refreshActiveWingCoconuts()
                    local needed = WingsConfig.CoconutsPerSide * 2
                    if #activeWingCoconuts < needed and not isSpawningWings then
                        task.spawn(spawnWingsBatch)
                    end
                end
            end

            local leftWingTipCF = nil
            local rightWingTipCF = nil

            -- A. COCONUT WINGS (Resonance + Toy Tornado Orbit Physics Loop)
            if WingsConfig.Type == "Coconut" then
                local coconuts = activeWingCoconuts
                local wingPhase = WingsConfig.WingPhase
                local n39 = -0.15 + math.sin(wingPhase) * (math.rad(WingsConfig.FlapAngle) * 0.8)

                local torsoPart = char:FindFirstChild("Torso") or hrp
                local cFrame2 = torsoPart.CFrame + predOffset
                local wingBaseCF = cFrame2 * CFrame.new(0, WingsConfig.HeightOffset * 0.3, WingsConfig.BackOffset)
                local leftWingBase = wingBaseCF * CFrame.Angles(0, 0, -n39)
                local rightWingBase = wingBaseCF * CFrame.Angles(0, 0, n39)

                -- Calculate wave ripple for 6 segments
                local wingRipple = WingsConfig.WingRipple
                for seg = 1, 6 do
                    wingRipple[seg] = math.sin(wingPhase - (seg - 1) * 0.35) * 0.08
                end

                local maxLeftSeg = 0
                local maxRightSeg = 0
                local neededWingCoconuts = (WingsConfig.CoconutsPerSide or 6) * 2
                local destroyRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
                for idx = #coconuts, 1, -1 do
                    local item = coconuts[idx]
                    if not item or not item.Parent or item:GetAttribute("PendingDestroy") then
                        table.remove(coconuts, idx)
                    elseif idx > neededWingCoconuts then
                        item:SetAttribute("PendingDestroy", true)
                        if destroyRF then pcall(function() destroyRF:FireServer(item) end) end
                        table.remove(coconuts, idx)
                    end
                end
                for idx = 1, #coconuts do
                    local item = coconuts[idx]
                    local isLeft = (idx <= 6)
                    local segIdx = isLeft and idx or (idx - 6)
                    if segIdx <= 6 then
                        local sideSign = isLeft and -1 or 1
                        local baseCF = isLeft and leftWingBase or rightWingBase
                        local sideSpacing = isLeft and (WingsConfig.LeftSpacing or WingsConfig.Spacing) or (WingsConfig.RightSpacing or WingsConfig.Spacing)
                        local n53 = (segIdx - 1) * sideSpacing
                        local ripple = wingRipple[segIdx] or 0

                        local xOffset = sideSign * (0.55 + n53)
                        local yOffset = 0.05 - (n53 / 1.1) * 0.16 + ripple
                        local zOffset = (n53 / 1.1) * 0.06 + ripple * 0.35

                        local segPos = CFrame.new(xOffset, yOffset, zOffset)
                        local segRot = CFrame.Angles(ripple * 0.6, sideSign * -0.18, sideSign * (ripple * 0.8 - math.rad(WingsConfig.WingAngle * 0.15)))

                        local targetCF = baseCF * segPos * segRot
                        driveToyOrbitPart(item, targetCF, "WingBP", "WingBG", eyePos, srf, shouldRefreshNet)

                        if isLeft then
                            if segIdx >= maxLeftSeg then
                                maxLeftSeg = segIdx
                                leftWingTipCF = targetCF
                            end
                        else
                            if segIdx >= maxRightSeg then
                                maxRightSeg = segIdx
                                rightWingTipCF = targetCF
                            end
                        end
                    end
                end

            -- B. PALLET WINGS (Toy Tornado Orbit Physics Loop)
            elseif WingsConfig.Type == "Pallet" then
                local pallets = activeWingPallets
                local countPerSide = WingsConfig.PalletsPerSide
                local neededPallets = countPerSide * 2
                local destroyRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
                for idx = #pallets, 1, -1 do
                    local entry = pallets[idx]
                    if not entry or not entry.Model or not entry.Model.Parent or not entry.Main or not entry.Main.Parent or entry.Model:GetAttribute("PendingDestroy") then
                        table.remove(pallets, idx)
                    elseif idx > neededPallets then
                        entry.Model:SetAttribute("PendingDestroy", true)
                        if destroyRF then pcall(function() destroyRF:FireServer(entry.Model) end) end
                        table.remove(pallets, idx)
                    end
                end

                local flapRad = math.rad(WingsConfig.FlapAngle)
                local flapSpd = WingsConfig.FlapSpeed

                local leftIdx = 1
                local rightIdx = 1
                local maxLeftPallet = 0
                local maxRightPallet = 0

                for idx = 1, #pallets do
                    local entry = pallets[idx]
                    local isLeft = (idx % 2 ~= 0)
                    local sideIdx = isLeft and leftIdx or rightIdx

                    if sideIdx <= countPerSide then
                        local wave = math.sin(t * flapSpd - (sideIdx * 0.18))
                        local currentFlapAngle = wave * flapRad
                        local sideSign = isLeft and -1 or 1

                        local sideSpread = (isLeft and (WingsConfig.LeftSpacing or WingsConfig.Spacing) or (WingsConfig.RightSpacing or WingsConfig.Spacing)) * 2.7
                        local xOffset = sideSign * (8.5 + (sideIdx - 1) * sideSpread)
                        local yOffset = WingsConfig.HeightOffset + ((sideIdx - 1) * WingsConfig.ElevationStep) + (wave * 0.35)
                        local zOffset = WingsConfig.BackOffset - ((sideIdx - 1) * 0.15)

                        local targetPos = predHRPCF.Position
                            + (predHRPCF.RightVector * xOffset)
                            + (predHRPCF.UpVector * yOffset)
                            + (predHRPCF.LookVector * zOffset)

                        local baseUpright = math.rad(WingsConfig.WingAngle or 55)
                        local yaw = sideSign * math.rad(10)
                        local pitch = math.rad(6)
                        local roll = sideSign * (baseUpright + (sideIdx - 1) * math.rad(10) + currentFlapAngle)

                        local targetRot = predHRPCF
                            * CFrame.Angles(0, yaw, 0)
                            * CFrame.Angles(pitch, 0, roll)
                        local targetCF = targetRot + (targetPos - targetRot.Position)

                        driveToyOrbitPart(entry.Model, targetCF, "WingBP", "WingBG", eyePos, srf, shouldRefreshNet)

                        if isLeft then
                            if sideIdx >= maxLeftPallet then
                                maxLeftPallet = sideIdx
                                leftWingTipCF = targetCF
                            end
                            leftIdx = leftIdx + 1
                        else
                            if sideIdx >= maxRightPallet then
                                maxRightPallet = sideIdx
                                rightWingTipCF = targetCF
                            end
                            rightIdx = rightIdx + 1
                        end
                    end
                end
            end

            -- C. 4 WING TIP SPARKLERS (Toy Tornado Orbit Physics Loop)
            if WingsConfig.TipSparklers then
                if not leftWingTipCF and hrp then
                    local sideSign = -1
                    local maxSpread = (WingsConfig.PalletsPerSide or 4)
                    local tipSpread = ((sideSign < 0) and (WingsConfig.LeftSpacing or 1.1) or (WingsConfig.RightSpacing or 1.1)) * 2.7
                    local xOffset = sideSign * (8.5 + (maxSpread - 1) * tipSpread)
                    local yOffset = (WingsConfig.HeightOffset or 2.5) + ((maxSpread - 1) * (WingsConfig.ElevationStep or 0.3))
                    local zOffset = (WingsConfig.BackOffset or 0.2) - ((maxSpread - 1) * 0.15)
                    local targetPos = predHRPCF.Position + (predHRPCF.RightVector * xOffset) + (predHRPCF.UpVector * yOffset) + (predHRPCF.LookVector * zOffset)
                    local baseUpright = math.rad(WingsConfig.WingAngle or 55)
                    local roll = sideSign * (baseUpright + (maxSpread - 1) * math.rad(10))
                    local targetRot = predHRPCF * CFrame.Angles(0, sideSign * math.rad(10), 0) * CFrame.Angles(math.rad(6), 0, roll)
                    leftWingTipCF = targetRot + (targetPos - targetRot.Position)
                end
                if not rightWingTipCF and hrp then
                    local sideSign = 1
                    local maxSpread = (WingsConfig.PalletsPerSide or 4)
                    local tipSpread = ((sideSign < 0) and (WingsConfig.LeftSpacing or 1.1) or (WingsConfig.RightSpacing or 1.1)) * 2.7
                    local xOffset = sideSign * (8.5 + (maxSpread - 1) * tipSpread)
                    local yOffset = (WingsConfig.HeightOffset or 2.5) + ((maxSpread - 1) * (WingsConfig.ElevationStep or 0.3))
                    local zOffset = (WingsConfig.BackOffset or 0.2) - ((maxSpread - 1) * 0.15)
                    local targetPos = predHRPCF.Position + (predHRPCF.RightVector * xOffset) + (predHRPCF.UpVector * yOffset) + (predHRPCF.LookVector * zOffset)
                    local baseUpright = math.rad(WingsConfig.WingAngle or 55)
                    local roll = sideSign * (baseUpright + (maxSpread - 1) * math.rad(10))
                    local targetRot = predHRPCF * CFrame.Angles(0, sideSign * math.rad(10), 0) * CFrame.Angles(math.rad(6), 0, roll)
                    rightWingTipCF = targetRot + (targetPos - targetRot.Position)
                end

                refreshActiveWingSparklers()
                if #activeWingSparklers < 4 and not isSpawningWings and (t - lastWingsRecheck > 1.0) then
                    task.spawn(spawnWingTipSparklers)
                end

                for idx = 1, math.min(#activeWingSparklers, 4) do
                    local sparklerModel = activeWingSparklers[idx]
                    if sparklerModel and sparklerModel.Parent and not sparklerModel:GetAttribute("PendingDestroy") then
                        local sparklerTargetCF = nil
                        if idx == 1 and leftWingTipCF then
                            sparklerTargetCF = leftWingTipCF * CFrame.new(-3.2, 0.2, 0.6) * CFrame.Angles(0, math.rad(-15), math.rad(90))
                        elseif idx == 2 and leftWingTipCF then
                            sparklerTargetCF = leftWingTipCF * CFrame.new(-3.2, -0.2, -0.6) * CFrame.Angles(0, math.rad(15), math.rad(90))
                        elseif idx == 3 and rightWingTipCF then
                            sparklerTargetCF = rightWingTipCF * CFrame.new(3.2, 0.2, 0.6) * CFrame.Angles(0, math.rad(15), -math.rad(90))
                        elseif idx == 4 and rightWingTipCF then
                            sparklerTargetCF = rightWingTipCF * CFrame.new(3.2, -0.2, -0.6) * CFrame.Angles(0, math.rad(-15), -math.rad(90))
                        end

                        if sparklerTargetCF then
                            driveToyOrbitPart(sparklerModel, sparklerTargetCF, "WingTipBP", "WingTipBG", eyePos, srf, shouldRefreshNet)
                        end
                    end
                end
            end
        end

        -- 2. CHARACTER ATTACHMENTS (Dih: Pencil/Coconut, Ass: Coconut Ass — Toy Tornado Orbit Loop)
        local currentTipCF = nil

        if CharAttachConfig.DihType == "Pencil" then
            local neededPencils = math.clamp(CharAttachConfig.PencilCount or 3, 1, 6)
            if t - lastDickRecheck > 0.6 then
                lastDickRecheck = t
                refreshActiveCharPencils()
                if #activeCharPencils < neededPencils and not isSpawningCharDih then
                    task.spawn(spawnCharDihBatch)
                end
            end

            local pencils = activeCharPencils
            local destroyRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
            for idx = #pencils, 1, -1 do
                local entry = pencils[idx]
                if not entry or not entry.Model or not entry.Model.Parent or not entry.Main or not entry.Main.Parent or entry.Model:GetAttribute("PendingDestroy") then
                    table.remove(pencils, idx)
                elseif idx > neededPencils then
                    entry.Model:SetAttribute("PendingDestroy", true)
                    if destroyRF then pcall(function() destroyRF:FireServer(entry.Model) end) end
                    table.remove(pencils, idx)
                end
            end

            local pitchRad = math.rad(CharAttachConfig.AnglePitch)
            for idx = 1, #pencils do
                local entry = pencils[idx]
                local baseCF = predHRPCF * CFrame.new(0, CharAttachConfig.HeightOffset, -CharAttachConfig.ForwardOffset)
                local shaftCF = baseCF * CFrame.Angles(pitchRad, 0, 0) * CFrame.new(0, 0, -(idx - 1) * 1.35)
                local targetRot = shaftCF * CFrame.Angles(0, math.rad(90), 0)

                driveToyOrbitPart(entry.Model, targetRot, "CharPencilBP", "CharPencilBG", eyePos, srf, shouldRefreshNet)

                if idx == #pencils then
                    currentTipCF = shaftCF * CFrame.new(0, 0, -1.35)
                end
            end
        elseif CharAttachConfig.DihType == "Coconut" then
            local neededCoconuts = math.clamp(CharAttachConfig.CoconutAmount or 8, 3, 15)
            if t - lastDickRecheck > 0.6 then
                lastDickRecheck = t
                refreshActiveCharCoconuts()
                if #activeCharCoconuts < neededCoconuts and not isSpawningCharDih then
                    task.spawn(spawnCharDihBatch)
                end
            end

            local coconuts = activeCharCoconuts
            local destroyRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
            for idx = #coconuts, 1, -1 do
                local item = coconuts[idx]
                if not item or not item.Parent or item:GetAttribute("PendingDestroy") then
                    table.remove(coconuts, idx)
                elseif idx > neededCoconuts then
                    item:SetAttribute("PendingDestroy", true)
                    if destroyRF then pcall(function() destroyRF:FireServer(item) end) end
                    table.remove(coconuts, idx)
                end
            end

            local pitchRad = math.rad(CharAttachConfig.AnglePitch)
            for idx = 1, #coconuts do
                local item = coconuts[idx]
                local targetCF
                if idx == 1 then
                    targetCF = predHRPCF * CFrame.new(-0.45, CharAttachConfig.HeightOffset, -CharAttachConfig.ForwardOffset)
                elseif idx == 2 then
                    targetCF = predHRPCF * CFrame.new(0.45, CharAttachConfig.HeightOffset, -CharAttachConfig.ForwardOffset)
                else
                    local baseCF = predHRPCF * CFrame.new(0, CharAttachConfig.HeightOffset + 0.1, -CharAttachConfig.ForwardOffset)
                    targetCF = baseCF * CFrame.Angles(pitchRad, 0, 0) * CFrame.new(0, 0, -(idx - 2) * 0.95)
                    if idx == #coconuts then
                        currentTipCF = targetCF * CFrame.new(0, 0, -0.95)
                    end
                end

                driveToyOrbitPart(item, targetCF, "CharDihBP", "CharDihBG", eyePos, srf, shouldRefreshNet)
            end
        end

        -- DIH SUCK & SIT TRAP (Old Grab-Method: Pulls victim with real CreateGrabLine & sits on tip)
        if CharAttachConfig.TrapOnTouch then
            if not currentTipCF and hrp then
                -- Reliable fallback tip CFrame in front of crotch if toy not spawned yet
                local fOff = CharAttachConfig.ForwardOffset or 1.2
                local hOff = CharAttachConfig.HeightOffset or -0.4
                currentTipCF = hrp.CFrame * CFrame.new(0, hOff, -fOff - 2.5)
            end

            if currentTipCF then
                local tipPos = currentTipCF.Position
                local seatedPos = tipPos + Vector3.new(0, 0.25, 0)
                -- Arkasını dönük oturma (Facing forward away from player, back towards player)
                local seatedRot = hrp.CFrame.Rotation
                local targetCF = CFrame.new(seatedPos) * seatedRot
                local createLine = ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("CreateGrabLine")
                local destroyLine = ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("DestroyGrabLine")

                -- Validate active target: only release if dead or disconnected
                local currentTarget = CharAttachConfig.TrappedPlayer
                if currentTarget then
                    if not currentTarget.Parent or not currentTarget.Character then
                        releaseTrappedPlayers()
                        currentTarget = nil
                    else
                        local tHum = currentTarget.Character:FindFirstChildOfClass("Humanoid")
                        if not tHum or tHum.Health <= 0 then
                            releaseTrappedPlayers()
                            currentTarget = nil
                        end
                    end
                end

                -- If no target locked, pick the single closest candidate within trap radius
                if not currentTarget then
                    local bestTarget = nil
                    local bestDist = CharAttachConfig.TrapRadius or 12
                    for _, otherP in ipairs(Players:GetPlayers()) do
                        if otherP ~= LocalPlayer and otherP.Character and not TR_IsWhitelisted(otherP) then
                            local otherHRP = otherP.Character:FindFirstChild("HumanoidRootPart")
                            local otherHum = otherP.Character:FindFirstChildOfClass("Humanoid")
                            if otherHRP and otherHum and otherHum.Health > 0 then
                                local dist = (otherHRP.Position - tipPos).Magnitude
                                if dist <= bestDist then
                                    bestDist = dist
                                    bestTarget = otherP
                                end
                            end
                        end
                    end
                    if bestTarget then
                        CharAttachConfig.TrappedPlayer = bestTarget
                        currentTarget = bestTarget
                        CharAttachConfig.TrapLineCreated = false
                    end
                end

                -- Apply grab pull lock strictly with the OLD method (CreateGrabLine + BodyPosition + Sit)
                if currentTarget and currentTarget.Character and not TR_IsWhitelisted(currentTarget) then
                    local targetHRP = currentTarget.Character:FindFirstChild("HumanoidRootPart")
                    local targetTorso = currentTarget.Character:FindFirstChild("Torso") or currentTarget.Character:FindFirstChild("UpperTorso")
                    local targetHead = currentTarget.Character:FindFirstChild("Head")
                    local targetHum = currentTarget.Character:FindFirstChildOfClass("Humanoid")

                    if targetHRP and targetHum and targetHum.Health > 0 then
                        local now = tick()

                        -- 1. Claim network ownership with Ray from eyes to target
                        local lastSRF = CharAttachConfig.LastTrapSRF or 0
                        if srf and (now - lastSRF > 0.15) then
                            CharAttachConfig.LastTrapSRF = now
                            local rayCF = CFrame.new(eyePos, targetHRP.Position)
                            pcall(function() srf:FireServer(targetHRP, rayCF) end)
                            if targetTorso then
                                pcall(function() srf:FireServer(targetTorso, CFrame.new(eyePos, targetTorso.Position)) end)
                            end
                            if targetHead then
                                pcall(function() srf:FireServer(targetHead, CFrame.new(eyePos, targetHead.Position)) end)
                            end
                        end

                        -- 2. Create real server grab line (Auto Line Pull: one-time on initial lock to prevent loud repeating sound & visual clutter)
                        if createLine and CharAttachConfig.TrapPullLine then
                            if not CharAttachConfig.TrapLineCreated then
                                CharAttachConfig.TrapLineCreated = true
                                CharAttachConfig.LastTrapLineTime = now
                                pcall(function()
                                    local grabPart = targetTorso or targetHRP
                                    createLine:FireServer(grabPart, CFrame.new(0, 0, 0))
                                end)
                            end
                        end

                        -- Mute scream sound on victim so it does not constantly play
                        local scream = targetHRP:FindFirstChild("Scream") or (targetTorso and targetTorso:FindFirstChild("Scream"))
                        if scream and scream.Playing then
                            scream.Playing = false
                        end

                        -- 3. Disable collisions so victim glides smoothly without flinging
                        for _, pt in ipairs(currentTarget.Character:GetDescendants()) do
                            if pt:IsA("BasePart") then
                                pt.CanCollide = false
                                pt.CanQuery = false
                            end
                        end

                        -- 4. Force sit animation & lock state
                        targetHum.Sit = true
                        targetHum.PlatformStand = false
                        pcall(function() targetHum:ChangeState(Enum.HumanoidStateType.Seated) end)

                        -- 5. BodyPosition & BodyGyro locking victim seated right on tip
                        local bp = targetHRP:FindFirstChild("DihSuckBP") or Instance.new("BodyPosition", targetHRP)
                        bp.Name = "DihSuckBP"
                        bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
                        bp.P = 500000
                        bp.D = 300
                        bp.Position = seatedPos

                        local bg = targetHRP:FindFirstChild("DihSuckBG") or Instance.new("BodyGyro", targetHRP)
                        bg.Name = "DihSuckBG"
                        bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
                        bg.P = 300000
                        bg.D = 200
                        bg.CFrame = targetCF

                        if targetTorso then
                            local bpTorso = targetTorso:FindFirstChild("DihSuckBP") or Instance.new("BodyPosition", targetTorso)
                            bpTorso.Name = "DihSuckBP"
                            bpTorso.MaxForce = Vector3.new(1e9, 1e9, 1e9)
                            bpTorso.P = 500000
                            bpTorso.D = 300
                            bpTorso.Position = seatedPos

                            local bgTorso = targetTorso:FindFirstChild("DihSuckBG") or Instance.new("BodyGyro", targetTorso)
                            bgTorso.Name = "DihSuckBG"
                            bgTorso.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
                            bgTorso.P = 300000
                            bgTorso.D = 200
                            bgTorso.CFrame = targetCF
                        end

                        local pullDir = (seatedPos - targetHRP.Position)
                        if pullDir.Magnitude > 1.2 then
                            targetHRP.AssemblyLinearVelocity = pullDir.Unit * 45 + hrp.AssemblyLinearVelocity
                            targetHRP.CFrame = CFrame.new(targetHRP.Position:Lerp(seatedPos, 0.35)) * seatedRot
                        else
                            targetHRP.CFrame = targetCF
                            if targetTorso then targetTorso.CFrame = targetCF end
                            targetHRP.AssemblyLinearVelocity = hrp.AssemblyLinearVelocity
                        end
                        targetHRP.AssemblyAngularVelocity = Vector3.zero
                    end
                end
            end
        end

    -- SPERM (Ejaculation: Shoots Sunny-Side Up Eggs from tip of Dih ONLY when a player is at the tip, 5-second interval)
        if CharAttachConfig.Sperm and hrp then
            local nowSperm = tick()
            local tip = currentTipCF or (hrp.CFrame * CFrame.new(0, -0.35, -3.8))
            local hasPlayerAtTip = false

            -- Check if trapped victim is at the tip
            if CharAttachConfig.TrappedPlayer and CharAttachConfig.TrappedPlayer.Character then
                local tHRP = CharAttachConfig.TrappedPlayer.Character:FindFirstChild("HumanoidRootPart") or CharAttachConfig.TrappedPlayer.Character:FindFirstChild("Torso")
                if tHRP and (tHRP.Position - tip.Position).Magnitude <= 6.5 then
                    hasPlayerAtTip = true
                end
            end
            -- Check if any AutoClicker victim is at the tip
            if not hasPlayerAtTip and ACState and ACState.ActiveTargets then
                for tPlr, _ in pairs(ACState.ActiveTargets) do
                    local tChar = tPlr and tPlr.Character
                    local tHRP = tChar and (tChar:FindFirstChild("HumanoidRootPart") or tChar:FindFirstChild("Torso"))
                    if tHRP and (tHRP.Position - tip.Position).Magnitude <= 6.5 then
                        hasPlayerAtTip = true
                        break
                    end
                end
            end
            -- Check any non-whitelisted player close in front of the tip
            if not hasPlayerAtTip then
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer and p.Character and not TR_IsWhitelisted(p) then
                        local pTorso = p.Character:FindFirstChild("Torso") or p.Character:FindFirstChild("HumanoidRootPart")
                        if pTorso and (pTorso.Position - tip.Position).Magnitude <= 5.5 then
                            hasPlayerAtTip = true
                            break
                        end
                    end
                end
            end

            -- Only spawn when someone is at the tip, every 5.0 seconds (no spamming when tip is empty)
            if hasPlayerAtTip and (nowSperm - (CharAttachConfig.LastSpermTime or 0) >= 5.0) then
                CharAttachConfig.LastSpermTime = nowSperm
                task.spawn(function()
                    local spawnPos = tip.Position + (tip.LookVector * 1.5)
                    local spawnCF = CFrame.new(spawnPos, spawnPos + tip.LookVector)
                    local egg = spawnSingleToy("FoodDippyEgg", spawnCF)
                    if egg then
                        local eggPart = egg:FindFirstChild("Main") or egg:FindFirstChild("SoundPart") or egg.PrimaryPart or egg:FindFirstChildWhichIsA("BasePart")
                        if eggPart then
                            eggPart.CanCollide = true
                            eggPart.AssemblyLinearVelocity = (tip.LookVector * 55) + Vector3.new(0, 12, 0)
                        end
                        task.delay(4.5, function()
                            pcall(function()
                                local dt = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
                                if dt and egg and egg.Parent then dt:FireServer(egg) end
                            end)
                        end)
                    end
                end)
            end
        end

        -- Character Ass (Coconut Ass on rear cheeks — Toy Tornado Orbit Loop)
        if CharAttachConfig.AssType == "Coconut Ass" then
            refreshActiveCharAss()
            local needed = math.clamp(CharAttachConfig.AssCheeks or 2, 2, 4)
            if #activeCharAss < needed and not isSpawningCharAss then
                task.spawn(spawnCharAssBatch)
            end
            local destroyRF = ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")
            for idx = #activeCharAss, 1, -1 do
                local item = activeCharAss[idx]
                if not item or not item.Parent or item:GetAttribute("PendingDestroy") then
                    table.remove(activeCharAss, idx)
                elseif idx > needed then
                    item:SetAttribute("PendingDestroy", true)
                    if destroyRF then pcall(function() destroyRF:FireServer(item) end) end
                    table.remove(activeCharAss, idx)
                end
            end
            for idx = 1, #activeCharAss do
                local item = activeCharAss[idx]
                local targetCF
                if idx == 1 then
                    targetCF = predHRPCF * CFrame.new(-0.42, -1.05, 0.5)  -- Left Butt Cheek
                elseif idx == 2 then
                    targetCF = predHRPCF * CFrame.new(0.42, -1.05, 0.5)   -- Right Butt Cheek
                elseif idx == 3 then
                    targetCF = predHRPCF * CFrame.new(-0.42, 0.45, -0.65) -- Left Boob (Chest)
                else
                    targetCF = predHRPCF * CFrame.new(0.42, 0.45, -0.65)  -- Right Boob (Chest)
                end
                driveToyOrbitPart(item, targetCF, "CharAssBP", "CharAssBG", eyePos, srf, shouldRefreshNet)
            end
        end

        -- 2B. BLOW (LAP HOLD & LEG SPREAD STRADDLE)
        if CharAttachConfig.BlowActive then
            local blowTarget = CharAttachConfig.BlowTargetPlayer
            if blowTarget then
                if not blowTarget.Parent or not blowTarget.Character or TR_IsWhitelisted(blowTarget) then
                    releaseBlowPlayer()
                    CharAttachConfig.BlowTargetPlayer = nil
                    blowTarget = nil
                else
                    local tHum = blowTarget.Character:FindFirstChildOfClass("Humanoid")
                    local tHRP = blowTarget.Character:FindFirstChild("HumanoidRootPart")
                    if not tHum or not tHRP or tHum.Health <= 0 then
                        releaseBlowPlayer()
                        blowTarget = nil
                    end
                end
            end

            -- Find closest player within Blow range if not locked
            if not blowTarget then
                local bestTarget = nil
                local bestDist = CharAttachConfig.BlowRange or 25
                for _, otherP in ipairs(Players:GetPlayers()) do
                    if otherP ~= LocalPlayer and otherP.Character and not TR_IsWhitelisted(otherP) then
                        local otherHRP = otherP.Character:FindFirstChild("HumanoidRootPart")
                        local otherHum = otherP.Character:FindFirstChildOfClass("Humanoid")
                        if otherHRP and otherHum and otherHum.Health > 0 then
                            local dist = (otherHRP.Position - hrp.Position).Magnitude
                            if dist <= bestDist then
                                bestDist = dist
                                bestTarget = otherP
                            end
                        end
                    end
                end
                if bestTarget then
                    CharAttachConfig.BlowTargetPlayer = bestTarget
                    blowTarget = bestTarget
                end
            end

            -- Lock in Lap Hold with legs spread flanking torso
            if blowTarget and blowTarget.Character then
                local tChar = blowTarget.Character
                local tHRP = tChar:FindFirstChild("HumanoidRootPart")
                local tHum = tChar:FindFirstChildOfClass("Humanoid")

                if tHRP and tHum and tHum.Health > 0 then
                    -- Network Ownership
                    if srf then
                        pcall(function() srf:FireServer(tHRP, tHRP.CFrame) end)
                    end

                    -- Disable collision on victim
                    for _, pt in ipairs(tChar:GetDescendants()) do
                        if pt:IsA("BasePart") then
                            pt.CanCollide = false
                            pt.CanQuery = false
                        end
                    end

                    -- Force PlatformStand, Ragdoll and disable AutoRotate so victim is visibly ragdolled
                    tHum.PlatformStand = true
                    tHum.AutoRotate = false
                    pcall(function() tHum:ChangeState(Enum.HumanoidStateType.Ragdoll) end)

                    local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
                    local ragdollRemote = charEvents and charEvents:FindFirstChild("RagdollRemote")
                    if ragdollRemote then
                        pcall(function() ragdollRemote:FireServer(tHRP, 0) end)
                    end

                    -- Destroy FTAP grab line on victim to prevent being stuck in hands
                    local grabEvts = ReplicatedStorage:FindFirstChild("GrabEvents")
                    local destroyLine = grabEvts and grabEvts:FindFirstChild("DestroyGrabLine")
                    if destroyLine then
                        pcall(function() destroyLine:FireServer(tHRP) end)
                        local tTorso = tChar:FindFirstChild("Torso") or tChar:FindFirstChild("UpperTorso")
                        if tTorso then pcall(function() destroyLine:FireServer(tTorso) end) end
                    end

                    -- Sever any arm/hand welds connecting player to victim
                    local lpChar = LocalPlayer and LocalPlayer.Character
                    if lpChar then
