task.spawn(function()
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local SlotsFolder = workspace:FindFirstChild('Slots') or workspace:WaitForChild('Slots', 2)
local SlotsScreen = SlotsFolder and (SlotsFolder:FindFirstChild('Slots') or SlotsFolder:WaitForChild('Slots', 2))
local SlotGui = SlotsScreen and SlotsScreen:FindFirstChild('Screen') and (SlotsScreen.Screen:FindFirstChild('SlotGui') or SlotsScreen.Screen:WaitForChild('SlotGui', 2))
local TimeTextObj = SlotGui and SlotGui:FindFirstChild('TimeLeftFrame') and (SlotGui.TimeLeftFrame:FindFirstChild('TimeText') or SlotGui.TimeLeftFrame:WaitForChild('TimeText', 2))
local slotHandle = SlotsScreen and SlotsScreen:FindFirstChild('SlotHandle') and SlotsScreen.SlotHandle:FindFirstChild('Handle')
local targetTime = '0:00'
local farmingActive = false
local slotTeleportPosition = Vector3.new(-224.941177, 91.364975, 425.75116)
local savedCFrame = nil

local hasNotifiedSlot = false
task.spawn(function()
    while task.wait(0.5) do
        pcall(function()
            if not farmingActive then
                hasNotifiedSlot = false
                return
            end

            if TimeTextObj and TimeTextObj.Parent then
                local txt = tostring(TimeTextObj.Text or "")
                local m, s = txt:match("(%d+):(%d+)")
                if m and s then
                    local totalSecs = tonumber(m) * 60 + tonumber(s)
                    if totalSecs <= 10 and totalSecs > 0 then
                        if not hasNotifiedSlot then
                            hasNotifiedSlot = true
                            Library:Notify({
                                Title = "Spin Slots Alert!",
                                Content = string.format("10 SECONDS LEFT (%s)! Go Spin Slots Now!", txt),
                                Duration = 5
                            })
                            pcall(function()
                                local snd = Instance.new("Sound", workspace)
                                snd.SoundId = "rbxassetid://9069609200"
                                snd.Volume = 1.5
                                snd:Play()
                                task.delay(2, function() snd:Destroy() end)
                            end)
                        end
                    elseif totalSecs > 15 then
                        hasNotifiedSlot = false
                    end
                end
            end
        end)
    end
end)

function farmLoop()
    while farmingActive do
        task.wait(1)

        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild('HumanoidRootPart')

        if not hrp then
            continue
        end

        savedCFrame = hrp.CFrame

        local currentTime = TimeTextObj and TimeTextObj.Text

        if currentTime == targetTime then
            hrp.CFrame = CFrame.new(slotTeleportPosition)

            task.wait(1)
            pcall(function()
                ReplicatedStorage.GrabEvents.SetNetworkOwner:FireServer(slotHandle, CFrame.new(slotTeleportPosition))
            end)
            task.wait(1)

            if hrp and hrp.Parent then
                hrp.CFrame = savedCFrame
            end
        end
    end
end

