-- ===============================
-- SOUND (BELL)
-- ===============================
function playKickSound()
	local s = Instance.new("Sound")
	s.SoundId = "rbxassetid://79150789336480" -- Bell (Deltarune)
	s.Volume = 5
	s.PlayOnRemove = true
	s.Parent = SoundService
	s:Destroy()
end

-- ===============================
-- NOTIFY (XOCU)
-- ===============================
function notifyKick(displayName, username)
	Library:Notify({ Title = "Ranax FTAP ", Content = displayName .. " (" .. username .. ") has been kicked", Duration = 6,
	 })
end

-- ===============================
-- HELPERS
-- ===============================
function getClosestPlayer(pos)
	local closestPlr = nil
	local closestDist = math.huge
	for _, plr in ipairs(Players:GetPlayers()) do
		if plr ~= LocalPlayer and plr.Character then
			local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
			if hrp then
				local dist = (hrp.Position - pos).Magnitude
				if dist < closestDist then
					closestDist = dist
					closestPlr = plr
				end
			end
		end
	end
	return closestPlr
end

-- ===============================
-- BLACK HOLE DETECT
-- ===============================
Workspace.ChildAdded:Connect(function(obj)
	if obj.Name == "BlackHoleKick" or obj.Name == "BlackHoleDetected" then
		task.wait(0.05)
		local pos
		if obj:IsA("BasePart") then
			pos = obj.Position
		elseif obj:IsA("Model") and obj.PrimaryPart then
			pos = obj.PrimaryPart.Position
		end
		if not pos then
			return
		end
		local plr = getClosestPlayer(pos)
		if not plr then
			return
		end
		playKickSound()
		notifyKick(plr.DisplayName, plr.Name)
	end
end)
    end)
    if not _ok then warn("[TRFTAP] BlackHole error: " .. tostring(_err)) end
end)

