    if not tpEnabled then return end
    if not currentTpBind or currentTpBind == Enum.KeyCode.Unknown then return end
    if input.KeyCode == currentTpBind or input.UserInputType == currentTpBind then
        executeTeleportToMouse()
    end
end)
