    do

    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local LocalPlayer = Players.LocalPlayer

    local Remotes = {
        SpawnToy = (ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("SpawnToyRemoteFunction")) or (ReplicatedStorage:WaitForChild("MenuToys", 2) and ReplicatedStorage.MenuToys:WaitForChild("SpawnToyRemoteFunction", 2)),
        SetNetOwner = (ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner")) or (ReplicatedStorage:WaitForChild("GrabEvents", 2) and ReplicatedStorage.GrabEvents:WaitForChild("SetNetworkOwner", 2)),
        BombExplode = (ReplicatedStorage:FindFirstChild("BombEvents") and ReplicatedStorage.BombEvents:FindFirstChild("BombExplode")) or (ReplicatedStorage:WaitForChild("BombEvents", 2) and ReplicatedStorage.BombEvents:WaitForChild("BombExplode", 2)),
        DestroyToy = (ReplicatedStorage:FindFirstChild("MenuToys") and ReplicatedStorage.MenuToys:FindFirstChild("DestroyToy")) or (ReplicatedStorage:WaitForChild("MenuToys", 2) and ReplicatedStorage.MenuToys:WaitForChild("DestroyToy", 2))
    }

    local snowballActive = false
    local snowballTask = nil

    ToggleBlock:CreateToggle({
        Name = "Loop Snowball(For ragdoll)",
        Default = false,
        Callback = function(v)
            snowballActive = v

            if snowballTask then
                task.cancel(snowballTask)
                snowballTask = nil
            end

            if v then
                snowballTask = task.spawn(function()
                    while snowballActive do
                        local target = FGM.State.SelectedTarget and Players:FindFirstChild(FGM.State.SelectedTarget)
                        if not target or not target.Character then
                            task.wait(0.1)
                            continue 
                        end

                        local tRoot = target.Character:FindFirstChild("HumanoidRootPart")
                        if not tRoot then 
                            task.wait(0.1)
                            continue 
                        end

                        local char = LocalPlayer.Character
                        local hrp = char and char:FindFirstChild("HumanoidRootPart")
                        if not hrp then 
                            task.wait(0.1)
                            continue 
                        end

                        local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                        if not inv then 
                            task.wait(0.1)
                            continue 
                        end

                        local ball = inv:FindFirstChild("BallSnowball")
                        if not ball then
                            task.spawn(function()
                                pcall(function() 
                                    Remotes.SpawnToy:InvokeServer("BallSnowball", hrp.CFrame * CFrame.new(0, 10, 20), Vector3.zero) 
                                end)
                            end)
                            task.wait(0.15)
                        else
                            local SoundPart = ball:FindFirstChild("SoundPart")
                            if SoundPart then
                                pcall(function() 
                                    Remotes.SetNetOwner:FireServer(SoundPart, SoundPart.CFrame) 
                                end)
                                task.wait(0.05)

                                SoundPart.CFrame = tRoot.CFrame
                                task.wait(0.05)

                                local payload = {
                                    Radius = 0,
                                    Color = Color3.new(0, 0, 0),
                                    TimeLength = 0,
                                    Model = ball,
                                    Type = "SnowPoof",
                                    ExplodesByFire = false,
                                    MaxForcePerStudSquared = 0,
                                    Hitbox = SoundPart,
                                    ImpactSpeed = 0,
                                    ExplodesByPointy = false,
                                    DestroysModel = true,
                                    PositionPart = SoundPart
                                }
                                
                                pcall(function() 
                                    Remotes.BombExplode:FireServer(payload, Vector3.zero) 
                                end)
                                task.wait(0.15)
                            else
                                task.wait(0.1)
                            end
                        end
                    end
                end)
            end
        end
    })
end

