        anim.AnimationId = BangState.AnimId
        local ok, track = pcall(function()
            return animator:LoadAnimation(anim)
        end)
        if ok and track then
            BangState.Track = track
            BangState.Track.Priority = Enum.AnimationPriority.Action
            BangState.Track:Play()
