                pcall(function() SetToggleState("Bang (Slow)", on) end)
                BangState.Active = on
                if on then
                    startBang()
                else
                    stopBang()
                end
                for _, other in ipairs(bangToggles) do
                    if other ~= bt and other.Set and other.Value ~= on then
                        pcall(function() other:Set(on) end)
                    end
                end
            end
        })
        table.insert(bangToggles, bt)
