        SpeedR15 = 0.95,
        TimeStart = 0.6,
    }

    local function isR15Char(char)
        local hum = char and char:FindFirstChildWhichIsA("Humanoid")
        if not hum then return false end
        return hum.RigType == Enum.HumanoidRigType.R15
    end

    local function stopJerk()
        JerkState.Active = false
        _G.JerkActive = false
        if JerkState.Track then
            pcall(function() JerkState.Track:Stop() end)
            JerkState.Track = nil
        end
        if JerkState.LoopThread then
            pcall(function() task.cancel(JerkState.LoopThread) end)
            JerkState.LoopThread = nil
        end
    end

    local function startJerk()
        if JerkState.Active then return end
        JerkState.Active = true
        _G.JerkActive = true

        JerkState.LoopThread = task.spawn(function()
            while JerkState.Active or _G.JerkActive do
                local plr = Players.LocalPlayer
                local char = plr and plr.Character
                if not char or not char.Parent then
                    stopJerk()
                    break
                end
                local hum = char:FindFirstChildWhichIsA("Humanoid")
                if not hum or hum.Health <= 0 then
                    stopJerk()
                    break
                end

                local r15 = isR15Char(char)

                local anim = Instance.new("Animation")
                anim.AnimationId = r15 and "rbxassetid://698251653" or "rbxassetid://72042024"

                local animator = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 1)
                local ok, newTrack = pcall(function()
                    if animator then
                        return animator:LoadAnimation(anim)
                    else
                        return hum:LoadAnimation(anim)
                    end
                end)

                if ok and newTrack then
                    JerkState.Track = newTrack
                    JerkState.Track.Priority = Enum.AnimationPriority.Action4
                    JerkState.Track:Play()
                    local mult = tonumber(JerkState.Speed) or tonumber(_G.JerkSpeed) or 1.0
                    JerkState.Track:AdjustSpeed((r15 and JerkState.SpeedR15 or JerkState.SpeedR6) * mult)
                    JerkState.Track.TimePosition = JerkState.TimeStart

                    task.wait(0.08)
                    while (JerkState.Active or _G.JerkActive) and JerkState.Track and JerkState.Track.TimePosition < (r15 and 0.7 or 0.65) do
                        task.wait(0.05)
                    end

                    if JerkState.Track then
                        pcall(function() JerkState.Track:Stop() end)
                        JerkState.Track = nil
                    end
                else
                    task.wait(0.1)
                end
            end
        end)
    end

    local jerkToggles = {}

    local function toggleJerk(force)
        local target = (force ~= nil) and force or (not JerkState.Active)
        if target == JerkState.Active and force ~= nil then return end
        pcall(function() SetToggleState("Jerk", target) end)
        if target then
            startJerk()
            pcall(function() notify("Jerk", "Jerk: ON", 2) end)
        else
            stopJerk()
            pcall(function() notify("Jerk", "Jerk: OFF", 2) end)
        end
        for _, jt in ipairs(jerkToggles) do
            if jt and jt.Set and jt.Value ~= target and not JerkState.Syncing then
                JerkState.Syncing = true
                pcall(function() jt:Set(target) end)
                JerkState.Syncing = false
            end
        end
        local tgl = (Toggles and Toggles.Jerk) or (Options and Options.Jerk)
        if tgl and tgl.Set and not JerkState.Syncing then
            JerkState.Syncing = true
            pcall(function() tgl:Set(target) end)
            JerkState.Syncing = false
        end
    end
