            end
        })
    end

    UserInputService.InputBegan:Connect(function(input, gpe)
        if gpe or (UserInputService:GetFocusedTextBox() ~= nil) then return end
        local bind = JerkState.Keybind or "J"
        local match = false
        if typeof(bind) == "string" then
            if (input.KeyCode and input.KeyCode.Name == bind) or (input.UserInputType and input.UserInputType.Name == bind) then
                match = true
            end
        elseif typeof(bind) == "EnumItem" then
            if input.KeyCode == bind or input.UserInputType == bind then
                match = true
            end
        elseif type(bind) == "table" and bind.Key then
            if input.KeyCode == bind.Key or input.UserInputType == bind.Key then
                match = true
            end
        end
        if match then
            toggleJerk()
        end
    end)

    if Players.LocalPlayer then
        Players.LocalPlayer.CharacterAdded:Connect(function(char)
            stopJerk()
            local h = char:WaitForChild("Humanoid", 5)
            if h then
                h.Died:Connect(stopJerk)
            end
        end)
        local curChar = Players.LocalPlayer.Character
        local curHum = curChar and curChar:FindFirstChildOfClass("Humanoid")
        if curHum then
            curHum.Died:Connect(stopJerk)
        end
    end
    end)
    if not _ok then warn("[TRFTAP] Troll/Jerk/Bang error: " .. tostring(_err)) end
end)

