    local RunService = game:GetService("RunService")

    local function setMouseUnlocked(state)
        mouseUnlocked = state
        if mouseUnlocked then
            pcall(function()
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                UserInputService.MouseIconEnabled = true
            end)
            if not mouseUnlockConn then
                mouseUnlockConn = RunService.RenderStepped:Connect(function()
                    if mouseUnlocked then
                        if not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
                            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                        end
                        UserInputService.MouseIconEnabled = true
                    end
                end)
            end
            pcall(function() notify("Mouse", "Mouse Unlocked (Free Cursor)", 1.5) end)
        else
            if mouseUnlockConn then
                mouseUnlockConn:Disconnect()
                mouseUnlockConn = nil
            end
            pcall(function() notify("Mouse", "Mouse Locked", 1.5) end)
        end
    end

    local function toggleMouseUnlock()
        setMouseUnlocked(not mouseUnlocked)
