                currentMouseBind = bind
            end
            toggleMouseUnlock()
        end
    })

    UserInputService.InputBegan:Connect(function(input, gpe)
        if gpe or UserInputService:GetFocusedTextBox() then return end
        if input.KeyCode == currentMouseBind or (currentMouseBind == Enum.KeyCode.M and input.KeyCode == Enum.KeyCode.M) then
