do
    local function _initDecoyEngine()
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local RS = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local table_clear = table.clear or function(t) for k in pairs(t) do t[k] = nil end end
    local function notify(title, content, duration)
        pcall(function()
            if Library and Library.Notify then
                Library:Notify({ Title = title or "Decoy", Content = content or "", Duration = duration or 3 })
            end
        end)
    end

    local DecoyGroup = Tabs.Decoy:CreateBlock({Name = "Decoy Follower & AI", Side = "Left"})
    local DecoyActions = Tabs.Decoy:CreateBlock({Name = "Clone Spawner & Actions", Side = "Right"})

    local DecoyConfig = {
        FollowEnabled = false,
        SelectedPlayerName = "",
        TargetMode = "Follow Me (Bodyguard)", -- Default to bodyguard so it tracks LocalPlayer immediately!
        MovementMode = "Pathfind Walk",
        WalkSpeed = 32,
        JumpPower = 80,
        StopDistance = 4,
        AutoJumpObstacles = true,
        NoclipClones = false,
        CircleRadius = 8,
        CircleSpeed = 3,
    }

    local activeDecoys = {}
    local decoyFollowThread = nil

    local function getDecoyFolder()
        local name = (LocalPlayer and LocalPlayer.Name) or (Players.LocalPlayer and Players.LocalPlayer.Name)
        return name and workspace:FindFirstChild(name .. "SpawnedInToys")
    end

    local function refreshActiveDecoys()
        local folders = getMyToyFolders()
        local valid = {}
        for _, folder in ipairs(folders) do
            for _, item in ipairs(folder:GetChildren()) do
                if item.Name == "YouDecoy" and item:IsA("Model") and item:FindFirstChild("HumanoidRootPart") and item:FindFirstChildOfClass("Humanoid") then
                    table.insert(valid, item)
                end
            end
        end
        activeDecoys = valid
        return valid
    end

    local function applyPhysicsToDecoy(decoy)
        if not decoy or not decoy.Parent then return end
        local hrp = decoy:FindFirstChild("HumanoidRootPart")
        local hum = decoy:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end

        pcall(function()
            local grabEvents = RS and RS:FindFirstChild("GrabEvents")
            local setNet = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
            if setNet then
                setNet:FireServer(hrp, hrp.CFrame)
            end
        end)

        pcall(function()
            hum.Sit = false
            hum.PlatformStand = false
            hum:ChangeState(Enum.HumanoidStateType.Running)
            hum.WalkSpeed = DecoyConfig.WalkSpeed
            hum.UseJumpPower = true
            hum.JumpPower = DecoyConfig.JumpPower
            hum.AutoRotate = true
        end)

        for _, pt in ipairs(decoy:GetDescendants()) do
            if pt:IsA("Seat") or pt:IsA("VehicleSeat") then
                pcall(function() pt.Disabled = true end)
            elseif pt:IsA("Weld") or pt:IsA("SeatWeld") then
                pcall(function() pt:Destroy() end)
            elseif DecoyConfig.NoclipClones and pt:IsA("BasePart") then
                pt.CanCollide = false
            end
        end
    end

    local function spawnDecoyClone(cf)
        local menuToys = RS and RS:FindFirstChild("MenuToys")
        local spawnRF = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction")
        if not spawnRF then return nil end
        local lp = LocalPlayer or Players.LocalPlayer
        local char = lp and lp.Character
        local myHRP = char and char:FindFirstChild("HumanoidRootPart")
        local baseCF = cf or (myHRP and myHRP.CFrame * CFrame.new(0, 2, -4)) or CFrame.new(0, 10, 0)

        local folder = getDecoyFolder()
        local spawnedDecoy = nil
        local cConn
        if folder then
            cConn = folder.ChildAdded:Connect(function(child)
                if child.Name == "YouDecoy" then
                    spawnedDecoy = child
                    if cConn then cConn:Disconnect() end
                end
            end)
        end

        pcall(function()
            spawnRF:InvokeServer("YouDecoy", baseCF, Vector3.zero)
        end)

        local tWait = tick()
        repeat task.wait(0.04) until spawnedDecoy or tick() - tWait > 1.2
        if cConn then cConn:Disconnect() end

        if spawnedDecoy then
            task.wait(0.1)
            applyPhysicsToDecoy(spawnedDecoy)
            refreshActiveDecoys()
            notify("Decoy", "Decoy Clone spawned successfully!", 2)
        end
        return spawnedDecoy
    end

    local function despawnAllDecoys()
        local folder = getDecoyFolder()
        local menuToys = RS and RS:FindFirstChild("MenuToys")
        local destroyRE = menuToys and menuToys:FindFirstChild("DestroyToy")
        if not folder or not destroyRE then return end

        for _, item in ipairs(folder:GetChildren()) do
            if item.Name == "YouDecoy" then
                pcall(function()
                    destroyRE:FireServer(item)
                end)
            end
        end
        table_clear(activeDecoys)
        notify("Decoy", "All Decoy Clones despawned.", 2)
    end

    local function getTargetPosition()
        local lp = LocalPlayer or Players.LocalPlayer
        local char = lp and lp.Character
        local myHRP = char and char:FindFirstChild("HumanoidRootPart")

        if DecoyConfig.TargetMode == "Follow Me (Bodyguard)" then
            return myHRP and myHRP.Position, myHRP
        elseif DecoyConfig.TargetMode == "Closest Player" then
            if not myHRP then return nil, nil end
            local closestPos = nil
            local closestHRP = nil
            local closestDist = math.huge
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr ~= lp and plr.Character then
                    local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local d = (hrp.Position - myHRP.Position).Magnitude
                        if d < closestDist then
                            closestDist = d
                            closestPos = hrp.Position
                            closestHRP = hrp
                        end
                    end
                end
            end
            return closestPos, closestHRP
        else
            local targetName = DecoyConfig.SelectedPlayerName
            if not targetName or targetName == "" then return nil, nil end
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr.Name == targetName or plr.DisplayName == targetName or (targetName and targetName:find(plr.Name, 1, true)) then
                    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        return hrp.Position, hrp
                    end
                end
            end
        end
        return nil, nil
    end

    local function runFollowIteration(dt)
        refreshActiveDecoys()
        if #activeDecoys == 0 then return end

        local targetPos, targetHRP = getTargetPosition()
        if not targetPos or not targetHRP then return end

        local timeNow = tick()

        for idx, decoy in ipairs(activeDecoys) do
            if decoy and decoy.Parent then
                local dHRP = decoy:FindFirstChild("HumanoidRootPart")
                local dHum = decoy:FindFirstChildOfClass("Humanoid")

                if dHRP and dHum and dHum.Health > 0 then
                    -- Unseat immediately if seated or platform standing
                    if dHum.Sit then
                        dHum.Sit = false
                        dHum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    end
                    if dHum.PlatformStand then
                        dHum.PlatformStand = false
                    end

                    -- Ensure client network ownership of decoy
                    local grabEvents = RS and RS:FindFirstChild("GrabEvents")
                    local setNet = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
                    if setNet then
                        pcall(function() setNet:FireServer(dHRP, dHRP.CFrame) end)
                    end

                    if dHum.WalkSpeed ~= DecoyConfig.WalkSpeed then
                        dHum.WalkSpeed = DecoyConfig.WalkSpeed
                    end
                    if dHum.JumpPower ~= DecoyConfig.JumpPower then
                        dHum.UseJumpPower = true
                        dHum.JumpPower = DecoyConfig.JumpPower
                    end

                    local dist = (dHRP.Position - targetPos).Magnitude

                    local stopDist = DecoyConfig.StopDistance or 4
                    local walkSpeed = DecoyConfig.WalkSpeed or 32

                    if DecoyConfig.MovementMode == "Pathfind Walk" then
                        if dist > stopDist then
                            local flatTarget = Vector3.new(targetPos.X, dHRP.Position.Y, targetPos.Z)
                            local diff = flatTarget - dHRP.Position
                            if diff.Magnitude > 0.5 then
                                local dir = diff.Unit
                                dHRP.CFrame = CFrame.lookAt(dHRP.Position, flatTarget)
                                dHum:Move(dir, false)
                                dHum:MoveTo(targetPos)
                                dHRP.AssemblyLinearVelocity = Vector3.new(dir.X * walkSpeed, dHRP.AssemblyLinearVelocity.Y, dir.Z * walkSpeed)
                            else
                                dHum:Move(Vector3.zero, false)
                            end

                            if DecoyConfig.AutoJumpObstacles then
                                if (targetPos.Y - dHRP.Position.Y) > 2.5 then
                                    dHum.Jump = true
                                    local jp = DecoyConfig.JumpPower or 50
                                    dHRP.AssemblyLinearVelocity = Vector3.new(dHRP.AssemblyLinearVelocity.X, jp, dHRP.AssemblyLinearVelocity.Z)
                                elseif dHRP.AssemblyLinearVelocity.Magnitude < 2 and dist > 6 then
                                    dHum.Jump = true
                                end
                            end
                        else
                            dHum:Move(Vector3.zero, false)
                            dHRP.AssemblyLinearVelocity = Vector3.new(0, dHRP.AssemblyLinearVelocity.Y, 0)
                        end

                    elseif DecoyConfig.MovementMode == "Speed Rush (Ram)" then
                        local flatTarget = Vector3.new(targetPos.X, dHRP.Position.Y, targetPos.Z)
                        local diff = flatTarget - dHRP.Position
                        if diff.Magnitude > 1.0 then
                            local dir = diff.Unit
                            dHRP.CFrame = CFrame.lookAt(dHRP.Position, flatTarget)
                            dHum:Move(dir, false)
                            local rushSpeed = walkSpeed * 1.6
                            dHRP.AssemblyLinearVelocity = Vector3.new(dir.X * rushSpeed, dHRP.AssemblyLinearVelocity.Y, dir.Z * rushSpeed)
                        end
                        if DecoyConfig.AutoJumpObstacles and (targetPos.Y - dHRP.Position.Y) > 2.5 then
                            dHum.Jump = true
                        end

                    elseif DecoyConfig.MovementMode == "Hover Stalk" then
                        local hoverTarget = targetHRP.CFrame * CFrame.new(0, 3.5, 4).Position
                        local bp = dHRP:FindFirstChild("DecoyHoverBP") or Instance.new("BodyPosition", dHRP)
                        bp.Name = "DecoyHoverBP"
                        bp.MaxForce = Vector3.new(1e8, 1e8, 1e8)
                        bp.P = 40000
                        bp.D = 600
                        bp.Position = hoverTarget

                        local bg = dHRP:FindFirstChild("DecoyHoverBG") or Instance.new("BodyGyro", dHRP)
                        bg.Name = "DecoyHoverBG"
                        bg.MaxTorque = Vector3.new(1e8, 1e8, 1e8)
                        bg.P = 25000
                        bg.CFrame = CFrame.new(dHRP.Position, targetPos)

                    elseif DecoyConfig.MovementMode == "Orbit Circle" then
                        local angle = timeNow * (DecoyConfig.CircleSpeed or 2) + (idx * (math.pi * 2 / #activeDecoys))
                        local offset = Vector3.new(math.cos(angle) * (DecoyConfig.CircleRadius or 8), 0, math.sin(angle) * (DecoyConfig.CircleRadius or 8))
                        local circlePos = targetPos + offset
                        local diff = circlePos - dHRP.Position
                        if diff.Magnitude > 1.0 then
                            local dir = diff.Unit
                            dHRP.CFrame = CFrame.lookAt(dHRP.Position, Vector3.new(circlePos.X, dHRP.Position.Y, circlePos.Z))
                            dHum:Move(dir, false)
                            dHRP.AssemblyLinearVelocity = Vector3.new(dir.X * walkSpeed, dHRP.AssemblyLinearVelocity.Y, dir.Z * walkSpeed)
                        else
                            dHum:Move(Vector3.zero, false)
                        end
                    end
                end
            end
        end
    end

    local function setFollowActive(active)
        DecoyConfig.FollowEnabled = active
        if active then
            if not decoyFollowThread then
                decoyFollowThread = task.spawn(function()
                    while DecoyConfig.FollowEnabled do
                        pcall(function() runFollowIteration(0.1) end)
                        task.wait(0.08)
                    end
                    decoyFollowThread = nil
                end)
            end
        else
            decoyFollowThread = nil
        end
    end

    local function getPlayerList()
        local list = {}
        local lp = LocalPlayer or Players.LocalPlayer
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= lp then
                table.insert(list, p.DisplayName .. " (@" .. p.Name .. ")")
            end
        end
        table.sort(list)
        return list
    end

    -- ==================== LEFT BLOCK: CONTROLS & SETTINGS ====================
    DecoyGroup:CreateToggle({
        Name = "Follow Target Active",
        Default = false,
        Callback = function(val)
            setFollowActive(val)
        end
    })

    local playerDropdown = DecoyGroup:CreateDropdown({
        Name = "Select Target Player",
        Items = getPlayerList(),
        Default = getPlayerList()[1] or "",
        Callback = function(val)
            DecoyConfig.SelectedPlayerName = val:match("@([%w_]+)") or val
        end
    })

    DecoyGroup:CreateButton({
        Name = "Refresh Player List",
        Callback = function()
            local updated = getPlayerList()
            if playerDropdown and playerDropdown.Refresh then
                playerDropdown:Refresh(updated, true)
            end
            notify("Decoy", "Player list refreshed!", 2)
        end
    })

    DecoyGroup:CreateDropdown({
        Name = "Target Mode",
        Items = {"Selected Player", "Follow Me (Bodyguard)", "Closest Player"},
        Default = "Selected Player",
        Callback = function(val)
            DecoyConfig.TargetMode = val
        end
    })

    DecoyGroup:CreateDropdown({
        Name = "Movement Behavior",
        Items = {"Pathfind Walk", "Speed Rush (Ram)", "Hover Stalk", "Orbit Circle"},
        Default = "Pathfind Walk",
        Callback = function(val)
            DecoyConfig.MovementMode = val
            if val ~= "Hover Stalk" then
                for _, d in ipairs(activeDecoys) do
                    if d and d:FindFirstChild("HumanoidRootPart") then
                        local bp = d.HumanoidRootPart:FindFirstChild("DecoyHoverBP")
                        local bg = d.HumanoidRootPart:FindFirstChild("DecoyHoverBG")
                        if bp then bp:Destroy() end
                        if bg then bg:Destroy() end
                    end
                end
            end
        end
    })

    DecoyGroup:CreateSlider({
        Name = "Clone WalkSpeed",
        Min = 16,
        Max = 200,
        Default = 32,
        Callback = function(val)
            DecoyConfig.WalkSpeed = val
            for _, d in ipairs(activeDecoys) do
                local hum = d:FindFirstChildOfClass("Humanoid")
                if hum then hum.WalkSpeed = val end
            end
        end
    })

    DecoyGroup:CreateSlider({
        Name = "Clone JumpPower",
        Min = 50,
        Max = 350,
        Default = 80,
        Callback = function(val)
            DecoyConfig.JumpPower = val
            for _, d in ipairs(activeDecoys) do
                local hum = d:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum.UseJumpPower = true
                    hum.JumpPower = val
                end
            end
        end
    })

    DecoyGroup:CreateSlider({
        Name = "Stop Distance",
        Min = 2,
        Max = 40,
        Default = 4,
        Callback = function(val)
            DecoyConfig.StopDistance = val
        end
    })

    DecoyGroup:CreateToggle({
        Name = "Auto Jump Over Obstacles",
        Default = true,
        Callback = function(val)
            DecoyConfig.AutoJumpObstacles = val
        end
    })

    -- ==================== RIGHT BLOCK: SPAWNER & ACTIONS ====================
    DecoyActions:CreateButton({
        Name = "Spawn Decoy Clone (Single)",
        Callback = function()
            task.spawn(spawnDecoyClone)
        end
    })

    DecoyActions:CreateButton({
        Name = "Spawn Clone Army (x3)",
        Callback = function()
            task.spawn(function()
                local lp = LocalPlayer or Players.LocalPlayer
                local myHRP = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
                if not myHRP then return end
                for i = 1, 3 do
                    local offset = CFrame.new((i - 2) * 4, 2, -4)
                    spawnDecoyClone(myHRP.CFrame * offset)
                    task.wait(0.2)
                end
            end)
        end
    })

    DecoyActions:CreateButton({
        Name = "Spawn Clone Swarm (x5)",
        Callback = function()
            task.spawn(function()
                local lp = LocalPlayer or Players.LocalPlayer
                local myHRP = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
                if not myHRP then return end
                for i = 1, 5 do
                    local angle = (i / 5) * math.pi * 2
                    local offset = CFrame.new(math.cos(angle) * 6, 2, math.sin(angle) * 6)
                    spawnDecoyClone(myHRP.CFrame * offset)
                    task.wait(0.18)
                end
            end)
        end
    })

    DecoyActions:CreateButton({
        Name = "Bring All Clones To Me",
        Callback = function()
            local lp = LocalPlayer or Players.LocalPlayer
            local myHRP = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
            if not myHRP then return end
            refreshActiveDecoys()
            for idx, d in ipairs(activeDecoys) do
                local hrp = d:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local angle = (idx / math.max(1, #activeDecoys)) * math.pi * 2
                    hrp.CFrame = myHRP.CFrame * CFrame.new(math.cos(angle) * 4, 1, math.sin(angle) * 4)
                    local grabEvents = RS and RS:FindFirstChild("GrabEvents")
                    local setNet = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
                    if setNet then
                        pcall(function() setNet:FireServer(hrp, hrp.CFrame) end)
                    end
                end
            end
            notify("Decoy", "All clones teleported to your position!", 2)
        end
    })

    DecoyActions:CreateButton({
        Name = "Fling Target with Clones",
        Callback = function()
            task.spawn(function()
                local targetPos, targetHRP = getTargetPosition()
                if not targetHRP then
                    notify("Decoy", "No valid target selected to fling!", 2)
                    return
                end
                refreshActiveDecoys()
                if #activeDecoys == 0 then
                    notify("Decoy", "No active clones found to fling with!", 2)
                    return
                end

                for _, d in ipairs(activeDecoys) do
                    local hrp = d:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local bv = Instance.new("BodyVelocity")
                        bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                        bv.Velocity = (targetHRP.Position - hrp.Position).Unit * 400
                        bv.Parent = hrp

                        local bav = Instance.new("BodyAngularVelocity")
                        bav.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                        bav.AngularVelocity = Vector3.new(300000, 300000, 300000)
                        bav.Parent = hrp

                        hrp.CFrame = targetHRP.CFrame

                        task.delay(0.6, function()
                            pcall(function() bv:Destroy() end)
                            pcall(function() bav:Destroy() end)
                        end)
                    end
                end
                notify("Decoy", "Clones launched at target!", 3)
            end)
        end
    })

    DecoyActions:CreateToggle({
        Name = "Noclip Clones (Pass Through Walls)",
        Default = false,
        Callback = function(val)
            DecoyConfig.NoclipClones = val
            for _, d in ipairs(activeDecoys) do
                for _, pt in ipairs(d:GetDescendants()) do
                    if pt:IsA("BasePart") then
                        pt.CanCollide = not val
                    end
                end
            end
        end
    })

    DecoyActions:CreateButton({
        Name = "Despawn / Delete All Decoy Clones",
        Callback = function()
            despawnAllDecoys()
        end
    })
    end
    task.spawn(function()
        local _ok, _err = pcall(_initDecoyEngine)
        if not _ok then warn("[TRFTAP] Decoy error: " .. tostring(_err)) end
    end)
end

