    local ACState = {
        Enabled = false,
        SelectedPose = "Doggy-Pose Sex",
        TargetMode = "Selected Target", -- "Selected Target", "All In Radius (Mass)", "Whole Server (Mass)"
        SearchRadius = 50,
        SelectedTargetName = "None",
        SelectedCenterName = "LocalPlayer",
        CustomPoseCenter = false,
        RagdollInAC = true,
        Transparency = 0,
        IndependentPoses = false,
        SelectedLimb = "Torso",
        CustomPresetName = "",
        CustomPresets = {},
        AnimateThrust = true,
        ThrustSpeed = 6.0,
        ThrustDistance = 0.8,
        SyncSelfAnimation = false,
        BodyOffset = Vector3.new(0, -1.4, -1.4),
        LimbRotation = {
            Torso = Vector3.new(100, -180, 0),
            Head = Vector3.new(90, 0, 0),
            ["Right Arm"] = Vector3.new(100, 0, 0),
            ["Left Arm"] = Vector3.new(100, 0, 0),
            ["Right Leg"] = Vector3.new(90, 0, 40),
            ["Left Leg"] = Vector3.new(90, 0, -40),
        },
        LimbOffset = {
            Torso = Vector3.zero,
            Head = Vector3.new(0, 1, 0),
            ["Right Arm"] = Vector3.new(1, 0.5, 0),
            ["Left Arm"] = Vector3.new(-1, 0.5, 0),
            ["Right Leg"] = Vector3.new(0, 1, 0),
            ["Left Leg"] = Vector3.new(0, 1, 0),
        },
        ActiveTargets = {},
    }

    local function resolveACPlayer(nameOrStr)
        if not nameOrStr or nameOrStr == "None" or nameOrStr == "" then return nil end
        local raw = tostring(nameOrStr)
        local username = raw:match("%(@(.+)%)") or raw:match("^%s*(.-)%s*$")
        local p = Players:FindFirstChild(username)
        if p then return p end
        for _, player in ipairs(Players:GetPlayers()) do
            if player.Name:lower() == username:lower() or player.DisplayName:lower() == username:lower() then
                return player
            end
        end
        return nil
    end

    local function getACPlayerList()
        local list = { "None" }
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p)) then
                table.insert(list, p.DisplayName .. " (@" .. p.Name .. ")")
            end
        end
        return list
    end

    local function notify(title, content, duration)
        pcall(function()
            if Library and Library.Notify then
                Library:Notify({
                    Title = title or "Auto-Clicker",
                    Content = content or "",
                    Duration = duration or 3
                })
            end
        end)
    end

    local lastSafeZoneWarnTick = 0
    local function showBottomSafeZoneAlert(playerName)
        local text = (playerName and (playerName .. " is in a safe zone (Plot)!") or "Target player is in a safe zone (Plot)!")
        pcall(function()
            if Library and Library.Notify then
                Library:Notify({
                    Title = "Safe Zone Alert",
                    Content = text,
                    Duration = 2.5
                })
            end
        end)

        pcall(function()
            local CoreGui = game:GetService("CoreGui")
            local Players = game:GetService("Players")
            local TweenService = game:GetService("TweenService")
            local lp = Players.LocalPlayer
            local parentGui = CoreGui
            pcall(function()
                if not parentGui:IsA("BasePlayerGui") then
                    parentGui = lp:FindFirstChild("PlayerGui")
                end
            end)

            local alertGui = parentGui:FindFirstChild("Ranax_BottomAlertGui")
            if not alertGui then
                alertGui = Instance.new("ScreenGui")
                alertGui.Name = "Ranax_BottomAlertGui"
                alertGui.ResetOnSpawn = false
                alertGui.IgnoreGuiInset = true
                alertGui.DisplayOrder = 99999
                alertGui.Parent = parentGui
            end

            local existingPill = alertGui:FindFirstChild("SafeZonePill")
            if existingPill then existingPill:Destroy() end

            local Pill = Instance.new("Frame")
            Pill.Name = "SafeZonePill"
            Pill.AnchorPoint = Vector2.new(0.5, 1)
            Pill.Position = UDim2.new(0.5, 0, 1, 60)
            Pill.Size = UDim2.new(0, 390, 0, 42)
            Pill.BackgroundColor3 = Color3.fromRGB(18, 14, 22)
            Pill.BackgroundTransparency = 0.12
            Pill.BorderSizePixel = 0
            Pill.Parent = alertGui

            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(0, 12)
            corner.Parent = Pill

            local stroke = Instance.new("UIStroke")
            stroke.Color = Color3.fromRGB(255, 75, 75)
            stroke.Thickness = 1.2
            stroke.Transparency = 0.25
            stroke.Parent = Pill

            local Icon = Instance.new("ImageLabel")
            Icon.Name = "Icon"
            Icon.AnchorPoint = Vector2.new(0, 0.5)
            Icon.Position = UDim2.new(0, 12, 0.5, 0)
            Icon.Size = UDim2.new(0, 22, 0, 22)
            Icon.BackgroundTransparency = 1
            Icon.Image = "rbxassetid://10826661578"
            Icon.ImageColor3 = Color3.fromRGB(255, 85, 85)
            Icon.Parent = Pill

            local Label = Instance.new("TextLabel")
            Label.Name = "Label"
            Label.AnchorPoint = Vector2.new(0, 0.5)
            Label.Position = UDim2.new(0, 42, 0.5, 0)
            Label.Size = UDim2.new(1, -54, 1, 0)
            Label.BackgroundTransparency = 1
            Label.Font = Enum.Font.GothamBold
            Label.Text = text
            Label.TextColor3 = Color3.fromRGB(255, 230, 230)
            Label.TextSize = 13
            Label.TextXAlignment = Enum.TextXAlignment.Left
            Label.Parent = Pill

            local tiIn = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
            TweenService:Create(Pill, tiIn, { Position = UDim2.new(0.5, 0, 1, -36) }):Play()

            task.delay(2.5, function()
                if Pill and Pill.Parent then
                    local tiOut = TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
                    local tw = TweenService:Create(Pill, tiOut, { Position = UDim2.new(0.5, 0, 1, 60), BackgroundTransparency = 1 })
                    tw:Play()
                    tw.Completed:Connect(function()
                        if Pill and Pill.Parent then Pill:Destroy() end
                    end)
                end
            end)
        end)
    end

    local function isPlayerInSafeZone(plr)
        if not plr then return false end
        -- 1. Check native FTAP player flags (managed directly by the game server)
        local inPlot = plr:FindFirstChild("InPlot")
        if inPlot and inPlot:IsA("BoolValue") and inPlot.Value == true then
            return true
        end
        local inOwned = plr:FindFirstChild("InOwnedPlot")
        if inOwned and inOwned:IsA("BoolValue") and inOwned.Value == true then
            return true
        end
        -- 2. Check PlayersInPlots folder (official safe zone registration in FTAP)
        local plotItems = workspace:FindFirstChild("PlotItems")
        if plotItems then
            local pip = plotItems:FindFirstChild("PlayersInPlots")
            if pip and pip:FindFirstChild(plr.Name) then
                return true
            end
        end
        return false
    end

    local function forceRagdollTarget(tChar)
        if not tChar then return end
        local tHum = tChar:FindFirstChildOfClass("Humanoid")
        local tTorso = tChar:FindFirstChild("Torso") or tChar:FindFirstChild("HumanoidRootPart")
        if not (tHum and tTorso) then return end

        tHum.PlatformStand = true
        tHum.AutoRotate = false
        pcall(function()
            tHum:ChangeState(Enum.HumanoidStateType.Physics)
        end)

        local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
        if charEvents then
            local r1 = charEvents:FindFirstChild("Ragdoll")
            local r2 = charEvents:FindFirstChild("RagdollRemote")
            if r1 then pcall(function() r1:FireServer(tTorso, 0) end) end
            if r2 then pcall(function() r2:FireServer(tTorso, 0) end) end
        end
    end

    local function cleanupTarget(target, data)
        if not target then return end
        pcall(function()
            local tChar = target.Character or (data and data.Character)
            if not tChar then return end

            local tHum = tChar:FindFirstChildOfClass("Humanoid")
            local tTorso = tChar:FindFirstChild("Torso") or tChar:FindFirstChild("UpperTorso")
            local tHRP = tChar:FindFirstChild("HumanoidRootPart")

            -- 1. Re-enable ALL Motor6Ds across the entire character and reset Transform to identity
            for _, m in ipairs(tChar:GetDescendants()) do
                if m:IsA("Motor6D") then
                    m.Enabled = true
                    pcall(function() m.Transform = CFrame.identity end)
                end
            end

            -- 2. Remove all AutoClicker forces, constraints, and custom attachments
            for _, pt in ipairs(tChar:GetDescendants()) do
                if pt:IsA("BasePart") then
                    pt.CanCollide = true
                    pt.CanQuery = true
                    pt.CanTouch = true
                    pt.LocalTransparencyModifier = 0
                    pt.AssemblyLinearVelocity = Vector3.zero
                    pt.AssemblyAngularVelocity = Vector3.zero

                    local bp = pt:FindFirstChild("AutoClickerBP")
                    if bp then bp:Destroy() end
                    local bg = pt:FindFirstChild("AutoClickerBG")
                    if bg then bg:Destroy() end
                    local att0 = pt:FindFirstChild("ACAtt0")
                    if att0 then att0:Destroy() end
                    local att1 = pt:FindFirstChild("ACAtt1")
                    if att1 then att1:Destroy() end
                    for _, child in ipairs(pt:GetChildren()) do
                        if child.Name:sub(1, 6) == "ACAtt_" then
                            child:Destroy()
                        end
                    end
                elseif pt:IsA("BallSocketConstraint") and pt.Name == "AutoClickerBSC" then
                    pt:Destroy()
                end
            end

            -- 3. Restore Humanoid speeds, posture, and state
            if tHum then
                if data and data.OrigWalkSpeed and data.OrigWalkSpeed > 0 then
                    tHum.WalkSpeed = data.OrigWalkSpeed
                else
                    tHum.WalkSpeed = 16
                end
                if data and data.OrigJumpPower and data.OrigJumpPower > 0 then
                    tHum.JumpPower = data.OrigJumpPower
                else
                    tHum.JumpPower = 50
                end
                tHum.PlatformStand = false
                tHum.Sit = false
                tHum.AutoRotate = true

                pcall(function()
                    tHum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
                task.defer(function()
                    pcall(function()
                        tHum:ChangeState(Enum.HumanoidStateType.Running)
                    end)
                end)
            end

            -- 4. Tell server to cancel ragdoll and remove grab line
            local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
            if charEvents then
                local r1 = charEvents:FindFirstChild("Ragdoll")
                local r2 = charEvents:FindFirstChild("RagdollRemote")
                local ragPart = tHRP or tTorso
                if r1 and ragPart then pcall(function() r1:FireServer(ragPart, 0) end) end
                if r2 and ragPart then pcall(function() r2:FireServer(ragPart, 0) end) end
                if tTorso and tTorso ~= ragPart then
                    if r1 then pcall(function() r1:FireServer(tTorso, 0) end) end
                    if r2 then pcall(function() r2:FireServer(tTorso, 0) end) end
                end
            end

            local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
            local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")
            if destroyLine then
                if tHRP then pcall(function() destroyLine:FireServer(tHRP) end) end
                if tTorso and tTorso ~= tHRP then pcall(function() destroyLine:FireServer(tTorso) end) end
            end
        end)
    end

