    local function applyACPreset(presetName)
        local pose = AutoClickerPoses[presetName]
        if pose then
            if pose.BodyPos then
                ACState.BodyOffset = Vector3.new(pose.BodyPos[1] or 0, pose.BodyPos[2] or 0, pose.BodyPos[3] or -5)
            end
            for limb, angles in pairs(pose) do
                if limb ~= "BodyPos" and type(angles) == "table" then
                    ACState.LimbRotation[limb] = Vector3.new(angles[1] or 0, angles[2] or 0, angles[3] or 0)
                end
            end
            if notify then notify("Auto-Clicker", "Loaded: " .. tostring(presetName), 2) end
        end
    end

