    local function playResAnim(animName)
        stopResAnim()
        if not resAnimActive then return end
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local animator = hum and (hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum))
        local animId = resonanceAnimMap[animName]
        if not (animator and animId) then return end
        local animObj = Instance.new("Animation")
        animObj.AnimationId = animId
        local ok, trk = pcall(function() return animator:LoadAnimation(animObj) end)
        if ok and trk then
            currentPlayingAnimTrack = trk
            currentPlayingAnimTrack.Looped = true
            currentPlayingAnimTrack.Priority = Enum.AnimationPriority.Action4
            currentPlayingAnimTrack:Play()
            currentPlayingAnimTrack:AdjustSpeed(resAnimSpeed)
        end
    end

    ResonanceAnimBlock:CreateDropdown({
        Name = "Select Animation",
        List = resonanceAnimList,
        Default = "Struggle",
        Callback = function(v)
            selectedResAnim = v or "Struggle"
            if resAnimActive then
                playResAnim(selectedResAnim)
            end
        end
    })

    ResonanceAnimBlock:CreateToggle({
        Name = "Play Resonance Animation",
        Default = false,
        Callback = function(v)
            resAnimActive = v
            if v then
                playResAnim(selectedResAnim)
            else
                stopResAnim()
            end
        end
    })

    ResonanceAnimBlock:CreateSlider({
        Name = "Animation Speed",
        Min = 0,
        Max = 20,
        Default = 1,
        Rounding = 1,
        Callback = function(v)
            resAnimSpeed = v
            if currentPlayingAnimTrack then
                pcall(function() currentPlayingAnimTrack:AdjustSpeed(v) end)
            end
        end
    })

    -- =========================================================================
    -- BACKGROUND EXECUTION ENGINE (Resonance 1:1 Physics, Thrust & Orientation)
    -- =========================================================================
    RunService.Heartbeat:Connect(function()
        if not ACState.Enabled then
            if next(ACState.ActiveTargets) then
                for target, data in pairs(ACState.ActiveTargets) do
                    cleanupTarget(target, data)
                end
                ACState.ActiveTargets = {}
                local myChar = LocalPlayer.Character
                local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if myHRP then
                    myHRP.AssemblyLinearVelocity = Vector3.zero
                    myHRP.AssemblyAngularVelocity = Vector3.zero
                end
            end
            ACState.IsFetchingAny = false
            if ACState.SyncSelfAnimation and _G.StopSexAnim then
                pcall(_G.StopSexAnim)
            end
            return
        end

        local myChar = LocalPlayer.Character
        local myTorso = myChar and (myChar:FindFirstChild("Torso") or myChar:FindFirstChild("HumanoidRootPart"))
        if not myTorso then return end

        -- Center resolution (Resonance 1:1)
        local centerTorso = myTorso
        if ACState.CustomPoseCenter and ACState.SelectedCenterName ~= "LocalPlayer" and ACState.SelectedCenterName ~= "None" then
            local cPlr = Players:FindFirstChild(ACState.SelectedCenterName)
            if cPlr and cPlr.Character then
                centerTorso = cPlr.Character:FindFirstChild("Torso") or cPlr.Character:FindFirstChild("HumanoidRootPart") or myTorso
            end
        end

        -- Target resolution (Dropdown target or Toplu Tutma) with Safe Zone (Plot) Protection
        local currentTargets = {}
        local safeZoneWarned = false
        if ACState.TargetMode == "Whole Server (Mass)" then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p)) and p.Character then
                    local hum = p.Character:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 then
                        if isPlayerInSafeZone(p) then
                            if tick() - lastSafeZoneWarnTick > 3 and not safeZoneWarned then
                                lastSafeZoneWarnTick = tick()
                                safeZoneWarned = true
                                showBottomSafeZoneAlert(p.DisplayName or p.Name)
                            end
                        else
                            table.insert(currentTargets, p)
                        end
                    end
                end
            end
        elseif ACState.TargetMode == "All In Radius (Mass)" then
            local myPos = myTorso.Position
            local r = ACState.SearchRadius or 50
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p)) and p.Character then
                    local pTorso = p.Character:FindFirstChild("Torso") or p.Character:FindFirstChild("HumanoidRootPart")
                    local hum = p.Character:FindFirstChildOfClass("Humanoid")
                    if pTorso and hum and hum.Health > 0 then
                        if (pTorso.Position - myPos).Magnitude <= r then
                            if isPlayerInSafeZone(p) then
                                if tick() - lastSafeZoneWarnTick > 3 and not safeZoneWarned then
                                    lastSafeZoneWarnTick = tick()
                                    safeZoneWarned = true
                                    showBottomSafeZoneAlert(p.DisplayName or p.Name)
                                end
                            else
                                table.insert(currentTargets, p)
                            end
                        end
                    end
                end
            end
        else
            local targetPlr = resolveACPlayer(ACState.SelectedTargetName)
            if not targetPlr then
                local myPos = myTorso.Position
                local nearestDist = 2000
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(p)) and p.Character then
                        local pTorso = p.Character:FindFirstChild("HumanoidRootPart") or p.Character:FindFirstChild("Torso")
                        if pTorso then
                            local dist = (pTorso.Position - myPos).Magnitude
                            if dist <= nearestDist then
                                nearestDist = dist
                                targetPlr = p
                            end
                        end
                    end
                end
            end
            if targetPlr and targetPlr.Character and not (_G.TR_IsWhitelisted and _G.TR_IsWhitelisted(targetPlr)) then
                if isPlayerInSafeZone(targetPlr) then
                    if tick() - lastSafeZoneWarnTick > 3 then
                        lastSafeZoneWarnTick = tick()
                        showBottomSafeZoneAlert(targetPlr.DisplayName or targetPlr.Name)
                    end
                else
                    table.insert(currentTargets, targetPlr)
                end
            end
        end

        if #currentTargets == 0 then
            if next(ACState.ActiveTargets) then
                for target, data in pairs(ACState.ActiveTargets) do
                    cleanupTarget(target, data)
                end
                ACState.ActiveTargets = {}
                local myChar = LocalPlayer.Character
                local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if myHRP then
                    myHRP.AssemblyLinearVelocity = Vector3.zero
                    myHRP.AssemblyAngularVelocity = Vector3.zero
                end
            end
            ACState.IsFetchingAny = false
            if ACState.SyncSelfAnimation and _G.StopSexAnim then
                pcall(_G.StopSexAnim)
            end
            return
        end

        -- Clean up inactive targets
        local validMap = {}
        for _, p in ipairs(currentTargets) do validMap[p] = true end
        for target, data in pairs(ACState.ActiveTargets) do
            if not validMap[target] then
                cleanupTarget(target, data)
                ACState.ActiveTargets[target] = nil
            end
        end

        -- Thrust Animation & Cycle calculation
        local poseName = tostring(ACState.SelectedPose or "")
        local poseData = AutoClickerPoses[poseName]
        local isSexPose = poseName:find("Sex") or poseName:find("Blowjob") or (poseData and poseData.ThrustAxis)
        local thrustX, thrustY, thrustZ = 0, 0, 0
        if ACState.AnimateThrust and isSexPose then
            local cycle = math.sin(tick() * (ACState.ThrustSpeed or 6.0))
            local dist = (ACState.ThrustDistance or 0.8)
            local thrust = cycle * dist
            if poseName == "Standing Sex" or (poseData and poseData.ThrustAxis == "Y") then
                thrustY = thrust
                thrustZ = 0
                thrustX = 0
            elseif poseName:find("Blowjob") then
                thrustY = thrust * 0.35
                thrustZ = thrust * 0.7
            elseif poseName:find("Missionary") then
                thrustY = thrust * 0.4
                thrustZ = thrust * 0.5
            else
                thrustZ = thrust
            end
        end

        -- Self Animation Sync (Bang / Jerk)
        if ACState.SyncSelfAnimation and _G.StartSexAnim then
            if isSexPose then
                if poseName:find("Blowjob") then
                    _G.StartSexAnim(false)
                else
                    _G.StartSexAnim(true)
                end
            end
        end

        local animatedBodyOffset = Vector3.new(
            ACState.BodyOffset.X + thrustX,
            ACState.BodyOffset.Y + thrustY,
            ACState.BodyOffset.Z + thrustZ
        )

        local totalTargets = #currentTargets
        for tIdx, targetPlr in ipairs(currentTargets) do
            local tChar = targetPlr and targetPlr.Character
            local tTorso = tChar and (tChar:FindFirstChild("Torso") or tChar:FindFirstChild("HumanoidRootPart"))
            local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
            if tTorso and tHum and tHum.Health > 0 then

        local data = ACState.ActiveTargets[targetPlr]
        if not data or data.Character ~= tChar then
            data = {
                Character = tChar,
                Torso = tTorso,
                LineCreated = false,
                Gyros = {},
                OrigWalkSpeed = tHum.WalkSpeed,
                OrigJumpPower = tHum.JumpPower,
                Fetched = false,
                Fetching = false,
            }
            ACState.ActiveTargets[targetPlr] = data

            -- Halt victim walking and movement immediately
            tHum.WalkSpeed = 0
            tHum.JumpPower = 0
            tHum.PlatformStand = true
            tHum.AutoRotate = false

            -- Instant noclip across all victim parts
            for _, pt in ipairs(tChar:GetDescendants()) do
                if pt:IsA("BasePart") then
                    pt.CanCollide = false
                    pt.CanQuery = false
                    pt.CanTouch = false
                end
            end

            forceRagdollTarget(tChar)
        end

        local myHRP = myChar:FindFirstChild("HumanoidRootPart") or myTorso
        local tHRP = tChar:FindFirstChild("HumanoidRootPart") or tTorso

        -- Adama Figure Grab gibi TP olup tutup geri ışınlama (1:1 Figure Grab Seam)
        if not data.Fetched and not data.Fetching and not ACState.IsFetchingAny then
            local dist = (myHRP.Position - tHRP.Position).Magnitude
            if dist > 4 then
                data.Fetching = true
                ACState.IsFetchingAny = true
                task.spawn(function()
                    local savedPos = myHRP.CFrame
                    local fetchSuccess = false
                    pcall(function()
                        if not ACState.Enabled or not targetPlr or not targetPlr.Character then return end

                        -- Noclip victim through walls
                        for _, p in ipairs(tChar:GetDescendants()) do
                            if p:IsA("BasePart") then
                                p.CanCollide = false
                                p.CanTouch = false
                                p.CanQuery = false
                            end
                        end
-- (LocalPlayer collision left untouched)

                        local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
                        local srf = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
                        local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")
                        local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
                        local ragdollRemote = charEvents and (charEvents:FindFirstChild("Ragdoll") or charEvents:FindFirstChild("RagdollRemote"))

                        -- 1. Hedefin tam yanına ışınlan (Figure Grab 1:1)
                        myHRP.CFrame = tHRP.CFrame * CFrame.new(0, 0, 2.5)
                        myHRP.AssemblyLinearVelocity = Vector3.zero
                        task.wait(0.03)

                        -- 2. 8 kez SetNetworkOwner, 4 kez DestroyGrabLine
                        if srf then
                            for i = 1, 8 do
                                pcall(function() srf:FireServer(tHRP, tHRP.CFrame) end)
                                local torso = tChar:FindFirstChild("Torso")
                                if torso then pcall(function() srf:FireServer(torso, torso.CFrame) end) end
                                task.wait(0.01)
                            end
                        end

                        if ragdollRemote then
                            pcall(function() ragdollRemote:FireServer(tHRP, 0) end)
                        end

                        if destroyLine then
                            for i = 1, 4 do
                                pcall(function() destroyLine:FireServer(tHRP) end)
                                local torso = tChar:FindFirstChild("Torso")
                                if torso then pcall(function() destroyLine:FireServer(torso) end) end
                                task.wait(0.01)
                            end
                        end

                        -- 3. Kurbanı önceki konuma ışınla
                        local bringCF = savedPos * CFrame.new(0, -1.2, -1.4)
                        pcall(function() tChar:PivotTo(bringCF) end)
                        tHRP.CFrame = bringCF
                        local torso = tChar:FindFirstChild("Torso")
                        if torso then torso.CFrame = bringCF end
                        tHRP.AssemblyLinearVelocity = Vector3.zero
                        pcall(function()
                            tHum.PlatformStand = true
                            tHum.AutoRotate = false
                        end)

                        task.wait(0.03)
                        fetchSuccess = true
                    end)

                    -- 4. Kendini her durumda önceki konuma geri ışınla
                    pcall(function()
                        if myHRP and myHRP.Parent then
                            myHRP.CFrame = savedPos
                            myHRP.AssemblyLinearVelocity = Vector3.zero
                        end
                    end)

                    data.Fetched = fetchSuccess
                    data.Fetching = false
                    ACState.IsFetchingAny = false
                end)
            else
                data.Fetched = true
            end
        end

        if data.Fetching then
            continue
        end

        -- Break victim animation lock locally on Torso Motor6D joints
        local actualTorso = tChar:FindFirstChild("Torso")
        if actualTorso then
            for _, m in ipairs(actualTorso:GetChildren()) do
                if m:IsA("Motor6D") and m.Enabled then
                    m.Enabled = false
                end
            end
        end

        -- Collision disable on victim BaseParts and RagdollLimbParts (Resonance 1:1)
        for _, pt in ipairs(tChar:GetDescendants()) do
            if pt:IsA("BasePart") then
                pt.CanCollide = false
                pt.CanQuery = false
                pt.CanTouch = false
                if ACState.Transparency > 0 then
                    pt.LocalTransparencyModifier = ACState.Transparency
                end
            end
        end

        -- (Victim noclipped above; LocalPlayer collision left untouched)

        -- Ragdoll refresh (Resonance standard)
        if ACState.RagdollInAC then
            tHum.PlatformStand = true
            tHum.AutoRotate = false
            pcall(function()
                tHum:ChangeState(Enum.HumanoidStateType.Physics)
            end)
            local ragdolledVal = tHum:FindFirstChild("Ragdolled")
            if not ragdolledVal or ragdolledVal.Value == false then
                if tick() - (data.LastRagdoll or 0) > 0.8 then
                    data.LastRagdoll = tick()
                    forceRagdollTarget(tChar)
                end
            end
        end

        -- Periodic Network Ownership & Grab Line cleanup across ALL limbs (Resonance 1:1)
        if tick() - (data.LastNetRefresh or 0) > 0.15 then
            data.LastNetRefresh = tick()
            local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
            local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")
            if destroyLine then
                pcall(function() destroyLine:FireServer(tTorso) end)
            end
            local srf = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
            if srf then
                local partsToOwn = { "Torso", "HumanoidRootPart", "Head", "Right Arm", "Left Arm", "Right Leg", "Left Leg" }
                for _, pName in ipairs(partsToOwn) do
                    local pPart = tChar:FindFirstChild(pName)
                    if pPart and pPart:IsA("BasePart") then
                        local rayCF = CFrame.new((myTorso.CFrame * CFrame.new(0, 1.593, 0)).Position, pPart.Position)
                        pcall(function() srf:FireServer(pPart, rayCF) end)
                    end
                end
            end
        end

        local fanAngle = (totalTargets > 1) and ((tIdx - (totalTargets + 1) / 2) * 0.45) or 0
        local centerCF = centerTorso.CFrame * CFrame.Angles(0, fanAngle, 0)
        local targetWorldPos = (centerCF * CFrame.new(animatedBodyOffset)).Position

        -- Torso BodyPosition (Resonance 1:1 smooth target updating)
        local bp = tTorso:FindFirstChild("AutoClickerBP") or Instance.new("BodyPosition", tTorso)
        bp.Name = "AutoClickerBP"
        bp.D = 450
        bp.P = 40000
        bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        if not data.BodyTarget or (data.BodyTarget - targetWorldPos).Magnitude > 0.04 then
            bp.Position = targetWorldPos
            data.BodyTarget = targetWorldPos
        end

        -- Orientation calculation (Resonance 1:1 + NaN/Singularity Immunity)
        local isShoulderSit = (poseName == "Shoulder-Sitting")
        local faceForward = isShoulderSit or (poseData and poseData.FaceForward)

        local diffX = centerCF.Position.X - targetWorldPos.X
        local diffZ = centerCF.Position.Z - targetWorldPos.Z
        local distXZ = math.sqrt(diffX * diffX + diffZ * diffZ)

        local baseFacingCF
        if faceForward or distXZ < 0.35 then
            baseFacingCF = centerCF.Rotation
        else
            local lookDir = Vector3.new(diffX, 0, diffZ).Unit
            baseFacingCF = CFrame.lookAt(Vector3.zero, lookDir)
        end

        local torsoAngles = ACState.LimbRotation.Torso or Vector3.zero
        local torsoRotFrame = CFrame.Angles(math.rad(torsoAngles.X), math.rad(torsoAngles.Y), math.rad(torsoAngles.Z))
        local torsoTargetRot = baseFacingCF * torsoRotFrame
        local targetGyroCF = CFrame.new(targetWorldPos) * torsoTargetRot.Rotation

        -- Torso BodyGyro (Resonance 1:1)
        local bgTorso = tTorso:FindFirstChild("AutoClickerBG") or Instance.new("BodyGyro", tTorso)
        bgTorso.Name = "AutoClickerBG"
        bgTorso.D = 500
        bgTorso.P = 7500
        bgTorso.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
        if not data.GyroTarget or data.GyroTarget ~= targetGyroCF then
            bgTorso.CFrame = targetGyroCF
            data.GyroTarget = targetGyroCF
        end

        -- Snap CFrame ONLY on huge desync / initial teleport (> 9 studs) to avoid physics fight & sliding
        local currentDist = (tTorso.Position - targetWorldPos).Magnitude
        if currentDist > 9 then
            tTorso.CFrame = targetGyroCF
            local tHRP = tChar:FindFirstChild("HumanoidRootPart")
            if tHRP and tHRP ~= tTorso then tHRP.CFrame = targetGyroCF end
        end

        -- Match velocity with center player to eliminate sliding and jitter
        tTorso.AssemblyLinearVelocity = centerTorso.AssemblyLinearVelocity
        tTorso.AssemblyAngularVelocity = Vector3.zero

        local tHRP = tChar:FindFirstChild("HumanoidRootPart")
        if tHRP and tHRP ~= tTorso then
            tHRP.AssemblyLinearVelocity = centerTorso.AssemblyLinearVelocity
            tHRP.AssemblyAngularVelocity = Vector3.zero
        end

        -- Individual Limbs (Resonance 1:1 BallSocketConstraint & BodyGyro + Realtime Kinematic Fallback)
        local limbs = { "Head", "Right Arm", "Left Arm", "Right Leg", "Left Leg" }
        local jointPosTorso = {
            Head = Vector3.new(0, 1, 0),
            ["Right Arm"] = Vector3.new(1, 0.5, 0),
            ["Left Arm"] = Vector3.new(-1, 0.5, 0),
            ["Right Leg"] = Vector3.new(0.5, -1, 0),
            ["Left Leg"] = Vector3.new(-0.5, -1, 0),
        }
        local jointPosLimb = {
            Head = Vector3.new(0, -0.5, 0),
            ["Right Arm"] = Vector3.new(-0.5, 0.5, 0),
            ["Left Arm"] = Vector3.new(0.5, 0.5, 0),
            ["Right Leg"] = Vector3.new(0, 1, 0),
            ["Left Leg"] = Vector3.new(0, 1, 0),
        }
        local limbCenterFromJoint = {
            Head = Vector3.new(0, 0.5, 0),
            ["Right Arm"] = Vector3.new(0.5, -0.5, 0),
            ["Left Arm"] = Vector3.new(-0.5, -0.5, 0),
            ["Right Leg"] = Vector3.new(0, -1, 0),
            ["Left Leg"] = Vector3.new(0, -1, 0),
        }

        local ragdolledVal = tHum:FindFirstChild("Ragdolled")
        local isServerRagdolled = ragdolledVal and ragdolledVal.Value == true

        for _, limbName in ipairs(limbs) do
            local limbPart = tChar:FindFirstChild(limbName)
            if limbPart and limbPart:IsA("BasePart") then
                limbPart.CanCollide = false
                local ragdollLimb = limbPart:FindFirstChild("RagdollLimbPart")
                if ragdollLimb and ragdollLimb:IsA("BasePart") then
                    ragdollLimb.CanCollide = false
                end

                -- Joint attachment (Resonance 1:1 or Fallback BallSocket)
                local bsc = limbPart:FindFirstChildOfClass("BallSocketConstraint")
                if not bsc and actualTorso then
                    local att0 = actualTorso:FindFirstChild("ACAtt_" .. limbName) or Instance.new("Attachment", actualTorso)
                    att0.Name = "ACAtt_" .. limbName
                    att0.Position = jointPosTorso[limbName] or Vector3.zero

                    local att1 = limbPart:FindFirstChild("ACAtt1") or Instance.new("Attachment", limbPart)
                    att1.Name = "ACAtt1"
                    att1.Position = jointPosLimb[limbName] or Vector3.zero

                    bsc = Instance.new("BallSocketConstraint", limbPart)
                    bsc.Name = "AutoClickerBSC"
                    bsc.Attachment0 = att0
                    bsc.Attachment1 = att1
                    bsc.LimitsEnabled = false
                    bsc.TwistLimitsEnabled = false
                end

                if bsc then
                    bsc.LimitsEnabled = false
                    bsc.TwistLimitsEnabled = false
                    local lOff = ACState.LimbOffset[limbName]
                    if lOff and bsc.Attachment1 and bsc.Attachment1.Position ~= lOff then
                        bsc.Attachment1.Position = lOff
                    end
                end

                -- Limb BodyGyro: orientation relative to tTorso (Resonance 1:1)
                local rotAngles = ACState.LimbRotation[limbName] or Vector3.zero
                local rotFrame = CFrame.Angles(math.rad(rotAngles.X), math.rad(rotAngles.Y), math.rad(rotAngles.Z))
                local limbTargetRot = tTorso.CFrame * rotFrame

                local gyro = limbPart:FindFirstChild("AutoClickerBG") or Instance.new("BodyGyro", limbPart)
                gyro.Name = "AutoClickerBG"
                gyro.D = 500
                gyro.P = 7500
                gyro.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                gyro.CFrame = limbTargetRot

                -- If victim is not yet fully server-ragdolled, force anatomical socket CFrame so limbs pose visibly with zero delay
                if not isServerRagdolled and actualTorso then
                    local pTorsoPivot = jointPosTorso[limbName] or Vector3.zero
                    local pCenterOffset = limbCenterFromJoint[limbName] or Vector3.zero
                    limbPart.CFrame = actualTorso.CFrame * CFrame.new(pTorsoPivot) * rotFrame * CFrame.new(pCenterOffset)
                end

                limbPart.AssemblyLinearVelocity = centerTorso.AssemblyLinearVelocity
                limbPart.AssemblyAngularVelocity = Vector3.zero
            end
        end
            end
        end
    end)
    end
    task.spawn(function()
        local _ok, _err = pcall(_initAutoClickerTab)
        if not _ok then warn("[TRFTAP] AutoClicker error: " .. tostring(_err)) end
    end)
end

-- =========================================================================
-- TAB: WHITELIST (UNIVERSAL FRIEND & PLAYER IMMUNITY SYSTEM)
-- =========================================================================
do
    local function _initWhitelistTab()
        if not Tabs.Whitelist or not Tabs.Whitelist.CreateBlock then return end

        local Players = game:GetService("Players")
        local StarterGui = game:GetService("StarterGui")
        local LocalPlayer = Players.LocalPlayer

        local function notify(title, desc, duration)
            title = title or "Ranax Whitelist"
            pcall(function()
                if Library and Library.Notify then
                    Library:Notify({
                        Title = title,
                        Content = desc or "",
                        Duration = duration or 2.5
                    })
                else
                    StarterGui:SetCore("SendNotification", {
                        Title = title,
                        Text = desc or "",
                        Duration = duration or 2.5
                    })
                end
            end)
        end

        local FriendsBlock = Tabs.Whitelist:CreateBlock({ Name = "Friends Protection", Side = "Left" })
        local PlayersBlock = Tabs.Whitelist:CreateBlock({ Name = "Whitelist Manager", Side = "Right" })

        local selectedFriend = "None"
        local selectedServerPlayer = "None"
        local selectedWhitelisted = "None"

        local FriendDropdownRef = nil
        local ServerPlayerDropdownRef = nil
        local CurrentWhitelistDropdownRef = nil

        local function getFriendsInServer()
            local list = { "None" }
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then
                    local isF = false
                    pcall(function()
                        isF = LocalPlayer:IsFriendsWith(p.UserId)
                    end)
                    if isF then
                        table.insert(list, p.Name)
                    end
                end
            end
            return list
        end

        local function getServerPlayers()
            local list = { "None" }
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then
                    table.insert(list, p.Name)
                end
            end
            return list
        end

        local function getWhitelistEntries()
            local list = { "None" }
            if _G.TR_Whitelist then
                for key, val in pairs(_G.TR_Whitelist) do
                    if val then
                        table.insert(list, tostring(key))
                    end
                end
            end
            return list
        end

        local function refreshAll()
            pcall(function()
                local friends = getFriendsInServer()
                local serverPlrs = getServerPlayers()
                local wl = getWhitelistEntries()

                if FriendDropdownRef and FriendDropdownRef.Refresh then
                    FriendDropdownRef:Refresh(friends)
                end
                if ServerPlayerDropdownRef and ServerPlayerDropdownRef.Refresh then
                    ServerPlayerDropdownRef:Refresh(serverPlrs)
                end
                if CurrentWhitelistDropdownRef and CurrentWhitelistDropdownRef.Refresh then
                    CurrentWhitelistDropdownRef:Refresh(wl)
                end
            end)
        end

        -- ---------------------------------------------------------------------
        -- LEFT BLOCK: Friends Protection
        -- ---------------------------------------------------------------------
        FriendsBlock:CreateToggle({
            Name = "Auto-Whitelist All Friends",
            Default = (_G.TR_AutoWhitelistFriends == true),
            Callback = function(v)
                _G.TR_AutoWhitelistFriends = v
                notify("Whitelist", "Auto-Whitelist Friends: " .. (v and "ENABLED" or "DISABLED"), 2)
            end
        })

        FriendDropdownRef = FriendsBlock:CreateDropdown({
            Name = "Select Friend in Server",
            List = getFriendsInServer(),
            Default = "None",
            Callback = function(v)
                selectedFriend = v or "None"
            end
        })

        FriendsBlock:CreateButton({
            Name = "Add Friend to Whitelist",
            Callback = function()
                if selectedFriend and selectedFriend ~= "None" and selectedFriend ~= "" then
                    _G.TR_Whitelist[selectedFriend] = true
                    local pl = Players:FindFirstChild(selectedFriend)
                    if pl then
                        _G.TR_Whitelist[tostring(pl.UserId)] = true
                    end
                    refreshAll()
                    notify("Whitelist", "Whitelisted friend: " .. tostring(selectedFriend), 2)
                else
                    notify("Whitelist", "No friend selected", 2)
                end
            end
        })

        FriendsBlock:CreateButton({
            Name = "Remove Friend from Whitelist",
            Callback = function()
                if selectedFriend and selectedFriend ~= "None" and selectedFriend ~= "" then
                    _G.TR_Whitelist[selectedFriend] = nil
                    local pl = Players:FindFirstChild(selectedFriend)
                    if pl then
                        _G.TR_Whitelist[tostring(pl.UserId)] = nil
                    end
                    refreshAll()
                    notify("Whitelist", "Removed friend: " .. tostring(selectedFriend), 2)
                else
                    notify("Whitelist", "No friend selected", 2)
                end
            end
        })

        FriendsBlock:CreateButton({
            Name = "Add All Server Friends",
            Callback = function()
                local count = 0
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer then
                        local isF = false
                        pcall(function() isF = LocalPlayer:IsFriendsWith(p.UserId) end)
                        if isF then
                            _G.TR_Whitelist[p.Name] = true
                            _G.TR_Whitelist[tostring(p.UserId)] = true
                            count = count + 1
                        end
                    end
                end
                refreshAll()
                notify("Whitelist", "Added " .. count .. " server friends to whitelist", 2)
            end
        })

        -- ---------------------------------------------------------------------
        -- RIGHT BLOCK: Whitelist Manager
        -- ---------------------------------------------------------------------
        ServerPlayerDropdownRef = PlayersBlock:CreateDropdown({
            Name = "Select Server Player",
            List = getServerPlayers(),
            Default = "None",
            Callback = function(v)
                selectedServerPlayer = v or "None"
            end
        })

        PlayersBlock:CreateButton({
            Name = "Add Player to Whitelist",
            Callback = function()
                if selectedServerPlayer and selectedServerPlayer ~= "None" and selectedServerPlayer ~= "" then
                    _G.TR_Whitelist[selectedServerPlayer] = true
                    local pl = Players:FindFirstChild(selectedServerPlayer)
                    if pl then
                        _G.TR_Whitelist[tostring(pl.UserId)] = true
                    end
                    refreshAll()
                    notify("Whitelist", "Whitelisted player: " .. tostring(selectedServerPlayer), 2)
                else
                    notify("Whitelist", "No player selected", 2)
                end
            end
        })

        CurrentWhitelistDropdownRef = PlayersBlock:CreateDropdown({
            Name = "Current Whitelist",
            List = getWhitelistEntries(),
            Default = "None",
            Callback = function(v)
                selectedWhitelisted = v or "None"
            end
        })

        PlayersBlock:CreateButton({
            Name = "Remove Selected from Whitelist",
            Callback = function()
                if selectedWhitelisted and selectedWhitelisted ~= "None" and selectedWhitelisted ~= "" then
                    _G.TR_Whitelist[selectedWhitelisted] = nil
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p.Name == selectedWhitelisted or tostring(p.UserId) == selectedWhitelisted then
                            _G.TR_Whitelist[p.Name] = nil
                            _G.TR_Whitelist[tostring(p.UserId)] = nil
                        end
                    end
                    refreshAll()
                    notify("Whitelist", "Removed: " .. tostring(selectedWhitelisted), 2)
                else
                    notify("Whitelist", "No whitelist entry selected", 2)
                end
            end
        })

        PlayersBlock:CreateButton({
            Name = "Refresh All Lists",
            Callback = function()
                refreshAll()
                notify("Whitelist", "All whitelist and player lists refreshed", 1.5)
            end
        })

        PlayersBlock:CreateButton({
            Name = "Clear Entire Whitelist",
            Callback = function()
                table.clear(_G.TR_Whitelist)
                refreshAll()
                notify("Whitelist", "Whitelist completely cleared", 2)
            end
        })

        -- Auto-refresh on player join/leave
        Players.PlayerAdded:Connect(function()
            task.wait(0.5)
            refreshAll()
        end)
        Players.PlayerRemoving:Connect(function()
            task.wait(0.5)
            refreshAll()
        end)
    end
    task.spawn(function()
        local _ok, _err = pcall(_initWhitelistTab)
        if not _ok then warn("[TRFTAP] Whitelist error: " .. tostring(_err)) end
    end)
end

print("Ranax FTAP Loaded")
-- =========================================================================
-- Universal Grab-Drop Floor Collision & Anti-Sink Safeguard
-- Prevents victims from falling through the floor or into the void when dropped
-- =========================================================================
Workspace.ChildAdded:Connect(function(child)
    if child.Name == "GrabParts" then
        task.defer(function()
            local grabPart = child:WaitForChild("GrabPart", 1)
            local weld = grabPart and grabPart:WaitForChild("WeldConstraint", 1)
            local part1 = weld and weld.Part1
            local heldChar = part1 and (part1.Parent:FindFirstChildOfClass("Humanoid") and part1.Parent or (part1.Parent.Parent and part1.Parent.Parent:FindFirstChildOfClass("Humanoid") and part1.Parent.Parent))
            
            if heldChar and heldChar ~= LocalPlayer.Character then
                child:GetPropertyChangedSignal("Parent"):Connect(function()
                    if not child.Parent and heldChar and heldChar.Parent then
                        task.defer(function()
                            for _, p in ipairs(heldChar:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    if p.Name == "Torso" or p.Name == "UpperTorso" or p.Name == "LowerTorso" or p.Name == "Head" or p.Name == "HumanoidRootPart" then
                                        p.CanCollide = true
                                    else
                                        p.CanCollide = false
                                    end
                                end
                            end
                            local hrp = heldChar:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                if hrp.AssemblyLinearVelocity.Y < 0 then
                                    hrp.AssemblyLinearVelocity = Vector3.new(hrp.AssemblyLinearVelocity.X, 0, hrp.AssemblyLinearVelocity.Z)
                                end
                                local rayParams = RaycastParams.new()
                                rayParams.FilterType = Enum.RaycastFilterType.Exclude
                                rayParams.FilterDescendantsInstances = {heldChar}
                                local hit = Workspace:Raycast(hrp.Position + Vector3.new(0, 3, 0), Vector3.new(0, -12, 0), rayParams)
                                if hit and hrp.Position.Y < hit.Position.Y + 2.5 then
                                    hrp.CFrame = CFrame.new(hrp.Position.X, hit.Position.Y + 3.2, hrp.Position.Z) * hrp.CFrame.Rotation
                                end
                            end
                        end)
                    end
                end)
            end
        end)
    end
end)
